    pub const SANITIZER_GROUP_UNMEASURED: Rule = Rule {
        id: "sanitizer-group-unmeasured",
        premise: InstrumentLimitation,
        statement: "the compile enabled a sanitizer group whose mode the probe's functions did not establish",
        stage: Stage::Sanitizer,
        arms: &[Arm::Measured],
        evidence: Evidence::CompileSanitizerLists,
    };
    /// The measured compile enables the signed-integer-overflow sanitizer, whose own check of
