    #[test]
    fn the_link_input_rule_withholds_the_listed_linked_checks_and_nothing_else() {
        let mut listed = 0;
        for id in LINK_INPUT_READINGS {
            let (probe, check) = crate::probe::CORPUS
                .iter()
                .find_map(|p| p.checks.iter().find(|c| c.id == *id).map(|c| (p, c)))
                .unwrap_or_else(|| panic!("{id} is not a check"));
            assert_ne!(
                probe.link_mode,
                crate::probe::LinkMode::Object,
                "{id} reads no link"
            );
            assert_ne!(check.channel(), Channel::Macro, "{id} reads a dump");
            listed += 1;
        }
        for id in LINK_ANDED_MARKINGS {
            assert!(
                LINK_INPUT_READINGS.contains(id),
                "{id} is ANDed at the link"
            );
        }
        let mut walked = 0;
        let mut fired = 0;
        for check in crate::probe::CORPUS.iter().flat_map(|p| p.checks) {
            assert!(
                link_inputs_limitation(check, None).is_none(),
                "{}",
                check.id
            );
            let gating = link_inputs_limitation(check, Some("/srv/crtbeginS.o"));
            assert_eq!(
                gating.is_some(),
                LINK_INPUT_READINGS.contains(&check.id),
                "{}",
                check.id
            );
            if let Some(gating) = gating {
                assert_eq!(gating.rule, gating_rule::LINK_INPUTS_UNMATCHED);
                assert!(
                    gating.reason.contains("/srv/crtbeginS.o"),
                    "{}",
                    gating.reason
                );
                fired += 1;
            }
            walked += 1;
        }
        assert_eq!(listed, LINK_INPUT_READINGS.len());
        assert_eq!(fired, listed, "each listed check fired once");
        assert_eq!(
            walked,
            crate::probe::CORPUS
                .iter()
                .map(|p| p.checks.len())
                .sum::<usize>()
        );
    }

    #[test]
    fn the_clean_link_rule_withholds_the_checks_reading_the_clean_link_and_nothing_else() {
        const FIRES: &[&str] = &["linker-default-noexecstack"];
        let mut walked = 0_usize;
        let mut fired: Vec<&str> = Vec::new();
        for probe in crate::probe::CORPUS {
            for check in probe.checks {
                assert!(clean_link_limitation(check, None).is_none(), "{}", check.id);
                let gating = clean_link_limitation(check, Some("/srv/px/ld"));
                assert_eq!(gating.is_some(), FIRES.contains(&check.id), "{}", check.id);
                if let Some(gating) = gating {
                    assert!(check.measures_toolchain_default, "{}", check.id);
                    assert_ne!(
                        probe.link_mode,
                        crate::probe::LinkMode::Object,
                        "{} reads no link",
                        check.id
                    );
                    assert!(
                        LINK_INPUT_READINGS.contains(&check.id),
                        "{}: the link's inputs decide its observable",
                        check.id
                    );
                    assert_eq!(gating.rule, gating_rule::CLEAN_LINK_UNMATCHED);
                    assert_eq!(gating.rule.verdict(), Verdict::Indeterminate);
                    assert!(gating.reason.contains("/srv/px/ld"), "{}", gating.reason);
                    fired.push(check.id);
                }
                walked += 1;
            }
        }
        assert_eq!(
            fired, FIRES,
            "the rule fires on the pinned checks, each once"
        );
        assert_eq!(
            walked,
            crate::probe::CORPUS
                .iter()
                .map(|p| p.checks.len())
                .sum::<usize>()
        );
    }

    #[test]
    fn the_compile_input_rule_withholds_the_listed_checks_and_nothing_else() {
        let corpus_checks = || crate::probe::CORPUS.iter().flat_map(|p| p.checks);
        let mut listed = 0;
        for id in COMPILE_INPUT_READINGS {
            assert!(
                corpus_checks().any(|c| c.id == *id),
                "{id} is not a corpus check"
            );
            assert!(
                !LINK_INPUT_READINGS.contains(id),
                "{id} is withheld by the link-input rule, and one stage would hide the other"
            );
            listed += 1;
        }
        let mut walked = 0;
        let mut fired = 0;
        let mut macro_channel = 0;
        for check in corpus_checks() {
            if check.channel() == Channel::Macro {
                assert!(
                    COMPILE_INPUT_READINGS.contains(&check.id),
                    "{} reads a macro, which a -D the driver adds decides",
                    check.id
                );
                macro_channel += 1;
            }
            assert!(
                compile_inputs_limitation(check, None).is_none(),
                "{}",
                check.id
            );
            // The difference fed names no header word, so the words the reason is held to
            // below are the sentence's own.
            let gating = compile_inputs_limitation(check, Some("its programs differ"));
            assert_eq!(
                gating.is_some(),
                COMPILE_INPUT_READINGS.contains(&check.id)
                    || EXCEPTION_MODEL_READINGS.contains(&check.id),
                "{}",
                check.id
            );
            if let Some(gating) = gating {
                assert_eq!(gating.rule, gating_rule::COMPILE_INPUTS_UNMATCHED);
                fired += 1;
            }
            walked += 1;
        }
        for id in EXCEPTION_MODEL_READINGS {
            assert!(
                corpus_checks().any(|c| c.id == *id),
                "{id} is not a corpus check"
            );
            assert!(
                !COMPILE_INPUT_READINGS.contains(id) && !LINK_INPUT_READINGS.contains(id),
                "{id} is withheld by the model comparison alone"
            );
        }
        assert_eq!(listed, COMPILE_INPUT_READINGS.len());
        assert_eq!(
            fired,
            listed + EXCEPTION_MODEL_READINGS.len(),
            "each listed check fired once"
        );
        assert!(macro_channel > 0, "the corpus has macro-channel checks");
        assert_eq!(
            walked,
            crate::probe::CORPUS
                .iter()
                .map(|p| p.checks.len())
                .sum::<usize>()
        );
    }

    #[test]
    fn an_observable_the_artifact_cannot_carry_is_not_applicable() {
        let check = crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks.iter())
            .find(|c| c.id == "relative-relocs")
            .expect("the corpus ships relative-relocs");

        // A fixed-address executable: the artifact the linker produces when the keyword
        // is accepted and nothing else was asked for.
        let facts = |elf_type: &str, pie: bool| -> ElfFacts {
            serde_json::from_value(serde_json::json!({
                "aarch64_bti": false, "aarch64_pac": false, "aarch64_gcs": false,
                "bind_now": false, "df_1_noopen": false, "df_1_pie": pie,
                "dt_debug": false, "dt_relr": false, "dt_soname": false, "dynamic_tags": [],
                "elf_class": 64, "elf_data": "little-endian",
                "elf_type": elf_type, "gnu_property_types": [], "gnu_relro": false,
                "gnu_stack_executable": false, "gnu_stack_present": true,
                "has_dynamic": true, "has_interp": true, "machine": "x86_64",
                "needed": [], "pie": pie, "recorded_command_line": "",
                "relro": "none", "rpath": [], "runpath": [], "sections": [],
                "self_report": "", "shared_object": false, "static_pie": false,
                "statically_linked": false, "symbol_count": 0, "textrel": false,
                "watched_symbols": {}, "x86_ibt": false, "x86_shstk": false,
            }))
            .expect("the fixture matches ElfFacts")
        };
        let fixed = facts("ET_EXEC", false);
        let gating = artifact_limitation(Verdict::Off, check, Outcome::Absent, Some(&fixed))
            .expect("a fixed-address link cannot carry DT_RELR");
        assert_eq!(gating.rule, gating_rule::ARTIFACT_CANNOT_CARRY);
        assert!(
            gating.reason.contains("position-independent"),
            "the reason names what the artifact would have to be: {}",
            gating.reason
        );

        let pie = facts("ET_DYN", true);
        assert!(
            artifact_limitation(Verdict::Off, check, Outcome::Absent, Some(&pie)).is_none(),
            "a position-independent link can carry it, so `off` is a real reading"
        );
        assert!(
            artifact_limitation(
                Verdict::Indeterminate,
                check,
                Outcome::Indeterminate,
                Some(&fixed)
            )
            .is_some(),
            "a withheld reading in an artifact that cannot carry the observable is gated"
        );

        // A detector that found the observable anyway has refuted the precondition, and
        // the measurement is what survives.
        for verdict in [Verdict::On, Verdict::Partial] {
            assert!(
                artifact_limitation(verdict, check, Outcome::Present, Some(&fixed)).is_none(),
                "{verdict:?} in an artifact the rule calls impossible refutes the rule, \
                 and the rule must not overrule it"
            );
        }
        // And the reading's outcome is what says so, because the verdict alone cannot: a
        // `present` reading whose level the scale could not grade is `indeterminate` too.
        assert!(
            artifact_limitation(
                Verdict::Indeterminate,
                check,
                Outcome::Present,
                Some(&fixed)
            )
            .is_none(),
            "a present reading withheld on its level keeps the level's reason"
        );

        // No facts, no claim.
        assert!(artifact_limitation(Verdict::Off, check, Outcome::Absent, None).is_none());
    }

    #[test]
    fn a_reading_withheld_on_its_level_keeps_its_reason_over_the_artifact_rule() {
        let check = crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks.iter())
            .find(|c| c.id == "relro")
            .expect("the corpus ships relro");
        assert!(check.levels.grade().is_some(), "relro is graded");
        let no_dynamic: ElfFacts = serde_json::from_value(serde_json::json!({
            "aarch64_bti": false, "aarch64_pac": false, "aarch64_gcs": false,
            "bind_now": null, "df_1_noopen": false, "df_1_pie": false,
            "dt_debug": false, "dt_relr": false, "dt_soname": false, "dynamic_tags": [],
            "elf_class": 64, "elf_data": "little-endian",
            "elf_type": "ET_EXEC", "gnu_property_types": [], "gnu_relro": null,
            "gnu_stack_executable": false, "gnu_stack_present": true,
            "has_dynamic": false, "has_interp": false, "machine": "x86_64",
            "needed": [], "pie": false, "recorded_command_line": "",
            "relro": null, "rpath": [], "runpath": [], "sections": [],
            "self_report": "", "shared_object": false, "static_pie": false,
            "statically_linked": true, "symbol_count": 0, "textrel": false,
            "watched_symbols": {}, "x86_ibt": false, "x86_shstk": false,
        }))
        .expect("the fixture matches ElfFacts");
        let off_scale = detection(Outcome::Present, Some("bogus"));
        let (verdict, controls) = decide(
            &off_scale,
            arm(Some(&detection(Outcome::Present, Some("full")))),
            arm(Some(&detection(Outcome::Absent, None))),
            None,
            check.levels.grade(),
        );
        assert!(controls.discriminating());
        assert_eq!(verdict, Verdict::Indeterminate);
        let level = level_gating(verdict, check, &off_scale).expect("the level rule speaks");
        assert_eq!(level.rule, gating_rule::LEVEL_OFF_SCALE);
        assert!(
            artifact_limitation(verdict, check, off_scale.outcome, Some(&no_dynamic)).is_none(),
            "the artifact rule declines a present reading, whatever the verdict"
        );
        // The same artifact with a reading that found nothing is the artifact rule's own
        // case, so the rule is shown to be live on this object.
        assert!(
            artifact_limitation(
                Verdict::Indeterminate,
                check,
                Outcome::Indeterminate,
                Some(&no_dynamic)
            )
            .is_some(),
            "an artifact with no dynamic section cannot carry RELRO"
        );
    }

    #[test]
    fn a_truncated_read_table_withholds_as_indeterminate_under_artifact_unreadable() {
        let check = |id: &str| {
            crate::probe::CORPUS
                .iter()
                .flat_map(|p| p.checks.iter())
                .find(|c| c.id == id)
                .unwrap_or_else(|| panic!("the corpus ships {id}"))
        };
        let facts = |truncations: serde_json::Value| -> ElfFacts {
            serde_json::from_value(serde_json::json!({
                "aarch64_bti": false, "aarch64_pac": false, "aarch64_gcs": false,
                "bind_now": true, "df_1_noopen": false, "df_1_pie": false,
                "dt_debug": false, "dt_relr": false, "dt_soname": false, "dynamic_tags": [],
                "elf_class": 64, "elf_data": "little-endian",
                "elf_type": "ET_EXEC", "gnu_property_types": [], "gnu_relro": true,
                "gnu_stack_executable": false, "gnu_stack_present": true,
                "has_dynamic": true, "has_interp": true, "machine": "x86_64",
                "needed": [], "pie": false, "recorded_command_line": "",
                "relro": "full", "rpath": [], "runpath": [], "sections": [],
                "self_report": "", "shared_object": false, "static_pie": false,
                "statically_linked": false, "symbol_count": 0, "textrel": false,
                "truncations": truncations,
                "watched_symbols": {}, "x86_ibt": false, "x86_shstk": false,
            }))
            .expect("the fixture matches ElfFacts")
        };

        let cut_symbols = facts(serde_json::json!([
            {"table": "symbols", "kind": "unread", "detail": ".symtab unreadable at symbol 3 of 40"}
        ]));
        let gating = truncation_limitation(check("canary-emitted"), Some(&cut_symbols))
            .expect("a check reading the symbol tables is withheld when one was cut");
        assert_eq!(gating.rule, gating_rule::ARTIFACT_UNREADABLE);
        assert!(
            gating.reason.contains("symbols table") && gating.reason.contains("symbol 3 of 40"),
            "the reason names the table and the reader's own sentence: {}",
            gating.reason
        );
        assert_eq!(
            truncated_reading(check("canary-emitted"), Some(&cut_symbols)).as_deref(),
            Some(gating.reason.as_str()),
            "the arm sentence and the gating reason are one wording"
        );
        assert!(
            truncation_limitation(check("relro"), Some(&cut_symbols)).is_none(),
            "relro reads no symbol table, so a cut one is no reason to withhold it"
        );

        let dropped_view = facts(serde_json::json!([
            {"table": "dynamic", "kind": "ignored",
             "detail": "SHT_DYNAMIC section at 0x3f0+0x20 lies outside every PT_DYNAMIC segment"}
        ]));
        assert!(
            truncation_limitation(check("relro"), Some(&dropped_view)).is_none(),
            "an ignored view was dropped for the loader's, and the facts are whole"
        );

        let cut_names = facts(serde_json::json!([
            {"table": "section-names", "kind": "unread", "detail": "section names: e_shstrndx is SHN_UNDEF"}
        ]));
        let mut examined = 0usize;
        for c in crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks.iter())
            .filter(|c| c.channel() == Channel::ElfStatic)
        {
            // `ret-protector-emitted` reads the section list itself (2026-09-30); every
            // other elf-static check reads nothing reached by section name.
            assert_eq!(
                truncation_limitation(c, Some(&cut_names)).is_some(),
                c.reads().contains(&crate::elf::ElfTable::SectionNames),
                "{}: withheld exactly when it declares section-names",
                c.id
            );
            examined += 1;
        }
        assert!(examined > 0, "no elf-static check was examined");
        let gating = truncation_limitation(check("fortify-enforced-known"), Some(&cut_names))
            .expect("the self-report is reached by section name");
        assert_eq!(gating.rule, gating_rule::ARTIFACT_UNREADABLE);

        // No facts, no claim.
        assert!(truncation_limitation(check("canary-emitted"), None).is_none());
    }

    /// An arm as `decide` receives it, with no flags: the tests here are about the
    /// verdict, and `decide_publishes_exactly_the_flags_it_was_handed` is about the flags.
    fn arm(detection: Option<&Detection>) -> ArmInput<'_> {
        ArmInput {
            detection,
            flags: Vec::new(),
            overridden: None,
        }
    }

    /// A regime arm that was required and evaluated, or `None` where none was required.
    fn regime_arm(detection: Option<&Detection>) -> Option<ArmInput<'_>> {
        detection.map(|d| arm(Some(d)))
    }

    #[test]
    fn decide_publishes_exactly_the_flags_it_was_handed() {
        const OUTCOMES: [Option<Outcome>; 4] = [
            None,
            Some(Outcome::Present),
            Some(Outcome::Absent),
            Some(Outcome::Indeterminate),
        ];
        let detection = |outcome: Outcome| Detection {
            outcome,
            level: None,
            observed: String::new(),
            rule: None,
        };
        let mut points = 0usize;
        for bare in [Outcome::Present, Outcome::Absent, Outcome::Indeterminate] {
            for positive in OUTCOMES {
                for negative in OUTCOMES {
                    for regime in OUTCOMES {
                        let b = detection(bare);
                        let p = positive.map(detection);
                        let n = negative.map(detection);
                        let r = regime.map(detection);
                        let (_, controls) = decide(
                            &b,
                            ArmInput {
                                detection: p.as_ref(),
                                flags: vec!["-sentinel-positive".to_owned()],
                                overridden: None,
                            },
                            ArmInput {
                                detection: n.as_ref(),
                                flags: vec!["-sentinel-negative".to_owned()],
                                overridden: None,
                            },
                            r.as_ref().map(|d| ArmInput {
                                detection: Some(d),
                                flags: vec!["-O2".to_owned(), "-sentinel-regime".to_owned()],
                                overridden: None,
                            }),
                            None,
                        );
                        points = points.saturating_add(1);
                        assert_eq!(controls.positive.flags, ["-sentinel-positive"]);
                        assert_eq!(controls.negative.flags, ["-sentinel-negative"]);
                        assert_eq!(
                            controls.regime_negative.is_some(),
                            r.is_some(),
                            "the regime arm is published exactly when it was handed in"
                        );
                        if let Some(arm) = controls.regime_negative {
                            assert_eq!(arm.flags, ["-O2", "-sentinel-regime"]);
                        }
                    }
                }
            }
        }
        assert_eq!(points, 3 * 4 * 4 * 4, "the whole lattice was visited");

        let b = detection(Outcome::Present);
        let p = detection(Outcome::Present);
        let n = detection(Outcome::Absent);
        let (verdict, controls) = decide(
            &b,
            arm(Some(&p)),
            arm(Some(&n)),
            Some(ArmInput {
                detection: None,
                flags: vec!["-sentinel-regime".to_owned()],
                overridden: None,
            }),
            None,
        );
        assert_eq!(verdict, Verdict::ProbeInvalid);
        assert_eq!(
            controls.withheld(),
            Some(WithheldBecause::RegimeUnevaluable),
            "a required regime arm with no detection is an unevaluable arm"
        );
        let published = controls
            .regime_negative
            .expect("the arm is published, with the flags that built it");
        assert_eq!(published.flags, ["-sentinel-regime"]);
        assert!(published.outcome.is_none());
    }

    #[test]
    fn decide_is_enumerated_over_every_combination_of_its_inputs() {
        const OUTCOMES: [Option<Outcome>; 4] = [
            None,
            Some(Outcome::Present),
            Some(Outcome::Absent),
            Some(Outcome::Indeterminate),
        ];
        let detection = |outcome: Outcome, level: Option<&str>| Detection {
            outcome,
            level: level.map(str::to_owned),
            observed: String::new(),
            rule: None,
        };
        let mut points = 0usize;
        let mut seen: std::collections::BTreeSet<&str> = std::collections::BTreeSet::new();
        for bare in [Outcome::Present, Outcome::Absent, Outcome::Indeterminate] {
            for level in GRADE_AXIS_LEVELS {
                for grade in GRADE_AXIS {
                    for positive in OUTCOMES {
                        for negative in OUTCOMES {
                            for regime in OUTCOMES {
                                let b = detection(bare, level);
                                let p = positive.map(|o| detection(o, None));
                                let n = negative.map(|o| detection(o, None));
                                let r = regime.map(|o| detection(o, None));
                                let (verdict, controls) = decide(
                                    &b,
                                    arm(p.as_ref()),
                                    arm(n.as_ref()),
                                    regime_arm(r.as_ref()),
                                    grade,
                                );
                                points = points.saturating_add(1);
                                seen.insert(verdict.as_str());

                                // The rule the whole project rests on: a measurement
                                // requires a triple that discriminated.
                                if verdict.is_measurement() {
                                    assert!(
                                        controls.discriminating(),
                                        "{verdict:?} published on a triple that did not \
                                         discriminate: {controls:?}"
                                    );
                                }
                                // And the converse, with the reason always named.
                                if !controls.discriminating() {
                                    assert_eq!(
                                        verdict,
                                        Verdict::ProbeInvalid,
                                        "a triple that did not discriminate must withhold"
                                    );
                                    assert!(
                                        controls.withheld().is_some(),
                                        "a withheld triple names why"
                                    );
                                }
                                // `off` requires the positive arm to have shown the
                                // observable and the negative arm its absence, both.
                                if verdict == Verdict::Off {
                                    assert_eq!(positive, Some(Outcome::Present));
                                    assert_eq!(negative, Some(Outcome::Absent));
                                    assert_eq!(b.outcome, Outcome::Absent);
                                }
                            }
                        }
                    }
                }
            }
        }
        assert_eq!(
            points,
            3 * GRADE_AXIS_LEVELS.len() * GRADE_AXIS.len() * 4 * 4 * 4,
            "the enumeration is complete"
        );

        // Which verdicts `decide` can reach, and which are reserved for a path that is
        // not the control triple.
        let reached: Vec<&str> = seen.iter().copied().collect();
        assert_eq!(
            reached,
            ["indeterminate", "off", "on", "partial", "probe-invalid"],
            "the triple decides these and no others"
        );
        let elsewhere = [
            // a gating rule whose premise is a fact about the toolchain
            gating_rule::Premise::ToolchainFact.verdict(),
            // a gating rule whose premise is that the question has no referent here
            gating_rule::Premise::Inapplicable.verdict(),
            // `Variant::sufficient_for`, before a detector is ever called
            Verdict::BuildFailed,
            Verdict::RunFailed,
        ];
        // The third class, an instrument limitation, reserves nothing: it publishes the
        // verdict the triple also reaches when it cannot see, which is the point of the
        // class.
        assert!(
            seen.contains(
                gating_rule::Premise::InstrumentLimitation
                    .verdict()
                    .as_str()
            ),
            "an instrument limitation publishes what the triple publishes when it cannot see"
        );
        for verdict in elsewhere {
            assert!(
                !seen.contains(verdict.as_str()),
                "{verdict:?} is reserved for a path other than the triple, and the \
                 enumeration reached it"
            );
        }
        assert_eq!(
            reached.len().saturating_add(elsewhere.len()),
            Verdict::ALL.len(),
            "every verdict in the vocabulary is either decided here or reserved above"
        );
        eprintln!("report: decide enumerated over {points} points, reaching {seen:?}");
    }
    #[test]
    fn contradicted_is_exactly_the_unpublishable_basis() {
        use crate::env::{Execution, ExecutionMode, ModeBasis, ModeEvidence, mode_basis};

        let modes = [
            ExecutionMode::Host,
            ExecutionMode::Container,
            ExecutionMode::Vm,
        ];
        let observations = [
            None,
            Some(ExecutionMode::Host),
            Some(ExecutionMode::Container),
            Some(ExecutionMode::Vm),
        ];
        let mut contradicted = 0;
        let mut clean = 0;

        for asserted in modes {
            for observed in observations {
                let basis = mode_basis(observed, asserted);
                let execution = Execution {
                    mode: asserted,
                    engine: None,
                    image: None,
                    detection: "operator-supplied via --execution".to_owned(),
                    mode_evidence: ModeEvidence {
                        basis,
                        observed,
                        observation: "fixture".to_owned(),
                    },
                    // Built as a literal rather than by widening `not_applicable`'s
                    // visibility: a test is not a reason to loosen a module boundary.
                    image_attestation: crate::env::ImageAttestation {
                        status: crate::env::AttestationStatus::NotApplicable,
                        established_by: "fixture",
                        attestation: None,
                    },
                };
                let refused = execution_mode_agrees(&execution).is_some();
                assert_eq!(
                    basis == ModeBasis::AssertedAndContradicted,
                    refused,
                    "asserted {asserted:?} with observed {observed:?}: basis {} but the \
                     consistency pass {} refuse it",
                    basis.as_str(),
                    if refused { "does" } else { "does not" }
                );
                if refused {
                    contradicted += 1;
                } else {
                    clean += 1;
                }
                assert_eq!(
                    !refused,
                    ModeBasis::PUBLISHABLE.contains(&basis),
                    "a basis is publishable exactly when no contradiction refuses the report"
                );
            }
        }

        // The frame, not just the count: a property asserted over an empty or lopsided sweep
        // would pass while examining nothing.
        assert_eq!(
            (contradicted, clean),
            (6, 6),
            "the sweep must cover 12 (asserted, observed) pairs, 6 of them contradictory"
        );
    }

    #[test]
    fn the_withholding_sets_cannot_disagree_with_the_verdict_tally() {
        use std::collections::BTreeMap;
        let counts = |pairs: &[(&str, usize)]| -> BTreeMap<String, usize> {
            pairs.iter().map(|(k, v)| ((*k).to_owned(), *v)).collect()
        };
        let coverage = |verdicts: BTreeMap<String, usize>, w: Withholding| Coverage {
            checks_expected: 0,
            checks_attempted: 0,
            checks_valid: 0,
            checks_skipped: 0,
            checks_missing: Vec::new(),
            checks_unexpected: Vec::new(),
            checks_not_applicable_here: 0,
            corpus_checks_total: 0,
            verdict_counts: verdicts,
            profile_flags_unexamined: Vec::new(),
            withholding: w,
            all_checks_attempted: false,
            all_verdicts_published: false,
            truncations: Vec::new(),
            gate: None,
        };
        let tally = || {
            counts(&[
                ("on", 8),
                ("off", 31),
                ("partial", 1),
                ("unsupported", 4),
                ("indeterminate", 3),
            ])
        };
        let set = |count: usize,
                   by_verdict: &[(&str, usize)],
                   by_rule: &[(&str, usize)],
                   no_named_cause: usize| WithholdingSet {
            count,
            by_verdict: counts(by_verdict),
            by_rule: counts(by_rule),
            by_withheld_cause: BTreeMap::new(),
            no_named_cause,
        };
        let honest = || Withholding {
            published: 40,
            earned_limitations: set(4, &[("unsupported", 4)], &[("arch-gated", 4)], 0),
            instrument_withholdings: set(3, &[("indeterminate", 3)], &[], 3),
        };
        assert!(
            withholding_agrees(&coverage(tally(), honest())).is_empty(),
            "a report whose two accounts match must not be refused"
        );

        // The failure that matters: a verdict moves from withheld to measured in one place
        // and not the other, which is how a report silently improves.
        let mut improved = honest();
        improved.published = 43;
        improved.instrument_withholdings = WithholdingSet::default();
        let fired = withholding_agrees(&coverage(tally(), improved));
        assert!(
            fired.iter().all(|c| c.rule == RULE_WITHHOLDING)
                && fired
                    .iter()
                    .any(|c| c.claims.iter().any(|claim| claim.contains("43"))),
            "the refusal names the rule and carries the edited number: {fired:?}"
        );

        // The withholding moved into the earned set with every sum kept and a rule that
        // earns a limitation beside it: the verdict is not one a limitation carries.
        let mut excused = honest();
        excused.earned_limitations = set(
            7,
            &[("unsupported", 4), ("indeterminate", 3)],
            &[("arch-gated", 7)],
            0,
        );
        excused.instrument_withholdings = WithholdingSet::default();
        assert!(!withholding_agrees(&coverage(tally(), excused)).is_empty());

        // An earned set counted under a rule whose premise is the instrument's.
        let mut unearned = honest();
        unearned.earned_limitations = set(
            4,
            &[("unsupported", 4)],
            &[("cpu-lacks-shadow-stack", 4)],
            0,
        );
        assert!(!withholding_agrees(&coverage(tally(), unearned)).is_empty());

        // A set whose verdicts do not sum to its own count, the field disagreeing with
        // itself rather than with its source.
        let mut inconsistent = honest();
        inconsistent.instrument_withholdings.count = 2;
        assert!(!withholding_agrees(&coverage(tally(), inconsistent)).is_empty());

        // And a reason list one short of the count.
        let mut unreasoned = honest();
        unreasoned.instrument_withholdings.no_named_cause = 2;
        assert!(!withholding_agrees(&coverage(tally(), unreasoned)).is_empty());

        // A verdict counted zero times, in the tally or in a set, is the absence of one.
        let mut zero_tallied = tally();
        zero_tallied.insert("probe-invalid".to_owned(), 0);
        assert!(withholding_agrees(&coverage(zero_tallied, honest())).is_empty());
        let mut zero_set = honest();
        zero_set
            .instrument_withholdings
            .by_verdict
            .insert("probe-invalid".to_owned(), 0);
        assert!(withholding_agrees(&coverage(tally(), zero_set)).is_empty());
    }
    use super::*;

    #[test]
    fn the_gate_record_is_held_to_the_observations_it_excuses() {
        let held = |check: &str, rule: gating_rule::Rule| {
            let mut o = observation(check, "-f", Channel::Runtime, rule.verdict());
            o.gating = Some(Gating {
                rule,
                arch: None,
                libc: None,
                needs_vm: false,
                reason: "fixture".to_owned(),
            });
            o
        };
        let observations = vec![
            held("a", gating_rule::NO_CHECK_ON_TARGET),
            held("b", gating_rule::FRAME_REUSE_DID_NOT_HOLD),
            held("c", gating_rule::ARCH_OUTSIDE_TABLE),
            held("d", gating_rule::MACHINE_LACKS_BTI),
            observation("e", "-f", Channel::Runtime, Verdict::ProbeInvalid),
            observation("f", "-f", Channel::Runtime, Verdict::On),
            held("g", gating_rule::NO_CHECK_ON_TARGET),
        ];
        let all: std::collections::BTreeSet<Allowance> = Allowance::ALL.into_iter().collect();
        let gate = Gate::of(&observations, all.clone());
        let excused = |checks: &[&str]| -> Vec<Excused> {
            checks
                .iter()
                .map(|c| Excused {
                    check: (*c).to_owned(),
                    rule: Allowance::NoCheckOnTarget,
                })
                .collect()
        };
        assert_eq!(gate.excused, excused(&["a", "g"]));
        assert!(
            Gate::of(&observations, std::collections::BTreeSet::new())
                .excused
                .is_empty(),
            "a gate with no rule allowed excuses nothing"
        );
        assert_eq!(
            serde_json::to_value(&gate).expect("serializes"),
            serde_json::json!({
                "allowed": ["no-check-on-target"],
                "excused": [
                    {"check": "a", "rule": "no-check-on-target"},
                    {"check": "g", "rule": "no-check-on-target"}
                ]
            })
        );
        // Both lists are written when empty.
        assert_eq!(
            serde_json::to_value(Gate::of(&[], std::collections::BTreeSet::new()))
                .expect("serializes"),
            serde_json::json!({"allowed": [], "excused": []})
        );

        let mut cov = coverage(
            &observations,
            &ids_of(&observations),
            observations.len(),
            &bare(),
            Vec::new(),
        );
        assert!(cov.gate.is_none(), "coverage() leaves the gate to measure");
        cov.gate = Some(gate.clone());
        assert!(
            coverage_agrees(&cov, &observations, &bare()).is_empty(),
            "a record derived from its own observations is not refused"
        );
        let relabelled = Gate {
            allowed: std::collections::BTreeSet::new(),
            ..gate.clone()
        };
        for edited in [
            Gate {
                excused: excused(&["a"]),
                ..gate.clone()
            },
            Gate {
                excused: excused(&["a", "b", "g"]),
                ..gate.clone()
            },
            Gate {
                excused: Vec::new(),
                ..gate
            },
            relabelled,
        ] {
            cov.gate = Some(edited.clone());
            let found = coverage_agrees(&cov, &observations, &bare());
            assert!(
                found.iter().any(|c| c.rule == RULE_COVERAGE
                    && c.claims
                        .iter()
                        .any(|x| x.starts_with("coverage.gate.excused = "))),
                "{edited:?}: {found:?}"
            );
        }
    }

    #[test]
    fn the_allowance_is_spelt_as_its_rule_and_refuses_every_other() {
        for allowance in Allowance::ALL {
            assert_eq!(
                serde_json::to_value(allowance).expect("serializes"),
                serde_json::json!(allowance.as_str())
            );
            assert_eq!(allowance.as_str().parse::<Allowance>(), Ok(allowance));
            assert_eq!(
                allowance.rule().premise,
                gating_rule::Premise::InstrumentLimitation
            );
        }
        let refused = |text: &str| text.parse::<Allowance>().expect_err(text);
        let outside = refused("arch-outside-table");
        assert!(
            outside.contains("has no allowance: the mechanism table has no row"),
            "{outside}"
        );
        for rule in [
            gating_rule::CPU_LACKS_SHADOW_STACK,
            gating_rule::MACHINE_LACKS_BTI,
            gating_rule::MACHINE_LACKS_PAC,
            gating_rule::CPU_SHOWS_NO_FPAC,
        ] {
            let line = refused(rule.id);
            assert!(line.contains("it is a machine limit"), "{line}");
        }
        let earned = refused(gating_rule::ARCH.id);
        assert!(earned.contains("needs none"), "{earned}");
        let run = refused(gating_rule::FRAME_REUSE_DID_NOT_HOLD.id);
        assert!(run.contains("could not measure"), "{run}");
        let word = refused("no-check");
        assert!(word.starts_with("no-check is not a gating rule"), "{word}");
        for line in [outside, earned, run, word] {
            assert!(
                line.ends_with("the one rule --allow takes is no-check-on-target"),
                "{line}"
            );
        }
    }

    #[test]
    fn coverage_cannot_disagree_with_the_observations_it_counts() {
        let a = || observation("a", "-Da", Channel::Macro, Verdict::On);
        let b = || observation("b", "-Db", Channel::Macro, Verdict::Off);

        let healthy_obs = vec![a(), b()];
        let healthy = coverage(&healthy_obs, &ids_of(&healthy_obs), 2, &bare(), Vec::new());
        assert!(
            coverage_agrees(&healthy, &healthy_obs, &bare()).is_empty(),
            "a block computed from its own observations must not be refused"
        );

        // One check measured twice.
        let doubled_obs = vec![a(), a()];
        let doubled = coverage(&doubled_obs, &ids_of(&doubled_obs), 2, &bare(), Vec::new());
        let fired = coverage_agrees(&doubled, &doubled_obs, &bare());
        assert!(
            fired
                .iter()
                .any(|c| c.rule == RULE_COVERAGE && c.claims.iter().any(|x| x.contains("a x2"))),
            "a repeated check id must be named: {fired:?}"
        );

        // A tally that lost a verdict, which is how a count-only check goes quiet.
        let mut lost = coverage(&healthy_obs, &ids_of(&healthy_obs), 2, &bare(), Vec::new());
        lost.verdict_counts.insert("off".to_owned(), 0);
        assert!(
            coverage_agrees(&lost, &healthy_obs, &bare())
                .iter()
                .any(|c| c
                    .claims
                    .iter()
                    .any(|x| x.contains("verdict_counts totals 1"))),
            "verdict_counts must sum to checks_attempted"
        );

        // An expected id that never came back is named, and a name that has an
        // observation cannot be in the missing list.
        let mut expected = ids_of(&healthy_obs);
        expected.insert("c".to_owned());
        let short = coverage(&healthy_obs, &expected, 3, &bare(), Vec::new());
        assert_eq!(short.checks_missing, vec!["c".to_owned()]);
        assert_eq!(short.checks_skipped, 1);
        assert!(coverage_agrees(&short, &healthy_obs, &bare()).is_empty());
        let mut lying = short.clone();
        lying.checks_missing = vec!["a".to_owned()];
        assert!(
            coverage_agrees(&lying, &healthy_obs, &bare())
                .iter()
                .any(|c| c.detail.contains("has an observation")),
            "a missing list naming an observed check is a contradiction"
        );

        // An observation the selection never asked for is the other direction.
        let narrow: std::collections::BTreeSet<String> = ["a".to_owned()].into_iter().collect();
        let surplus = coverage(&healthy_obs, &narrow, 2, &bare(), Vec::new());
        assert_eq!(surplus.checks_unexpected, vec!["b".to_owned()]);
        assert_eq!(surplus.checks_expected, 1);
        assert!(
            coverage_agrees(&surplus, &healthy_obs, &bare()).is_empty(),
            "the block records the surplus and stays consistent with itself"
        );
    }

    fn detection(outcome: Outcome, level: Option<&str>) -> Detection {
        Detection {
            outcome,
            level: level.map(ToOwned::to_owned),
            observed: "test".to_owned(),
            rule: None,
        }
    }

    #[test]
    fn whole_object_level_is_claimed_only_from_a_rung_that_established_an_absence() {
        let mut points = 0;
        let mut seen_one = 0;
        let mut seen_none = 0;
        for &ge1 in Verdict::ALL {
            for &sub in Verdict::ALL {
                for &pn in Verdict::ALL {
                    points += 1;
                    let observations = vec![
                        obs(RUNG_GE_1, Polarity::Harden, ge1, ""),
                        obs(RUNG_GE_2_SUBOBJECT, Polarity::Harden, sub, ""),
                        obs(RUNG_GE_2_PERCENT_N, Polarity::Harden, pn, ""),
                    ];
                    let Some(r) = fortify_ratchet(&observations, &FactStore::default()) else {
                        continue;
                    };
                    let establishes = |v: Verdict| matches!(v, Verdict::Off | Verdict::Unsupported);
                    match r.whole_object_level.as_deref() {
                        Some("2") => assert!(
                            sub == Verdict::On || pn == Verdict::On,
                            "level 2 without a level-2 rung firing: {ge1:?}/{sub:?}/{pn:?}"
                        ),
                        Some("1") => {
                            seen_one += 1;
                            assert!(
                                ge1 == Verdict::On && (establishes(sub) || establishes(pn)),
                                "level 1 claims subobject bounds are absent, which needs a \
                                 level-2 rung that established an absence: {ge1:?}/{sub:?}/{pn:?}"
                            );
                        }
                        Some("0") => assert!(
                            establishes(ge1),
                            "level 0 needs the level-1 rung to have established an absence: \
                             {ge1:?}/{sub:?}/{pn:?}"
                        ),
                        Some(other) => panic!("unexpected whole_object_level {other}"),
                        None => seen_none += 1,
                    }
                }
            }
        }
        assert_eq!(points, 9 * 9 * 9, "the enumeration must cover the lattice");
        assert!(
            seen_one > 0,
            "no point produced level 1; the test is vacuous"
        );
        assert!(seen_none > 0, "no point withheld; the test is vacuous");
    }

    #[test]
    fn a_subobject_bound_lost_in_the_wrapper_does_not_carry_the_ratchet_to_level_one() {
        let gated = |rule: gating_rule::Rule| {
            let mut o = obs(
                RUNG_GE_2_SUBOBJECT,
                Polarity::Harden,
                Verdict::Unsupported,
                "",
            );
            o.gating = Some(Gating {
                rule,
                arch: None,
                libc: None,
                needs_vm: false,
                reason: String::new(),
            });
            o
        };
        let whole = |sub: Observation, pn: Verdict| {
            fortify_ratchet(
                &[
                    obs(RUNG_GE_1, Polarity::Harden, Verdict::On, ""),
                    sub,
                    obs(RUNG_GE_2_PERCENT_N, Polarity::Harden, pn, ""),
                ],
                &FactStore::default(),
            )
            .expect("three rungs ran")
            .whole_object_level
        };
        let wrapper = gating_rule::SUBOBJECT_BOUND_LOST_IN_WRAPPER;
        for pn in [
            Verdict::ProbeInvalid,
            Verdict::Indeterminate,
            Verdict::BuildFailed,
            Verdict::RunFailed,
        ] {
            assert_eq!(whole(gated(wrapper), pn), None, "%n rung {pn:?}");
        }
        assert_eq!(whole(gated(wrapper), Verdict::Off).as_deref(), Some("1"));
        assert_eq!(
            whole(gated(gating_rule::LIBC_DECLARED), Verdict::ProbeInvalid).as_deref(),
            Some("1")
        );
    }

    /// [`obs`] for a check that observes a request or a marking rather than protection.
    fn obs_as(check: &str, observes: Observes, verdict: Verdict, defect: &str) -> Observation {
        let mut o = obs(check, Polarity::Harden, verdict, defect);
        o.observes = observes;
        o
    }

