    #[test]
    fn every_defect_status_is_the_one_its_verdicts_license() {
        let status_of = |status: &str, on: usize, partial: usize, off: usize, bearing: usize| {
            let mut counts = BTreeMap::new();
            for (k, v) in [("on", on), ("partial", partial), ("off", off)] {
                if v > 0 {
                    counts.insert(k.to_owned(), v);
                }
            }
            let mut coverage = BTreeMap::new();
            coverage.insert(
                "d".to_owned(),
                DefectStatus {
                    defect: crate::probe::DEFECTS[0],
                    status: status.to_owned(),
                    complete: false,
                    from_checks: (0..bearing).map(|i| format!("c{i}")).collect(),
                    verdict_counts: counts,
                },
            );
            let obs: Vec<Observation> = (0..bearing)
                .map(|i| {
                    let mut o =
                        observation(&format!("c{i}"), "-Dflag", Channel::Macro, Verdict::On);
                    o.defects = vec!["d".to_owned()];
                    o
                })
                .collect();
            defect_status_agrees(&coverage, &obs)
                .into_iter()
                .any(|c| c.claims.iter().any(|claim| claim.contains(".status")))
        };

        // (status, on, partial, off, bearing, contradiction expected)
        for (status, on, partial, off, bearing, bad) in [
            // mitigated: every bearing check produced a full `on`, and nothing less.
            ("mitigated", 2, 0, 0, 2, false),
            ("mitigated", 1, 1, 0, 2, true),
            // not-mitigated: something was decided, and none of it was protective.
            ("not-mitigated", 0, 0, 2, 2, false),
            // decided == 0 is `unknown`, not an accusation.
            ("not-mitigated", 0, 0, 0, 1, true),
            // a protective verdict present.
            ("not-mitigated", 1, 0, 0, 1, true),
            // a partial present.
            ("not-mitigated", 0, 1, 0, 1, true),
            // unknown: nothing decided at all.
            ("unknown", 0, 0, 0, 2, false),
            ("unknown", 0, 0, 1, 2, true),
            // partial: some protection, but not the whole class.
            ("partial", 1, 0, 1, 2, false),
            ("partial", 0, 1, 1, 2, false),
            // every bearing check `on` is `mitigated`, not `partial`.
            ("partial", 2, 0, 0, 2, true),
            // nothing protective at all is `not-mitigated`.
            ("partial", 0, 0, 1, 1, true),
            // a status value the vocabulary does not contain licenses nothing.
            ("invented", 1, 0, 0, 1, true),
        ] {
            assert_eq!(
                status_of(status, on, partial, off, bearing),
                bad,
                "status={status} on={on} partial={partial} off={off} bearing={bearing}"
            );
        }
    }

    #[test]
    fn each_applicability_gate_fires_on_its_own_condition() {
        use crate::env::KernelAttribution::{Assumed, Borrowed, Established};

        // A portable check is measured everywhere.
        use crate::mechanism::Outcome;
        assert_eq!(
            gate_outcome("pie", "x86_64"),
            Outcome::Measured,
            "a portable check is measured everywhere"
        );
        assert_eq!(gate_outcome("pie", "riscv64"), Outcome::Measured);
        assert_eq!(gate_outcome("gcs-macro", "aarch64"), Outcome::Measured);
        assert_eq!(gate_outcome("gcs-macro", "x86_64"), Outcome::Absent);
        assert_eq!(
            gate_outcome("cet-macro", "x86"),
            Outcome::Measured,
            "either listed name measures"
        );
        assert_eq!(gate_outcome("textrel-absent", "aarch64"), Outcome::Measured);
        assert_eq!(
            gate_outcome("linker-default-noexecstack", "aarch64"),
            Outcome::Unread
        );
        assert_eq!(
            gate_outcome("cet-macro", "outside-arch-macros"),
            Outcome::Outside
        );
        assert_eq!(gate_outcome("gcs-macro", "riscv"), Outcome::Outside);

        // The kernel gate is the conjunction of two independent facts, and neither alone
        // withholds: a check that does not depend on kernel policy is measured under a
        // borrowed kernel, and one that does is measured where whose kernel it is was
        // established.
        let assumed = Assumed {
            observation: "nothing settled it",
        };
        let rule = |needs_vm, kernel| kernel_withholding("-f", needs_vm, kernel).map(|g| g.rule);
        assert_eq!(rule(false, Borrowed), None);
        assert_eq!(rule(false, assumed), None);
        assert_eq!(rule(true, Established), None);
        assert_eq!(rule(true, Borrowed), Some(gating_rule::NEEDS_VM));
        assert_eq!(
            rule(true, assumed),
            Some(gating_rule::EXECUTION_MODE_ASSUMED)
        );
    }

    #[test]
    fn a_kernel_policy_check_is_withheld_under_a_borrowed_kernel_and_under_the_default() {
        use crate::env::KernelAttribution::{Assumed, Borrowed, Established};
        let needs = crate::probe::Gate {
            needs_vm: true,
            ..crate::probe::PORTABLE
        };
        let observation = "no runtime marker file, no /run/systemd/container, /proc/1/environ \
                           unreadable (permission denied, os error 13), the identity uid map \
                           `0 0 4294967295`, /proc/1/comm is `bash`";
        let assumed = Assumed { observation };
        let mut rows = 0;
        for (gate, kernel, expected) in [
            (&needs, Established, None),
            (&needs, Borrowed, Some(gating_rule::NEEDS_VM)),
            (&needs, assumed, Some(gating_rule::EXECUTION_MODE_ASSUMED)),
            (&crate::probe::PORTABLE, Established, None),
            (&crate::probe::PORTABLE, Borrowed, None),
            (&crate::probe::PORTABLE, assumed, None),
        ] {
            rows += 1;
            let got = gate_applicability("noexecstack-enforced", "-f", gate, kernel, "x86_64");
            match (got, expected) {
                (Applicability::Applicable, None) => {}
                (Applicability::Untrustworthy(g), Some(rule)) => {
                    assert_eq!(g.rule, rule, "{kernel:?}");
                    assert!(g.needs_vm && g.arch.is_none() && g.libc.is_none());
                    assert_eq!(g.rule.verdict(), Verdict::Indeterminate);
                    if rule == gating_rule::EXECUTION_MODE_ASSUMED {
                        assert!(
                            g.reason.contains(observation)
                                && g.reason.contains("--execution host")
                                && g.reason.contains("--execution vm"),
                            "{}",
                            g.reason
                        );
                    }
                }
                (Applicability::Applicable, Some(rule)) => {
                    panic!(
                        "{kernel:?} with needs_vm {} measured, not {}",
                        gate.needs_vm, rule.id
                    )
                }
                (_, _) => panic!(
                    "{kernel:?} with needs_vm {} read another way",
                    gate.needs_vm
                ),
            }
        }
        assert_eq!(rows, 6, "two gates by three attributions");
    }

    #[test]
    fn the_gate_names_the_check_that_reads_the_targets_answer_under_another_question() {
        use crate::env::KernelAttribution::Established;
        let decide = |id: &str, arch: &str| {
            let c = crate::probe::CORPUS
                .iter()
                .flat_map(|p| p.checks)
                .find(|c| c.id == id)
                .unwrap_or_else(|| panic!("{id} is a check"));
            gate_applicability(c.id, c.flag, &c.gate, Established, arch)
        };
        let Applicability::Unsupported(elsewhere) = decide("pac-ret-enforced", "x86_64") else {
            panic!("x86_64 answers return-address authentication with the shadow stack");
        };
        assert_eq!(elsewhere.rule, gating_rule::ARCH);
        assert_eq!(elsewhere.rule.verdict(), Verdict::Unsupported);
        assert_eq!(elsewhere.arch.as_deref(), Some("x86_64"));
        let Applicability::Unread(unread) = decide("pac-ret-enforced", "x86") else {
            panic!("no check reads the shadow stack on x86");
        };
        assert_eq!(unread.rule, gating_rule::NO_CHECK_ON_TARGET);
        assert_eq!(unread.arch, None);

        // What `--fail-on-missing` counts follows: of the gated checks on an x86_64 target,
        // `bti-enforced`, withheld, is a shortfall, and `pac-ret-enforced`, settled, is not;
        // on x86 both are.
        let short = |arch: &str| -> Vec<String> {
            shortfalls(&gated_observations_under(arch), std::iter::empty())
                .iter()
                .map(|s| s.check().to_owned())
                .filter(|c| c == "bti-enforced" || c == "pac-ret-enforced")
                .collect()
        };
        assert_eq!(short("x86_64"), ["bti-enforced"]);
        assert_eq!(short("x86"), ["bti-enforced", "pac-ret-enforced"]);
    }

    #[test]
    fn the_gate_publishes_each_table_decision_under_its_own_rule() {
        use crate::env::KernelAttribution::Established;
        let check = |id: &str| -> &'static Check {
            crate::probe::CORPUS
                .iter()
                .flat_map(|p| p.checks)
                .find(|c| c.id == id)
                .unwrap_or_else(|| panic!("{id} is a check"))
        };
        let decide = |id: &str, arch: &str| {
            let c = check(id);
            gate_applicability(c.id, c.flag, &c.gate, Established, arch)
        };

        let Applicability::Unsupported(absent) = decide("cet-macro", "aarch64") else {
            panic!("x86 CET is absent from aarch64, which answers with BTI and PAC");
        };
        assert_eq!(absent.rule, gating_rule::ARCH);
        assert_eq!(absent.arch.as_deref(), Some("aarch64"));
        assert_eq!(
            absent.reason,
            "-fcf-protection=full applies to [\"x86_64\", \"x86\"]; this build targets aarch64",
            "the sentence arch-gated published before the table, to the byte"
        );

        let Applicability::Unread(own) = decide("linker-default-noexecstack", "aarch64") else {
            panic!(
                "PT_GNU_STACK exists on aarch64 and linker-default-noexecstack has no \
                 construction for it"
            );
        };
        assert_eq!(own.rule, gating_rule::NO_CHECK_ON_TARGET);
        assert_eq!(own.rule.verdict(), Verdict::Indeterminate);
        assert_eq!(own.arch, None, "chard's limit, not the target's");
        for word in ["aarch64", "PT_GNU_STACK", "no check reads it there"] {
            assert!(own.reason.contains(word), "{word}: {}", own.reason);
        }

        let Applicability::Unread(sibling) = decide("shadow-stack-enforced", "aarch64") else {
            panic!("aarch64 answers shadow-stack enforcement with GCS, which no check reads");
        };
        assert_eq!(sibling.rule, gating_rule::NO_CHECK_ON_TARGET);
        assert_eq!(sibling.arch, None);
        for word in [
            "aarch64",
            "Guarded Control Stack",
            "which no check reads",
            "FEAT_GCS",
        ] {
            assert!(sibling.reason.contains(word), "{word}: {}", sibling.reason);
        }

        let Applicability::Unread(x86) = decide("zero-call-used-regs", "x86") else {
            panic!(
                "the clearing exists on x86 and the check's pattern search reads x86_64 and aarch64"
            );
        };
        assert_eq!(x86.rule, gating_rule::NO_CHECK_ON_TARGET);
        assert!(x86.reason.contains("xor %edx,%edx"), "{}", x86.reason);

        let Applicability::Unread(outside) = decide("cet-macro", "riscv64") else {
            panic!("riscv64 has no row");
        };
        assert_eq!(outside.rule, gating_rule::ARCH_OUTSIDE_TABLE);
        assert_eq!(outside.rule.verdict(), Verdict::Indeterminate);
        assert_eq!(outside.arch, None);
        for word in ["riscv64", "no row", "x86 CET"] {
            assert!(outside.reason.contains(word), "{word}: {}", outside.reason);
        }

        assert!(matches!(
            decide("cet-macro", "x86_64"),
            Applicability::Applicable
        ));
        assert!(matches!(
            decide("pie", "riscv64"),
            Applicability::Applicable
        ));
    }

    #[test]
    fn the_withholdings_say_what_the_check_is_constructed_for() {
        use crate::env::KernelAttribution::Established;
        let check = |id: &str| -> &'static Check {
            crate::probe::CORPUS
                .iter()
                .flat_map(|p| p.checks)
                .find(|c| c.id == id)
                .unwrap_or_else(|| panic!("{id} is a check"))
        };
        let decide = |id: &str, arch: &str| {
            let c = check(id);
            gate_applicability(c.id, c.flag, &c.gate, Established, arch)
        };

        // The flag applies to the target, which is why the mechanism is there; `arch-gated`
        // keeps its sentence, true where the mechanism is absent.
        for (id, arch) in [
            ("linker-default-noexecstack", "aarch64"),
            ("shadow-stack-enforced", "aarch64"),
            ("shadow-stack-enforced", "x86"),
            ("ubsan-trap-mode", "x86"),
            ("zero-call-used-regs", "x86"),
            ("cet-macro", "riscv64"),
        ] {
            let (Applicability::Unread(g) | Applicability::Unsupported(g)) = decide(id, arch)
            else {
                panic!("{id} on {arch} is withheld");
            };
            assert_ne!(g.rule, gating_rule::ARCH, "{id} on {arch}");
            assert!(
                g.reason.starts_with(&format!(
                    "chard's check of {} is constructed for ",
                    check(id).flag
                )) && !g.reason.contains(" applies to "),
                "{id} on {arch}: {}",
                g.reason
            );
        }
        // Each says nothing of the target its own witness contradicts: Linux enforces no shadow
        // stack for a 32-bit program, and ld.bfd writes no PT_GNU_STACK for an aarch64 object
        // that carries no note.
        let Applicability::Unread(ss) = decide("shadow-stack-enforced", "x86") else {
            panic!("shadow-stack-enforced is unread on x86");
        };
        assert!(!ss.reason.contains("the kernel enforces"), "{}", ss.reason);
        let Applicability::Unread(stack) = decide("linker-default-noexecstack", "aarch64") else {
            panic!("linker-default-noexecstack is unread on aarch64");
        };
        assert!(
            stack
                .reason
                .contains("which has the linker's choice of stack permission"),
            "{}",
            stack.reason
        );
    }

    #[test]
    fn a_contradicted_target_s_withheld_checks_are_not_out_of_reach() {
        let mut measured = observation("a", "-Da", Channel::Macro, Verdict::On);
        measured.controls = Some(Controls {
            positive: ControlArm {
                flags: Vec::new(),
                outcome: Some(Outcome::Present),
                detail: None,
                build: None,
                run: None,
                macro_source: None,
                macro_dump: None,
                decoded: None,
                overridden: None,
            },
            negative: ControlArm {
                flags: Vec::new(),
                outcome: Some(Outcome::Absent),
                detail: None,
                build: None,
                run: None,
                macro_source: None,
                macro_dump: None,
                decoded: None,
                overridden: None,
            },
            regime_negative: None,
            discrimination: Discrimination::Discriminating,
        });
        let withheld = |check: &str, rule: gating_rule::Rule| {
            let mut o = observation(check, "-mflag", Channel::Macro, rule.verdict());
            o.gating = Some(Gating {
                rule,
                arch: Some("x86_64".to_owned()),
                libc: None,
                needs_vm: false,
                reason: "forged".to_owned(),
            });
            o
        };
        let obs = vec![
            measured,
            withheld("gcs-macro", gating_rule::ARCH),
            withheld("branch-protection-macro", gating_rule::ARCH),
            withheld("cet-macro", gating_rule::TARGET_CONTRADICTED),
            withheld("cet-marked", gating_rule::TARGET_CONTRADICTED),
            withheld("cet-marked-object", gating_rule::TARGET_CONTRADICTED),
            withheld("textrel-absent", gating_rule::TARGET_ABI_CONTRADICTED),
        ];
        let fed = obs.len();
        let cov = coverage(&obs, &ids_of(&obs), fed, &bare(), Vec::new());
        assert_eq!(
            cov.checks_not_applicable_here, 2,
            "only the arch-gated two are out of reach"
        );
        let w = &cov.withholding;
        assert_eq!(w.earned_limitations.count, 2, "{w:?}");
        assert_eq!(w.instrument_withholdings.count, 4, "{w:?}");
        assert_eq!(
            w.published + w.earned_limitations.count + w.instrument_withholdings.count,
            fed,
            "every observation fed lands in one bucket: {w:?}"
        );
        assert!(!cov.all_verdicts_published);
        // The count and the earned limitations' arch-gated tally are one fact, held both
        // ways by the coverage rule: a count of every gating naming an `arch`, six, is refused.
        assert!(not_applicable_disagrees(&cov).is_none());
        let mut forged = cov.clone();
        forged.checks_not_applicable_here = 6;
        let (claims, _) = not_applicable_disagrees(&forged).expect("a forged count is refused");
        assert!(claims[1].ends_with("= 2"), "{claims:?}");
        forged.checks_not_applicable_here = 1;
        assert!(
            not_applicable_disagrees(&forged).is_some(),
            "a count below the tally is refused too"
        );
        let lines = shortfalls(&obs, obs.iter().map(|o| o.check.as_str()));
        let named: Vec<&str> = lines.iter().map(Shortfall::check).collect();
        assert_eq!(
            named,
            [
                "cet-macro",
                "cet-marked",
                "cet-marked-object",
                "textrel-absent"
            ],
            "each withheld check is a --fail-on-missing line, and no arch-gated one is"
        );
    }

    #[test]
    fn a_mechanism_no_check_reads_here_is_a_missing_measurement() {
        let arm = |outcome: Outcome| ControlArm {
            flags: Vec::new(),
            outcome: Some(outcome),
            detail: None,
            build: None,
            run: None,
            macro_source: None,
            macro_dump: None,
            decoded: None,
            overridden: None,
        };
        let mut measured = observation("a", "-Da", Channel::Macro, Verdict::On);
        measured.controls = Some(Controls {
            positive: arm(Outcome::Present),
            negative: arm(Outcome::Absent),
            regime_negative: None,
            discrimination: Discrimination::Discriminating,
        });
        let check = crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks)
            .find(|c| c.id == "linker-default-noexecstack")
            .expect("linker-default-noexecstack is a check");
        let Applicability::Unread(gating) = gate_applicability(
            check.id,
            check.flag,
            &check.gate,
            crate::env::KernelAttribution::Established,
            "aarch64",
        ) else {
            panic!("linker-default-noexecstack is unread on aarch64");
        };
        let mut unread = observation(
            "linker-default-noexecstack",
            check.flag,
            Channel::ElfStatic,
            gating.rule.verdict(),
        );
        unread.gating = Some(gating);
        let obs = vec![measured, unread];
        let cov = coverage(&obs, &ids_of(&obs), 2, &bare(), Vec::new());
        assert_eq!(
            cov.checks_not_applicable_here, 0,
            "unread is not out of reach"
        );
        assert_eq!(
            (
                cov.withholding.earned_limitations.count,
                cov.withholding.instrument_withholdings.count
            ),
            (0, 1),
            "the unread check is the instrument's"
        );
        assert!(!cov.all_verdicts_published, "indeterminate is not settled");
    }

    #[test]
    fn the_derived_helpers_hold_at_their_boundaries() {
        use std::time::{Duration, UNIX_EPOCH};

        // `grade_level` at its edges: no grade reads nothing, and an ask off its own
        // scale puts every reading off the scale rather than meeting by accident.
        assert_eq!(grade_level(None, Some("anything")), None);
        assert_eq!(grade_level(None, None), None);
        let misspelled = Grade {
            scale: crate::probe::Scale::Ordered(&["basic", "strong", "all"]),
            recommended: "stong",
            ungraded: &[],
        };
        assert_eq!(
            grade_level(Some(&misspelled), Some("all")),
            Some(Grading::OffScale),
            "an ask that is not on its scale grades nothing"
        );

        // `family`: the disjunction is what puts both spellings in one group.
        assert_eq!(family("-fPIE"), "pie");
        assert_eq!(
            family("-fPIC (no text relocations)"),
            "-fPIC (no text relocations)"
        );
        assert_eq!(family("-ftrapv (libgcc helper)"), "trapv");
        assert_eq!(unqualified("-fPIC (shared link)"), "-fPIC");
        assert_eq!(unqualified("-fPIC"), "-fPIC");
        assert_eq!(family("-pie"), "pie");
        assert_eq!(family("-D_FORTIFY_SOURCE=3"), "fortify");
        assert_eq!(family("-fno-ret-protector"), family("-fret-protector"));
        assert_eq!(family("-fno-exceptions"), family("-fexceptions"));
        assert_eq!(
            family("-fsanitize=undefined"),
            family("-fsanitize-trap=undefined")
        );
        assert_eq!(
            family("-fno-sanitize-trap=undefined"),
            family("-fsanitize-trap=undefined")
        );
        assert_eq!(
            family("-fsanitize-undefined-trap-on-error"),
            family("-fsanitize-trap=undefined")
        );
        assert_ne!(
            family("-fsanitize=address"),
            family("-fsanitize-trap=undefined")
        );
        assert_eq!(family("-fexceptions (emitted)"), family("-fexceptions"));
        assert_eq!(family("-fnon-call-exceptions"), family("-fexceptions"));
        assert_eq!(family("-fno-trapv"), family("-ftrapv"));
        assert_eq!(family("-fplt"), family("-fno-plt"));
        assert_eq!(family("-ftrapv (libgcc helper)"), family("-ftrapv"));
        assert_ne!(family("-fwrapv"), family("-ftrapv"));
        assert_eq!(family("-fignore-exceptions"), family("-fexceptions"));
        assert_ne!(
            family("-fasynchronous-unwind-tables"),
            family("-fexceptions")
        );

        // `iso8601_utc`: two fixed points, one of them a leap day.
        assert_eq!(iso8601_utc(UNIX_EPOCH), "1970-01-01T00:00:00Z");
        assert_eq!(
            iso8601_utc(UNIX_EPOCH + Duration::from_secs(1_709_164_800)),
            "2024-02-29T00:00:00Z",
            "a leap day, which is what the era arithmetic is for"
        );
        assert_eq!(
            iso8601_utc(UNIX_EPOCH + Duration::from_secs(1_735_689_599)),
            "2024-12-31T23:59:59Z",
            "the last second of a leap year"
        );
        // Each date takes a different branch of the civil-calendar arithmetic.
        for (secs, want) in [
            (951_782_400_u64, "2000-02-29T00:00:00Z"),
            (951_868_800, "2000-03-01T00:00:00Z"),
            (4_107_542_400, "2100-03-01T00:00:00Z"),
            (4_107_456_000, "2100-02-28T00:00:00Z"),
            (1_000_000_000, "2001-09-09T01:46:40Z"),
            (86_399, "1970-01-01T23:59:59Z"),
            (86_400, "1970-01-02T00:00:00Z"),
        ] {
            assert_eq!(
                iso8601_utc(UNIX_EPOCH + Duration::from_secs(secs)),
                want,
                "epoch second {secs}"
            );
        }
    }

    #[test]
    fn a_runtime_arm_tells_a_failed_run_from_a_failed_build() {
        let blank = || Variant {
            macros: BTreeMap::new(),
            macros_preprocessor: BTreeMap::new(),
            macro_source: "preprocessor",
            macro_dump: None,
            elf: None,
            build: None,
            run: None,
            run_error: None,
            elf_error: None,
            unwitnessed: None,
            artifact: None,
            structured: None,
            workdir: None,
        };
        let built_record = || BuildRecord {
            argv: vec!["cc".to_owned()],
            dropped_flags: Vec::new(),
            exit_status: 0,
            stdout: String::new(),
            stderr: String::new(),
            duration_ms: 1,
            artifact_sha256: Some("0".repeat(64)),
            stdout_sha256: None,
            stdout_unterminated: false,
        };
        let variant = |run_error: bool, built: bool| {
            let mut v = blank();
            if run_error {
                v.run_error = Some("could not spawn".to_owned());
            }
            if built {
                v.build = Some(built_record());
            }
            v.sufficient_for(Channel::Runtime)
        };

        assert_eq!(variant(true, false), Err(Verdict::RunFailed));
        assert_eq!(
            variant(false, true),
            Err(Verdict::RunFailed),
            "a build that succeeded and produced no run is a run failure, whether or not \
             the spawn error survived"
        );
        assert_eq!(
            variant(false, false),
            Err(Verdict::BuildFailed),
            "no artifact and no error is the build having failed"
        );

        let mut ran = blank();
        ran.run = Some(RunRecord {
            argv: vec!["probe".to_owned()],
            exit_status: 0,
            signal: None,
            stdout: String::new(),
            stderr: String::new(),
            timed_out: false,
            deadline_ms: None,
            output_error: None,
            output_truncated: false,
            duration_ms: 1,
            environment: None,
        });
        assert_eq!(ran.sufficient_for(Channel::Runtime), Ok(()));
    }

    #[test]
    fn either_level_two_rung_alone_moves_the_ratchet() {
        let rung = |check: &str, verdict: Verdict| {
            let mut o = observation(check, "-D_FORTIFY_SOURCE=2", Channel::Runtime, verdict);
            o.level = None;
            o
        };
        let level_of = |obs: Vec<Observation>| {
            fortify_ratchet(&obs, &FactStore::default()).and_then(|r| r.whole_object_level)
        };

        // Rung 1 on, then each level-2 rung alone.
        let base = || rung(RUNG_GE_1, Verdict::On);
        assert_eq!(
            level_of(vec![base(), rung(RUNG_GE_2_SUBOBJECT, Verdict::On)]),
            Some("2".to_owned()),
            "the subobject rung alone establishes level 2"
        );
        assert_eq!(
            level_of(vec![base(), rung(RUNG_GE_2_PERCENT_N, Verdict::On)]),
            Some("2".to_owned()),
            "and so does the %n rung, through its own code path"
        );

        // And on the absence side: rung 1 fired, either level-2 rung demonstrably absent.
        assert_eq!(
            level_of(vec![base(), rung(RUNG_GE_2_SUBOBJECT, Verdict::Off)]),
            Some("1".to_owned()),
            "one rung demonstrating absence settles the level below"
        );
        assert_eq!(
            level_of(vec![base(), rung(RUNG_GE_2_PERCENT_N, Verdict::Off)]),
            Some("1".to_owned())
        );
    }

    #[test]
    fn the_completeness_flags_need_every_conjunct() {
        let corpus_total = crate::probe::total_checks();
        // Measured *and* validated: `checks_valid` counts observations whose triple
        // discriminated, so an observation with no controls is attempted and not valid.
        let all_on = |n: usize| -> Vec<Observation> {
            (0..n)
                .map(|i| {
                    let mut o =
                        observation(&format!("c{i}"), "-Dflag", Channel::Macro, Verdict::On);
                    o.controls = Some(Controls {
                        positive: ControlArm {
                            flags: Vec::new(),
                            outcome: Some(Outcome::Present),
                            detail: None,
                            build: None,
                            run: None,
                            macro_source: None,
                            macro_dump: None,
                            decoded: None,
                            overridden: None,
                        },
                        negative: ControlArm {
                            flags: Vec::new(),
                            outcome: Some(Outcome::Absent),
                            detail: None,
                            build: None,
                            run: None,
                            macro_source: None,
                            macro_dump: None,
                            decoded: None,
                            overridden: None,
                        },
                        regime_negative: None,
                        discrimination: Discrimination::Discriminating,
                    });
                    o
                })
                .collect()
        };

        // Everything attempted, everything valid, every verdict a measurement.
        let complete = coverage(
            &all_on(corpus_total),
            &numbered_ids(corpus_total),
            corpus_total,
            &bare(),
            Vec::new(),
        );
        assert!(complete.all_checks_attempted);
        assert!(complete.all_verdicts_published);

        // One check short: attempted != corpus_total, and both flags must fall with it.
        let short = coverage(
            &all_on(corpus_total - 1),
            &numbered_ids(corpus_total),
            corpus_total,
            &bare(),
            Vec::new(),
        );
        assert!(!short.all_checks_attempted);
        assert_eq!(short.withholding.instrument_withholdings.count, 0);
        assert!(
            !short.all_verdicts_published,
            "a run that skipped a check has not published every verdict, whatever the ones \
             it did publish say"
        );

        // Everything attempted, one verdict withheld behind a triple that discriminated:
        // nothing may claim the report is complete.
        let mut withheld = all_on(corpus_total);
        withheld[0].verdict = Verdict::Indeterminate;
        let partial = coverage(
            &withheld,
            &numbered_ids(corpus_total),
            corpus_total,
            &bare(),
            Vec::new(),
        );
        assert!(partial.all_checks_attempted);
        assert!(
            !partial.all_verdicts_published,
            "an indeterminate verdict is not a published measurement"
        );

        // And one triple that did not discriminate: every check was attempted, and the
        // `probe-invalid` is the instrument's, counted under its cause.
        let mut one_invalid = all_on(corpus_total);
        if let Some(controls) = one_invalid[0].controls.as_mut() {
            controls.discrimination = Discrimination::Withheld(WithheldBecause::PositiveSilent);
        }
        one_invalid[0].verdict = Verdict::ProbeInvalid;
        let unvalidated = coverage(
            &one_invalid,
            &numbered_ids(corpus_total),
            corpus_total,
            &bare(),
            Vec::new(),
        );
        assert!(
            unvalidated.all_checks_attempted,
            "every check was attempted"
        );
        assert_eq!(unvalidated.checks_valid, corpus_total - 1);
        assert_eq!(
            unvalidated
                .withholding
                .instrument_withholdings
                .by_withheld_cause
                .get("positive-silent"),
            Some(&1)
        );
        assert!(!unvalidated.all_verdicts_published);
    }

    #[test]
    fn every_unpublished_verdict_is_named_once() {
        let n = 4;
        let ids = numbered_ids(n);
        let corpus = || ids.iter().map(String::as_str);
        // The limitation the rule earns, whichever of the two its premise reserves.
        let gated = || {
            let mut o = observation("c?", "-Dflag", Channel::Macro, gating_rule::ARCH.verdict());
            o.gating = Some(Gating {
                rule: gating_rule::ARCH,
                arch: Some("aarch64".to_owned()),
                libc: None,
                needs_vm: false,
                reason: "an aarch64 check on another target".to_owned(),
            });
            o
        };
        let settled = |i: usize| {
            let mut o = if i == 3 {
                gated()
            } else {
                observation("c?", "-Dflag", Channel::Macro, Verdict::On)
            };
            o.check = format!("c{i}");
            o
        };
        let agrees = |obs: &[Observation]| {
            let found = shortfalls(obs, corpus());
            let published = coverage(obs, &ids, n, &bare(), Vec::new()).all_verdicts_published;
            assert_eq!(
                found.is_empty(),
                published,
                "the lines and the field disagree: {found:?}"
            );
            found.iter().map(ToString::to_string).collect::<Vec<_>>()
        };

        let whole: Vec<Observation> = (0..n).map(settled).collect();
        assert!(agrees(&whole).is_empty(), "a settled run names nothing");

        // Each half alone: one verdict withheld over a whole run, and one check missing
        // from a run that settled the rest.
        let mut one = whole.clone();
        one[0].verdict = Verdict::Indeterminate;
        assert_eq!(
            agrees(&one),
            ["c0: indeterminate; the report records no reason beside it"]
        );
        // The detector's own reading is the reason where no rule or triple gives one.
        one[0].evidence.observed = Some("the detector's reading".to_owned());
        assert_eq!(agrees(&one), ["c0: indeterminate: the detector's reading"]);
        let short: Vec<Observation> = whole.iter().skip(1).cloned().collect();
        assert_eq!(agrees(&short), ["c0: not attempted"]);

        let mut withheld = whole.clone();
        withheld[2].verdict = Verdict::ProbeInvalid;
        withheld[2].controls = Some(Controls {
            positive: ControlArm {
                flags: Vec::new(),
                outcome: Some(Outcome::Absent),
                detail: None,
                build: None,
                run: None,
                macro_source: None,
                macro_dump: None,
                decoded: None,
                overridden: None,
            },
            negative: ControlArm {
                flags: Vec::new(),
                outcome: Some(Outcome::Absent),
                detail: None,
                build: None,
                run: None,
                macro_source: None,
                macro_dump: None,
                decoded: None,
                overridden: None,
            },
            regime_negative: None,
            discrimination: Discrimination::Withheld(WithheldBecause::PositiveSilent),
        });
        withheld[0].verdict = Verdict::Indeterminate;
        // The limitation with no rule attached: unsettled, and said as such.
        withheld[3].gating = None;
        // And one check never handed in, which sorts among the rest by id.
        withheld.remove(1);
        assert_eq!(
            agrees(&withheld),
            [
                "c0: indeterminate; the report records no reason beside it",
                "c1: not attempted",
                format!(
                    "c2: probe-invalid: {} [controls.withheld_because positive-silent]",
                    WithheldBecause::PositiveSilent.sentence()
                )
                .as_str(),
                format!(
                    "c3: {} without a gating rule that earns it",
                    gating_rule::ARCH.verdict().as_str()
                )
                .as_str(),
            ]
        );
    }

    #[test]
    fn the_shortfalls_agree_with_the_gate_for_every_verdict_and_rule() {
        let ids = numbered_ids(1);
        let mut pairs = 0_usize;
        for verdict in Verdict::ALL.iter().copied() {
            for rule in std::iter::once(None).chain(gating_rule::ALL.iter().copied().map(Some)) {
                let mut o = observation("c0", "-Dflag", Channel::Macro, verdict);
                o.gating = rule.map(|rule| Gating {
                    rule,
                    arch: None,
                    libc: None,
                    needs_vm: false,
                    reason: "a gating rule".to_owned(),
                });
                let obs = [o];
                let found = shortfalls(&obs, ids.iter().map(String::as_str));
                let cov = coverage(&obs, &ids, 1, &bare(), Vec::new());
                let published = cov.all_verdicts_published;
                assert_eq!(
                    found.is_empty(),
                    published,
                    "{} beside {:?}: {found:?}",
                    verdict.as_str(),
                    rule.map(|r| r.id)
                );
                // An oracle written from the premise classes alone, apart from `Standing`
                // and `is_earned_limitation`: a measurement settles, `unsupported` beside a
                // toolchain fact and `not-applicable` beside an inapplicable premise settle,
                // and nothing else does.
                let premise = rule.map(|r| r.premise);
                let settles = match verdict {
                    Verdict::On | Verdict::Off | Verdict::Partial => true,
                    Verdict::Unsupported => premise == Some(gating_rule::Premise::ToolchainFact),
                    Verdict::NotApplicable => premise == Some(gating_rule::Premise::Inapplicable),
                    _ => false,
                };
                assert_eq!(
                    published,
                    settles,
                    "{} beside {:?}",
                    verdict.as_str(),
                    rule.map(|r| r.id)
                );
                let w = &cov.withholding;
                assert_eq!(
                    (
                        w.instrument_withholdings.count,
                        w.earned_limitations.count,
                        w.published
                    ),
                    if !settles {
                        (1, 0, 0)
                    } else if verdict.is_measurement() {
                        (0, 0, 1)
                    } else {
                        (0, 1, 0)
                    },
                    "{} beside {:?}",
                    verdict.as_str(),
                    rule.map(|r| r.id)
                );
                assert!(
                    withholding_agrees(&cov).is_empty()
                        && withholding_split_disagrees(&cov, &obs).is_none()
                        && completeness_flag_disagrees(&cov).is_none(),
                    "the block measure derives agrees with every statement over it"
                );
                if let Some(rule) = rule {
                    assert_eq!(
                        gating_rule::by_id(rule.id).map(|r| (r.id, r.premise)),
                        Some((rule.id, rule.premise)),
                        "every rule is found by its id"
                    );
                }
                if let (Some(rule), [line]) = (rule, found.as_slice()) {
                    let text = line.to_string();
                    assert!(text.contains(rule.id), "the line names its rule: {text}");
                    if verdict.is_earned_limitation() {
                        assert_eq!(
                            text,
                            format!(
                                "c0: {} under gating rule {}, which does not earn it",
                                verdict.as_str(),
                                rule.id
                            )
                        );
                    }
                }
                pairs += 1;
            }
        }
        assert_eq!(pairs, Verdict::ALL.len() * (gating_rule::ALL.len() + 1));
    }

    #[test]
    fn the_identity_statements_run_over_an_older_block() {
        let older = serde_json::json!({"observations": [],
            "coverage": {"checks_expected": 0, "checks_valid": 0, "checks_attempted": 0, "corpus_checks_total": 0,
                         "verdict_counts": {}, "all_verdicts_published": true,
                         "withholding": {"published": 0, "withheld": 0,
                                         "percent_withheld": 0.0}}});
        // Each identity statement is refused beside the older finding.
        let mut ids = older.clone();
        ids["observations"] = serde_json::json!([{"check": "pie", "verdict": "off",
                                                  "observes": "protection",
                                                  "polarity": "harden"}]);
        let coverage = &mut ids["coverage"];
        for (key, value) in [
            ("checks_expected", serde_json::json!(0)),
            ("checks_attempted", serde_json::json!(1)),
            ("corpus_checks_total", serde_json::json!(1)),
            ("verdict_counts", serde_json::json!({"off": 1})),
            ("checks_unexpected", serde_json::json!(["pie"])),
            ("all_checks_attempted", serde_json::json!(true)),
            ("checks_missing", serde_json::json!(["pie"])),
            ("checks_skipped", serde_json::json!(2)),
            ("checks_valid", serde_json::json!(1)),
        ] {
            coverage[key] = value;
        }
        let read = reread_contradictions(&ids);
        assert_eq!(read.older.len(), 1, "{read:?}");
        let coverage_claims: Vec<&str> = read
            .contradictions
            .iter()
            .filter(|c| c.rule == RULE_COVERAGE)
            .map(|c| c.claims[0].as_str())
            .collect();
        for named in [
            "coverage.all_checks_attempted = true",
            "coverage.checks_skipped = 2",
            "coverage.checks_missing names pie",
            "coverage.checks_valid = 1",
            "coverage.all_verdicts_published = true",
        ] {
            assert!(
                coverage_claims.contains(&named),
                "{named}: {coverage_claims:?}"
            );
        }
    }

    #[test]
    fn an_older_withholding_block_is_named_as_older_on_read() {
        let older = serde_json::json!({"observations": [],
            "coverage": {"checks_expected": 0, "checks_valid": 0, "checks_attempted": 0, "corpus_checks_total": 0,
                         "verdict_counts": {}, "all_verdicts_published": true,
                         "withholding": {"published": 0, "withheld": 0,
                                         "percent_withheld": 0.0}}});
        let read = reread_contradictions(&older);
        // Nothing of `coverage` but the older finding; the bare report's missing
        // `environment` is its own finding.
        assert!(
            !read.unreadable.iter().any(|u| u.contains("`coverage`")),
            "{read:?}"
        );
        assert!(read.contradictions.is_empty(), "{read:?}");
        assert_eq!(read.older.len(), 1, "{read:?}");
        // An older finding alone is still a finding: the refusal keys on it.
        assert!(!read.is_empty());

        // The older block set aside, the rest of `coverage` is still held to the
        // observations: a tally edited to disagree with them is a contradiction beside the
        // older finding, so the report does not read as older alone.
        let mut lying = older.clone();
        lying["coverage"]["verdict_counts"] = serde_json::json!({"off": 1});
        let read = reread_contradictions(&lying);
        assert_eq!(read.older.len(), 1, "{read:?}");
        assert!(
            read.contradictions.iter().any(|c| c.rule == RULE_COVERAGE),
            "{read:?}"
        );

        // The completeness flag, where the counts decide it without the block: a check
        // attempted short of the corpus makes `all_verdicts_published` false whatever was
        // withheld.
        let mut short = older.clone();
        short["coverage"]["corpus_checks_total"] = serde_json::json!(1);
        let read = reread_contradictions(&short);
        assert!(
            read.contradictions.iter().any(|c| c.rule == RULE_COVERAGE
                && c.claims.iter().any(|claim| claim.contains("= not read"))),
            "{read:?}"
        );
        let mut honest_short = short;
        honest_short["coverage"]["all_verdicts_published"] = serde_json::json!(false);
        assert!(
            reread_contradictions(&honest_short)
                .contradictions
                .is_empty(),
            "the flag false beside a short count agrees"
        );
        let mut whole = older.clone();
        whole["coverage"]["all_verdicts_published"] = serde_json::json!(false);
        assert!(
            reread_contradictions(&whole).contradictions.is_empty(),
            "with every check attempted the flag turns on the instrument count, which the \
             older block does not give"
        );

        // A block in today's shape that also carries `withheld` is today's block edited, not
        // the older one: unreadable, never older.
        let mut stray = serde_json::json!({"observations": [],
            "coverage": {"checks_expected": 0, "checks_valid": 0, "checks_attempted": 0, "corpus_checks_total": 0,
                         "verdict_counts": {}, "all_verdicts_published": true,
                         "withholding": {"published": 0, "withheld": 0,
                             "earned_limitations": {"count": 0, "no_named_cause": 0},
                             "instrument_withholdings": {"count": 0, "no_named_cause": 0}}}});
        let read = reread_contradictions(&stray);
        assert!(read.older.is_empty(), "{read:?}");
        assert!(
            read.unreadable.iter().any(|u| u.contains("`coverage`")),
            "{read:?}"
        );
        stray["coverage"]["withholding"]
            .as_object_mut()
            .expect("an object")
            .remove("withheld");
        assert!(
            !reread_contradictions(&stray)
                .unreadable
                .iter()
                .any(|u| u.contains("`coverage`")),
            "the same block without `withheld` reads"
        );

        let mut damaged = older.clone();
        damaged["coverage"]["checks_attempted"] = serde_json::json!("many");
        let read = reread_contradictions(&damaged);
        assert_eq!(read.older.len(), 1, "{read:?}");
        assert_eq!(
            read.unreadable
                .iter()
                .filter(|u| u.contains("`coverage`"))
                .count(),
            1,
            "{read:?}"
        );

        let mut edited = older;
        edited["coverage"]["withholding"] = serde_json::json!({"published": 0});
        let read = reread_contradictions(&edited);
        assert!(
            !read.unreadable.is_empty(),
            "an older withholding block is named on reread"
        );
        assert!(read.older.is_empty(), "{read:?}");
    }

    #[test]
    fn an_older_withholding_block_keeps_its_gate_record_held() {
        let older = serde_json::json!({"observations": [],
            "coverage": {"checks_expected": 0, "checks_valid": 0, "checks_attempted": 0, "corpus_checks_total": 0,
                         "verdict_counts": {}, "all_verdicts_published": true,
                         "withholding": {"published": 0, "withheld": 0,
                                         "percent_withheld": 0.0}}});

        let mut gated = older.clone();
        gated["coverage"]["gate"] = serde_json::json!({"allowed": ["no-check-on-target"],
            "excused": [{"check": "bti-enforced", "rule": "no-check-on-target"}]});
        let read = reread_contradictions(&gated);
        assert!(
            read.contradictions.iter().any(|c| c.rule == RULE_COVERAGE
                && c.claims
                    .first()
                    .is_some_and(|x| x.starts_with("coverage.gate.excused = "))),
            "{read:?}"
        );
    }

    /// An observation of `id` carrying `verdict` under the gating `rule`.
    fn gated_by(id: &str, verdict: Verdict, rule: gating_rule::Rule) -> Observation {
        let mut o = observation(id, "-Dflag", Channel::Macro, verdict);
        o.gating = Some(Gating {
            rule,
            arch: None,
            libc: None,
            needs_vm: false,
            reason: "r".to_owned(),
        });
        o
    }

    /// `o` beside a triple that withheld for `cause`.
    fn withheld_by(mut o: Observation, cause: WithheldBecause) -> Observation {
        let arm = ControlArm {
            flags: Vec::new(),
            outcome: None,
            detail: None,
            build: None,
            run: None,
            macro_source: None,
            macro_dump: None,
            decoded: None,
            overridden: None,
        };
        o.controls = Some(Controls {
            positive: arm.clone(),
            negative: arm,
            regime_negative: None,
            discrimination: Discrimination::Withheld(cause),
        });
        o
    }

    /// The earned half of [`the_withholding_sets_are_the_standing_of_each_observation`]: an
    /// architecture gate and a flag the driver does not know.
    fn earned_only() -> Vec<Observation> {
        vec![
            observation("on", "-Dflag", Channel::Macro, Verdict::On),
            gated_by("arch", Verdict::Unsupported, gating_rule::ARCH),
            withheld_by(
                gated_by("unknown", Verdict::Unsupported, gating_rule::FLAG_UNKNOWN),
                WithheldBecause::PositiveIndeterminate,
            ),
        ]
    }

    #[test]
    fn the_twinless_macro_checks_are_compile_input_readings() {
        let mut fed = 0_usize;
        for (id, _) in MACRO_WITHOUT_TWIN {
            assert!(
                COMPILE_INPUT_READINGS.contains(id),
                "{id} has no twin and is not a compile-input reading, so a handed-on header \
                 word would reach it unheld"
            );
            fed += 1;
        }
        assert_eq!(fed, MACRO_WITHOUT_TWIN.len());
    }

    #[test]
    fn every_macro_check_has_twins_or_a_reason() {
        let checks: Vec<&Check> = crate::probe::CORPUS.iter().flat_map(|p| p.checks).collect();
        let find = |id: &str| checks.iter().find(|c| c.id == id).copied();
        let mut macro_checks = 0;
        for c in &checks {
            if c.channel() != Channel::Macro {
                continue;
            }
            macro_checks += 1;
            let in_table = MACRO_TWINS.iter().any(|t| t.macro_check == c.id);
            let excluded = MACRO_WITHOUT_TWIN.iter().any(|(id, _)| *id == c.id);
            let request = c.observes == Observes::Request;
            assert_eq!(
                usize::from(in_table) + usize::from(excluded) + usize::from(request),
                1,
                "{}: in MACRO_TWINS {in_table}, in MACRO_WITHOUT_TWIN {excluded}, a request \
                 {request}; exactly one holds",
                c.id
            );
        }
        assert!(macro_checks > 0, "the corpus has macro-channel checks");
        for (id, reason) in MACRO_WITHOUT_TWIN {
            assert!(!reason.is_empty(), "{id} is left out with no reason");
            let c = find(id).unwrap_or_else(|| panic!("{id} is not a corpus check"));
            assert_eq!(
                c.channel(),
                Channel::Macro,
                "{id} is not on the macro channel"
            );
        }
        for row in MACRO_TWINS {
            let m = find(row.macro_check)
                .unwrap_or_else(|| panic!("{} is not a corpus check", row.macro_check));
            assert_eq!(m.channel(), Channel::Macro, "{}", row.macro_check);
            assert!(
                !row.witnesses.is_empty(),
                "{} has no witness",
                row.macro_check
            );
            for w in row.witnesses {
                let t =
                    find(w.check).unwrap_or_else(|| panic!("{} is not a corpus check", w.check));
                assert!(
                    WITNESS_CHANNELS.contains(&t.channel()),
                    "{} reads {} on the {} channel, which is not the built thing",
                    row.macro_check,
                    w.check,
                    t.channel().as_str()
                );
                for word in w.components {
                    assert!(
                        m.levels.admits(word),
                        "{}: `{word}` is not a word on {}'s scale",
                        w.check,
                        row.macro_check
                    );
                }
            }
        }
        // The groups' pairs are the table's.
        for m in checks.iter().filter(|c| c.channel() == Channel::Macro) {
            let Some(group) = m.corroborates else {
                continue;
            };
            for t in checks.iter().filter(|t| {
                t.corroborates == Some(group) && WITNESS_CHANNELS.contains(&t.channel())
            }) {
                let held = MACRO_TWINS.iter().any(|row| {
                    row.macro_check == m.id && row.witnesses.iter().any(|w| w.check == t.id)
                });
                assert!(
                    held,
                    "{} and {} share the corroboration group `{group}` and MACRO_TWINS does \
                     not pair them",
                    m.id, t.id
                );
            }
        }
    }

    /// A macro reading with a level, for the twin tests: a corpus observation on its own
    /// channel, as `measure` publishes it.
    fn levelled(id: &str, verdict: Verdict, level: Option<&str>) -> Observation {
        let mut o = corpus_observation(id, verdict);
        o.level = level.map(ToOwned::to_owned);
        o
    }

    /// [`withhold_contradicted_macros`] over `observations`, handing back the run and what
    /// it withheld.
    fn twin_run(observations: Vec<Observation>) -> (Vec<Observation>, MacroWithholding) {
        let mut observations = observations;
        let withheld = withhold_contradicted_macros(&mut observations);
        (observations, withheld)
    }

    /// The cell `id` of a run.
    fn twin_cell(observations: &[Observation], id: &str) -> Observation {
        observations
            .iter()
            .find(|o| o.check == id)
            .cloned()
            .unwrap_or_else(|| panic!("{id} is in the run"))
    }

    #[test]
    fn a_macro_reading_contradicted_by_its_twin_is_withheld_and_the_twin_keeps_its_verdict() {
        let (out, withheld) = twin_run(vec![
            levelled("cet-macro", Verdict::On, Some("full")),
            levelled("cet-marked", Verdict::Off, None),
            levelled("cet-endbr-emitted", Verdict::Off, None),
        ]);
        assert_eq!(withheld.ids(), vec!["cet-macro".to_owned()]);
        let macro_cell = twin_cell(&out, "cet-macro");
        assert_eq!(macro_cell.verdict, Verdict::Indeterminate);
        assert_eq!(macro_cell.level, None);
        let gating = macro_cell.gating.expect("withheld under a rule");
        assert_eq!(gating.rule, gating_rule::MACRO_CONTRADICTED);
        for needle in [
            "`cet-macro` read `on` at `full`",
            "`cet-marked` reads `off`",
            "`cet-endbr-emitted` reads `off`",
        ] {
            assert!(
                gating.reason.contains(needle),
                "{needle}: {}",
                gating.reason
            );
        }
        assert_eq!(twin_cell(&out, "cet-marked").verdict, Verdict::Off);
        assert_eq!(twin_cell(&out, "cet-endbr-emitted").verdict, Verdict::Off);
        let diagnostics = withheld.diagnostics();
        assert_eq!(diagnostics.len(), 1);
        assert_eq!(diagnostics[0].severity, Severity::Warning);
        assert_eq!(diagnostics[0].context.as_deref(), Some("cet-macro"));
        assert!(
            diagnostics[0].message.contains("`cet-marked` reads `off`")
                && diagnostics[0]
                    .message
                    .contains("`cet-macro` read `on` at `full` on the macro channel")
                && diagnostics[0].message.contains("cannot say which"),
            "{}",
            diagnostics[0].message
        );

        // Absent beside present: the `off` mirror.
        let (out, withheld) = twin_run(vec![
            levelled("cet-macro", Verdict::Off, None),
            levelled("cet-marked", Verdict::On, Some("full")),
        ]);
        assert_eq!(withheld.ids(), vec!["cet-macro".to_owned()]);
        assert_eq!(twin_cell(&out, "cet-macro").verdict, Verdict::Indeterminate);
        assert_eq!(twin_cell(&out, "cet-marked").verdict, Verdict::On);

        // One twin agrees, one contradicts, and the reason names the one that did.
        let (out, withheld) = twin_run(vec![
            levelled("ssp-level", Verdict::On, Some("strong")),
            levelled("canary-emitted", Verdict::On, None),
            levelled("ssp-level-emitted", Verdict::Off, None),
        ]);
        assert_eq!(withheld.ids(), vec!["ssp-level".to_owned()]);
        let reason = twin_cell(&out, "ssp-level")
            .gating
            .expect("withheld")
            .reason;
        assert!(
            reason.contains("`ssp-level-emitted` reads `off`"),
            "{reason}"
        );
        assert!(
            reason.contains("`canary-emitted` reads `on` on the elf-static channel, agreeing"),
            "{reason}"
        );
    }

    #[test]
    fn an_honest_compile_and_link_split_is_withheld_and_says_so() {
        for (verdict, level, twin) in [
            (Verdict::On, Some("2"), Verdict::Off),
            (Verdict::Off, None, Verdict::On),
        ] {
            let (out, withheld) = twin_run(vec![
                levelled("pie-macro", verdict, level),
                levelled("pie", twin, (twin == Verdict::On).then_some("pie")),
            ]);
            assert_eq!(withheld.ids(), vec!["pie-macro".to_owned()], "{verdict:?}");
            assert!(twin_cell(&out, "pie-macro").gating.is_some(), "withheld");
            assert_eq!(twin_cell(&out, "pie").verdict, twin);
        }
        // The other pairs, each way.
        for (m, t, level) in [
            ("gcs-macro", "gcs-marked", None),
            ("branch-protection-macro", "branch-protection-marked", None),
            ("exceptions-macro", "except-table-emitted", None),
        ] {
            let (_, withheld) = twin_run(vec![
                levelled(m, Verdict::On, level),
                levelled(t, Verdict::Off, None),
            ]);
            assert_eq!(withheld.ids(), vec![m.to_owned()], "{m} on beside {t} off");
            let (_, withheld) = twin_run(vec![
                levelled(m, Verdict::Off, None),
                levelled(t, Verdict::On, level),
            ]);
            assert_eq!(withheld.ids(), vec![m.to_owned()], "{m} off beside {t} on");
            let (_, withheld) = twin_run(vec![
                levelled(m, Verdict::On, level),
                levelled(t, Verdict::On, level),
            ]);
            assert!(withheld.is_empty(), "{m} on beside {t} on");
        }
    }

    #[test]
    fn a_witness_consulted_for_an_absent_reading_only_decides_only_there() {
        let (_, withheld) = twin_run(vec![
            levelled("pic-macro", Verdict::Off, None),
            levelled("pic-object-relocs", Verdict::On, None),
        ]);
        assert_eq!(withheld.ids(), vec!["pic-macro".to_owned()]);
        let (_, withheld) = twin_run(vec![
            levelled("pic-macro", Verdict::On, Some("2")),
            levelled("pic-object-relocs", Verdict::Off, None),
        ]);
        assert!(withheld.is_empty(), "{withheld:?}");
        let (_, withheld) = twin_run(vec![
            levelled("cet-macro", Verdict::On, None),
            levelled("cet-endbr-emitted", Verdict::Off, None),
        ]);
        assert_eq!(withheld.ids(), vec!["cet-macro".to_owned()]);
        // A level the scale does not admit consults the component witness too; only a
        // known word outside its components (`return`) excludes it.
        let (_, withheld) = twin_run(vec![
            levelled("cet-macro", Verdict::On, Some("fullest")),
            levelled("cet-endbr-emitted", Verdict::Off, None),
        ]);
        assert_eq!(withheld.ids(), vec!["cet-macro".to_owned()]);
    }

    #[test]
    fn the_twin_table_is_the_pinned_list() {
        type Witness = (&'static str, &'static [&'static str], bool);
        type Row = (&'static str, Vec<Witness>);
        let rows: Vec<Row> = MACRO_TWINS
            .iter()
            .map(|t| {
                (
                    t.macro_check,
                    t.witnesses
                        .iter()
                        .map(|w| (w.check, w.components, w.absent_only))
                        .collect(),
                )
            })
            .collect();
        let none: &[&str] = &[];
        let expected: Vec<Row> = vec![
            (
                "ssp-level",
                vec![
                    ("ssp-level-emitted", none, false),
                    ("canary-emitted", none, false),
                ],
            ),
            ("pie-macro", vec![("pie", none, false)]),
            (
                "cet-macro",
                vec![
                    ("cet-marked", none, false),
                    ("cet-marked-object", none, false),
                    ("cet-endbr-emitted", &["branch", "full"], false),
                ],
            ),
            ("gcs-macro", vec![("gcs-marked", none, false)]),
            (
                "branch-protection-macro",
                vec![("branch-protection-marked", none, false)],
            ),
            (
                "exceptions-macro",
                vec![("except-table-emitted", none, false)],
            ),
            ("pic-macro", vec![("pic-object-relocs", none, true)]),
            (
                "optimization-enabled",
                vec![("optimization-applied", none, false)],
            ),
        ];
        assert_eq!(rows, expected);
        for t in MACRO_TWINS {
            for w in t.witnesses {
                assert!(
                    !w.absent_only || w.components.is_empty(),
                    "{}: a witness is absent-only or by component, not both",
                    w.check
                );
            }
        }
    }

    #[test]
    fn an_opt_in_reading_is_held_to_nothing_beside_a_present_twin() {
        let (out, withheld) = twin_run(vec![
            levelled("ssp-level", Verdict::Partial, Some("explicit")),
            levelled("canary-emitted", Verdict::On, None),
            levelled("ssp-level-emitted", Verdict::On, Some("basic")),
        ]);
        assert!(withheld.is_empty(), "{withheld:?}");
        assert_eq!(twin_cell(&out, "ssp-level").verdict, Verdict::Partial);
    }

    #[test]
    fn a_group_with_a_member_withheld_under_the_twin_rule_says_so() {
        let corroborates = |id: &str| corpus_check_by_id(id).and_then(|c| c.corroborates);
        let mut observations = vec![
            levelled("cet-macro", Verdict::On, Some("full")),
            levelled("cet-marked", Verdict::Off, None),
        ];
        withhold_contradicted_macros(&mut observations);
        let groups = corroboration(&observations, &corroborates);
        let note = &groups["cet"].note;
        assert!(
            note.starts_with(
                "CONTRADICTED: `cet-macro` withheld under macro-contradicted-by-artifact"
            ) && note.contains("one other member of this group measured, `cet-marked`")
                && !note.contains("not a disagreement"),
            "{note}"
        );
        assert!(groups["cet"].agree);
        let mut observations = vec![
            levelled("ssp-level", Verdict::On, Some("strong")),
            levelled("canary-emitted", Verdict::On, None),
            levelled("ssp-level-emitted", Verdict::Off, None),
        ];
        withhold_contradicted_macros(&mut observations);
        let groups = corroboration(&observations, &corroborates);
        let note = &groups["stack-protector"].note;
        assert!(
            note.starts_with("CONTRADICTED: `ssp-level`")
                && note.contains("the other members of this group disagree among themselves"),
            "{note}"
        );
        assert!(!groups["stack-protector"].agree);
        // The contradicting check outside the group: `cet-endbr-emitted` is not a member
        // of `cet`, and the note says a check, not a member, read the opposite presence;
        // with `cet-marked` agreeing, it is the one other member measured.
        let mut observations = vec![
            levelled("cet-macro", Verdict::On, Some("full")),
            levelled("cet-marked", Verdict::On, Some("full")),
            levelled("cet-endbr-emitted", Verdict::Off, None),
        ];
        withhold_contradicted_macros(&mut observations);
        let groups = corroboration(&observations, &corroborates);
        let note = &groups["cet"].note;
        assert!(
            note.starts_with("CONTRADICTED: `cet-macro`")
                && note.contains("since a check reading `cet`")
                && note.contains("one other member of this group measured, `cet-marked`"),
            "{note}"
        );
        // And with no other member measured.
        let mut observations = vec![
            levelled("cet-macro", Verdict::On, Some("full")),
            levelled("cet-endbr-emitted", Verdict::Off, None),
        ];
        withhold_contradicted_macros(&mut observations);
        let groups = corroboration(&observations, &corroborates);
        assert!(
            groups["cet"]
                .note
                .contains("no other member of this group measured"),
            "{}",
            groups["cet"].note
        );
        let mut withheld = levelled("ssp-level", Verdict::Indeterminate, None);
        withheld.gating = Some(Gating {
            rule: gating_rule::MACRO_SPOOFED,
            arch: None,
            libc: None,
            needs_vm: false,
            reason: "the list".to_owned(),
        });
        let observations = vec![
            withheld,
            levelled("canary-emitted", Verdict::On, None),
            levelled("ssp-level-emitted", Verdict::Off, None),
        ];
        let groups = corroboration(&observations, &corroborates);
        let note = &groups["stack-protector"].note;
        assert!(
            note.starts_with("CHANNELS DISAGREE") && !note.contains("not a disagreement"),
            "{note}"
        );
    }

    #[test]
    fn a_component_witness_speaks_at_its_levels_and_a_level_split_is_not_a_contradiction() {
        let (_, withheld) = twin_run(vec![
            levelled("cet-macro", Verdict::Partial, Some("return")),
            levelled("cet-endbr-emitted", Verdict::Off, None),
        ]);
        assert!(withheld.is_empty(), "{withheld:?}");
        for (verdict, level) in [
            (Verdict::Partial, Some("branch")),
            (Verdict::On, Some("full")),
        ] {
            let (_, withheld) = twin_run(vec![
                levelled("cet-macro", verdict, level),
                levelled("cet-endbr-emitted", Verdict::Off, None),
            ]);
            assert_eq!(withheld.ids(), vec!["cet-macro".to_owned()], "{level:?}");
        }
        let (_, withheld) = twin_run(vec![
            levelled("cet-macro", Verdict::Off, None),
            levelled("cet-endbr-emitted", Verdict::On, None),
        ]);
        assert_eq!(withheld.ids(), vec!["cet-macro".to_owned()]);
        let (_, withheld) = twin_run(vec![
            levelled("cet-macro", Verdict::Partial, Some("return")),
            levelled("cet-marked", Verdict::Off, None),
        ]);
        assert_eq!(withheld.ids(), vec!["cet-macro".to_owned()]);
        let (_, withheld) = twin_run(vec![
            levelled("cet-macro", Verdict::Partial, Some("branch")),
            levelled("cet-marked", Verdict::Partial, Some("return")),
        ]);
        assert!(withheld.is_empty(), "{withheld:?}");
    }

    #[test]
    fn a_withheld_absent_opt_in_or_unlisted_twin_decides_nothing() {
        for twin_verdict in [
            Verdict::Indeterminate,
            Verdict::ProbeInvalid,
            Verdict::Unsupported,
            Verdict::NotApplicable,
            Verdict::BuildFailed,
        ] {
            let (out, withheld) = twin_run(vec![
                levelled("cet-macro", Verdict::On, Some("full")),
                levelled("cet-marked", twin_verdict, None),
            ]);
            assert!(withheld.is_empty(), "{twin_verdict:?}: {withheld:?}");
            assert_eq!(twin_cell(&out, "cet-macro").verdict, Verdict::On);
        }
        let (_, withheld) = twin_run(vec![levelled("cet-macro", Verdict::On, Some("full"))]);
        assert!(withheld.is_empty());

        let mut gated = levelled("cet-macro", Verdict::Indeterminate, None);
        gated.gating = Some(Gating {
            rule: gating_rule::MACRO_SPOOFED,
            arch: None,
            libc: None,
            needs_vm: false,
            reason: "the list".to_owned(),
        });
        let (out, withheld) = twin_run(vec![
            gated,
            levelled("cet-marked", Verdict::On, Some("full")),
        ]);
        assert!(withheld.is_empty());
        assert_eq!(
            twin_cell(&out, "cet-macro").gating.map(|g| g.rule),
            Some(gating_rule::MACRO_SPOOFED)
        );

        // An opt-in level is held to nothing: its artifact readers read `off` by design.
        let (_, withheld) = twin_run(vec![
            levelled("ssp-level", Verdict::Partial, Some("explicit")),
            levelled("canary-emitted", Verdict::Off, None),
            levelled("ssp-level-emitted", Verdict::Off, None),
        ]);
        assert!(withheld.is_empty(), "{withheld:?}");

        // A twin on another channel is not the built thing, whatever its id.
        let mut diag = levelled("pie", Verdict::Off, None);
        diag.channel = Channel::CompilerDiag;
        let (_, withheld) = twin_run(vec![levelled("pie-macro", Verdict::On, Some("2")), diag]);
        assert!(withheld.is_empty(), "{withheld:?}");
        // A pair consulted for an absent reading only, present here, and a request, are
        // held to nothing.
        let (_, withheld) = twin_run(vec![
            levelled("pic-macro", Verdict::On, Some("2")),
            levelled("pic-object-relocs", Verdict::Off, None),
            levelled("fortify-requested", Verdict::On, Some("3")),
            levelled("fortify-enforced-known", Verdict::Off, None),
        ]);
        assert!(withheld.is_empty(), "{withheld:?}");
        // And the honest shapes move nothing.
        let (_, withheld) = twin_run(vec![
            levelled("pie-macro", Verdict::On, Some("2")),
            levelled("pie", Verdict::On, Some("pie")),
            levelled("exceptions-macro", Verdict::On, None),
            levelled("except-table-emitted", Verdict::On, None),
            levelled("cet-macro", Verdict::Partial, Some("return")),
            levelled("cet-marked", Verdict::Partial, Some("return")),
            levelled("cet-marked-object", Verdict::Partial, Some("return")),
            levelled("cet-endbr-emitted", Verdict::Off, None),
        ]);
        assert!(withheld.is_empty(), "{withheld:?}");
    }

    #[test]
    fn a_macro_measurement_beside_a_contradicting_twin_is_a_contradiction_at_publish_and_on_read() {
        let observations = vec![
            levelled("cet-macro", Verdict::On, Some("full")),
            levelled("cet-marked", Verdict::Off, None),
        ];
        let found = macro_verdicts_agree_with_twins(&observations);
        assert_eq!(found.len(), 1, "{found:?}");
        assert_eq!(found[0].rule, RULE_MACRO_TWIN);
        assert_eq!(found[0].property, "observations[cet-macro].verdict");
        assert_eq!(
            found[0].claims,
            vec![
                "observations[cet-macro].verdict = on at `full` on the macro channel".to_owned(),
                "observations[cet-marked].verdict = off on the elf-static channel".to_owned(),
            ]
        );

        // Withheld by the rule: nothing to raise.
        let mut withheld = observations.clone();
        withhold_contradicted_macros(&mut withheld);
        assert!(macro_verdicts_agree_with_twins(&withheld).is_empty());

        // Withheld under the rule with no twin that measured: unearned.
        let alone = vec![
            withheld[0].clone(),
            levelled("cet-marked", Verdict::Indeterminate, None),
        ];
        let found = macro_verdicts_agree_with_twins(&alone);
        assert_eq!(found.len(), 1, "{found:?}");
        assert_eq!(found[0].property, "observations[cet-macro].gating");
        assert!(
            found[0].claims[1].contains("no twin of `cet-macro`"),
            "{found:?}"
        );

        // On read, from the file's words alone.
        let doc = |verdict: &str, twin: &str| {
            serde_json::json!({
                "observations": [
                    {"check": "cet-macro", "verdict": verdict, "channel": "macro",
                     "level": "full"},
                    {"check": "cet-marked", "verdict": twin, "channel": "elf-static"},
                ]
            })
        };
        let mine = |reread: Reread| -> Vec<Contradiction> {
            reread
                .contradictions
                .into_iter()
                .filter(|c| c.rule == RULE_MACRO_TWIN)
                .collect()
        };
        let found = mine(reread_contradictions(&doc("on", "off")));
        assert_eq!(found.len(), 1, "{found:?}");
        assert_eq!(
            found[0].claims[1],
            "observations[cet-marked].verdict = off on the elf-static channel"
        );
        assert!(mine(reread_contradictions(&doc("on", "on"))).is_empty());
        assert!(mine(reread_contradictions(&doc("indeterminate", "off"))).is_empty());
        // No channel written: this build's corpus channel for the check, the direction
        // that withholds, so the twin is still read.
        let unchannelled = serde_json::json!({
            "observations": [
                {"check": "cet-macro", "verdict": "on"},
                {"check": "cet-marked", "verdict": "off"},
            ]
        });
        assert_eq!(mine(reread_contradictions(&unchannelled)).len(), 1);
        // The second clause on read: a withholding beside no twin that measured.
        let unearned = serde_json::json!({
            "observations": [
                {"check": "cet-macro", "verdict": "indeterminate", "channel": "macro",
                 "gating": {"rule": "macro-contradicted-by-artifact",
                            "premise": "instrument-limitation", "needs_vm": false,
                            "reason": "r"}},
                {"check": "cet-marked", "verdict": "indeterminate", "channel": "elf-static"},
            ]
        });
        let found = mine(reread_contradictions(&unearned));
        assert_eq!(found.len(), 1, "{found:?}");
        assert_eq!(found[0].property, "observations[cet-macro].gating");
        assert!(REREAD_RULES.contains(&RULE_MACRO_TWIN));
        assert!(OBSERVATION_REREAD_RULES.contains(&RULE_MACRO_TWIN));
    }

    #[test]
    fn a_macro_measurement_over_an_artifact_with_no_account_is_a_contradiction() {
        let build = |artifact: Option<&str>| {
            Some(BuildRecord {
                argv: vec!["cc".to_owned()],
                dropped_flags: Vec::new(),
                exit_status: 0,
                stdout: String::new(),
                stderr: String::new(),
                duration_ms: 1,
                artifact_sha256: artifact.map(ToOwned::to_owned),
                stdout_sha256: None,
                stdout_unterminated: false,
            })
        };
        let elf_with = |text: &str| {
            let mut elf = elf_of_machine("x86_64");
            elf.self_report = text.to_owned();
            elf.sections = vec![".chard.report".to_owned()];
            FactEntry::Elf { elf: Box::new(elf) }
        };
        let mut store = FactStore::default();
        for (key, entry) in [
            (
                "aa",
                elf_with("CHARD-REPORT-V2\n__PIE__=2\nCHARD-REPORT-END"),
            ),
            (
                "bb",
                elf_with("CHARD-REPORT-V2\n__PIE__ undefined\nCHARD-REPORT-END"),
            ),
            ("cc", elf_with("")),
            (
                "dd",
                FactEntry::Unreadable {
                    error: "file too short to be ELF".to_owned(),
                    mach_o: false,
                },
            ),
            (
                "ee",
                FactEntry::Unreadable {
                    error: crate::elf::MACH_O_REFUSAL.to_owned(),
                    mach_o: true,
                },
            ),
        ] {
            store.insert(key.repeat(32), entry).expect("distinct keys");
        }
        let obs = |verdict: Verdict, artifact: Option<&str>| {
            let mut o = observation("ssp-level", "-fstack-protector", Channel::Macro, verdict);
            o.build = build(artifact.map(|k| k.repeat(32)).as_deref());
            o
        };
        let fired = |o: &Observation, macos: bool| {
            let found = macro_verdicts_earned_by_artifacts(std::slice::from_ref(o), &store, macos);
            assert!(found.len() <= 1, "{found:?}");
            found.into_iter().next()
        };

        // An account, defined macros or all `?`, earns the measurement on every host.
        assert!(fired(&obs(Verdict::Off, Some("aa")), false).is_none());
        assert!(fired(&obs(Verdict::Off, Some("bb")), false).is_none());
        assert!(fired(&obs(Verdict::Off, Some("bb")), true).is_none());
        // No report in the section: refused everywhere.
        let found = fired(&obs(Verdict::Off, Some("cc")), false).expect("fires");
        assert_eq!(found.rule, RULE_SELF_REPORT);
        assert_eq!(found.property, "observations[ssp-level].verdict");
        assert!(
            found.claims[1].contains("and the section is empty"),
            "{found:?}"
        );
        assert!(fired(&obs(Verdict::On, Some("cc")), true).is_some());
        // The reader refused the artifact: on every host, macOS included (an ELF
        // cross-compiler's artifact there), unless it refused a Mach-O object on macOS.
        let found = fired(&obs(Verdict::On, Some("dd")), false).expect("fires");
        assert!(
            found.claims[1].contains("file too short to be ELF"),
            "{found:?}"
        );
        assert!(fired(&obs(Verdict::On, Some("dd")), true).is_some());
        assert!(fired(&obs(Verdict::On, Some("ee")), true).is_none());
        let found = fired(&obs(Verdict::On, Some("ee")), false).expect("fires off macOS");
        assert!(found.claims[1].contains("a Mach-O object"), "{found:?}");
        // No artifact written: every host.
        assert!(fired(&obs(Verdict::Partial, None), false).is_some());
        assert!(fired(&obs(Verdict::Partial, None), true).is_some());
        // A withheld verdict, another channel, and a probe that built nothing are outside.
        assert!(fired(&obs(Verdict::Indeterminate, Some("cc")), false).is_none());
        let mut elf_static = observation(
            "canary-emitted",
            "-fstack-protector",
            Channel::ElfStatic,
            Verdict::Off,
        );
        elf_static.build = build(Some(&"cc".repeat(32)));
        assert!(fired(&elf_static, false).is_none());
        let mut unbuilt = obs(Verdict::Off, None);
        unbuilt.build = None;
        assert!(fired(&unbuilt, false).is_none());
        // The witness word alone decides nothing: a measurement over an account, with
        // `macro_source` reading `preprocessor` as the fact-store fixtures write it, stands.
        let mut dump = obs(Verdict::Off, Some("aa"));
        dump.evidence.macro_source = Some("preprocessor".to_owned());
        assert!(fired(&dump, false).is_none());
    }

    #[test]
    fn a_run_with_only_earned_limitations_answered_every_question_it_could() {
        let earned_only = earned_only();
        let w = Withholding::of(&earned_only);
        assert_eq!(w.published, 1);
        assert_eq!(w.earned_limitations.count, 2);
        assert_eq!(
            w.earned_limitations.by_rule.keys().collect::<Vec<_>>(),
            [gating_rule::ARCH.id, gating_rule::FLAG_UNKNOWN.id],
            "the rule is the reason, and the triple's cause is not counted beside it"
        );
        assert!(w.earned_limitations.by_withheld_cause.is_empty());
        assert_eq!(w.instrument_withholdings, WithholdingSet::default());
        let ids: std::collections::BTreeSet<String> =
            earned_only.iter().map(|o| o.check.clone()).collect();
        let cov = coverage(&earned_only, &ids, earned_only.len(), &bare(), Vec::new());
        assert!(
            cov.all_verdicts_published,
            "a run with only earned limitations answered every question it could"
        );
    }

    #[test]
    fn the_withholding_sets_are_the_standing_of_each_observation() {
        let gated = gated_by;
        let triple = withheld_by;
        let mut mixed = earned_only();
        mixed.push(observation(
            "bare-unsupported",
            "-Dflag",
            Channel::Macro,
            Verdict::Unsupported,
        ));
        mixed.push(gated(
            "misfiled",
            Verdict::Unsupported,
            gating_rule::CPU_LACKS_SHADOW_STACK,
        ));
        mixed.push(triple(
            gated(
                "cpu",
                Verdict::Indeterminate,
                gating_rule::CPU_LACKS_SHADOW_STACK,
            ),
            WithheldBecause::PositiveIndeterminate,
        ));
        mixed.push(triple(
            observation("invalid", "-Dflag", Channel::Macro, Verdict::ProbeInvalid),
            WithheldBecause::NegativeAlsoShows,
        ));
        mixed.push(observation(
            "failed",
            "-Dflag",
            Channel::Macro,
            Verdict::BuildFailed,
        ));
        let w = Withholding::of(&mixed);
        assert_eq!((w.published, w.earned_limitations.count), (1, 2));
        let i = &w.instrument_withholdings;
        assert_eq!(i.count, 5);
        assert_eq!(
            i.by_verdict
                .iter()
                .map(|(k, v)| (k.as_str(), *v))
                .collect::<Vec<_>>(),
            [
                ("build-failed", 1),
                ("indeterminate", 1),
                ("probe-invalid", 1),
                ("unsupported", 2)
            ],
            "an unsupported no rule earns is the instrument's, with or without a rule"
        );
        assert_eq!(
            i.by_rule.get(gating_rule::CPU_LACKS_SHADOW_STACK.id),
            Some(&2)
        );
        assert_eq!(
            i.by_withheld_cause
                .iter()
                .map(|(k, v)| (k.as_str(), *v))
                .collect::<Vec<_>>(),
            [("negative-also-shows", 1)]
        );
        assert_eq!(
            i.no_named_cause, 2,
            "the bare unsupported and the build failure"
        );
        let ids: std::collections::BTreeSet<String> =
            mixed.iter().map(|o| o.check.clone()).collect();
        let cov = coverage(&mixed, &ids, mixed.len(), &bare(), Vec::new());
        assert!(!cov.all_verdicts_published);
        assert_eq!(
            shortfalls(&mixed, ids.iter().map(String::as_str)).len(),
            i.count,
            "the gate names exactly the instrument's withholdings"
        );

        // No observations: nothing in either set, and nothing published.
        let empty = Withholding::of::<Observation>(&[]);
        assert_eq!(
            (
                empty.published,
                empty.earned_limitations.count,
                empty.instrument_withholdings.count
            ),
            (0, 0, 0)
        );
    }

    #[test]
    fn every_gating_rule_id_is_distinct() {
        use std::collections::BTreeSet;

        let ids: BTreeSet<&str> = gating_rule::ALL.iter().map(|r| r.id).collect();
        assert_eq!(
            ids.len(),
            gating_rule::ALL.len(),
            "two gating rules share an id, so every count over them merges the pair"
        );
        assert!(
            ids.iter()
                .all(|id| !id.is_empty() && id.chars().all(|c| c.is_ascii_lowercase() || c == '-')),
            "an id a consumer has to quote is kebab-case and non-empty: {ids:?}"
        );
    }

    #[test]
    fn a_gating_rule_publishes_the_verdict_its_premise_reserves() {
        use gating_rule::Premise;
        use std::collections::BTreeSet;

        let verdicts: BTreeSet<&str> = Premise::ALL.iter().map(|p| p.verdict().as_str()).collect();
        assert_eq!(verdicts.len(), Premise::ALL.len(), "one verdict per class");
        assert!(Premise::ToolchainFact.verdict().is_earned_limitation());
        assert!(Premise::Inapplicable.verdict().is_earned_limitation());
        assert!(
            !Premise::InstrumentLimitation
                .verdict()
                .is_earned_limitation()
        );
        assert!(!Premise::InstrumentLimitation.verdict().is_measurement());

        for rule in gating_rule::ALL {
            for &verdict in Verdict::ALL.iter().filter(|v| !v.is_measurement()) {
                let mut obs = observation("c", "-f", Channel::ElfStatic, verdict);
                obs.gating = Some(Gating {
                    rule: *rule,
                    arch: None,
                    libc: None,
                    needs_vm: false,
                    reason: "r".to_owned(),
                });
                assert_eq!(
                    obs.is_settled(),
                    verdict == rule.verdict() && verdict.is_earned_limitation(),
                    "{} ({:?}) under {verdict:?}",
                    rule.id,
                    rule.premise
                );
            }
        }
    }

    #[test]
    fn every_gating_rule_is_one_coherent_row_of_the_table() {
        use gating_rule::{Evidence, Stage, Triple};

        for rule in gating_rule::ALL {
            assert!(
                !rule.statement.trim().is_empty(),
                "{} states no premise",
                rule.id
            );
            if let Evidence::ToolSentence { arm, .. } = rule.evidence {
                assert!(
                    rule.arms.contains(&arm),
                    "{} quotes the {arm:?} arm and does not consult it",
                    rule.id
                );
            }
            // The target stage reads the `e_machine` of every artifact the run built, which
            // is no one build of this check's, and the twin stage reads the settled
            // verdicts of other checks.
            assert_eq!(
                rule.stage.triple() == Triple::None
                    || matches!(rule.stage, Stage::Target | Stage::Twin),
                rule.arms.is_empty(),
                "{} at {:?} consults {:?}",
                rule.id,
                rule.stage,
                rule.arms
            );
            assert_eq!(
                rule.stage.triple() == Triple::Withheld,
                rule.stage == Stage::Declared,
                "{}",
                rule.id
            );
        }
    }

    #[test]
    fn a_listing_is_owed_by_the_arm_that_did_not_behave() {
        use Outcome::{Absent, Indeterminate, Present};

        let states = [None, Some(Present), Some(Absent), Some(Indeterminate)];
        let expected =
            |positive: Option<Outcome>, negative: Option<Outcome>| match (positive, negative) {
                (Some(Present), Some(Present)) => Some(Arm::Negative),
                (Some(Absent), None | Some(Present | Absent | Indeterminate)) => {
                    Some(Arm::Positive)
                }
                (None | Some(Indeterminate), _)
                | (Some(Present), None | Some(Absent | Indeterminate)) => None,
            };
        let (mut negative_owed, mut positive_owed, mut none_owed) = (0, 0, 0);
        for positive in states {
            for negative in states {
                let owed = owed_listing(positive, negative);
                assert_eq!(
                    owed,
                    expected(positive, negative),
                    "{positive:?} {negative:?}"
                );
                match owed {
                    Some(Arm::Negative) => negative_owed += 1,
                    Some(Arm::Positive) => positive_owed += 1,
                    None => none_owed += 1,
                }
            }
        }
        assert_eq!(
            (negative_owed, positive_owed, none_owed),
            (1, 4, 11),
            "one state owes the negative arm's listing, four the positive arm's, eleven none"
        );
    }

    #[test]
    #[expect(
        clippy::too_many_lines,
        reason = "one walk over every arm state, with and without a record on each arm"
    )]
    fn every_withheld_cause_is_reachable() {
        use std::collections::BTreeMap;

        let arms = [
            None,
            Some(Outcome::Present),
            Some(Outcome::Absent),
            Some(Outcome::Indeterminate),
        ];
        let mut reached: BTreeMap<WithheldBecause, usize> = BTreeMap::new();
        // Each arm with and without what the driver's compile command showed of its flag: a
        // record is read in the one state that asks for it, and handed to `decide` in any
        // other it changes nothing and is not published.
        let shown = |with: bool, flag: &str, by: &str| ArmInput {
            detection: None,
            flags: vec![flag.to_owned()],
            overridden: with.then(|| {
                crate::overridden::Listed::Overridden(crate::overridden::Overridden {
                    flag: flag.to_owned(),
                    by: by.to_owned(),
                })
            }),
        };
        for positive in arms {
            for negative in arms {
                for regime in arms {
                    for (on_positive, on_negative) in
                        [(false, false), (true, false), (false, true), (true, true)]
                    {
                        let det = |o: Option<Outcome>| o.map(|o| detection(o, None));
                        let (positive_seen, negative_seen) = (det(positive), det(negative));
                        let (verdict, controls) = decide(
                            &detection(Outcome::Present, None),
                            ArmInput {
                                detection: positive_seen.as_ref(),
                                ..shown(
                                    on_positive,
                                    "-fstack-protector-all",
                                    "-fno-stack-protector",
                                )
                            },
                            ArmInput {
                                detection: negative_seen.as_ref(),
                                ..shown(
                                    on_negative,
                                    "-fno-stack-protector",
                                    "-fstack-protector-strong",
                                )
                            },
                            regime_arm(det(regime).as_ref()),
                            None,
                        );
                        let state = format!(
                            "positive {positive:?} ({on_positive}), negative {negative:?} \
                             ({on_negative}), regime {regime:?}"
                        );
                        let owed = owed_listing(positive, negative);
                        let kept = (
                            controls.positive.overridden.is_some(),
                            controls.negative.overridden.is_some(),
                        );
                        assert_eq!(
                            kept,
                            (
                                on_positive && owed == Some(Arm::Positive),
                                on_negative && owed == Some(Arm::Negative)
                            ),
                            "{state}"
                        );
                        assert_eq!(
                            controls.withheld() == Some(WithheldBecause::PositiveOverridden),
                            kept.0,
                            "{state}"
                        );
                        assert_eq!(
                            controls.withheld() == Some(WithheldBecause::NegativeOverridden),
                            kept.1,
                            "{state}"
                        );
                        // A record never earns a verdict: the triple withholds as it does
                        // with no record on either arm.
                        let (bare_verdict, bare_controls) = decide(
                            &detection(Outcome::Present, None),
                            arm(positive_seen.as_ref()),
                            arm(negative_seen.as_ref()),
                            regime_arm(det(regime).as_ref()),
                            None,
                        );
                        assert_eq!(verdict, bare_verdict, "{state}");
                        assert_eq!(
                            controls.discriminating(),
                            bare_controls.discriminating(),
                            "{state}"
                        );
                        assert!(stray_overridden(&controls).is_empty(), "{state}");
                        if let Some(cause) = controls.withheld() {
                            *reached.entry(cause).or_insert(0) += 1;
                        }
                    }
                }
            }
        }

        let missing: Vec<&str> = WithheldBecause::ALL
            .iter()
            .filter(|c| !reached.contains_key(c))
            .map(|c| c.as_str())
            .collect();
        assert!(
            missing.is_empty(),
            "causes no control triple can produce: {missing:?}"
        );
    }

    #[test]
    fn control_arm_outcomes_are_three_valued_in_the_report() {
        assert_eq!(Outcome::Present.as_str(), "present");
        assert_eq!(Outcome::Absent.as_str(), "absent");
        assert_eq!(Outcome::Indeterminate.as_str(), "indeterminate");
        assert_eq!(
            serde_json::to_value(Outcome::Indeterminate).expect("an outcome serializes"),
            serde_json::json!("indeterminate"),
            "the serialized spelling and the one the fixtures compare against are one \
             mapping, not two that happen to agree"
        );
    }

    #[test]
    fn no_negative_control_and_a_present_bare_build_cannot_be_trusted() {
        let (verdict, _) = decide(
            &detection(Outcome::Present, None),
            arm(Some(&detection(Outcome::Present, None))),
            arm(None),
            None,
            None,
        );
        assert_eq!(verdict, Verdict::ProbeInvalid);
    }

    #[test]
    fn a_weaker_level_than_recommended_is_partial() {
        let (verdict, _) = decide(
            &detection(Outcome::Present, Some("2")),
            arm(Some(&detection(Outcome::Present, Some("3")))),
            arm(Some(&detection(Outcome::Absent, None))),
            None,
            crate::probe::FORTIFY_LEVELS.grade(),
        );
        assert_eq!(verdict, Verdict::Partial);
    }

    #[test]
    fn a_stronger_level_than_recommended_is_still_on() {
        // -fstack-protector-all exceeds the recommended `strong`; it must not be
        // demoted to `partial` by a naive string comparison.
        let (verdict, _) = decide(
            &detection(Outcome::Present, Some("all")),
            arm(Some(&detection(Outcome::Present, Some("all")))),
            arm(Some(&detection(Outcome::Absent, None))),
            None,
            crate::probe::SSP_LEVELS.grade(),
        );
        assert_eq!(verdict, Verdict::On);
    }

    #[test]
    fn a_confounded_regime_withholds_the_verdict_despite_clean_controls() {
        let (verdict, controls) = decide(
            &detection(Outcome::Present, Some("zero")),
            arm(Some(&detection(Outcome::Present, Some("zero")))),
            arm(Some(&detection(Outcome::Absent, None))),
            regime_arm(
                // The regime-matched negative still shows the observable.
                Some(&detection(Outcome::Present, Some("zero"))),
            ),
            None,
        );
        assert_eq!(verdict, Verdict::ProbeInvalid);
        assert!(!controls.discriminating());
        assert_eq!(
            controls.withheld(),
            Some(WithheldBecause::RegimeConfounded),
            "a signal the regime arm reproduces is not attributable to the flag"
        );
    }

    #[test]
    fn an_unconfounded_regime_leaves_the_verdict_alone() {
        let (verdict, controls) = decide(
            &detection(Outcome::Present, None),
            arm(Some(&detection(Outcome::Present, None))),
            arm(Some(&detection(Outcome::Absent, None))),
            regime_arm(Some(&detection(Outcome::Absent, None))),
            None,
        );
        assert_eq!(verdict, Verdict::On);
        assert!(controls.discriminating());
        assert_eq!(
            controls.regime_negative.and_then(|a| a.outcome),
            Some(Outcome::Absent)
        );
    }

    #[test]
    fn a_macro_dump_that_failed_withholds_the_channel_whatever_it_printed() {
        let defines = || BTreeMap::from([("__SSP_STRONG__".to_owned(), "3".to_owned())]);
        let dump = |status: i32, stderr: &str| BuildRecord {
            argv: vec!["cc".to_owned(), "-dM".to_owned(), "-E".to_owned()],
            dropped_flags: Vec::new(),
            exit_status: status,
            stdout: String::new(),
            stderr: stderr.to_owned(),
            duration_ms: 1,
            artifact_sha256: None,
            stdout_sha256: None,
            stdout_unterminated: false,
        };
        let variant = |macros: BTreeMap<String, String>, dump: Option<BuildRecord>| Variant {
            macros_preprocessor: macros.clone(),
            macros,
            macro_source: "preprocessor",
            macro_dump: dump,
            elf: None,
            build: None,
            run: None,
            run_error: None,
            elf_error: None,
            unwitnessed: None,
            artifact: None,
            structured: None,
            workdir: None,
        };

        // Exited non-zero with defines printed.
        let failed = variant(
            defines(),
            Some(dump(
                1,
                "\nfatal error: late.h: No such file or directory\n",
            )),
        );
        assert_eq!(
            failed.sufficient_for(Channel::Macro),
            Err(Verdict::Indeterminate),
            "a dump that exited 1 is not evidence, however many defines it printed first"
        );
        let reason = failed
            .macro_dump_failure()
            .expect("a failed dump names its failure");
        assert!(
            reason.contains("exited 1") && reason.contains("late.h: No such file"),
            "the reason must quote the exit status and the first stderr line: {reason}"
        );

        // Exited 0 and defined nothing: a compiler that preprocessed nothing.
        let empty = variant(BTreeMap::new(), Some(dump(0, "")));
        assert_eq!(
            empty.sufficient_for(Channel::Macro),
            Err(Verdict::Indeterminate)
        );
        assert!(
            empty
                .macro_dump_failure()
                .is_some_and(|r| r.contains("defined no macros")),
            "an empty dump names emptiness rather than an exit status"
        );

        // A dump that succeeded and defined something is readable, and so is the artifact's
        // own account read over it.
        let clean = variant(defines(), Some(dump(0, "")));
        assert_eq!(clean.sufficient_for(Channel::Macro), Ok(()));
        assert_eq!(clean.macro_dump_failure(), None);

        // The artifact's self-report does not rescue a failed dump: a comparison against a
        // truncated dump is against nothing in particular.
        let mut artifact = variant(defines(), Some(dump(1, "error")));
        artifact.macro_source = "compiled-artifact";
        assert_eq!(
            artifact.sufficient_for(Channel::Macro),
            Err(Verdict::Indeterminate)
        );

        // Nor an empty one.
        let mut rescued = variant(defines(), Some(dump(0, "")));
        rescued.macros_preprocessor = BTreeMap::new();
        rescued.macro_source = "compiled-artifact";
        assert_eq!(
            rescued.sufficient_for(Channel::Macro),
            Err(Verdict::Indeterminate),
            "an artifact self-report must not rescue a dump that defined nothing"
        );
        assert!(
            rescued
                .macro_dump_failure()
                .is_some_and(|r| r.contains("defined no macros"))
        );

        // No dump at all: a probe that never asked for one, which no macro check reads.
        let none = variant(BTreeMap::new(), None);
        assert_eq!(
            none.sufficient_for(Channel::Macro),
            Err(Verdict::Indeterminate)
        );
        assert!(
            none.macro_dump_failure()
                .is_some_and(|r| r.contains("no macro dump")),
            "a variant with no dump says so rather than reporting an empty one"
        );

        // No dump beside macros read from elsewhere: no dump failed, so none is named.
        assert_eq!(variant(defines(), None).macro_dump_failure(), None);
    }

    #[test]
    fn a_macro_reading_beside_a_failed_build_is_build_failed() {
        let record = |status: i32| BuildRecord {
            argv: vec!["cc".to_owned()],
            dropped_flags: Vec::new(),
            exit_status: status,
            stdout: String::new(),
            stderr: String::new(),
            duration_ms: 1,
            artifact_sha256: None,
            stdout_sha256: None,
            stdout_unterminated: false,
        };
        let variant = |dump: i32, build: Option<i32>| {
            let macros = BTreeMap::from([("__ARM_FEATURE_BTI_DEFAULT".to_owned(), "1".to_owned())]);
            Variant {
                macros_preprocessor: macros.clone(),
                macros,
                macro_source: "preprocessor",
                macro_dump: Some(record(dump)),
                elf: None,
                build: build.map(record),
                run: None,
                run_error: None,
                elf_error: None,
                unwitnessed: None,
                artifact: None,
                structured: None,
                workdir: None,
            }
        };
        assert_eq!(
            variant(0, Some(1)).sufficient_for(Channel::Macro),
            Err(Verdict::BuildFailed),
            "a dump beside a failed build is not a reading of that build"
        );
        assert_eq!(
            variant(1, Some(1)).sufficient_for(Channel::Macro),
            Err(Verdict::BuildFailed),
            "a dump that failed with its build is the build's failure"
        );
        assert_eq!(
            variant(1, Some(0)).sufficient_for(Channel::Macro),
            Err(Verdict::Indeterminate),
            "a failed dump beside a build that ran keeps its own verdict"
        );
        assert_eq!(
            variant(1, None).sufficient_for(Channel::Macro),
            Err(Verdict::Indeterminate),
            "a failed dump of a probe that builds nothing is its own failure"
        );
        assert_eq!(variant(0, Some(0)).sufficient_for(Channel::Macro), Ok(()));
        assert_eq!(variant(0, None).sufficient_for(Channel::Macro), Ok(()));
    }

    #[test]
    fn an_unreadable_artifact_is_indeterminate_and_an_unbuilt_one_is_not() {
        let variant = |elf_error: Option<&str>| Variant {
            macros: BTreeMap::new(),
            macros_preprocessor: BTreeMap::new(),
            macro_source: "preprocessor",
            macro_dump: None,
            elf: None,
            build: None,
            run: None,
            run_error: None,
            elf_error: elf_error.map(|why| ArtifactRefusal {
                why: why.to_owned(),
                mach_o: false,
            }),
            unwitnessed: None,
            artifact: None,
            structured: None,
            workdir: None,
        };

        assert_eq!(
            variant(Some("not an ELF file")).sufficient_for(Channel::ElfStatic),
            Err(Verdict::Indeterminate),
            "the artifact exists and was not read; the protection is unmeasured, not absent"
        );
        assert_eq!(
            variant(None).sufficient_for(Channel::ElfStatic),
            Err(Verdict::BuildFailed),
            "no artifact and no read error is a build that produced nothing"
        );
    }

    #[test]
    fn a_measured_build_refused_for_a_profile_flag_is_build_failed_on_the_diagnostic_channel() {
        let variant = |build: Option<BuildRecord>, elf: Option<ElfFacts>| Variant {
            macros: BTreeMap::new(),
            macros_preprocessor: BTreeMap::new(),
            macro_source: "preprocessor",
            macro_dump: None,
            elf,
            build,
            run: None,
            run_error: None,
            elf_error: None,
            unwitnessed: None,
            artifact: None,
            structured: None,
            workdir: None,
        };
        let mut supplying = bare();
        supplying.cflags = vec!["-O2".to_owned(), "-Wchard-no-such-flag".to_owned()];
        supplying.ldflags = vec!["-Wl,--no-such-option".to_owned()];
        let not_supplying = bare();
        let canary = "probe.c:3:9: warning: unused variable 'chard_canary_unused' \
                      [-Wunused-variable]";
        let own_error = "probe.c:9:1: error: expected ';'";

        // Refusals: the tool stopped on the line, with or without a severity word, and
        // whatever it printed before.
        let refusals = [
            "gcc: error: unrecognized command-line option '-Wchard-no-such-flag'",
            "clang: error: unknown argument: '-Wchard-no-such-flag'",
            "error: unknown warning option '-Wchard-no-such-flag' \
             [-Werror,-Wunknown-warning-option]",
            "ld: unrecognized option '--no-such-option'",
        ];
        for line in refusals {
            let stderr = format!("{canary}\n{line}");
            let refused = variant(Some(stderr_record(1, &stderr)), None);
            assert_eq!(
                refused.sufficient_for(Channel::CompilerDiag),
                Ok(()),
                "the profile-free rule reads any build's stderr as the observable: {line}"
            );
            let withheld = refused
                .sufficient_for_measured(Channel::CompilerDiag, &supplying)
                .expect_err(line);
            assert_eq!(withheld.verdict, Verdict::BuildFailed, "{line}");
            let refusal = withheld.refusal.expect("a build-failed names its refusal");
            assert_eq!(refusal.line, line, "the refused line, not the first");
            assert!(
                refusal
                    .sentence
                    .contains("supplied by the profile not by this check"),
                "{}",
                refusal.sentence
            );
            assert_eq!(
                refused.sufficient_for_measured(Channel::CompilerDiag, &not_supplying),
                Ok(()),
                "a refusal of a flag the profile did not supply is the detector's to \
                 read: {line}"
            );
        }

        // Warned about and gone past: the build failed for the probe's own error, and the
        // diagnostics are read.
        let warnings = [
            "clang: warning: unknown warning option '-Wchard-no-such-flag' \
             [-Wunknown-warning-option]",
            "warning: unknown warning option '-Wchard-no-such-flag'; did you mean \
             '-Wchard-such-flag'? [-Wunknown-warning-option]",
            "cc1: note: unrecognized command-line option '-Wchard-no-such-flag' may have \
             been intended to silence earlier diagnostics",
        ];
        for line in warnings {
            let stderr = format!("{line}\n{canary}\n{own_error}");
            let warned = variant(Some(stderr_record(1, &stderr)), None);
            assert_eq!(
                warned.sufficient_for_measured(Channel::CompilerDiag, &supplying),
                Ok(()),
                "a flag the driver went on without did not fail the build: {line}"
            );
        }
        let warned_ok = variant(
            Some(stderr_record(
                0,
                "clang: warning: unknown warning option '-Wchard-no-such-flag'",
            )),
            None,
        );
        assert_eq!(
            warned_ok.sufficient_for_measured(Channel::CompilerDiag, &supplying),
            Ok(())
        );
        let broken = variant(Some(stderr_record(1, own_error)), None);
        assert_eq!(
            broken.sufficient_for_measured(Channel::CompilerDiag, &supplying),
            Ok(()),
            "a build that failed with no refusal in it is the silence rule's"
        );
        let unbuilt = variant(None, None)
            .sufficient_for_measured(Channel::CompilerDiag, &supplying)
            .expect_err("no build record");
        assert_eq!(
            (unbuilt.verdict, unbuilt.refusal),
            (Verdict::BuildFailed, None)
        );
    }

    #[test]
    fn the_profile_withholds_the_diagnostic_channel_alone() {
        let variant = |build: Option<BuildRecord>, elf: Option<ElfFacts>| Variant {
            macros: BTreeMap::new(),
            macros_preprocessor: BTreeMap::new(),
            macro_source: "preprocessor",
            macro_dump: None,
            elf,
            build,
            run: None,
            run_error: None,
            elf_error: None,
            unwitnessed: None,
            artifact: None,
            structured: None,
            workdir: None,
        };
        let mut supplying = bare();
        supplying.cflags = vec!["-O2".to_owned(), "-Wchard-no-such-flag".to_owned()];
        let not_supplying = bare();
        let refused = "probe.c:3:9: warning: unused variable 'chard_canary_unused'\n\
                       gcc: error: unrecognized command-line option '-Wchard-no-such-flag'";
        let read = variant(
            Some(stderr_record(1, refused)),
            Some(elf_of_machine("x86_64")),
        );
        assert_eq!(read.sufficient_for(Channel::ElfStatic), Ok(()));
        assert_eq!(
            read.sufficient_for_measured(Channel::ElfStatic, &supplying),
            Ok(()),
            "the profile withholds the compiler-diagnostic channel alone"
        );
        let unread = variant(Some(stderr_record(1, refused)), None)
            .sufficient_for_measured(Channel::ElfStatic, &supplying)
            .expect_err("no artifact");
        assert_eq!(unread.verdict, Verdict::BuildFailed);
        assert!(
            unread.refusal.is_some(),
            "the refusal rides with the build-failed"
        );
        let unread_runtime = variant(Some(stderr_record(1, refused)), None)
            .sufficient_for_measured(Channel::Runtime, &not_supplying)
            .expect_err("nothing to run");
        assert_eq!(
            (unread_runtime.verdict, unread_runtime.refusal),
            (Verdict::BuildFailed, None)
        );
    }

