    #[test]
    fn a_profile_flag_reaches_the_check_that_examines_it_under_every_spelling() {
        let key = |token: &str| flag_keys(token);
        let same = |profile_flag: &str, check_flag: &str| {
            let a = key(profile_flag);
            let b = key(check_flag);
            assert!(
                !a.is_empty() && a == b,
                "{profile_flag} keys as {a:?}, the check's {check_flag} keys as {b:?}"
            );
        };
        same("-D_FORTIFY_SOURCE=3", "-D_FORTIFY_SOURCE");
        same("-U_FORTIFY_SOURCE", "-D_FORTIFY_SOURCE");
        same("-D_FORTIFY_SOURCE=3", "-D_FORTIFY_SOURCE>=2");
        same(
            "-D_LIBCPP_HARDENING_MODE=_LIBCPP_HARDENING_MODE_FAST",
            "-D_LIBCPP_HARDENING_MODE",
        );
        same("-D_GLIBCXX_ASSERTIONS", "-D_GLIBCXX_ASSERTIONS");
        same("-fcf-protection", "-fcf-protection=full");
        same("-fcf-protection=full", "-fcf-protection=full");
        same("-fstack-protector-all", "-fstack-protector-strong");
        same("-fstack-protector-strong", "-fstack-protector-strong");
        same("-Wl,-z,relro", "-Wl,-z,relro");
        same("-Wl,-z,relro,-z,now", "-Wl,-z,relro");
        same("-Wl,-z,now", "-Wl,-z,now");
        same("-fstrict-flex-arrays=3", "-fstrict-flex-arrays");
        same(
            "-mbranch-protection=standard",
            "-mbranch-protection=standard",
        );
        same("-mbranch-protection=standard", "-mbranch-protection=gcs");
        same(
            "-ftrivial-auto-var-init=zero",
            "-ftrivial-auto-var-init=pattern",
        );
        same(
            "-fzero-init-padding-bits=all",
            "-fzero-init-padding-bits=all",
        );
        same("-pie", "-pie");
        same("-fPIE", "-fPIE");
        same("-O2", "-O2");
        same("-Os", "-O2");
        same(
            "-Werror=implicit-function-declaration",
            "-Werror=implicit-function-declaration",
        );
        // The comma-joined preprocessor form, as Fedora ships it.
        assert_eq!(
            key("-Wp,-U_FORTIFY_SOURCE,-D_FORTIFY_SOURCE=3"),
            vec![
                "-D_FORTIFY_SOURCE".to_owned(),
                "-D_FORTIFY_SOURCE".to_owned()
            ]
        );

        // And the distinctions that must survive: two warning checks are two checks, and
        // `-Werror=x` is not `-Werror`.
        assert_ne!(key("-Wformat=2"), key("-Wformat"));
        assert_ne!(key("-Werror=format-security"), key("-Werror=implicit-int"));
        assert_ne!(key("-fPIC"), key("-fPIE"));
        // An option's argument and a qualifier in a check's own flag yield nothing.
        for word in ["ssp-buffer-size=4", "(artifact", "markings)"] {
            assert!(
                key(word).is_empty(),
                "{word} yields no key: {:?}",
                key(word)
            );
        }

        // `--param` keys on its parameter in both spellings, on the profile's side and
        // on the check's, and two parameters are two keys.
        let param = |s: &str| vec![format!("--param {s}")];
        assert_eq!(key("--param=ssp-buffer-size=4"), param("ssp-buffer-size"));
        assert_eq!(
            keyed_flags(["--param", "ssp-buffer-size=4"]),
            vec![(
                "--param ssp-buffer-size=4".to_owned(),
                param("ssp-buffer-size")
            )]
        );
        assert_eq!(
            keyed_flags("--param ssp-buffer-size".split_whitespace()),
            vec![(
                "--param ssp-buffer-size".to_owned(),
                param("ssp-buffer-size")
            )]
        );
        assert_ne!(
            key("--param=inline-unit-growth=40"),
            key("--param=ssp-buffer-size=4")
        );
        assert_eq!(
            keyed_flags(["-O2", "--param"]),
            vec![
                ("-O2".to_owned(), vec!["optimization".to_owned()]),
                ("--param".to_owned(), vec!["--param".to_owned()])
            ],
            "a dangling --param keys on itself"
        );

        // The optimization family is `-O`, as written.
        assert_eq!(family("-Os"), "optimization");
        assert_eq!(family("-o"), "-o");
        assert_eq!(family("-ofoo"), "-ofoo");
        assert_ne!(key("-o"), key("-O2"));
    }

    #[test]
    fn the_openssf_tldr_profile_is_the_guides_rows_on_every_architecture() {
        let (cet, bti, zero) = (
            "-fcf-protection=full",
            "-mbranch-protection=standard",
            "-fzero-call-used-regs=used-gpr",
        );
        let portable = openssf_tldr_cflags("riscv64");
        assert!(
            portable
                .iter()
                .all(|f| ![cet, bti, zero].contains(&f.as_str())),
            "an architecture with no addendum row gets no architecture flag: {portable:?}"
        );
        assert_eq!(
            portable[portable.len() - 2..],
            ["-fPIE", "-pie"],
            "the executables row ends the list"
        );
        let with = |pair: [&str; 2]| -> Vec<String> {
            let mut flags = portable.clone();
            let at = flags.len() - 2;
            flags.splice(at..at, pair.iter().map(|f| (*f).to_owned()));
            flags
        };
        for (_, arch) in crate::toolchain::TRIPLE_ARCHS {
            let expected = match *arch {
                "x86_64" => with([cet, zero]),
                "aarch64" => with([bti, zero]),
                _ => portable.clone(),
            };
            assert_eq!(openssf_tldr_cflags(arch), expected, "on {arch}");
        }
        assert_eq!(
            openssf_tldr_cflags("x86"),
            portable,
            "32-bit x86 is not in the guide's x86_64 row and gets neither of its flags"
        );
    }

    #[test]
    fn the_guide_revision_is_published_on_the_guides_profile_only() {
        for (id, published) in [
            ("openssf-tldr", Some(crate::guide::REVISION)),
            ("bare", None),
            ("bare-optimized", None),
            ("explicit:0123456789ab", None),
        ] {
            let mut profile = Profile {
                id: id.to_owned(),
                flags_source: flags_source::USER.to_owned(),
                cflags: openssf_tldr_cflags("x86_64"),
                cxxflags: Vec::new(),
                ldflags: Vec::new(),
                toolchain_note: None,
                compiler_environment: crate::compile::CompilerEnvironment::of_this_run(),
            };
            assert_eq!(profile.guide_revision(), published, "{id}");
            let json = serde_json::to_value(&profile).expect("a profile serializes");
            assert_eq!(
                json.get("guide_revision")
                    .and_then(serde_json::Value::as_str),
                published,
                "{id}: {json}"
            );
            for absent in ["cxxflags", "ldflags", "toolchain_note"] {
                assert!(json.get(absent).is_none(), "{id}: {absent} in {json}");
            }
            profile.ldflags = vec!["-Wl,-z,now".to_owned()];
            profile.toolchain_note = Some("a note".to_owned());
            let json = serde_json::to_value(&profile).expect("a profile serializes");
            assert_eq!(json["ldflags"], serde_json::json!(["-Wl,-z,now"]), "{id}");
            assert_eq!(json["toolchain_note"], "a note", "{id}");
            assert_eq!(json["id"], id);
        }
    }

    #[test]
    fn the_openssf_tldr_flags_no_check_examines_are_the_ones_pinned_here() {
        const OPENSSF_TLDR_UNEXAMINED: &[&str] = &[];

        let corpus_flags: Vec<&str> = crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks)
            .map(|c| c.flag)
            .collect();
        assert!(corpus_flags.len() > 40, "the corpus is not being read");
        let archs: std::collections::BTreeSet<&str> = crate::toolchain::TRIPLE_ARCHS
            .iter()
            .map(|(_, arch)| *arch)
            .chain(["riscv64"])
            .collect();
        for arch in archs {
            let profile = Profile {
                id: "openssf-tldr".to_owned(),
                flags_source: flags_source::OPENSSF_GUIDE.to_owned(),
                cflags: openssf_tldr_cflags(arch),
                cxxflags: Vec::new(),
                ldflags: Vec::new(),
                toolchain_note: None,
                compiler_environment: crate::compile::CompilerEnvironment::of_this_run(),
            };
            let unexamined = profile_flags_unexamined(&profile, corpus_flags.iter().copied());
            assert_eq!(
                unexamined,
                OPENSSF_TLDR_UNEXAMINED
                    .iter()
                    .map(|s| (*s).to_owned())
                    .collect::<Vec<_>>(),
                "on {arch} the guide's flags with no check changed; update the pin here \
                 if the corpus moved on purpose"
            );
        }

        // The matcher is not vacuous: a list with flags no check reads names them, in
        // the list's own spelling and order, each once, and the truncation says so.
        let dirty = Profile {
            id: "explicit:test".to_owned(),
            flags_source: flags_source::USER.to_owned(),
            cflags: vec![
                "-O2".to_owned(),
                "-g".to_owned(),
                "-pipe".to_owned(),
                "-specs=/usr/lib/rpm/redhat/redhat-hardened-cc1".to_owned(),
                "-fstack-protector-strong".to_owned(),
                "-g".to_owned(),
                // One parameter a check examines, one no check does, and the output option.
                "--param".to_owned(),
                "ssp-buffer-size=4".to_owned(),
                "--param".to_owned(),
                "inline-unit-growth=40".to_owned(),
                "-o".to_owned(),
                "out".to_owned(),
            ],
            cxxflags: vec!["-Wp,-D_GLIBCXX_ASSERTIONS".to_owned()],
            ldflags: vec!["-Wl,--build-id=sha1".to_owned()],
            toolchain_note: None,
            compiler_environment: crate::compile::CompilerEnvironment::of_this_run(),
        };
        assert_eq!(
            profile_flags_unexamined(&dirty, corpus_flags.iter().copied()),
            vec![
                "-g".to_owned(),
                "-pipe".to_owned(),
                "-specs=/usr/lib/rpm/redhat/redhat-hardened-cc1".to_owned(),
                "--param inline-unit-growth=40".to_owned(),
                "-o".to_owned(),
                "-Wl,--build-id=sha1".to_owned(),
            ]
        );
        // Against a report carrying one observation, for `-O2`: everything but `-O2`
        // is unexamined by *this report*, which is the question a filtered run answers.
        let ids: std::collections::BTreeSet<String> = ["a".to_owned()].into_iter().collect();
        let obs = vec![observation("a", "-O2", Channel::Macro, Verdict::On)];
        let cov = coverage(&obs, &ids, 1, &dirty, Vec::new());
        assert_eq!(
            cov.profile_flags_unexamined.len(),
            9,
            "{:?}",
            cov.profile_flags_unexamined
        );
        assert!(
            !cov.profile_flags_unexamined.contains(&"-O2".to_owned()),
            "the one flag the report examined is not listed"
        );
        assert!(
            cov.truncations
                .iter()
                .any(|t| t.contains("examined by no check") && t.contains("-pipe")),
            "a filtered flag list is a truncation: {:?}",
            cov.truncations
        );

        // And the derived list is held to its inputs.
        let mut edited = cov.clone();
        edited.profile_flags_unexamined.pop();
        assert!(
            coverage_agrees(&edited, &obs, &dirty)
                .iter()
                .any(|c| c.detail.contains("unexamined-flag list")),
            "a list that no longer agrees with the profile is refused"
        );
    }

    /// A profile with no flags, for the coverage tests that are not about the flag list.
    fn bare() -> Profile {
        Profile {
            id: "bare".to_owned(),
            flags_source: flags_source::NONE.to_owned(),
            cflags: Vec::new(),
            cxxflags: Vec::new(),
            ldflags: Vec::new(),
            toolchain_note: None,
            compiler_environment: crate::compile::CompilerEnvironment::of_this_run(),
        }
    }

    /// The check ids a list of observations carries, as the selection that produced them.
    fn ids_of(observations: &[Observation]) -> std::collections::BTreeSet<String> {
        observations.iter().map(|o| o.check.clone()).collect()
    }

    /// The ids `c0`..`c{n-1}`, which is how the completeness tests name their checks.
    fn numbered_ids(n: usize) -> std::collections::BTreeSet<String> {
        (0..n).map(|i| format!("c{i}")).collect()
    }

    fn observation(check: &str, flag: &str, channel: Channel, verdict: Verdict) -> Observation {
        Observation {
            probe: "p".to_owned(),
            check: check.to_owned(),
            flag: flag.to_owned(),
            channel,
            polarity: Polarity::Harden,
            verdict,
            boundary: None,
            level: None,
            recommended_level: None,
            confidence: "high".to_owned(),
            observable: String::new(),
            defects: Vec::new(),
            observes: Observes::Protection,
            references: Vec::new(),
            evidence: EvidenceOut::default(),
            build: None,
            run: None,
            controls: None,
            gating: None,
            build_rejection: None,
            structured_diagnostics: None,
            notes: String::new(),
        }
    }

    #[test]
    fn the_withholding_sets_are_held_to_the_observations() {
        let arm = |outcome: Outcome| ControlArm {
            flags: Vec::new(),
            outcome: Some(outcome),
            detail: None,
            build: None,
            run: None,
            macro_source: None,
            macro_dump: None,
            decoded: None,
            overridden: None,
        };
        let triple = |check: &str, verdict: Verdict, discrimination: Discrimination| {
            let mut o = observation(check, "-f", Channel::ElfStatic, verdict);
            o.controls = Some(Controls {
                positive: arm(Outcome::Present),
                negative: arm(Outcome::Absent),
                regime_negative: None,
                discrimination,
            });
            o
        };
        let silent = Discrimination::Withheld(WithheldBecause::PositiveSilent);
        let observations = vec![
            triple("a", Verdict::ProbeInvalid, silent),
            triple("b", Verdict::Unsupported, silent),
            triple("c", Verdict::On, Discrimination::Discriminating),
            observation("d", "-g", Channel::ElfStatic, Verdict::Indeterminate),
        ];
        let w = Withholding::of(&observations);
        assert_eq!(
            w.instrument_withholdings
                .by_withheld_cause
                .get(WithheldBecause::PositiveSilent.as_str()),
            Some(&2),
            "the probe-invalid and the unsupported no rule earns"
        );
        assert_eq!(w.instrument_withholdings.no_named_cause, 1);

        let expected: std::collections::BTreeSet<String> =
            observations.iter().map(|o| o.check.clone()).collect();
        let cov = coverage(&observations, &expected, 4, &bare(), Vec::new());
        assert!(
            withholding_split_disagrees(&cov, &observations).is_none()
                && withholding_agrees(&cov).is_empty()
                && completeness_flag_disagrees(&cov).is_none(),
            "a coverage block derived from these observations agrees with them"
        );

        let mut lost = cov.clone();
        lost.withholding
            .instrument_withholdings
            .by_withheld_cause
            .clear();
        lost.withholding.instrument_withholdings.no_named_cause = 3;
        assert!(
            withholding_agrees(&lost).is_empty(),
            "the sums still hold, so only the recount can see it"
        );
        let fired = withholding_split_disagrees(&lost, &observations).expect("refused");
        assert_eq!(fired.rule, RULE_WITHHOLDING);

        let mut excused = cov.clone();
        assert_eq!(
            excused.withholding.instrument_withholdings.no_named_cause, 1,
            "the indeterminate is the member with no named cause"
        );
        let i = &mut excused.withholding.instrument_withholdings;
        i.count -= 1;
        i.no_named_cause -= 1;
        i.by_verdict.remove("indeterminate");
        excused.withholding.earned_limitations = WithholdingSet {
            count: 1,
            by_verdict: [("unsupported".to_owned(), 1)].into(),
            by_rule: [(gating_rule::ARCH.id.to_owned(), 1)].into(),
            ..WithholdingSet::default()
        };
        *excused
            .verdict_counts
            .get_mut("indeterminate")
            .expect("counted") -= 1;
        *excused
            .verdict_counts
            .entry("unsupported".to_owned())
            .or_insert(0) += 1;
        excused.verdict_counts.retain(|_, n| *n > 0);
        assert!(
            withholding_agrees(&excused).is_empty(),
            "every statement over the tally holds: {:?}",
            withholding_agrees(&excused)
        );
        assert!(withholding_split_disagrees(&excused, &observations).is_some());

        let mut claimed = cov;
        claimed.all_verdicts_published = true;
        let (claims, _) = completeness_flag_disagrees(&claimed).expect("refused");
        assert!(
            claims
                .iter()
                .any(|c| c.contains("instrument_withholdings.count = 3")),
            "{claims:?}"
        );
    }

    #[test]
    fn coverage_reports_incompleteness_rather_than_hiding_it() {
        let observations = vec![observation("a", "-Dflag", Channel::Macro, Verdict::On)];
        let mut expected = numbered_ids(9);
        expected.insert("a".to_owned());
        let cov = coverage(
            &observations,
            &expected,
            10,
            &bare(),
            vec!["dropped 9 for the test".to_owned()],
        );
        assert!(!cov.all_checks_attempted);
        assert_eq!(cov.checks_skipped, 9);
        assert_eq!(
            cov.checks_missing,
            numbered_ids(9).into_iter().collect::<Vec<_>>(),
            "the nine that never came back are named as well as counted"
        );
        assert!(
            cov.checks_unexpected.is_empty(),
            "no check came back that was not selected: {:?}",
            cov.checks_unexpected
        );
        assert_eq!(cov.corpus_checks_total, 10);
        assert_eq!(cov.checks_valid, 0);
        assert_eq!(cov.truncations.len(), 1);
    }

    #[test]
    fn the_arch_gated_checks_are_the_ones_we_named() {
        let mut by_arch: BTreeMap<String, Vec<&str>> = BTreeMap::new();
        for check in crate::probe::CORPUS.iter().flat_map(|p| p.checks) {
            if !check.gate.arch.is_empty() {
                by_arch
                    .entry(check.gate.arch.join(","))
                    .or_default()
                    .push(check.id);
            }
        }
        for list in by_arch.values_mut() {
            list.sort_unstable();
        }
        let named: BTreeMap<String, Vec<&str>> = [
            ("aarch64".to_owned(), {
                let mut v = vec![
                    "branch-protection-macro",
                    "branch-protection-marked",
                    "bti-enforced",
                    "gcs-macro",
                    "gcs-marked",
                    "pac-ret-enforced",
                ];
                v.sort_unstable();
                v
            }),
            (
                "x86_64,x86".to_owned(),
                vec![
                    "cet-endbr-emitted",
                    "cet-macro",
                    "cet-marked",
                    "cet-marked-object",
                    "linker-default-noexecstack",
                ],
            ),
            // The two architectures the guide recommends the flag for; an i386 build
            // withholds it here as well as the aarch64 group.
            (
                "x86_64,aarch64".to_owned(),
                vec![
                    "fortify-printf-flag",
                    "noexecstack-enforced",
                    "ubsan-trap-mode",
                    "zero-call-used-regs",
                ],
            ),
            // Linux's user shadow stack is x86_64's alone, so an i386 build withholds it
            // where the marking checks beside it stand.
            ("x86_64".to_owned(), vec!["shadow-stack-enforced"]),
            // The three machines whose relocation types its predicate names; any other
            // withholds it.
            (
                "x86_64,x86,aarch64".to_owned(),
                vec!["pic-object-relocs", "textrel-absent"],
            ),
        ]
        .into_iter()
        .collect();
        assert_eq!(
            by_arch, named,
            "the arch-gated checks changed. Every host exempts one of these groups from \
             `all_verdicts_published`, so the groups are the denominator and have to be \
             stated where a reader can see them."
        );

        // Both groups are non-empty, which is the property that matters: every host
        // withholds something on architecture alone, so `--fail-on-missing` is not
        // satisfiable anywhere and the exemption below cannot be quietly removed by a
        // corpus that lost one side.
        let aarch64_only = named["aarch64"].len();
        let x86_only = named["x86_64,x86"].len();
        assert!(
            aarch64_only > 0 && x86_only > 0,
            "one architecture group emptied: x86 {x86_only}, aarch64 {aarch64_only}"
        );
    }

    #[test]
    fn every_gate_architecture_is_one_an_artifact_can_name() {
        for check in crate::probe::CORPUS.iter().flat_map(|p| p.checks) {
            for &arch in check.gate.arch {
                let family = crate::toolchain::machine_family(arch)
                    .unwrap_or_else(|| panic!("{}: {arch} maps to no e_machine family", check.id));
                assert_eq!(
                    crate::toolchain::gate_arch_of_machine(family),
                    arch,
                    "{}: an artifact of {arch} carries {family}, which names another gate \
                     architecture",
                    check.id
                );
            }
        }
    }

    #[test]
    fn every_gate_architecture_has_an_arch_macro() {
        for check in crate::probe::CORPUS.iter().flat_map(|p| p.checks) {
            for &arch in check.gate.arch {
                let family = crate::toolchain::machine_family(arch)
                    .unwrap_or_else(|| panic!("{}: {arch} maps to no e_machine family", check.id));
                assert!(
                    crate::toolchain::ARCH_MACROS
                        .iter()
                        .any(|&(_, machine)| machine == family),
                    "{}: {arch} ({family}) has no macro in toolchain::ARCH_MACROS",
                    check.id
                );
            }
        }
    }

    /// An observation of `check` in `probe`, read from an artifact with digest `sha`,
    /// whose machine is the one [`machines`] stores under that digest, and which built its
    /// triple (the observations [`FactStore::measured_elf_of`] reads).
    fn artifact_observation(probe: &str, check: &str, sha: &str) -> Observation {
        let mut o = withheld_early(probe, check, sha);
        o.verdict = Verdict::On;
        o.controls = Some(Controls {
            positive: published_arm(Some(Outcome::Present)),
            negative: published_arm(Some(Outcome::Absent)),
            regime_negative: None,
            discrimination: Discrimination::Discriminating,
        });
        o
    }

    /// An observation of `check` in `probe` over the artifact with digest `sha`, withheld
    /// before its triple, the way `run_check` publishes one whose variant could not serve
    /// the channel: a build, a store entry for it, and no `controls`.
    fn withheld_early(probe: &str, check: &str, sha: &str) -> Observation {
        let mut o = observation(check, "-f", Channel::ElfStatic, Verdict::Indeterminate);
        o.probe = probe.to_owned();
        o.build = Some(BuildRecord {
            argv: Vec::new(),
            dropped_flags: Vec::new(),
            exit_status: 0,
            stdout: String::new(),
            stderr: String::new(),
            duration_ms: 0,
            artifact_sha256: Some(sha.to_owned()),
            stdout_sha256: None,
            stdout_unterminated: false,
        });
        o
    }

    /// A store holding, under each digest, the facts of an artifact of its machine.
    fn machines(pairs: &[(&str, &str)]) -> FactStore {
        let mut store = FactStore::default();
        for (sha, machine) in pairs {
            store
                .insert(
                    (*sha).to_owned(),
                    FactEntry::Elf {
                        elf: Box::new(elf_of_machine(machine)),
                    },
                )
                .expect("one machine per digest");
        }
        store
    }

    /// The facts of a PIE executable of `machine`, little-endian at the width the family's
    /// rows stand for (ELF32 for i386; an i386 object at ELF64 is one no toolchain writes,
    /// and the abi witness would hold it).
    fn elf_of_machine(machine: &str) -> ElfFacts {
        serde_json::from_value(serde_json::json!({
                "aarch64_bti": false, "aarch64_pac": false, "aarch64_gcs": false,
                "bind_now": false, "df_1_noopen": false, "df_1_pie": true,
                "dt_debug": false, "dt_relr": false, "dt_soname": false, "dynamic_tags": [],
                "elf_class": if machine == "i386" { 32 } else { 64 }, "elf_data": "little-endian",
                "elf_type": "ET_DYN", "gnu_property_types": [], "gnu_relro": false,
                "gnu_stack_executable": false, "gnu_stack_present": true,
                "has_dynamic": true, "has_interp": true, "machine": machine,
                "needed": [], "pie": true, "recorded_command_line": "",
                "relro": "none", "rpath": [], "runpath": [], "sections": [],
                "self_report": "", "shared_object": false, "static_pie": false,
                "statically_linked": false, "symbol_count": 0, "textrel": false,
                "watched_symbols": {}, "x86_ibt": false, "x86_shstk": false,
        }))
        .expect("the fixture matches ElfFacts")
    }

    #[test]
    fn a_build_withheld_before_its_triple_is_stored_and_not_read_as_the_target() {
        let foreign = withheld_early("p-foreign", "c", &"b".repeat(64));
        let mut facts = machines(&[(&"a".repeat(64), "x86_64")]);
        let mut fortified = elf_of_machine("aarch64");
        fortified.self_report = "_FORTIFY_IMPL=glibc".to_owned();
        facts
            .insert(
                "b".repeat(64),
                FactEntry::Elf {
                    elf: Box::new(fortified),
                },
            )
            .expect("a new digest");
        let native = artifact_observation("p-native", "c", &"a".repeat(64));
        let observations = vec![foreign.clone(), native];
        assert!(facts.elf_of(foreign.build.as_ref()).is_some(), "stored");
        assert_eq!(facts.measured_elf_of(&foreign), None, "not read");
        let read = artifact_machines(&observations, &facts);
        assert_eq!(read.len(), 1, "{read:?}");
        assert_eq!(read[0].machine, "x86_64");
        assert_eq!(measured_fortify_impl(&observations, &facts), None);
    }

    #[test]
    fn a_contradicted_target_withholds_the_verdicts_its_gate_decided() {
        let gated_out = || {
            let mut o = artifact_observation("link-defaults", "cet-marked", "aa");
            o.verdict = Verdict::Unsupported;
            o.gating = Some(Gating {
                rule: gating_rule::ARCH,
                arch: Some("aarch64".to_owned()),
                libc: None,
                needs_vm: false,
                reason: "r".to_owned(),
            });
            o
        };
        let mut observations = vec![
            gated_out(),
            artifact_observation("link-defaults", "branch-protection-marked", "aa"),
            artifact_observation("link-defaults", "pie", "aa"),
        ];
        let facts = machines(&[("aa", "x86_64")]);
        let artifacts = artifact_machines(&observations, &facts);
        assert_eq!(artifacts.len(), 1, "one artifact, by digest");
        let target = crate::toolchain::target_agreement(
            "aarch64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifacts,
            &["__aarch64__".to_owned()],
            None,
        );
        assert_eq!(
            target.agreement,
            crate::toolchain::ArchAgreement::Disagrees,
            "{}",
            target.evidence
        );

        // Before the withholding, the report publishes two verdicts over the contradicted
        // premise, and the rule names each.
        let before = target_arch_agrees(Some(&target), None, false, &[], &observations, &facts);
        let named: Vec<&str> = before.iter().map(|c| c.property.as_str()).collect();
        assert_eq!(
            named,
            [
                "observations[cet-marked].verdict",
                "observations[branch-protection-marked].verdict"
            ],
            "{before:?}"
        );

        let withheld = withhold_on_contradicted_target(&mut observations, &target);
        assert_eq!(withheld, ["cet-marked", "branch-protection-marked"]);
        for o in &observations[..2] {
            assert_eq!(o.verdict, Verdict::Indeterminate, "{}", o.check);
            let gating = o.gating.as_ref().expect("withheld under a rule");
            assert_eq!(gating.rule, gating_rule::TARGET_CONTRADICTED);
            assert!(
                gating.reason.contains("e_machine x86_64"),
                "the reason names the machine: {}",
                gating.reason
            );
        }
        assert!(
            observations[0]
                .gating
                .as_ref()
                .is_some_and(|g| g.reason.contains("unsupported under arch-gated")),
            "the reason quotes the verdict it had"
        );
        assert_eq!(
            observations[2].verdict,
            Verdict::On,
            "a portable check stands"
        );
        assert!(
            target_arch_agrees(Some(&target), None, false, &[], &observations, &facts).is_empty()
        );
        assert!(gating_verdict_agrees(&observations).is_empty());

        // A published block the artifacts do not give is refused, and so is a report that
        // never held its gate to them.
        let mut agreeing = target.clone();
        agreeing.agreement = crate::toolchain::ArchAgreement::Agrees;
        assert_eq!(
            target_arch_agrees(Some(&agreeing), None, false, &[], &observations, &facts).len(),
            1
        );
        assert_eq!(
            target_arch_agrees(None, None, false, &[], &observations, &facts).len(),
            1
        );
        // A run that read no ELF artifact still read the macro witness, so an absent block
        // is refused there too; only an empty observation list has nothing to hold.
        let no_elf = FactStore::default();
        assert!(
            artifact_machines(&observations, &no_elf).is_empty(),
            "with no ELF facts, no artifact names a machine"
        );
        assert_eq!(
            target_arch_agrees(None, None, false, &[], &observations, &no_elf).len(),
            1,
            "a no-ELF run publishing no toolchain.target is refused"
        );
        assert!(
            target_arch_agrees(None, None, false, &[], &[], &facts).is_empty(),
            "nothing to hold"
        );
    }

    #[test]
    fn only_a_machine_that_flips_the_gate_withholds() {
        let mut observations = vec![
            artifact_observation("link-defaults", "cet-marked", "aa"),
            artifact_observation("shared-object-defaults", "textrel-absent", "bb"),
        ];
        let facts = machines(&[("aa", "i386"), ("bb", "i386")]);
        let target = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifact_machines(&observations, &facts),
            &["__x86_64__".to_owned()],
            None,
        );
        assert_eq!(target.agreement, crate::toolchain::ArchAgreement::Disagrees);
        assert!(withhold_on_contradicted_target(&mut observations, &target).is_empty());
        assert!(observations.iter().all(|o| o.verdict == Verdict::On));
        assert!(
            target_arch_agrees(Some(&target), None, false, &[], &observations, &facts).is_empty()
        );

        let mut crossed = vec![
            artifact_observation("link-defaults", "cet-marked", "aa"),
            artifact_observation("cet-endbr", "cet-endbr-emitted", "bb"),
            artifact_observation("shared-object-defaults", "nodlopen", "bb"),
        ];
        let facts = machines(&[("aa", "aarch64"), ("bb", "aarch64")]);
        let target = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifact_machines(&crossed, &facts),
            &["__x86_64__".to_owned()],
            None,
        );
        assert_eq!(target.agreement, crate::toolchain::ArchAgreement::Disagrees);
        let withheld = withhold_on_contradicted_target(&mut crossed, &target);
        assert_eq!(withheld, ["cet-marked", "cet-endbr-emitted"]);
        assert_eq!(crossed[2].verdict, Verdict::On);
        assert!(target_arch_agrees(Some(&target), None, false, &[], &crossed, &facts).is_empty());

        let mut native = vec![artifact_observation("link-defaults", "cet-marked", "aa")];
        let agrees = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifact_machines(&native, &machines(&[("aa", "x86_64")])),
            &["__x86_64__".to_owned()],
            None,
        );
        assert_eq!(agrees.agreement, crate::toolchain::ArchAgreement::Agrees);
        assert!(withhold_on_contradicted_target(&mut native, &agrees).is_empty());
    }

    /// The eighteen gated checks, each as `gate_applicability` publishes it under `arch`
    /// before any build: a measured one as a read `on`, the rest gated out or withheld
    /// under the rule the mechanism table decides, so a withholding's "the verdict it had"
    /// is the one a run publishes.
    fn gated_observations_under(arch: &str) -> Vec<Observation> {
        crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks.iter().map(move |c| (p, c)))
            .filter(|(_, c)| !c.gate.arch.is_empty())
            .map(|(p, c)| {
                let mut o = artifact_observation(p.id, c.id, "aa");
                match gate_applicability(
                    c.id,
                    c.flag,
                    &c.gate,
                    crate::env::KernelAttribution::Established,
                    arch,
                ) {
                    Applicability::Applicable => {}
                    Applicability::Unsupported(g) => {
                        o.verdict = Verdict::Unsupported;
                        o.gating = Some(g);
                    }
                    Applicability::Unread(g) | Applicability::Untrustworthy(g) => {
                        o.verdict = Verdict::Indeterminate;
                        o.gating = Some(g);
                    }
                }
                o
            })
            .collect()
    }

    /// The ids of the gated checks, in corpus order: the eighteen.
    fn gated_check_ids() -> Vec<String> {
        let ids: Vec<String> = gated_observations_under("x86_64")
            .into_iter()
            .map(|o| o.check)
            .collect();
        assert_eq!(ids.len(), 18, "the eighteen gated checks: {ids:?}");
        ids
    }

    /// Under `target`, whose witnesses name a machine the mechanism table has no row for,
    /// every gated check decided under `arch` is withheld under
    /// `target-arch-contradicted` with a reason naming `witness`, a portable check stands,
    /// and the consistency rule refuses the report before the withholding and accepts it
    /// after. `flags` are the profile's C flags the published witness names.
    fn assert_outside_witness_withholds_every_gated_check(
        arch: &str,
        name: &str,
        target: &crate::toolchain::TargetArch,
        flags: &[String],
        facts: &FactStore,
        witness: &str,
    ) {
        let mut observations = gated_observations_under(arch);
        observations.push(artifact_observation("link-defaults", "pie", "aa"));
        let before = target_arch_agrees(Some(target), None, false, flags, &observations, facts);
        assert_eq!(
            before.len(),
            18,
            "{arch}, {name}: every gated verdict stands over the contradicted premise \
             before the withholding: {before:?}"
        );
        let withheld = withhold_on_contradicted_target(&mut observations, target);
        assert_eq!(withheld, gated_check_ids(), "{arch}, {name}");
        for o in &observations[..18] {
            assert_eq!(
                o.verdict,
                Verdict::Indeterminate,
                "{arch}, {name}: {}",
                o.check
            );
            assert_eq!(o.level, None, "{arch}, {name}: {}", o.check);
            let gating = o.gating.as_ref().expect("withheld under a rule");
            assert_eq!(gating.rule, gating_rule::TARGET_CONTRADICTED);
            assert_eq!(gating.arch.as_deref(), Some(arch));
            assert!(
                gating.reason.contains(witness)
                    && gating.reason.contains(&format!(" for {arch}, read from "))
                    && gating.reason.contains("the verdict it had ("),
                "{arch}, {name}, {}: the reason names the witness, the premise and the \
                 verdict it had: {}",
                o.check,
                gating.reason
            );
            // The decision the witness contradicts, in the table's own word for it
            // (measured, gated out, left unread, left outside the table), so a swapped
            // word fails here and not only where a fake driver asserts one of them.
            let word = gate_outcome(&o.check, arch).as_str();
            assert!(
                gating.reason.contains(&format!("it was {word} for {arch}")),
                "{arch}, {name}, {}: the reason names the decision: {}",
                o.check,
                gating.reason
            );
        }
        assert_eq!(
            observations[18].verdict,
            Verdict::On,
            "a portable check stands"
        );
        assert!(
            target_arch_agrees(Some(target), None, false, flags, &observations, facts).is_empty(),
            "{arch}, {name}"
        );
        assert!(
            gating_verdict_agrees(&observations).is_empty(),
            "{arch}, {name}"
        );
    }

    /// A store holding, under each digest, the facts of an artifact of its machine, width
    /// and byte order.
    fn shaped_machines(entries: &[(&str, &str, u8, crate::elf::ByteOrder)]) -> FactStore {
        let mut store = FactStore::default();
        for (sha, machine, class, order) in entries {
            let mut elf = elf_of_machine(machine);
            elf.elf_class = *class;
            elf.elf_data = Some(*order);
            store
                .insert((*sha).to_owned(), FactEntry::Elf { elf: Box::new(elf) })
                .expect("one artifact per digest");
        }
        store
    }

    /// Under `target`, whose abi witness disagrees, every gated check decided under
    /// `arch` is withheld under `target-abi-contradicted` with a reason naming the rows'
    /// width and order and `witness`, a portable check stands, the diagnostic is one error
    /// under `toolchain.target`, and the consistency rule refuses the report before the
    /// withholding and accepts it after.
    fn assert_abi_witness_withholds_every_gated_check(
        arch: &str,
        name: &str,
        target: &crate::toolchain::TargetArch,
        facts: &FactStore,
        witness: &str,
    ) {
        assert_eq!(
            target.abi.agreement,
            crate::toolchain::AbiAgreement::Disagrees,
            "{arch}, {name}: {:?}",
            target.abi
        );
        let mut observations = gated_observations_under(arch);
        observations.push(artifact_observation("link-defaults", "pie", "aa"));
        let before = target_arch_agrees(Some(target), None, false, &[], &observations, facts);
        assert_eq!(
            before.len(),
            18,
            "{arch}, {name}: every gated verdict stands over the contradicted premise \
             before the withholding: {before:?}"
        );
        let withheld = withhold_on_contradicted_target(&mut observations, target);
        assert_eq!(withheld, gated_check_ids(), "{arch}, {name}");
        let expected = target
            .abi
            .expected
            .expect("the rows stand for one")
            .to_string();
        for o in &observations[..18] {
            assert_eq!(
                o.verdict,
                Verdict::Indeterminate,
                "{arch}, {name}: {}",
                o.check
            );
            assert_eq!(o.level, None);
            let gating = o.gating.as_ref().expect("withheld under a rule");
            assert_eq!(
                gating.rule,
                gating_rule::TARGET_ABI_CONTRADICTED,
                "{}",
                o.check
            );
            assert_eq!(gating.arch.as_deref(), Some(arch));
            let word = gate_outcome(&o.check, arch).as_str();
            assert!(
                gating.reason.contains(witness)
                    && gating.reason.contains(&format!("stand for {expected}"))
                    && gating.reason.contains(&format!("it was {word} for {arch}"))
                    && gating.reason.contains("the verdict it had (")
                    && gating.reason.contains("(toolchain.target.abi)"),
                "{arch}, {name}, {}: {}",
                o.check,
                gating.reason
            );
        }
        assert_eq!(
            observations[18].verdict,
            Verdict::On,
            "a portable check stands"
        );
        assert!(
            target_arch_agrees(Some(target), None, false, &[], &observations, facts).is_empty(),
            "{arch}, {name}"
        );
        assert!(gating_verdict_agrees(&observations).is_empty());
        let diagnostics = target_witness_diagnostics(target, &withheld);
        assert_eq!(diagnostics.len(), 1, "{arch}, {name}: {diagnostics:?}");
        assert_eq!(diagnostics[0].severity, Severity::Error);
        assert!(
            diagnostics[0].message.contains(witness)
                && diagnostics[0].message.contains("target-abi-contradicted"),
            "{}",
            diagnostics[0].message
        );
    }

    #[test]
    fn an_artifact_at_the_other_width_or_order_withholds_every_gated_check() {
        use crate::elf::ByteOrder::{BigEndian, LittleEndian};
        for (arch, machine, class, order, name, witness) in [
            (
                "x86_64",
                "x86_64",
                32,
                LittleEndian,
                "x32",
                "carry ELF32 little-endian",
            ),
            (
                "aarch64",
                "aarch64",
                32,
                LittleEndian,
                "ILP32",
                "carry ELF32 little-endian",
            ),
            (
                "aarch64",
                "aarch64",
                64,
                BigEndian,
                "aarch64_be",
                "carry ELF64 big-endian",
            ),
        ] {
            let facts = shaped_machines(&[("aa", machine, class, order)]);
            let observations = [artifact_observation("link-defaults", "pie", "aa")];
            // The flagless dump agrees about the family and names the rows' own width and
            // order (the driver is the host's): the artifact alone contradicts.
            let macro_of = format!("__{machine}__");
            let target = crate::toolchain::target_agreement(
                arch,
                crate::toolchain::ArchSource::Dumpmachine,
                &artifact_machines(&observations, &facts),
                &[macro_of],
                None,
            )
            .with_intrinsic_abi(crate::toolchain::Abi::of_arch(arch));
            assert_eq!(
                target.agreement,
                crate::toolchain::ArchAgreement::Agrees,
                "{name}: the machine agrees; only the width or order contradicts"
            );
            assert_abi_witness_withholds_every_gated_check(arch, name, &target, &facts, witness);
        }
    }

    #[test]
    fn a_dump_at_the_other_order_withholds_every_gated_check_with_no_artifact() {
        use crate::elf::ByteOrder::{BigEndian, LittleEndian};
        use crate::toolchain::Abi;
        let facts = FactStore::default();
        for (flag, abi, witness) in [
            (
                "-mbig-endian",
                Abi {
                    class: 64,
                    order: BigEndian,
                },
                "__BYTE_ORDER__ big-endian, naming ELF64 big-endian",
            ),
            (
                "-mabi=ilp32",
                Abi {
                    class: 32,
                    order: LittleEndian,
                },
                "__SIZEOF_POINTER__ 4 and __BYTE_ORDER__ little-endian, naming ELF32 little-endian",
            ),
        ] {
            let dump = crate::toolchain::ProfileDump {
                flags: vec![flag.to_owned()],
                exit_status: 0,
                stdout_unterminated: false,
                macros_defined: 300,
                defined: vec!["__aarch64__".to_owned()],
                abi: Some(abi),
            };
            let target = crate::toolchain::target_agreement(
                "aarch64",
                crate::toolchain::ArchSource::Dumpmachine,
                &[],
                &["__aarch64__".to_owned()],
                Some(&dump),
            )
            .with_intrinsic_abi(Some(Abi {
                class: 64,
                order: LittleEndian,
            }));
            assert_eq!(
                target.agreement,
                crate::toolchain::ArchAgreement::NoElfArtifact
            );
            let mut observations = gated_observations_under("aarch64");
            let before = target_arch_agrees(
                Some(&target),
                None,
                false,
                &[flag.to_owned()],
                &observations,
                &facts,
            );
            assert_eq!(before.len(), 18, "{flag}: {before:?}");
            let withheld = withhold_on_contradicted_target(&mut observations, &target);
            assert_eq!(withheld, gated_check_ids(), "{flag}");
            for o in &observations {
                let gating = o.gating.as_ref().expect("withheld");
                assert_eq!(gating.rule, gating_rule::TARGET_ABI_CONTRADICTED, "{flag}");
                assert!(gating.reason.contains(witness), "{flag}: {}", gating.reason);
            }
            assert!(
                target_arch_agrees(
                    Some(&target),
                    None,
                    false,
                    &[flag.to_owned()],
                    &observations,
                    &facts
                )
                .is_empty(),
                "{flag}"
            );
        }
    }

    #[test]
    fn the_abi_rule_defers_to_the_machine_rule_and_moves_nothing_outside_the_table() {
        use crate::elf::ByteOrder::{BigEndian, LittleEndian};
        // An aarch64_be artifact under an x86_64 read: the machine disagrees and every
        // gated check is withheld under `target-arch-contradicted`, the abi reading nothing
        // of a foreign family.
        let facts = shaped_machines(&[("aa", "aarch64", 64, BigEndian)]);
        let mut observations = gated_observations_under("x86_64");
        let target = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifact_machines(&observations, &facts),
            &[],
            None,
        );
        assert_eq!(target.agreement, crate::toolchain::ArchAgreement::Disagrees);
        assert_eq!(
            target.abi.agreement,
            crate::toolchain::AbiAgreement::NoWitness
        );
        withhold_on_contradicted_target(&mut observations, &target);
        assert!(
            observations.iter().all(|o| o
                .gating
                .as_ref()
                .is_some_and(|g| g.rule == gating_rule::TARGET_CONTRADICTED)),
            "the machine rule names every one"
        );
        // An abi disagreement whose every check the machine rule took first: the abi
        // diagnostic says so rather than claiming "every" check or naming none.
        let facts = shaped_machines(&[
            ("aa", "x86_64", 32, LittleEndian),
            ("bb", "riscv", 64, LittleEndian),
        ]);
        let mut observations = gated_observations_under("x86_64");
        for o in &mut observations[8..] {
            o.build.as_mut().expect("a build").artifact_sha256 = Some("bb".to_owned());
        }
        let target = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifact_machines(&observations, &facts),
            &["__x86_64__".to_owned()],
            None,
        );
        assert_eq!(
            target.abi.agreement,
            crate::toolchain::AbiAgreement::Disagrees
        );
        let withheld = withhold_on_contradicted_target(&mut observations, &target);
        assert_eq!(withheld.under(gating_rule::TARGET_CONTRADICTED).len(), 18);
        assert!(
            withheld
                .under(gating_rule::TARGET_ABI_CONTRADICTED)
                .is_empty(),
            "the ABI rule withholds nothing the machine rule already withholds"
        );
        let diagnostics = target_witness_diagnostics(&target, &withheld);
        assert_eq!(diagnostics.len(), 2, "{diagnostics:?}");
        assert!(
            diagnostics[0].message.contains("18 verdict(s)"),
            "{diagnostics:?}"
        );
        assert!(
            target_arch_agrees(Some(&target), None, false, &[], &observations, &facts).is_empty()
        );
    }

    #[test]
    fn the_abi_rule_moves_nothing_outside_the_table_or_at_the_rows_own_abi() {
        use crate::elf::ByteOrder::LittleEndian;
        // Outside the table: an x32-shaped riscv artifact under a riscv64 read.
        let facts = shaped_machines(&[("aa", "riscv", 32, LittleEndian)]);
        let mut observations = gated_observations_under("riscv64");
        let target = crate::toolchain::target_agreement(
            "riscv64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifact_machines(&observations, &facts),
            &[],
            None,
        );
        assert_eq!(
            target.abi.agreement,
            crate::toolchain::AbiAgreement::Unmapped
        );
        let before: Vec<(Verdict, Option<&'static str>)> = observations
            .iter()
            .map(|o| (o.verdict, o.gating.as_ref().map(|g| g.rule.id)))
            .collect();
        assert!(withhold_on_contradicted_target(&mut observations, &target).is_empty());
        let after: Vec<(Verdict, Option<&'static str>)> = observations
            .iter()
            .map(|o| (o.verdict, o.gating.as_ref().map(|g| g.rule.id)))
            .collect();
        assert_eq!(before, after, "nothing moves under arch-outside-table");
        assert!(
            target_witness_diagnostics(&target, &TargetWithholding::default()).is_empty(),
            "an arch outside the table yields no witness diagnostic"
        );

        // The rows' own width and order: nothing withheld, no diagnostic.
        let facts = shaped_machines(&[("aa", "x86_64", 64, LittleEndian)]);
        let mut observations = gated_observations_under("x86_64");
        let target = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifact_machines(&observations, &facts),
            &["__x86_64__".to_owned()],
            None,
        )
        .with_intrinsic_abi(Some(crate::toolchain::Abi {
            class: 64,
            order: LittleEndian,
        }));
        assert_eq!(target.abi.agreement, crate::toolchain::AbiAgreement::Agrees);
        assert!(withhold_on_contradicted_target(&mut observations, &target).is_empty());
        assert!(
            target_witness_diagnostics(&target, &TargetWithholding::default()).is_empty(),
            "a target whose ABI agrees yields no witness diagnostic"
        );
    }

    #[test]
    fn the_abi_rule_yields_to_the_machine_rule_where_both_witnesses_speak() {
        use crate::elf::ByteOrder::LittleEndian;
        // Both witnesses contradict: an x32 artifact beside an aarch64 one under an x86_64
        // read.
        let facts = shaped_machines(&[
            ("aa", "x86_64", 32, LittleEndian),
            ("bb", "aarch64", 64, LittleEndian),
        ]);
        let mut observations = gated_observations_under("x86_64");
        for o in &mut observations[8..] {
            o.build.as_mut().expect("a build").artifact_sha256 = Some("bb".to_owned());
        }
        let target = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifact_machines(&observations, &facts),
            &["__x86_64__".to_owned()],
            None,
        );
        assert_eq!(target.agreement, crate::toolchain::ArchAgreement::Disagrees);
        assert_eq!(
            target.abi.agreement,
            crate::toolchain::AbiAgreement::Disagrees
        );
        let withheld = withhold_on_contradicted_target(&mut observations, &target);
        assert_eq!(withheld, gated_check_ids());
        // The checks the aarch64 machine flips keep the machine rule, which names the
        // stronger contradiction; the one it does not flip (`pic-object-relocs`, measured on
        // both) takes the abi rule.
        let (by_machine, by_abi): (Vec<&Observation>, Vec<&Observation>) =
            observations.iter().partition(|o| {
                gate_contradicted_by(
                    &o.check,
                    "x86_64",
                    target.witnessed_machines(crate::probe::Lang::C),
                )
                .is_some()
            });
        assert!(
            by_machine.len() >= 2 && !by_abi.is_empty(),
            "{} by machine, {} by abi",
            by_machine.len(),
            by_abi.len()
        );
        for o in &by_machine {
            let gating = o.gating.as_ref().expect("withheld");
            assert_eq!(gating.rule, gating_rule::TARGET_CONTRADICTED, "{}", o.check);
            assert!(
                gating.reason.ends_with("(toolchain.target)"),
                "{}: {}",
                o.check,
                gating.reason
            );
        }
        for o in &by_abi {
            let gating = o.gating.as_ref().expect("withheld");
            assert_eq!(
                gating.rule,
                gating_rule::TARGET_ABI_CONTRADICTED,
                "{}",
                o.check
            );
            assert!(
                gating.reason.ends_with("(toolchain.target.abi)"),
                "{}: {}",
                o.check,
                gating.reason
            );
        }
        assert!(
            target_arch_agrees(Some(&target), None, false, &[], &observations, &facts).is_empty()
        );
        // Each diagnostic names its own checks: one list for both would make each claim
        // the other's.
        assert_eq!(
            withheld.under(gating_rule::TARGET_CONTRADICTED).len(),
            by_machine.len()
        );
        assert_eq!(
            withheld.under(gating_rule::TARGET_ABI_CONTRADICTED).len(),
            by_abi.len()
        );
        let diagnostics = target_witness_diagnostics(&target, &withheld);
        assert_eq!(diagnostics.len(), 2, "{diagnostics:?}");
        let machine_diag = &diagnostics[0].message;
        let abi_diag = &diagnostics[1].message;
        assert!(
            machine_diag.contains(&format!("{} verdict(s)", by_machine.len()))
                && by_machine.iter().all(|o| machine_diag.contains(&o.check))
                && !by_abi.iter().any(|o| machine_diag.contains(&o.check)),
            "{machine_diag}"
        );
        assert!(
            abi_diag.starts_with("toolchain.target.abi disagrees: ")
                && abi_diag.contains(&format!(
                    "{} verdict(s) are withheld as indeterminate under target-abi-contradicted",
                    by_abi.len()
                ))
                && by_abi.iter().all(|o| abi_diag.contains(&o.check))
                && !by_machine.iter().any(|o| abi_diag.contains(&o.check)),
            "{abi_diag}"
        );
    }

    #[test]
    fn the_abi_rule_takes_the_checks_the_machine_rule_leaves() {
        use crate::elf::ByteOrder::LittleEndian;
        // The machine disagrees and flips the few gates x86 decides otherwise, which keep
        // its rule; the abi rule takes the rest.
        let facts = shaped_machines(&[
            ("aa", "x86_64", 32, LittleEndian),
            ("bb", "i386", 32, LittleEndian),
        ]);
        let mut observations = gated_observations_under("x86_64");
        for o in &mut observations[8..] {
            o.build.as_mut().expect("a build").artifact_sha256 = Some("bb".to_owned());
        }
        let target = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifact_machines(&observations, &facts),
            &["__x86_64__".to_owned()],
            None,
        );
        assert_eq!(target.agreement, crate::toolchain::ArchAgreement::Disagrees);
        assert_eq!(
            target.abi.agreement,
            crate::toolchain::AbiAgreement::Disagrees
        );
        assert_eq!(
            withhold_on_contradicted_target(&mut observations, &target),
            gated_check_ids()
        );
        let (by_machine, by_abi): (Vec<&Observation>, Vec<&Observation>) =
            observations.iter().partition(|o| {
                gate_contradicted_by(
                    &o.check,
                    "x86_64",
                    target.witnessed_machines(crate::probe::Lang::C),
                )
                .is_some()
            });
        assert!(
            !by_machine.is_empty() && by_abi.len() >= 2,
            "{} by machine, {} by abi",
            by_machine.len(),
            by_abi.len()
        );
        for o in by_machine {
            assert_eq!(
                o.gating.as_ref().expect("withheld").rule,
                gating_rule::TARGET_CONTRADICTED,
                "{}",
                o.check
            );
        }
        for o in by_abi {
            assert_eq!(
                o.gating.as_ref().expect("withheld").rule,
                gating_rule::TARGET_ABI_CONTRADICTED,
                "{}",
                o.check
            );
        }
        assert!(
            target_arch_agrees(Some(&target), None, false, &[], &observations, &facts).is_empty()
        );
    }

    #[test]
    fn a_published_abi_the_facts_do_not_give_is_refused() {
        use crate::elf::ByteOrder::LittleEndian;
        let facts = shaped_machines(&[("aa", "x86_64", 32, LittleEndian)]);
        let observations = [artifact_observation("link-defaults", "pie", "aa")];
        let mut target = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifact_machines(&observations, &facts),
            &[],
            None,
        );
        assert_eq!(
            target.abi.agreement,
            crate::toolchain::AbiAgreement::Disagrees
        );
        // Forge the block to say the artifacts agree.
        let honest = target.clone();
        target.abi.agreement = crate::toolchain::AbiAgreement::Agrees;
        target.abi.artifacts.clear();
        target
            .abi
            .artifacts
            .insert("ELF64 little-endian".to_owned(), 1);
        let out = target_arch_agrees(Some(&target), None, false, &[], &observations, &facts);
        assert!(
            out.iter().any(|c| c.property == "toolchain.target.abi"),
            "{out:?}"
        );
        // Each of the block's facts is held on its own: a dump the witness did not read, and
        // another expected width, are refused too (no other test fails if either is dropped
        // from the comparison).
        let refused = |forged: &crate::toolchain::TargetArch| {
            target_arch_agrees(Some(forged), None, false, &[], &observations, &facts)
                .iter()
                .any(|c| c.property == "toolchain.target.abi")
        };
        assert!(!refused(&honest), "the honest block stands");
        let mut dumps = honest.clone();
        dumps.abi.dumps.insert(
            "intrinsic macro dump".to_owned(),
            crate::toolchain::Abi {
                class: 32,
                order: LittleEndian,
            },
        );
        assert!(refused(&dumps), "a dump the witness did not read");
        let mut expected = honest.clone();
        expected.abi.expected = Some(crate::toolchain::Abi {
            class: 32,
            order: LittleEndian,
        });
        assert!(refused(&expected), "another expected width");
    }

    #[test]
    fn a_published_dump_width_the_dump_does_not_name_is_refused() {
        use crate::elf::ByteOrder::LittleEndian;
        let facts = FactStore::default();
        let observations: Vec<Observation> = Vec::new();
        let dump: BTreeMap<String, String> = [
            ("__x86_64__", "1"),
            ("__SIZEOF_POINTER__", "4"),
            ("__BYTE_ORDER__", "__ORDER_LITTLE_ENDIAN__"),
            ("__GNUC__", "16"),
        ]
        .into_iter()
        .map(|(k, v)| (k.to_owned(), v.to_owned()))
        .collect();
        let honest = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &[],
            &["__x86_64__".to_owned()],
            None,
        )
        .with_intrinsic_abi(Some(crate::toolchain::Abi {
            class: 32,
            order: LittleEndian,
        }));
        let on_abi = |t: &crate::toolchain::TargetArch,
                      dump: Option<&BTreeMap<String, String>>,
                      partial: bool| {
            target_arch_agrees(Some(t), dump, partial, &[], &observations, &facts)
                .into_iter()
                .filter(|c| c.property == "toolchain.target.macros.abi")
                .count()
        };
        assert_eq!(on_abi(&honest, Some(&dump), false), 0);
        let forged = honest
            .clone()
            .with_intrinsic_abi(Some(crate::toolchain::Abi {
                class: 64,
                order: LittleEndian,
            }));
        let mut forged = forged;
        forged.abi.agreement = crate::toolchain::AbiAgreement::Agrees;
        assert_eq!(
            on_abi(&forged, Some(&dump), false),
            1,
            "the dump names 4, the witness 8"
        );
        // A partial dump that still names both macros is held; one that names neither is not.
        assert_eq!(on_abi(&forged, Some(&dump), true), 1);
        let mut silent = dump.clone();
        silent.remove("__SIZEOF_POINTER__");
        assert_eq!(on_abi(&forged, Some(&silent), true), 0);
        assert_eq!(
            on_abi(&forged, None, false),
            0,
            "no dump published: nothing to hold"
        );
    }

    /// The three read families the gates name, each with its macro and `e_machine`.
    const FAMILIES: [(&str, &str, &str); 3] = [
        ("x86_64", "__x86_64__", "x86_64"),
        ("x86", "__i386__", "i386"),
        ("aarch64", "__aarch64__", "aarch64"),
    ];

    #[test]
    fn a_dump_outside_the_table_withholds_every_gated_check() {
        use crate::toolchain::{
            ArchAgreement, ArchSource, MacroAgreement, OUTSIDE_ARCH_MACROS, ProfileDump,
            target_agreement,
        };
        let silenced = || ProfileDump {
            abi: None,
            flags: vec!["--target=riscv64-linux-gnu".to_owned()],
            exit_status: 0,
            stdout_unterminated: false,
            macros_defined: 200,
            defined: Vec::new(),
        };
        let no_elf = machines(&[]);
        let mut held = 0;
        for (arch, own_macro, _) in FAMILIES {
            let witnesses: [(&str, ArchSource, Vec<String>, Option<ProfileDump>); 3] = [
                (
                    "the dump under the profile's flags",
                    ArchSource::Dumpmachine,
                    vec![own_macro.to_owned()],
                    Some(silenced()),
                ),
                (
                    "the flagless dump, the gate read from the kernel",
                    ArchSource::Kernel,
                    Vec::new(),
                    None,
                ),
                (
                    "the flagless dump, the gate read from -dumpmachine",
                    ArchSource::Dumpmachine,
                    Vec::new(),
                    None,
                ),
            ];
            for (name, source, flagless, profile) in witnesses {
                let flags: Vec<String> =
                    profile.as_ref().map_or_else(Vec::new, |p| p.flags.clone());
                let target = target_agreement(arch, source, &[], &flagless, profile.as_ref());
                assert_eq!(target.agreement, ArchAgreement::NoElfArtifact);
                let witness = match &target.profile_macros {
                    Some(p) => &p.witness,
                    None => &target.macros,
                };
                assert_eq!(
                    witness.agreement,
                    MacroAgreement::Disagrees,
                    "{arch}, {name}: {}",
                    witness.evidence
                );
                assert!(
                    target
                        .witnessed_machines(crate::probe::Lang::C)
                        .any(|m| m == OUTSIDE_ARCH_MACROS),
                    "{arch}, {name}: the witness names a machine outside the table"
                );
                assert_outside_witness_withholds_every_gated_check(
                    arch,
                    name,
                    &target,
                    &flags,
                    &no_elf,
                    "defines none of __x86_64__, __i386__, __aarch64__",
                );
                held += 1;
            }
        }
        assert_eq!(held, 9, "three read families, three dump witnesses each");
    }

    #[test]
    fn an_artifact_outside_the_table_withholds_every_gated_check() {
        use crate::toolchain::{ArchAgreement, ArchSource, MacroAgreement, target_agreement};
        for (arch, own_macro, _) in FAMILIES {
            let outside = machines(&[("aa", "riscv")]);
            let artifacts = artifact_machines(&gated_observations_under(arch), &outside);
            assert_eq!(artifacts.len(), 1, "{arch}: one artifact, by digest");
            let target = target_agreement(
                arch,
                ArchSource::Dumpmachine,
                &artifacts,
                &[own_macro.to_owned()],
                None,
            );
            assert_eq!(
                target.agreement,
                ArchAgreement::Disagrees,
                "{}",
                target.evidence
            );
            assert_eq!(target.macros.agreement, MacroAgreement::Agrees);
            assert_outside_witness_withholds_every_gated_check(
                arch,
                "an artifact of riscv",
                &target,
                &[],
                &outside,
                "e_machine riscv",
            );
        }
    }

    #[test]
    fn a_witness_of_the_read_family_moves_nothing() {
        use crate::toolchain::{ArchAgreement, ArchSource, target_agreement};
        for (arch, own_macro, family) in FAMILIES {
            let mut observations = gated_observations_under(arch);
            let facts = machines(&[("aa", family)]);
            let target = target_agreement(
                arch,
                ArchSource::Dumpmachine,
                &artifact_machines(&observations, &facts),
                &[own_macro.to_owned()],
                None,
            );
            assert_eq!(
                target.agreement,
                ArchAgreement::Agrees,
                "{}",
                target.evidence
            );
            assert!(
                withhold_on_contradicted_target(&mut observations, &target).is_empty(),
                "{arch}: every witness is of the read family"
            );
            assert!(
                target_arch_agrees(Some(&target), None, false, &[], &observations, &facts)
                    .is_empty()
            );
        }
    }

    /// The dump under a profile carrying `-undef`: it defines none of the three while
    /// every macro it would otherwise define is suppressed.
    fn silenced_dump() -> crate::toolchain::ProfileDump {
        crate::toolchain::ProfileDump {
            abi: None,
            flags: vec!["-undef".to_owned(), "-O2".to_owned()],
            exit_status: 0,
            stdout_unterminated: false,
            macros_defined: 15,
            defined: Vec::new(),
        }
    }

    #[test]
    fn a_dump_naming_another_family_is_not_overruled_by_agreeing_artifacts() {
        use crate::toolchain::{ArchAgreement, ArchSource, MacroAgreement, target_agreement};
        let forged = crate::toolchain::ProfileDump {
            abi: None,
            flags: vec!["-D__aarch64__=1".to_owned(), "-O2".to_owned()],
            exit_status: 0,
            stdout_unterminated: false,
            macros_defined: 350,
            defined: vec!["__aarch64__".to_owned()],
        };
        let mut observations = gated_observations_under("x86_64");
        let facts = machines(&[("aa", "x86_64")]);
        let target = target_agreement(
            "x86_64",
            ArchSource::Dumpmachine,
            &artifact_machines(&observations, &facts),
            &["__x86_64__".to_owned()],
            Some(&forged),
        );
        assert_eq!(target.agreement, ArchAgreement::Agrees);
        let profile = target.profile_macros.as_ref().expect("taken");
        assert_eq!(
            profile.witness.agreement,
            MacroAgreement::Disagrees,
            "{}",
            profile.witness.evidence
        );
        assert_eq!(
            profile.witness.machines().collect::<Vec<_>>(),
            ["aarch64"],
            "the forged macro names its machine"
        );
        let flipped: Vec<String> = gated_check_ids()
            .into_iter()
            .filter(|c| gate_outcome(c, "x86_64") != gate_outcome(c, "aarch64"))
            .collect();
        assert!(
            !flipped.is_empty(),
            "some check's gate outcome differs between x86_64 and aarch64"
        );
        let withheld = withhold_on_contradicted_target(&mut observations, &target);
        assert_eq!(
            withheld, flipped,
            "every check whose gate decides otherwise under aarch64 is withheld"
        );
        assert!(
            target_arch_agrees(
                Some(&target),
                None,
                false,
                &forged.flags,
                &observations,
                &facts
            )
            .is_empty()
        );
    }

    #[test]
    fn an_overruled_dump_is_published_as_overruled_and_not_as_a_contradiction() {
        use crate::toolchain::{ArchSource, MacroAgreement, target_agreement};
        let observations = gated_observations_under("x86_64");
        let facts = machines(&[("aa", "x86_64")]);
        let artifacts = artifact_machines(&observations, &facts);
        let flagless = ["__x86_64__".to_owned()];

        let overruled = target_agreement(
            "x86_64",
            ArchSource::Dumpmachine,
            &artifacts,
            &flagless,
            Some(&silenced_dump()),
        );
        assert_eq!(
            overruled
                .profile_macros
                .as_ref()
                .map(|p| p.witness.agreement),
            Some(MacroAgreement::Overruled)
        );
        let published = target_witness_diagnostics(&overruled, &TargetWithholding::default());
        assert_eq!(published.len(), 1, "{published:?}");
        assert_eq!(published[0].severity, Severity::Warning);
        assert_eq!(published[0].context.as_deref(), Some("toolchain.target"));
        assert!(
            published[0]
                .message
                .starts_with("a macro dump defining none of the architecture macros is overruled")
                && published[0].message.contains("under the profile's C flags")
                && !published[0].message.contains("contradicts")
                && !published[0].message.contains("no verdict moved"),
            "{}",
            published[0].message
        );

        let agreeing = target_agreement(
            "x86_64",
            ArchSource::Dumpmachine,
            &artifacts,
            &flagless,
            None,
        );
        assert!(
            target_witness_diagnostics(&agreeing, &TargetWithholding::default()).is_empty(),
            "agreeing artifacts yield no witness diagnostic"
        );

        // A disagreeing flagless dump beside the overruled profile dump: the error names
        // the flagless dump alone, and the overruled dump keeps its own warning.
        let mut crossed = overruled.clone();
        crossed.macros.agreement = MacroAgreement::Disagrees;
        crossed.macros.evidence = "the flagless dump defines __aarch64__".to_owned();
        let mut pie = TargetWithholding::default();
        pie.push("pie".to_owned(), gating_rule::TARGET_CONTRADICTED);
        let published = target_witness_diagnostics(&crossed, &pie);
        assert_eq!(published.len(), 2, "{published:?}");
        assert_eq!(published[0].severity, Severity::Error);
        assert!(
            published[0]
                .message
                .contains("the flagless dump defines __aarch64__")
                && !published[0].message.contains("under the profile's C flags")
                && published[0].message.contains("1 verdict(s)")
                && published[0].message.ends_with("pie"),
            "{}",
            published[0].message
        );
        assert_eq!(published[1].severity, Severity::Warning);
    }

    #[test]
    fn an_agreeing_artifact_witness_overrules_a_dump_that_defines_no_arch_macro() {
        use crate::toolchain::{ArchAgreement, ArchSource, MacroAgreement, target_agreement};
        let flags = ["-undef".to_owned(), "-O2".to_owned()];
        let true_unsupported: std::collections::BTreeSet<&str> = [
            "branch-protection-macro",
            "branch-protection-marked",
            "gcs-macro",
            "gcs-marked",
            "pac-ret-enforced",
        ]
        .into();

        let mut observations = gated_observations_under("x86_64");
        let facts = machines(&[("aa", "x86_64")]);
        let artifacts = artifact_machines(&observations, &facts);
        assert_eq!(artifacts.len(), 1, "one artifact, by digest");
        let target = target_agreement(
            "x86_64",
            ArchSource::Dumpmachine,
            &artifacts,
            &["__x86_64__".to_owned()],
            Some(&silenced_dump()),
        );
        assert_eq!(
            target.agreement,
            ArchAgreement::Agrees,
            "{}",
            target.evidence
        );
        let profile = target
            .profile_macros
            .as_ref()
            .expect("the dump under the flags");
        assert_eq!(
            profile.witness.agreement,
            MacroAgreement::Overruled,
            "{}",
            profile.witness.evidence
        );
        assert_eq!(profile.witness.defined, Vec::<String>::new());
        // The witness list is the artifacts' machines, then the flagless dump's, then
        // the profile dump's; the overruled dump adds nothing.
        assert_eq!(target.machines.keys().collect::<Vec<_>>(), ["x86_64"]);
        assert_eq!(target.macros.machines().collect::<Vec<_>>(), ["x86_64"]);
        assert_eq!(
            profile.witness.machines().count(),
            0,
            "an overruled dump names no machine"
        );
        assert_eq!(
            target
                .witnessed_machines(crate::probe::Lang::C)
                .collect::<Vec<_>>(),
            ["x86_64", "x86_64"]
        );
        assert!(
            target_arch_agrees(Some(&target), None, false, &flags, &observations, &facts)
                .is_empty()
        );
        assert!(withhold_on_contradicted_target(&mut observations, &target).is_empty());
        let unsupported: std::collections::BTreeSet<&str> = observations
            .iter()
            .filter(|o| o.verdict == Verdict::Unsupported)
            .map(|o| o.check.as_str())
            .collect();
        assert_eq!(unsupported, true_unsupported, "the true unsupported stand");
        assert_eq!(
            observations
                .iter()
                .filter(|o| o.verdict == Verdict::On)
                .count(),
            12,
            "the measured verdicts stand"
        );
        assert!(
            target_arch_agrees(Some(&target), None, false, &flags, &observations, &facts)
                .is_empty()
        );

        // A published `disagrees` the run's own artifacts overrule is refused.
        let mut forged = target.clone();
        forged
            .profile_macros
            .as_mut()
            .expect("the dump under the flags")
            .witness
            .agreement = MacroAgreement::Disagrees;
        assert_eq!(
            target_arch_agrees(Some(&forged), None, false, &flags, &observations, &facts).len(),
            1,
            "a published agreement its artifacts do not give is refused"
        );
    }

    #[test]
    fn a_silenced_dump_is_overruled_only_by_artifacts_of_the_read_family() {
        use crate::toolchain::{ArchAgreement, ArchSource, MacroAgreement, target_agreement};
        let flags = ["-undef".to_owned(), "-O2".to_owned()];

        // Beside no artifact, the dump is the one witness and stands.
        let mut alone = gated_observations_under("x86_64");
        let no_elf = machines(&[]);
        let target = target_agreement(
            "x86_64",
            ArchSource::Dumpmachine,
            &[],
            &["__x86_64__".to_owned()],
            Some(&silenced_dump()),
        );
        assert_eq!(target.agreement, ArchAgreement::NoElfArtifact);
        assert_eq!(
            target.profile_macros.as_ref().map(|p| p.witness.agreement),
            Some(MacroAgreement::Disagrees)
        );
        assert_eq!(
            withhold_on_contradicted_target(&mut alone, &target).len(),
            18
        );
        assert!(target_arch_agrees(Some(&target), None, false, &flags, &alone, &no_elf).is_empty());

        // Beside artifacts of another family, the dump and the artifacts agree against the
        // premise, and nothing overrules either.
        let mut crossed = gated_observations_under("x86_64");
        let aarch64 = machines(&[("aa", "aarch64")]);
        let target = target_agreement(
            "x86_64",
            ArchSource::Dumpmachine,
            &artifact_machines(&crossed, &aarch64),
            &["__x86_64__".to_owned()],
            Some(&silenced_dump()),
        );
        assert_eq!(target.agreement, ArchAgreement::Disagrees);
        assert_eq!(
            target.profile_macros.as_ref().map(|p| p.witness.agreement),
            Some(MacroAgreement::Disagrees)
        );
        assert_eq!(
            withhold_on_contradicted_target(&mut crossed, &target).len(),
            18
        );
        assert!(
            target_arch_agrees(Some(&target), None, false, &flags, &crossed, &aarch64).is_empty()
        );

        // The flagless dump is overruled by the same rule: the gate read the kernel, the
        // dump defined none of the three, and every artifact is of the read family.
        let mut flagless = gated_observations_under("x86_64");
        let facts = machines(&[("aa", "x86_64")]);
        let target = target_agreement(
            "x86_64",
            ArchSource::Kernel,
            &artifact_machines(&flagless, &facts),
            &[],
            None,
        );
        assert_eq!(target.agreement, ArchAgreement::Agrees);
        assert_eq!(
            target.macros.agreement,
            MacroAgreement::Overruled,
            "{}",
            target.macros.evidence
        );
        assert!(target.macros.evidence.contains("kernel"));
        assert_eq!(target.macros.machines().count(), 0);
        assert!(withhold_on_contradicted_target(&mut flagless, &target).is_empty());
        assert!(target_arch_agrees(Some(&target), None, false, &[], &flagless, &facts).is_empty());
        let mut forged = target.clone();
        forged.macros.agreement = MacroAgreement::Disagrees;
        assert_eq!(
            target_arch_agrees(Some(&forged), None, false, &[], &flagless, &facts).len(),
            1
        );
    }

    #[test]
    fn a_dump_with_no_arch_macro_withholds_every_gated_check() {
        let mut observations = vec![
            artifact_observation("toolchain-macros", "cet-macro", "aa"),
            artifact_observation("toolchain-macros", "branch-protection-macro", "aa"),
            artifact_observation("link-defaults", "pie", "aa"),
        ];
        let facts = machines(&[]);
        let absent = crate::toolchain::target_agreement(
            "aarch64",
            crate::toolchain::ArchSource::Dumpmachine,
            &[],
            &[],
            None,
        );
        assert_eq!(
            absent.macros.agreement,
            crate::toolchain::MacroAgreement::Disagrees,
            "{}",
            absent.macros.evidence
        );
        assert_eq!(
            target_arch_agrees(Some(&absent), None, false, &[], &observations, &facts).len(),
            2,
            "both gated verdicts stand over a contradicted premise"
        );
        let mut forged = absent.clone();
        forged.macros.agreement = crate::toolchain::MacroAgreement::NoArchMacro;
        assert!(
            !target_arch_agrees(Some(&forged), None, false, &[], &observations, &facts).is_empty(),
            "an absence published as no-arch-macro is refused"
        );
        let withheld = withhold_on_contradicted_target(&mut observations, &absent);
        assert_eq!(withheld, ["cet-macro", "branch-protection-macro"]);
        for (o, decided) in observations[..2].iter().zip(["gated out", "measured"]) {
            let reason = &o.gating.as_ref().expect("withheld").reason;
            assert!(
                reason.contains("macro dump defines none of __x86_64__")
                    && reason.contains(&format!("it was {decided} for aarch64")),
                "{}: the reason names the absence and the decision it contradicts: {reason}",
                o.check
            );
        }
        assert_eq!(
            observations[2].verdict,
            Verdict::On,
            "a portable check stands"
        );
        assert!(
            target_arch_agrees(Some(&absent), None, false, &[], &observations, &facts).is_empty()
        );
    }

    #[test]
    fn the_macro_witness_withholds_where_no_artifact_was_read() {
        let mut observations = vec![
            artifact_observation("toolchain-macros", "cet-macro", "aa"),
            artifact_observation("toolchain-macros", "branch-protection-macro", "aa"),
            artifact_observation("link-defaults", "pie", "aa"),
        ];
        let facts = machines(&[]);
        assert!(
            artifact_machines(&observations, &facts).is_empty(),
            "where no artifact was read, no machine is named"
        );
        let lie = crate::toolchain::target_agreement(
            "aarch64",
            crate::toolchain::ArchSource::Dumpmachine,
            &[],
            &["__x86_64__".to_owned()],
            None,
        );
        assert_eq!(
            lie.agreement,
            crate::toolchain::ArchAgreement::NoElfArtifact
        );
        assert_eq!(
            lie.macros.agreement,
            crate::toolchain::MacroAgreement::Disagrees,
            "{}",
            lie.macros.evidence
        );
        assert_eq!(
            target_arch_agrees(Some(&lie), None, false, &[], &observations, &facts).len(),
            2,
            "both gated verdicts stand over a contradicted premise before the withholding"
        );
        let withheld = withhold_on_contradicted_target(&mut observations, &lie);
        assert_eq!(withheld, ["cet-macro", "branch-protection-macro"]);
        let reason = &observations[0].gating.as_ref().expect("withheld").reason;
        assert!(
            reason.contains("macro dump defines __x86_64__, the macro of e_machine x86_64"),
            "the reason names the witness: {reason}"
        );
        assert_eq!(
            observations[2].verdict,
            Verdict::On,
            "a portable check stands"
        );
        assert!(target_arch_agrees(Some(&lie), None, false, &[], &observations, &facts).is_empty());

        let mut forged = lie.clone();
        forged.macros.agreement = crate::toolchain::MacroAgreement::Agrees;
        assert_eq!(
            target_arch_agrees(Some(&forged), None, false, &[], &observations, &facts).len(),
            1,
            "a published macro agreement its macros do not give is refused"
        );
        let dump: BTreeMap<String, String> = [("__aarch64__".to_owned(), "1".to_owned())].into();
        assert_eq!(
            target_arch_agrees(Some(&lie), Some(&dump), false, &[], &observations, &facts).len(),
            1,
            "published macros the published dump does not define are refused"
        );

        let honest = crate::toolchain::target_agreement(
            "aarch64",
            crate::toolchain::ArchSource::Dumpmachine,
            &[],
            &["__aarch64__".to_owned()],
            None,
        );
        assert_eq!(
            honest.macros.agreement,
            crate::toolchain::MacroAgreement::Agrees
        );
        let mut untouched = vec![artifact_observation(
            "toolchain-macros",
            "branch-protection-macro",
            "aa",
        )];
        assert!(withhold_on_contradicted_target(&mut untouched, &honest).is_empty());
        assert!(
            target_arch_agrees(Some(&honest), Some(&dump), false, &[], &untouched, &facts)
                .is_empty()
        );
    }

    #[test]
    fn the_gate_source_is_rederived_from_the_published_fields() {
        let cross = crate::toolchain::ProfileDump {
            abi: None,
            flags: vec!["--target=aarch64-linux-gnu".to_owned()],
            exit_status: 0,
            stdout_unterminated: false,
            macros_defined: 400,
            defined: vec!["__aarch64__".to_owned()],
        };
        let triple = Some("x86_64-redhat-linux");
        let (arch, source) = crate::toolchain::gate_target(triple, Some(&cross), "x86_64");
        let flagless = ["__x86_64__".to_owned()];
        let gated = crate::toolchain::target_agreement(&arch, source, &[], &flagless, Some(&cross));
        assert!(target_source_agrees(Some(&gated), triple, "x86_64").is_empty());
        assert!(target_source_agrees(None, triple, "x86_64").is_empty());

        let mut relabelled = gated.clone();
        relabelled.source = crate::toolchain::ArchSource::Dumpmachine;
        assert_eq!(
            target_source_agrees(Some(&relabelled), triple, "x86_64").len(),
            1
        );
        let flagless_gate = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &[],
            &flagless,
            Some(&cross),
        );
        let refused = target_source_agrees(Some(&flagless_gate), triple, "x86_64");
        assert_eq!(refused.len(), 1, "the dump resolves the selection");
        assert_eq!(refused[0].property, "toolchain.target.arch");
        let mut forged = flagless_gate.clone();
        forged.source = crate::toolchain::ArchSource::ProfileMacros;
        assert_eq!(
            target_source_agrees(Some(&forged), triple, "x86_64").len(),
            1,
            "a profile-macros label over an arch the dump does not name"
        );
        let mut unselected = gated.clone();
        if let Some(p) = unselected.profile_macros.as_mut() {
            p.flags = vec!["-O2".to_owned()];
        }
        assert_eq!(
            target_source_agrees(Some(&unselected), triple, "x86_64").len(),
            1,
            "flags that select no target leave the gate on -dumpmachine"
        );

        let mut observations = vec![artifact_observation("link-defaults", "cet-marked", "aa")];
        let facts = machines(&[("aa", "x86_64")]);
        let flags = cross.flags.clone();
        let target = crate::toolchain::target_agreement(
            &arch,
            source,
            &artifact_machines(&observations, &facts),
            &flagless,
            Some(&cross),
        );
        assert_eq!(target.agreement, crate::toolchain::ArchAgreement::Disagrees);
        assert!(
            !target_arch_agrees(Some(&target), None, false, &flags, &observations, &facts)
                .is_empty(),
            "a verdict gated on aarch64 over an x86_64 artifact is refused"
        );
        assert_eq!(
            withhold_on_contradicted_target(&mut observations, &target),
            ["cet-marked"]
        );
        assert!(
            target_arch_agrees(Some(&target), None, false, &flags, &observations, &facts)
                .is_empty()
        );
    }

    #[test]
    fn the_profile_dump_withholds_where_no_artifact_was_read() {
        let mut observations = vec![
            artifact_observation("link-defaults", "cet-marked", "aa"),
            artifact_observation("shared-object-defaults", "nodlopen", "aa"),
        ];
        let facts = machines(&[]);
        let flags = vec!["--target=aarch64-linux-gnu".to_owned()];
        let dump = crate::toolchain::ProfileDump {
            abi: None,
            flags: flags.clone(),
            exit_status: 0,
            stdout_unterminated: false,
            macros_defined: 350,
            defined: vec!["__aarch64__".to_owned()],
        };
        let target = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &[],
            &["__x86_64__".to_owned()],
            Some(&dump),
        );
        assert_eq!(
            target.macros.agreement,
            crate::toolchain::MacroAgreement::Agrees
        );
        assert_eq!(
            target_arch_agrees(Some(&target), None, false, &flags, &observations, &facts).len(),
            1,
            "cet-marked stands over a contradicted premise before the withholding"
        );
        let withheld = withhold_on_contradicted_target(&mut observations, &target);
        assert_eq!(withheld, ["cet-marked"]);
        let reason = &observations[0].gating.as_ref().expect("withheld").reason;
        assert!(
            reason.contains("under the profile's C flags defines __aarch64__"),
            "the reason names the witness: {reason}"
        );
        assert!(
            target_arch_agrees(Some(&target), None, false, &flags, &observations, &facts)
                .is_empty()
        );

        // Published exactly where the profile gives C flags, and under those flags.
        for (published, profile) in [
            (Some(&target), &[][..]),
            (Some(&target), &["-m64".to_owned()][..]),
        ] {
            assert_eq!(
                target_arch_agrees(published, None, false, profile, &observations, &facts)
                    .iter()
                    .filter(|c| c.property == "toolchain.target.profile_macros")
                    .count(),
                1,
                "{profile:?}"
            );
        }
        let mut dropped = target.clone();
        dropped.profile_macros = None;
        assert!(
            target_arch_agrees(Some(&dropped), None, false, &flags, &observations, &facts)
                .iter()
                .any(|c| c.property == "toolchain.target.profile_macros"),
            "a report that dropped the witness is refused"
        );

        let mut forged = target.clone();
        if let Some(p) = forged.profile_macros.as_mut() {
            p.witness.agreement = crate::toolchain::MacroAgreement::Agrees;
        }
        assert!(
            target_arch_agrees(Some(&forged), None, false, &flags, &observations, &facts)
                .iter()
                .any(|c| c.property == "toolchain.target.profile_macros"),
            "an agreement its dump does not give is refused"
        );
        let mut silenced = target.clone();
        if let Some(p) = silenced.profile_macros.as_mut() {
            p.exit_status = 1;
        }
        assert!(
            target_arch_agrees(Some(&silenced), None, false, &flags, &observations, &facts)
                .iter()
                .any(|c| c.property == "toolchain.target.profile_macros"),
            "a failed dump publishing a disagreement is refused"
        );
    }

    #[test]
    fn artifact_machines_carry_the_probes_language() {
        use crate::probe::Lang;
        use crate::toolchain::{ArchSource, MacroAgreement, ProfileDump, target_agreement};
        let c = artifact_observation("shared-object-defaults", "textrel-absent", "aa");
        let cxx = artifact_observation("cxx-stdlib-assertions", "cxx-hardening-requested", "bb");
        let facts = machines(&[("aa", "x86_64"), ("bb", "x86_64")]);
        let both = artifact_machines(&[c.clone(), cxx.clone()], &facts);
        assert_eq!(
            both.iter().map(|a| a.lang).collect::<Vec<_>>(),
            [Some(Lang::C), Some(Lang::Cxx)],
            "{both:?}"
        );
        let silent = ProfileDump {
            abi: None,
            flags: vec!["--target=riscv64-linux-gnu".to_owned(), "-O2".to_owned()],
            exit_status: 0,
            stdout_unterminated: false,
            macros_defined: 200,
            defined: Vec::new(),
        };
        let held = |observations: &[Observation]| {
            let artifacts = artifact_machines(observations, &facts);
            target_agreement(
                "x86_64",
                ArchSource::Dumpmachine,
                &artifacts,
                &["__x86_64__".to_owned()],
                None,
            )
            .with_cxx_dump(Some(&silent), &artifacts)
            .profile_macros_cxx
            .expect("taken")
            .witness
            .agreement
        };
        assert_eq!(held(std::slice::from_ref(&c)), MacroAgreement::Disagrees);
        assert_eq!(held(&[c, cxx]), MacroAgreement::Overruled);
    }

    #[test]
    fn the_cxx_dump_is_held_to_the_cxx_probes_and_the_cxx_flags() {
        let mut observations = vec![
            artifact_observation("shared-object-defaults", "textrel-absent", "aa"),
            artifact_observation("cxx-stdlib-assertions", "cxx-hardening-requested", "bb"),
        ];
        let facts = machines(&[]);
        let c_flags = vec!["-O2".to_owned()];
        let cxx_flags = vec!["--target=aarch64-linux-gnu".to_owned()];
        let dump = |flags: &[String], defined: &str| crate::toolchain::ProfileDump {
            abi: None,
            flags: flags.to_vec(),
            exit_status: 0,
            stdout_unterminated: false,
            macros_defined: 350,
            defined: vec![defined.to_owned()],
        };
        let target = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &[],
            &["__x86_64__".to_owned()],
            Some(&dump(&c_flags, "__x86_64__")),
        )
        .with_cxx_dump(Some(&dump(&cxx_flags, "__aarch64__")), &[]);
        assert!(
            withhold_on_contradicted_target(&mut observations, &target).is_empty(),
            "a C++ witness withholds no C probe's verdict"
        );
        assert!(
            target_arch_agrees(Some(&target), None, false, &c_flags, &observations, &facts)
                .is_empty()
        );

        let mut forged = target.clone();
        if let Some(p) = forged.profile_macros_cxx.as_mut() {
            p.witness.agreement = crate::toolchain::MacroAgreement::Agrees;
        }
        assert!(
            target_arch_agrees(Some(&forged), None, false, &c_flags, &observations, &facts)
                .iter()
                .any(|c| c.property == "toolchain.target.profile_macros_cxx"),
            "an agreement its dump does not give is refused"
        );

        // Published exactly where a C++ driver exists and the C++ flags differ, and under
        // those flags.
        let presence = |t: &crate::toolchain::TargetArch, c: &[String], cxx: &[String], driver| {
            profile_cxx_witness_agrees(Some(t), c, cxx, driver).len()
        };
        assert_eq!(presence(&target, &c_flags, &cxx_flags, true), 0);
        assert_eq!(
            presence(&target, &c_flags, &cxx_flags, false),
            1,
            "no C++ driver, no C++ dump"
        );
        assert_eq!(
            presence(&target, &c_flags, &c_flags, true),
            1,
            "equal flags, no C++ dump"
        );
        assert_eq!(
            presence(&target, &c_flags, &["-m64".to_owned()], true),
            1,
            "other flags"
        );
        let mut dropped = target.clone();
        dropped.profile_macros_cxx = None;
        assert_eq!(
            presence(&dropped, &c_flags, &cxx_flags, true),
            1,
            "a report that dropped the witness is refused"
        );
        assert_eq!(presence(&dropped, &c_flags, &cxx_flags, false), 0);
        assert!(profile_cxx_witness_agrees(None, &c_flags, &cxx_flags, true).is_empty());
    }

    #[test]
    fn a_partial_dump_is_held_only_to_the_macros_it_defines() {
        let observations = vec![artifact_observation("toolchain-macros", "cet-macro", "aa")];
        let facts = machines(&[]);
        let honest = crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &[],
            &["__x86_64__".to_owned()],
            None,
        );
        let empty = BTreeMap::new();
        for errored in [false, true] {
            assert!(
                target_arch_agrees(
                    Some(&honest),
                    Some(&empty),
                    errored,
                    &[],
                    &observations,
                    &facts
                )
                .is_empty(),
                "an empty dump (errored = {errored}) contradicts nothing"
            );
        }
        let gnuc_only: BTreeMap<String, String> = [("__GNUC__".to_owned(), "16".to_owned())].into();
        assert!(
            target_arch_agrees(
                Some(&honest),
                Some(&gnuc_only),
                true,
                &[],
                &observations,
                &facts
            )
            .is_empty(),
            "an errored dump lacking the architecture macro contradicts nothing"
        );
        assert_eq!(
            target_arch_agrees(
                Some(&honest),
                Some(&gnuc_only),
                false,
                &[],
                &observations,
                &facts
            )
            .len(),
            1,
            "a completed dump lacking the architecture macro is refused"
        );
        let other: BTreeMap<String, String> = [("__aarch64__".to_owned(), "1".to_owned())].into();
        assert_eq!(
            target_arch_agrees(
                Some(&honest),
                Some(&other),
                true,
                &[],
                &observations,
                &facts
            )
            .len(),
            1,
            "an errored dump defining an architecture macro outside `defined` is refused"
        );
    }

    #[test]
    fn a_check_this_isa_does_not_have_is_not_a_missing_measurement() {
        let arm = |outcome: Outcome| ControlArm {
            flags: Vec::new(),
            outcome: Some(outcome),
            detail: None,
            build: None,
            run: None,
            macro_source: None,
            macro_dump: None,
            decoded: None,
            overridden: None,
        };
        let discriminating = |mut o: Observation| {
            o.controls = Some(Controls {
                positive: arm(Outcome::Present),
                negative: arm(Outcome::Absent),
                regime_negative: None,
                discrimination: Discrimination::Discriminating,
            });
            o
        };
        let gated = |check: &str, arch: Option<&str>, libc: Option<&str>| {
            let mut o = observation(check, "-mflag", Channel::Macro, Verdict::Unsupported);
            o.gating = Some(Gating {
                // As production gates: `libc_limitation` publishes its own rule.
                rule: if libc.is_some() {
                    gating_rule::LIBC_DECLARED
                } else {
                    gating_rule::ARCH
                },
                arch: arch.map(str::to_owned),
                libc: libc.map(str::to_owned),
                needs_vm: false,
                reason: "gated".to_owned(),
            });
            o
        };

        let off_arch = vec![
            discriminating(observation("a", "-Da", Channel::Macro, Verdict::On)),
            discriminating(observation("b", "-Db", Channel::Macro, Verdict::Off)),
            gated("branch-protection-macro", Some("x86_64"), None),
        ];
        let cov = coverage(&off_arch, &ids_of(&off_arch), 3, &bare(), Vec::new());
        assert_eq!(cov.checks_not_applicable_here, 1);
        assert_eq!(cov.withholding.earned_limitations.count, 1);
        assert!(
            cov.all_verdicts_published,
            "a flag that does not exist for this target is not a gap in what was measured"
        );

        let off_libc = vec![
            discriminating(observation("a", "-Da", Channel::Macro, Verdict::On)),
            discriminating(observation("b", "-Db", Channel::Macro, Verdict::Off)),
            gated("fortify-runtime", None, Some("musl")),
        ];
        let cov = coverage(&off_libc, &ids_of(&off_libc), 3, &bare(), Vec::new());
        assert_eq!(cov.checks_not_applicable_here, 0);
        assert_eq!(
            (
                cov.withholding.earned_limitations.count,
                cov.withholding.instrument_withholdings.count
            ),
            (1, 0),
            "a libc limitation is an answer, counted with the architecture's"
        );
        assert!(
            cov.all_verdicts_published,
            "a limitation earned by forcing the flag on is a settled answer, and the run is whole"
        );

        // The rule is *earned*: the same verdict with no gating behind it is a limitation
        // nobody established, and it fails the gate.
        let mut unearned = off_libc;
        unearned[2].gating = None;
        let cov = coverage(&unearned, &ids_of(&unearned), 3, &bare(), Vec::new());
        assert!(
            !cov.all_verdicts_published,
            "an `unsupported` with no rule attached is not settled"
        );

        // And a withheld verdict fails it whatever the rest of the report says.
        for withheld in [
            Verdict::Indeterminate,
            Verdict::ProbeInvalid,
            Verdict::BuildFailed,
            Verdict::RunFailed,
        ] {
            let obs = vec![
                discriminating(observation("a", "-Da", Channel::Macro, Verdict::On)),
                observation("b", "-Db", Channel::Macro, withheld),
            ];
            let cov = coverage(&obs, &ids_of(&obs), 2, &bare(), Vec::new());
            assert!(
                !cov.all_verdicts_published,
                "{withheld:?} is a state of the harness, not an answer"
            );
        }
    }

    #[test]
    fn a_filtered_run_is_not_complete_even_though_it_met_its_own_expectation() {
        let observations = vec![observation("a", "-Dflag", Channel::Macro, Verdict::On)];
        let cov = coverage(
            &observations,
            &ids_of(&observations),
            17,
            &bare(),
            vec!["restricted to 1 of 7 probes".to_owned()],
        );
        assert_eq!(cov.checks_attempted, cov.checks_expected);
        assert!(
            !cov.all_checks_attempted,
            "a run covering 1 of 17 corpus checks must not report itself complete"
        );
        assert_eq!(cov.corpus_checks_total, 17);
    }

    fn rung(check: &str, level: &str, verdict: Verdict) -> Observation {
        let mut o = observation(check, "-D_FORTIFY_SOURCE", Channel::Runtime, verdict);
        o.level = Some(level.to_owned());
        o
    }

    #[test]
    fn freebsds_implementation_does_not_nest_the_levels() {
        for (implementation, monotone) in [("freebsd", true), ("apple", true), ("glibc", false)] {
            let carrier_sha = "d".repeat(64);
            let mut facts = FactStore::default();
            let mut elf = elf_of_machine("x86_64");
            elf.self_report =
                format!("CHARD-REPORT-V2\n_FORTIFY_IMPL={implementation}\nCHARD-REPORT-END");
            facts
                .insert(carrier_sha.clone(), FactEntry::Elf { elf: Box::new(elf) })
                .expect("a new digest");
            let obs = vec![
                artifact_observation("p-impl", "impl-carrier", &carrier_sha),
                rung(RUNG_GE_1, "1", Verdict::On),
                rung(RUNG_GE_2_SUBOBJECT, "2", Verdict::Off),
                rung(RUNG_GE_2_PERCENT_N, "2", Verdict::Off),
                rung(RUNG_LEVEL_3, "3", Verdict::On),
            ];
            let ratchet = fortify_ratchet(&obs, &facts).expect("a ratchet");
            assert_eq!(ratchet.implementation.as_deref(), Some(implementation));
            assert_eq!(ratchet.monotone, monotone, "{implementation}: {ratchet:?}");
        }
    }

    #[test]
    fn the_ratchet_resolves_each_level() {
        let cases = [
            (Verdict::Off, Verdict::Off, Verdict::Off, "0"),
            (Verdict::On, Verdict::Off, Verdict::Off, "1"),
            (Verdict::On, Verdict::On, Verdict::Off, "2"),
            (Verdict::On, Verdict::On, Verdict::On, "3"),
        ];
        for (ge1, ge2, lvl3, expected) in cases {
            let obs = vec![
                rung(RUNG_GE_1, "1", ge1),
                rung(RUNG_GE_2_SUBOBJECT, "2", ge2),
                rung(RUNG_GE_2_PERCENT_N, "2", ge2),
                rung(RUNG_LEVEL_3, "3", lvl3),
            ];
            let r = fortify_ratchet(&obs, &FactStore::default()).expect("rungs present");
            assert!(r.monotone, "expected monotone for level {expected}");
            assert_eq!(r.implied_level.as_deref(), Some(expected));
        }
    }

    #[test]
    fn the_ladder_coordinate_exists_only_where_the_axes_land_on_it() {
        let case = |sub: Verdict, dynamic: Verdict| {
            let obs = vec![
                rung(RUNG_GE_1, "1", Verdict::On),
                rung(RUNG_GE_2_SUBOBJECT, "2", sub),
                rung(RUNG_GE_2_PERCENT_N, "2", sub),
                rung(RUNG_LEVEL_3, "3", dynamic),
            ];
            let r = fortify_ratchet(&obs, &FactStore::default()).expect("rungs present");
            (
                r.implied_level,
                r.whole_object_level,
                r.dynamic_bounds,
                r.monotone,
            )
        };

        // glibc, every point on the ladder.
        assert_eq!(
            case(Verdict::Off, Verdict::Off),
            (
                Some("1".to_owned()),
                Some("1".to_owned()),
                Some(false),
                true
            )
        );
        assert_eq!(
            case(Verdict::On, Verdict::Off),
            (
                Some("2".to_owned()),
                Some("2".to_owned()),
                Some(false),
                true
            )
        );
        assert_eq!(
            case(Verdict::On, Verdict::On),
            (Some("3".to_owned()), Some("2".to_owned()), Some(true), true)
        );

        // fortify-headers: whole-object bounds, dynamically sized, subobject bounds
        // gated out as unsupported.
        let off_ladder = case(Verdict::Unsupported, Verdict::On);
        assert_eq!(off_ladder.0, None, "not a point on glibc's ladder");
        assert_eq!(off_ladder.1, Some("1".to_owned()));
        assert_eq!(off_ladder.2, Some(true));
        assert!(
            off_ladder.3,
            "an off-ladder reading is not an inconsistency"
        );
    }

    #[test]
    fn a_non_monotone_ratchet_withholds_the_level() {
        let obs = vec![
            rung(RUNG_GE_1, "1", Verdict::On),
            rung(RUNG_GE_2_SUBOBJECT, "2", Verdict::Off),
            rung(RUNG_GE_2_PERCENT_N, "2", Verdict::Off),
            rung(RUNG_LEVEL_3, "3", Verdict::On),
        ];
        let r = fortify_ratchet(&obs, &FactStore::default()).expect("rungs present");
        assert!(!r.monotone);
        assert!(
            r.implied_level.is_none(),
            "a faulty reading must not imply a level"
        );
        assert!(r.inconsistency.is_some());
    }

    #[test]
    fn a_non_monotone_ratchet_withholds_every_measured_rung_and_says_why() {
        let mut obs = vec![
            observation("other", "-fPIE", Channel::Macro, Verdict::On),
            rung(RUNG_GE_1, "1", Verdict::On),
            rung(RUNG_GE_2_SUBOBJECT, "2", Verdict::Off),
            rung(RUNG_GE_2_PERCENT_N, "2", Verdict::Unsupported),
            rung(RUNG_LEVEL_3, "3", Verdict::On),
        ];
        let before = fortify_ratchet(&obs, &FactStore::default()).expect("rungs present");
        assert!(!before.monotone, "the fixture is a faulty reading");
        let inconsistency = before.inconsistency.clone().expect("the fault is named");

        let (after, diagnostic) = withhold_inconsistent_rungs(&mut obs, &FactStore::default());

        let diagnostic = diagnostic.expect("an inconsistent ratchet is diagnosed");
        assert_eq!(diagnostic.severity, Severity::Error);
        assert!(
            diagnostic.message.contains(&inconsistency),
            "the diagnostic names the inconsistency: {}",
            diagnostic.message
        );
        assert_eq!(
            diagnostic.context.as_deref(),
            Some("every rung's verdict withheld")
        );

        let after = after.expect("the rungs are still present");
        assert!(
            !after.monotone,
            "a re-derivation over withheld rungs must not read as monotone"
        );
        assert_eq!(after.inconsistency.as_deref(), Some(inconsistency.as_str()));
        assert!(after.implied_level.is_none());

        let mut moved = 0usize;
        for o in &obs {
            match o.check.as_str() {
                RUNG_GE_1 | RUNG_GE_2_SUBOBJECT | RUNG_LEVEL_3 => {
                    assert_eq!(o.verdict, Verdict::Indeterminate, "{}", o.check);
                    assert!(o.level.is_none(), "{} keeps no level", o.check);
                    moved = moved.saturating_add(1);
                }
                RUNG_GE_2_PERCENT_N => assert_eq!(
                    o.verdict,
                    Verdict::Unsupported,
                    "an earned limitation is not retracted"
                ),
                _ => assert_eq!(
                    o.verdict,
                    Verdict::On,
                    "a non-rung observation is untouched"
                ),
            }
        }
        assert_eq!(moved, 3, "every measured rung was moved");
        // The summary agrees with the observations it summarises, by construction.
        for r in &after.rungs {
            let o = obs
                .iter()
                .find(|o| o.check == r.check)
                .expect("every rung has its observation");
            assert_eq!(r.verdict, o.verdict, "{}", r.check);
        }
    }

    #[test]
    fn a_monotone_ratchet_withholds_nothing() {
        let mut obs = vec![
            rung(RUNG_GE_1, "1", Verdict::On),
            rung(RUNG_GE_2_SUBOBJECT, "2", Verdict::On),
            rung(RUNG_GE_2_PERCENT_N, "2", Verdict::On),
            rung(RUNG_LEVEL_3, "3", Verdict::Off),
        ];
        let before: Vec<Verdict> = obs.iter().map(|o| o.verdict).collect();
        let (ratchet, diagnostic) = withhold_inconsistent_rungs(&mut obs, &FactStore::default());
        assert!(diagnostic.is_none());
        let ratchet = ratchet.expect("rungs present");
        assert!(ratchet.monotone);
        assert_eq!(ratchet.implied_level.as_deref(), Some("2"));
        let after: Vec<Verdict> = obs.iter().map(|o| o.verdict).collect();
        assert_eq!(before, after, "no verdict moved");

        let mut none: Vec<Observation> = Vec::new();
        assert!(matches!(
            withhold_inconsistent_rungs(&mut none, &FactStore::default()),
            (None, None)
        ));
    }

    /// Every implementation the ratchet's derivation reads, and none: the names
    /// `_FORTIFY_IMPL` takes in a self-report.
    const FORTIFY_IMPLEMENTATIONS: [Option<&str>; 5] = [
        None,
        Some("glibc"),
        Some("fortify-headers"),
        Some("apple"),
        Some("freebsd"),
    ];

    #[test]
    fn the_rung_rule_finds_nothing_over_any_ratchet_measure_derives() {
        let states: Vec<Option<Verdict>> = std::iter::once(None)
            .chain(Verdict::ALL.iter().copied().map(Some))
            .collect();
        let mut assignments = Vec::new();
        for a in &states {
            for b in &states {
                for c in &states {
                    for d in &states {
                        assignments.push((*a, *b, *c, *d));
                    }
                }
            }
        }
        let carrier_sha = "c".repeat(64);
        let (mut fed, mut ratchets, mut non_monotone) = (0usize, 0usize, 0usize);
        for implementation in FORTIFY_IMPLEMENTATIONS {
            let mut facts = FactStore::default();
            let mut carrier = Vec::new();
            if let Some(name) = implementation {
                let mut elf = elf_of_machine("x86_64");
                elf.self_report =
                    format!("CHARD-REPORT-V2\n_FORTIFY_IMPL={name}\nCHARD-REPORT-END");
                facts
                    .insert(carrier_sha.clone(), FactEntry::Elf { elf: Box::new(elf) })
                    .expect("a new digest");
                carrier.push(artifact_observation("p-impl", "impl-carrier", &carrier_sha));
            }
            for &(ge1, sub, pn, l3) in &assignments {
                for wrapped in [false, true] {
                    if wrapped && sub.is_none() {
                        continue;
                    }
                    let mut obs = carrier.clone();
                    for (id, level, verdict) in [
                        (RUNG_GE_1, "1", ge1),
                        (RUNG_GE_2_SUBOBJECT, "2", sub),
                        (RUNG_GE_2_PERCENT_N, "2", pn),
                        (RUNG_LEVEL_3, "3", l3),
                    ] {
                        let Some(verdict) = verdict else { continue };
                        let mut o = rung(id, level, verdict);
                        if wrapped && id == RUNG_GE_2_SUBOBJECT {
                            o.gating = Some(Gating {
                                rule: gating_rule::SUBOBJECT_BOUND_LOST_IN_WRAPPER,
                                arch: None,
                                libc: None,
                                needs_vm: false,
                                reason: "r".to_owned(),
                            });
                        }
                        obs.push(o);
                    }
                    let (ratchet, _) = withhold_inconsistent_rungs(&mut obs, &facts);
                    fed += 1;
                    if let Some(r) = &ratchet {
                        ratchets += 1;
                        if !r.monotone {
                            non_monotone += 1;
                        }
                        assert_eq!(
                            r.implementation.as_deref(),
                            implementation,
                            "the carrier names the implementation"
                        );
                    }
                    let found = fortify_ratchet_agrees_with_rungs(ratchet.as_ref(), &obs);
                    assert!(
                        found.is_empty(),
                        "{implementation:?} {ge1:?} {sub:?} {pn:?} {l3:?} wrapped={wrapped}: \
                         {ratchet:#?} {found:#?}"
                    );
                    let read: Vec<ObservationOnRead> =
                        serde_json::from_value(serde_json::to_value(&obs).expect("serializes"))
                            .expect("reads back");
                    let ratchet_read: Option<FortifyRatchet> = ratchet.as_ref().map(|r| {
                        serde_json::from_value(serde_json::to_value(r).expect("serializes"))
                            .expect("reads back")
                    });
                    assert!(
                        fortify_ratchet_agrees_with_rungs(ratchet_read.as_ref(), &read).is_empty(),
                        "the read adapter: {implementation:?} {ge1:?} {sub:?} {pn:?} {l3:?} \
                         wrapped={wrapped}"
                    );
                }
            }
        }
        // Absent or each verdict per rung, every assignment of the four, and those with a
        // subobject rung present once more under the wrapper gating, for each of five
        // implementations.
        let n = states.len();
        assert_eq!(n, Verdict::ALL.len() + 1);
        let per_implementation = n.pow(4) + (n - 1) * n.pow(3);
        let n_impl = FORTIFY_IMPLEMENTATIONS.len();
        assert_eq!(fed, n_impl * per_implementation, "every case was fed");
        assert_eq!(
            ratchets,
            n_impl * (per_implementation - 1),
            "all but the no-rung case"
        );
        assert!(
            non_monotone > 0,
            "the withheld-rung path was exercised: {non_monotone}"
        );
    }

    #[test]
