    fn corr(check: &str, channel: Channel, verdict: Verdict) -> Observation {
        observation(check, "-flag", channel, verdict)
    }

    #[test]
    fn channels_that_contradict_each_other_are_reported() {
        let obs = vec![
            corr("ssp-level", Channel::Macro, Verdict::On),
            corr("canary-emitted", Channel::ElfStatic, Verdict::Off),
        ];
        let groups = corroboration(&obs, &|c| {
            matches!(c, "ssp-level" | "canary-emitted").then_some("stack-protector")
        });
        let g = &groups["stack-protector"];
        assert!(!g.agree);
        assert!(g.note.contains("CHANNELS DISAGREE"));
        assert_eq!(g.channels.len(), 2);
    }

    #[test]
    fn partial_and_on_are_not_a_contradiction() {
        let obs = vec![
            corr("a", Channel::Macro, Verdict::On),
            corr("b", Channel::ElfStatic, Verdict::Partial),
        ];
        let groups = corroboration(&obs, &|_| Some("x"));
        assert!(groups["x"].agree);
    }

    #[test]
    fn two_readers_of_one_scale_reading_different_words_disagree() {
        const UNSAFE_FRAME: &str = "unsafe-frame";
        let key = |c: &str| {
            matches!(c, "ssp-level" | "canary-emitted" | "ssp-level-emitted")
                .then_some("stack-protector")
        };
        let at = |check: &str, channel: Channel, verdict: Verdict, level: &str| {
            let mut o = corr(check, channel, verdict);
            o.level = Some(level.to_owned());
            o.recommended_level = Some("strong".to_owned());
            o
        };
        let split = |macro_verdict: Verdict, macro_level: &str, artifact_level: &str| {
            vec![
                at(
                    "ssp-level-emitted",
                    Channel::ElfStatic,
                    Verdict::On,
                    artifact_level,
                ),
                corr("canary-emitted", Channel::ElfStatic, Verdict::On),
                at("ssp-level", Channel::Macro, macro_verdict, macro_level),
            ]
        };

        for (macro_verdict, macro_level, artifact_level) in [
            (Verdict::On, "all", UNSAFE_FRAME),
            (Verdict::On, "strong", UNSAFE_FRAME),
            (Verdict::Partial, "basic", UNSAFE_FRAME),
            (Verdict::On, "strong", "basic"),
        ] {
            let obs = split(macro_verdict, macro_level, artifact_level);
            let groups = corroboration(&obs, &key);
            let g = &groups["stack-protector"];
            assert!(
                !g.agree && g.corroborated && g.measured_channels == 2,
                "{macro_level} beside {artifact_level}: {g:?}"
            );
            assert!(
                g.note
                    .starts_with("LEVELS DISAGREE about `stack-protector`")
                    && g.note.contains(&format!("ssp-level at `{macro_level}`"))
                    && g.note
                        .contains(&format!("ssp-level-emitted at `{artifact_level}`"))
                    && !g.note.contains("CHANNELS DISAGREE"),
                "{}",
                g.note
            );
            assert!(corroboration_agrees(&groups, &obs, &key).is_empty());
            let mut forged = groups.clone();
            forged.get_mut("stack-protector").expect("group").agree = true;
            let found = corroboration_agrees(&forged, &obs, &key);
            assert!(
                found
                    .iter()
                    .any(|c| c.claims.iter().any(|s| s.contains("agree = true"))),
                "{found:?}"
            );
        }

        // The same word on both: agreement.
        let obs = split(Verdict::On, "strong", "strong");
        let groups = corroboration(&obs, &key);
        assert!(
            groups["stack-protector"].agree,
            "{:?}",
            groups["stack-protector"]
        );
        assert!(corroboration_agrees(&groups, &obs, &key).is_empty());

        // One reader with a word: nothing to compare it with.
        let obs = vec![
            at("ssp-level", Channel::Macro, Verdict::On, "all"),
            corr("canary-emitted", Channel::ElfStatic, Verdict::On),
            corr(
                "ssp-level-emitted",
                Channel::ElfStatic,
                Verdict::Indeterminate,
            ),
        ];
        assert!(corroboration(&obs, &key)["stack-protector"].agree);

        // Members the corpus does not know carry levels the comparison cannot place on a
        // scale, so two different words there are not a split.
        let mut a = corr("a", Channel::Macro, Verdict::On);
        a.level = Some("all".to_owned());
        let mut b = corr("b", Channel::ElfStatic, Verdict::On);
        b.level = Some("basic".to_owned());
        assert!(corroboration(&[a, b], &|_| Some("x"))["x"].agree);

        // An opt-in `partial` claims nothing about the probe's code and takes no part, so
        // `explicit` beside the artifact's `strong` is not a split.
        let obs = split(Verdict::Partial, "explicit", "strong");
        let g = &corroboration(&obs, &key)["stack-protector"];
        assert!(g.agree, "{g:?}");
    }

    #[test]
    fn the_safestack_cross_check_warns_exactly_where_flag_and_object_differ() {
        let reading = |verdict: Verdict, level: Option<&str>| {
            let mut o = corr("ssp-level-emitted", Channel::ElfStatic, verdict);
            o.level = level.map(str::to_owned);
            o
        };
        let profile = |flags: &[&str]| {
            let mut p = bare();
            p.cflags = flags.iter().map(|f| (*f).to_owned()).collect();
            p
        };
        let unsafe_frame = crate::probe::SSP_UNSAFE_FRAME;

        // Agreement in both directions.
        for flags in [
            &["-O2", "-fstack-protector-all", "-fsanitize=safe-stack"][..],
            &["-fsanitize=undefined,safe-stack"][..],
        ] {
            let obs = [reading(Verdict::On, Some(unsafe_frame))];
            assert!(
                safestack_cross_check(&obs, &profile(flags)).is_none(),
                "{flags:?}"
            );
        }
        let obs = [reading(Verdict::On, Some("strong"))];
        assert!(
            safestack_cross_check(&obs, &profile(&["-O2", "-fstack-protector-strong"])).is_none()
        );

        // The object carries SafeStack's selection and the flags name no request.
        let obs = [reading(Verdict::On, Some(unsafe_frame))];
        let d = safestack_cross_check(&obs, &profile(&["-O2", "-fstack-protector-all"]))
            .expect("a difference");
        assert_eq!(d.severity, Severity::Warning);
        assert_eq!(d.context.as_deref(), Some("ssp-level-emitted"));
        // `-fsanitize=address` and a misspelt flag are not requests.
        for flags in [
            &["-fsanitize=address"][..],
            &["-Wl,-fsanitize=safe-stack"][..],
            &["-fsanitize=safe-stack-x"][..],
        ] {
            assert!(
                safestack_cross_check(&obs, &profile(flags)).is_some(),
                "{flags:?}"
            );
        }

        // The flags ask and the object carries a rung.
        let obs = [reading(Verdict::On, Some("strong"))];
        assert!(
            safestack_cross_check(
                &obs,
                &profile(&["-fstack-protector-strong", "-fsanitize=safe-stack"]),
            )
            .is_some(),
            "a difference"
        );

        // No difference: `off` with the flag, a withheld reading, no reading at all.
        let flags = profile(&["-fno-stack-protector", "-fsanitize=safe-stack"]);
        assert!(safestack_cross_check(&[reading(Verdict::Off, None)], &flags).is_none());
        assert!(safestack_cross_check(&[reading(Verdict::Indeterminate, None)], &flags).is_none());
        assert!(
            safestack_cross_check(
                &[corr("canary-emitted", Channel::ElfStatic, Verdict::On)],
                &flags
            )
            .is_none()
        );
        assert!(safestack_cross_check(&[], &flags).is_none());

        let asks = |flags: &[&str]| requests_safestack(&profile(flags).cflags);
        assert!(asks(&["-fsanitize=safe-stack"]));
        assert!(asks(&["-fsanitize=cfi,safe-stack"]));
        assert!(!asks(&["-fsanitize=address"]));
        assert!(!asks(&["-fno-sanitize=safe-stack"]));
        // A later cancelling flag takes the request back, in order; `all` cancels too, and
        // a request after the cancellation stands.
        assert!(!asks(&[
            "-fsanitize=safe-stack",
            "-fno-sanitize=safe-stack"
        ]));
        assert!(!asks(&["-fsanitize=safe-stack", "-fno-sanitize=all"]));
        assert!(!asks(&[
            "-fsanitize=safe-stack",
            "-fno-sanitize=cfi,safe-stack"
        ]));
        assert!(asks(&["-fno-sanitize=safe-stack", "-fsanitize=safe-stack"]));
        assert!(asks(&["-fsanitize=safe-stack", "-fno-sanitize=address"]));
        // And the cross-check follows: the compiler honoured the cancellation, the object
        // carries a rung, and there is nothing to warn about.
        let obs = [reading(Verdict::On, Some("all"))];
        assert!(
            safestack_cross_check(
                &obs,
                &profile(&[
                    "-O2",
                    "-fstack-protector-all",
                    "-fsanitize=safe-stack",
                    "-fno-sanitize=safe-stack"
                ])
            )
            .is_none()
        );
    }

    #[test]
    fn an_opt_in_level_beside_an_artifact_reading_off_is_not_a_disagreement() {
        let ssp = |level: &str| {
            let mut o = corr("ssp-level", Channel::Macro, Verdict::Partial);
            o.level = Some(level.to_owned());
            o.recommended_level = Some("strong".to_owned());
            o
        };
        let key = |c: &str| {
            matches!(c, "ssp-level" | "canary-emitted" | "ssp-level-emitted")
                .then_some("stack-protector")
        };
        let readers = || {
            vec![
                corr("canary-emitted", Channel::ElfStatic, Verdict::Off),
                corr("ssp-level-emitted", Channel::ElfStatic, Verdict::Off),
            ]
        };

        let mut obs = readers();
        obs.insert(0, ssp("explicit"));
        let groups = corroboration(&obs, &key);
        let g = &groups["stack-protector"];
        assert!(g.agree && !g.corroborated, "{g:?}");
        assert_eq!(g.measured_channels, 1, "{g:?}");
        assert_eq!(g.verdicts["partial"], ["ssp-level"]);
        assert!(!g.sources.contains_key("ssp-level"), "{g:?}");
        assert_eq!(
            g.independent_witnesses,
            CorroboratingSource::distinct(&g.sources)
        );
        let found = corroboration_agrees(&groups, &obs, &key);
        assert!(found.is_empty(), "{found:?}");
        let mut forged = groups.clone();
        forged.get_mut("stack-protector").expect("group").agree = false;
        assert!(!corroboration_agrees(&forged, &obs, &key).is_empty());
        let mut forged = groups.clone();
        let f = forged.get_mut("stack-protector").expect("group");
        f.measured_channels = 2;
        f.corroborated = true;
        assert!(!corroboration_agrees(&forged, &obs, &key).is_empty());

        let mut obs = readers();
        obs.insert(0, ssp("explicit"));
        obs.push(corr("canary-runtime", Channel::Runtime, Verdict::Off));
        let key_rt = |c: &str| key(c).or((c == "canary-runtime").then_some("stack-protector"));
        let groups = corroboration(&obs, &key_rt);
        let g = &groups["stack-protector"];
        assert!(
            g.agree && g.corroborated && g.measured_channels == 2,
            "{g:?}"
        );
        assert!(g.note.starts_with("ssp-level at `explicit`"), "{}", g.note);
        assert!(corroboration_agrees(&groups, &obs, &key_rt).is_empty());

        let mut obs = readers();
        obs.insert(0, ssp("basic"));
        let groups = corroboration(&obs, &key);
        assert!(!groups["stack-protector"].agree);
        assert!(groups["stack-protector"].note.contains("CHANNELS DISAGREE"));
        assert!(corroboration_agrees(&groups, &obs, &key).is_empty());
    }

    #[test]
    fn every_opt_in_level_is_a_word_below_its_checks_ask() {
        assert!(
            !OPT_IN_LEVELS.is_empty(),
            "the opt-in levels are not empty, so the loop below checks something"
        );
        for (id, level) in OPT_IN_LEVELS {
            let check = crate::probe::CORPUS
                .iter()
                .flat_map(|p| p.checks.iter())
                .find(|c| c.id == *id)
                .unwrap_or_else(|| panic!("{id} is not a corpus check"));
            assert!(check.corroborates.is_some(), "{id} is in no group");
            let grade = check.levels.grade().expect("graded");
            assert_eq!(grade.meets(level), Some(false), "{id} at {level}");
        }
    }

