    #[test]
    fn one_measuring_channel_is_not_corroboration() {
        let obs = vec![
            corr("cet-macro", Channel::Macro, Verdict::On),
            corr("cet-marked", Channel::ElfStatic, Verdict::ProbeInvalid),
        ];
        let groups = corroboration(&obs, &|_| Some("cet"));
        let g = &groups["cet"];

        assert!(g.agree, "a withheld verdict cannot contradict");
        assert!(
            !g.corroborated,
            "one measuring channel cannot corroborate anything"
        );
        assert_eq!(g.measured_channels, 1);
        assert_eq!(g.channels.len(), 2, "both channels are still members");
        assert_eq!(
            g.withheld.get("cet-marked").map(String::as_str),
            Some("probe-invalid"),
            "the blind spot is named, not dropped"
        );
        assert!(
            g.note.contains("NOT CORROBORATED"),
            "the note must not read as agreement: {}",
            g.note
        );
        assert!(
            !g.note.contains("2 channel(s) agree"),
            "the withheld channel was counted as agreeing"
        );
    }

    #[test]
    fn two_measuring_channels_that_agree_are_corroborated() {
        let obs = vec![
            corr("cet-macro", Channel::Macro, Verdict::On),
            corr("cet-marked", Channel::ElfStatic, Verdict::On),
        ];
        let groups = corroboration(&obs, &|_| Some("cet"));
        let g = &groups["cet"];
        assert!(g.corroborated && g.agree);
        assert_eq!(g.measured_channels, 2);
        assert!(g.withheld.is_empty());
        assert!(g.note.contains("2 channel(s) measured this and agree"));
    }

    /// A member as `run_check` publishes it: the probe it came from, the digest of the
    /// artifact that probe built, and for the macro channel where its macros came from.
    fn sourced(
        check: &str,
        channel: Channel,
        probe: &str,
        sha: &str,
        macro_source: Option<&str>,
    ) -> Observation {
        let mut obs = corr(check, channel, Verdict::On);
        obs.probe = probe.to_owned();
        obs.evidence.macro_source = macro_source.map(ToOwned::to_owned);
        obs.build = Some(BuildRecord {
            argv: vec!["cc".to_owned()],
            dropped_flags: Vec::new(),
            exit_status: 0,
            stdout: String::new(),
            stderr: String::new(),
            duration_ms: 1,
            artifact_sha256: Some(sha.repeat(64)),
            stdout_sha256: None,
            stdout_unterminated: false,
        });
        obs
    }

    #[test]
    fn channels_reading_one_artifact_are_one_witness() {
        let obs = vec![
            sourced("req", Channel::Macro, "p", "a", Some("compiled-artifact")),
            sourced("sym", Channel::ElfStatic, "p", "a", None),
            sourced("run", Channel::Runtime, "p", "a", None),
        ];
        let groups = corroboration(&obs, &|_| Some("x"));
        let g = &groups["x"];
        assert!(g.corroborated && g.agree);
        assert_eq!(g.measured_channels, 3);
        assert_eq!(g.independent_witnesses, 1);
        assert!(
            g.sources.values().all(|s| s.witness == "artifact"
                && s.artifact_sha256.as_deref() == Some(&*"a".repeat(64))),
            "every source names the one artifact it read: {:?}",
            g.sources
        );
    }

    #[test]
    fn distinct_artifacts_and_the_preprocessor_dump_are_distinct_witnesses() {
        let obs = vec![
            sourced(
                "pie-macro",
                Channel::Macro,
                "m",
                "a",
                Some("compiled-artifact"),
            ),
            sourced("pie", Channel::ElfStatic, "l", "b", None),
        ];
        let g = &corroboration(&obs, &|_| Some("pie"))["pie"];
        assert_eq!(g.independent_witnesses, 2);
        assert!(g.note.contains("2 distinct witness(es)"), "{}", g.note);

        // The dump is outside the artifact even when the artifact is the same probe's.
        let obs = vec![
            sourced("pie-macro", Channel::Macro, "l", "b", Some("preprocessor")),
            sourced("pie", Channel::ElfStatic, "l", "b", None),
        ];
        let g = &corroboration(&obs, &|_| Some("pie"))["pie"];
        assert_eq!(g.independent_witnesses, 2);
        assert_eq!(g.sources["pie-macro"].witness, "preprocessor-dump");
        assert_eq!(g.sources["pie-macro"].artifact_sha256, None);
    }

