    #[test]
    fn the_structured_diagnostics_summary_is_held_to_its_comparisons() {
        use crate::structured::{ArmComparison, Comparison, Summary};
        let arm = |outcome: &'static str| ArmComparison {
            prose: "error",
            structured: if outcome == "agree" {
                "error"
            } else {
                "warning"
            },
            outcome,
            reason: None,
        };
        let mut obs = corr(
            "format-security-is-error",
            Channel::CompilerDiag,
            Verdict::On,
        );
        obs.structured_diagnostics = Some(Comparison {
            format: "-fdiagnostics-format=sarif",
            arms_expected: 3,
            arms: [("measured", arm("agree")), ("positive", arm("disagree"))]
                .into_iter()
                .collect(),
            arms_missing: vec!["negative"],
        });
        let unread = corr("warn-all", Channel::CompilerDiag, Verdict::ProbeInvalid);
        let observations = vec![obs, unread];
        let summary = Summary::over(Some("-fdiagnostics-format=sarif"), &observations);
        assert_eq!(
            (
                summary.checks_eligible,
                summary.checks_compared,
                summary.arms_expected,
                summary.arms_missing,
                summary.arms_compared
            ),
            (2, 1, 3, 1, 2)
        );
        assert!(structured_diagnostics_agree(Some(&summary), &observations).is_empty());
        assert!(
            Summary::findings(&observations)
                .iter()
                .any(|(_, m)| m.contains("negative arm was not compared")),
            "a missing arm is diagnosed"
        );

        let mut edited = summary.clone();
        edited.agreed = 2;
        let found = structured_diagnostics_agree(Some(&edited), &observations);
        assert!(!found.is_empty());
        assert!(found.iter().all(|c| c.rule == RULE_STRUCTURED));

        let mut dropped = summary.clone();
        dropped.not_compared.clear();
        assert!(
            structured_diagnostics_agree(Some(&dropped), &observations)
                .iter()
                .any(|c| c.claims[0].contains("not_compared")),
            "an eligible check dropped from the account is named"
        );

        let mut lost = observations.clone();
        if let Some(c) = lost[0].structured_diagnostics.as_mut() {
            c.arms_missing.clear();
        }
        let recomputed = Summary::over(Some("-fdiagnostics-format=sarif"), &lost);
        assert!(
            structured_diagnostics_agree(Some(&recomputed), &lost)
                .iter()
                .any(|c| c.property.starts_with("observations[")),
            "a comparison that lost an arm without naming it contradicts"
        );

        assert_eq!(structured_diagnostics_agree(None, &observations).len(), 1);
        assert!(structured_diagnostics_agree(None, &observations[1..]).is_empty());
    }

