    #[test]
    fn the_macro_evidence_filter_is_published_as_the_list_that_trims() {
        let filters = evidence_filters();
        let declared: std::collections::BTreeSet<&str> = crate::measure::MACRO_EVIDENCE_KEEP
            .iter()
            .copied()
            .collect();
        assert_eq!(
            filters
                .macros
                .names
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>(),
            declared.iter().copied().collect::<Vec<_>>(),
            "the published names are the declared list, sorted"
        );
        assert_eq!(filters.macros.size, declared.len());
        assert_eq!(filters.macros.sha256.len(), 64);
        assert_eq!(
            filters.macros.sha256,
            crate::digest::sha256_hex(filters.macros.names.join("\n").as_bytes()),
            "the digest is over the sorted, newline-joined names, so a reader can recompute it"
        );

        // Whatever the dump holds, what is kept is within the list.
        let mut dump: BTreeMap<String, String> = declared
            .iter()
            .map(|n| ((*n).to_owned(), "1".to_owned()))
            .collect();
        dump.insert("__SOMETHING_ELSE__".to_owned(), "1".to_owned());
        dump.insert("_DISTRO_HARDENING".to_owned(), "1".to_owned());
        let kept = crate::measure::relevant_macros(&dump);
        assert_eq!(kept.len(), declared.len());
        assert!(kept.keys().all(|k| declared.contains(k.as_str())));

        // And the trimming is a truncation on a report that did it; a report that did
        // not records none.
        let mut trimmed = observation("a", "-Da", Channel::Macro, Verdict::On);
        trimmed.evidence.macros = Some(kept);
        let obs = vec![trimmed];
        let cov = coverage(&obs, &ids_of(&obs), 1, &bare(), Vec::new());
        assert!(
            cov.truncations
                .iter()
                .any(|t| t.contains("evidence.macros on 1 observation(s)")
                    && t.contains(&filters.macros.sha256)),
            "{:?}",
            cov.truncations
        );
        let untrimmed = vec![observation("b", "-Db", Channel::ElfStatic, Verdict::On)];
        let cov = coverage(&untrimmed, &ids_of(&untrimmed), 1, &bare(), Vec::new());
        assert!(
            !cov.truncations
                .iter()
                .any(|t| t.contains("evidence.macros")),
            "a report that trimmed nothing records no trimming"
        );
    }

    #[test]
    fn a_volatile_reading_loses_its_value_and_keeps_its_line() {
        let marker = "SCPRT dist=";
        assert_eq!(
            mask_reading(
                "exit=0 out=\"SCPRT dist=8384719 n=67108864 ratio_pct=12\"",
                marker
            ),
            "exit=0 out=\"SCPRT dist=<volatile> n=67108864 ratio_pct=12\""
        );
        assert_eq!(
            mask_reading("SCPRT dist=1\nSCPRT dist=22 n=3", marker),
            "SCPRT dist=<volatile>\nSCPRT dist=<volatile> n=3"
        );
        assert_eq!(
            mask_reading("SCPRT dist= n=3 SCPRT dist", marker),
            "SCPRT dist= n=3 SCPRT dist"
        );
        assert_eq!(mask_reading("dist=5", marker), "dist=5");

        // A cut inside the marker leaves bare digits nothing can find.
        assert_eq!(
            mask_reading("[40 chars omitted]=8384719 n=67108864 ratio_pct=12", marker),
            "[40 chars omitted]=8384719 n=67108864 ratio_pct=12"
        );
        // So the detector never cuts the probe's line: two runs of one artifact that
        // differ in the reading's width, under a loader warning long enough to need a
        // cut, publish one `observed` once normalized.
        let warning = "ld.so: warning: ".to_owned() + &"x".repeat(300);
        let observed = |dist: &str| {
            let run = RunRecord {
                argv: vec!["stack_clash".to_owned()],
                exit_status: 0,
                signal: None,
                stdout: format!("SCPRT dist={dist} n=80000000 ratio_pct=12"),
                stderr: warning.clone(),
                timed_out: false,
                deadline_ms: None,
                output_error: None,
                output_truncated: false,
                duration_ms: 1,
                environment: None,
            };
            let macros = BTreeMap::new();
            let detection = crate::decode::runtime::detect_stack_clash(&crate::probe::Evidence {
                macros: &macros,
                elf: None,
                build: None,
                run: Some(&run),
                workdir: None,
            });
            assert_eq!(detection.outcome, Outcome::Present);
            assert!(crate::decode::common::carries_a_cut(&detection.observed));
            mask_reading(&detection.observed, marker)
        };
        // The wider reading is one more digit across a power of ten, both inside the
        // ratio-12 band of `n`, so both lines are arithmetic a probe could print: the
        // decoder withholds a line whose ratio disagrees.
        let short = observed("9999999");
        assert_eq!(short, observed("10000000"));
        assert!(
            short.contains("SCPRT dist=<volatile> n=80000000 ratio_pct=12"),
            "{short}"
        );
    }

    #[test]
    fn a_recorded_invocation_keeps_the_binary_name_and_drops_its_directory() {
        use std::ffi::OsString;
        let argv = |parts: &[&str]| parts.iter().map(|s| (*s).to_owned()).collect::<Vec<_>>();
        let recorded = |args: &[&str]| recorded_invocation(args.iter().map(OsString::from));
        assert_eq!(
            recorded(&["/opt/x/bin/chard", "measure", "--workdir", "/srv/u/w"]),
            argv(&["chard", "measure", "--workdir", "/srv/u/w"])
        );
        assert_eq!(recorded(&["chard", "probes"]), argv(&["chard", "probes"]));
        assert_eq!(recorded(&["./chard-copy"]), argv(&["chard-copy"]));
        assert_eq!(recorded(&["/a/b/"]), argv(&[""]));
        assert!(
            recorded(&[]).is_empty(),
            "an empty argv records nothing: {:?}",
            recorded(&[])
        );
        #[cfg(unix)]
        {
            use std::os::unix::ffi::OsStringExt;
            let got = recorded_invocation([
                OsString::from_vec(b"/d\xff/chard".to_vec()),
                OsString::from("--workdir"),
                OsString::from_vec(b"w\xff".to_vec()),
            ]);
            assert_eq!(got, argv(&["chard", "--workdir", "w\u{fffd}"]));
        }
    }

    #[test]
    fn a_normalized_invocation_keeps_the_measurement_and_loses_the_paths() {
        let argv = |parts: &[&str]| parts.iter().map(|s| (*s).to_owned()).collect::<Vec<_>>();
        assert_eq!(
            normalized_invocation(&argv(&[
                "/build/chard",
                "measure",
                "--cc",
                "cc",
                "--workdir",
                "/scratch/a",
                "--profile",
                "explicit",
                "--flags",
                "-O2",
                "--cxxflags",
                "-openmp",
                "--ldflags",
                "-o",
                "--output=/scratch/a.json",
                "-o",
                "/scratch/b.json",
                "-o/scratch/c.json",
                "-o=/scratch/d.json",
                "--image-attestation",
                "/scratch/att.json",
                "--image-attestation=/scratch/att.json",
                "--normalize",
            ])),
            argv(&[
                "chard",
                "measure",
                "--cc",
                "cc",
                "--workdir",
                "<normalized>",
                "--profile",
                "explicit",
                "--flags",
                "-O2",
                "--cxxflags",
                "-openmp",
                "--ldflags",
                "-o",
                "--output=<normalized>",
                "-o",
                "<normalized>",
                "-o<normalized>",
                "-o=<normalized>",
                "--image-attestation",
                "<normalized>",
                "--image-attestation=<normalized>",
                "--normalize",
            ])
        );
        assert!(
            normalized_invocation(&[]).is_empty(),
            "an empty argv normalizes to nothing: {:?}",
            normalized_invocation(&[])
        );
        // A long option that only begins with a path option's name is not that option.
        assert_eq!(
            normalized_invocation(&argv(&["chard", "--outputs", "--workdirs=x"])),
            argv(&["chard", "--outputs", "--workdirs=x"])
        );

        // Every volatile field names a node the schema has, and the two spellings of the
        // clock agree with the format the schema declares.
        assert_eq!(NORMALIZED_STARTED_UTC.len(), 20);
        assert!(NORMALIZED_STARTED_UTC.ends_with('Z'));
        assert_eq!(VOLATILE_FIELDS.len(), 5);
    }

    /// An attestation with a well-formed digest built from `byte`.
    fn attestation(byte: &str) -> crate::env::Attestation {
        let text = format!(
            r#"{{"verdict":"digest-matched","url":"https://example.invalid/img",
                 "served_by":"example.invalid",
                 "manifest_url":"https://example.invalid/SHA256SUMS",
                 "digest_kind":"sha256","digest":"{}","digest_matched":true,
                 "signature":"none"}}"#,
            byte.repeat(32)
        );
        crate::env::Attestation::from_json(&text).expect("well-formed")
    }

