    #[test]
    fn a_verdict_moves_the_run_id_and_not_the_inputs() {
        let base = identity_fixture();
        let mut moved = base.clone();
        moved.observations[0].verdict = Verdict::On;
        stamp(&mut moved);
        assert_eq!(base.run.inputs_sha256, moved.run.inputs_sha256);
        assert_ne!(base.run.id, moved.run.id);

        let mut reordered = base.clone();
        reordered.observations.reverse();
        stamp(&mut reordered);
        assert_eq!(base.run.id, reordered.run.id);
    }

    #[test]
    fn a_newline_in_a_value_cannot_forge_a_line() {
        let base = identity_fixture();
        let mut early = base.clone();
        early.run.harness_version = "X\nharness_revision=Y".to_owned();
        early.run.harness_revision = Some("Z".to_owned());
        let mut late = base.clone();
        late.run.harness_version = "X".to_owned();
        late.run.harness_revision = Some("Y\nharness_revision=Z".to_owned());

        let unescaped = |r: &Report| -> String {
            inputs_of(r)
                .lines
                .iter()
                .map(|(key, value)| match value {
                    Some(value) => format!("{key}={value}\n"),
                    None => format!("{key}\n"),
                })
                .collect()
        };
        assert_eq!(
            unescaped(&early),
            unescaped(&late),
            "the pair must collide without the escaping, or this test cannot fail"
        );
        assert_ne!(inputs_of(&early).sha256(), inputs_of(&late).sha256());
        for report in [&base, &early, &late] {
            let inputs = inputs_of(report);
            assert_eq!(inputs.canonical().lines().count(), inputs.lines.len());
        }
    }

    #[test]
    fn a_stored_artifact_without_the_runs_witness_is_a_contradiction() {
        let own = "ab".repeat(crate::elf::RUN_WITNESS_BYTES);
        let other = "cd".repeat(crate::elf::RUN_WITNESS_BYTES);
        let witness = ArtifactWitness {
            source: crate::compile::WitnessSource::OsRandom,
            nonce: own.clone(),
        };
        let store_of = |witnesses: &[&String]| {
            let mut elf = elf_of_machine("x86_64");
            elf.run_witness = witnesses.iter().map(|w| (*w).clone()).collect();
            let mut facts = FactStore::default();
            facts
                .insert("11".repeat(32), FactEntry::Elf { elf: Box::new(elf) })
                .expect("one entry");
            facts
        };
        let found = |facts: &FactStore, witness: Option<&ArtifactWitness>| {
            stored_facts_carry_the_witness(facts, witness)
        };

        assert!(found(&store_of(&[&own]), Some(&witness)).is_empty());
        assert!(found(&store_of(&[]), None).is_empty());
        for (what, witnesses) in [
            ("another run's nonce", vec![&other]),
            ("two nonces", vec![&own, &other]),
            ("no nonce", vec![]),
        ] {
            let contradictions = found(&store_of(&witnesses), Some(&witness));
            assert_eq!(contradictions.len(), 1, "{what}");
            assert_eq!(contradictions[0].rule, RULE_FACT_STORE, "{what}");
            assert!(
                contradictions[0].claims.iter().any(|c| c.contains(&own)),
                "{what}: {:?}",
                contradictions[0].claims
            );
        }
        assert_eq!(
            found(&store_of(&[&own]), None).len(),
            1,
            "a run with no witness stored an artifact that carries one"
        );

        let mut delta = store_of(&[&own]);
        let mut changes = serde_json::Map::new();
        changes.insert("run_witness".to_owned(), serde_json::json!([other]));
        delta
            .insert(
                "22".repeat(32),
                FactEntry::ElfDelta {
                    base: "11".repeat(32),
                    elf_changes: changes,
                },
            )
            .expect("a delta");
        let contradictions = found(&delta, Some(&witness));
        assert_eq!(contradictions.len(), 1, "{contradictions:?}");
        assert!(contradictions[0].property.contains(&"22".repeat(32)));
    }

    #[test]
    fn a_stored_object_another_compiler_built_is_a_contradiction() {
        use crate::toolchain::Kind;
        let store_of = |elf_type: &str, lines: &[&str]| {
            let mut elf = elf_of_machine("x86_64");
            elf.elf_type = elf_type.to_owned();
            elf.comment = lines.iter().map(|l| (*l).to_owned()).collect();
            let mut facts = FactStore::default();
            facts
                .insert("22".repeat(32), FactEntry::Elf { elf: Box::new(elf) })
                .expect("one entry");
            facts
        };
        let gcc = "GCC: (GNU) 16.2.1 20261029 (Red Hat 16.2.1-3)";
        let clang = "clang version 22.1.8 (Fedora 22.1.8-4.fc44)";
        let found =
            |facts: &FactStore| stored_objects_name_the_toolchain(facts, Kind::Clang, "22.1.8");
        assert!(found(&store_of("ET_REL", &[clang])).is_empty());
        assert!(found(&store_of("ET_REL", &[])).is_empty());
        assert!(found(&store_of("ET_DYN", &[gcc])).is_empty());
        let contradictions = found(&store_of("ET_REL", &[gcc]));
        assert_eq!(contradictions.len(), 1);
        assert_eq!(contradictions[0].rule, RULE_FACT_STORE);
        assert!(
            contradictions[0].claims[0].contains(gcc)
                && contradictions[0].claims[1] == "toolchain is clang 22.1.8",
            "{:?}",
            contradictions[0].claims
        );
    }

    #[test]
    fn a_report_storing_an_object_another_compiler_built_is_refused() {
        let mut report = publishable_fixture();
        report.toolchain.detected.kind = crate::toolchain::Kind::Clang;
        report.toolchain.detected.version = "22.1.8".to_owned();
        let named = |r: &Report| {
            consistency(r).contradictions.into_iter().any(|c| {
                c.rule == RULE_FACT_STORE
                    && c.claims
                        .iter()
                        .any(|claim| claim.contains("GCC: (GNU) 22.1.8"))
            })
        };
        assert!(!named(&report), "the fixture names no foreign compiler");
        let mut elf = elf_of_machine("x86_64");
        elf.elf_type = crate::measure::RELOCATABLE.to_owned();
        elf.comment = vec!["GCC: (GNU) 22.1.8".to_owned()];
        elf.run_witness = report
            .run
            .artifact_witness
            .iter()
            .map(|w| w.nonce.clone())
            .collect();
        report
            .facts
            .insert("5c".repeat(32), FactEntry::Elf { elf: Box::new(elf) })
            .expect("a key the fixture does not hold");
        assert!(named(&report), "{:?}", consistency(&report).contradictions);
    }

    #[test]
    fn the_set_aside_reason_names_what_the_check_reads_from() {
        let check = corpus_check_by_id("ssp-level-emitted").expect("a check of the corpus");
        let other = crate::compile::WitnessAbsence::OtherCompiler {
            lines: vec!["GCC: (GNU) 16.2.1".to_owned()],
            named: "clang 22.1.8".to_owned(),
            witnessed: true,
        };
        let gating = witness_gating(check, &other);
        assert_eq!(gating.rule, gating_rule::ARTIFACT_OTHER_COMPILER);
        assert!(
            gating
                .reason
                .contains("is read from a build of this run by the compiler the report names"),
            "{}",
            gating.reason
        );
        let foreign = witness_gating(check, &crate::compile::WitnessAbsence::Missing);
        assert_eq!(foreign.rule, gating_rule::ARTIFACT_UNWITNESSED);
        assert!(
            foreign
                .reason
                .contains("is read from a build of this run, and")
                && !foreign.reason.contains("the compiler the report names"),
            "{}",
            foreign.reason
        );
    }

    #[test]
    fn a_run_id_is_held_to_the_measurement_it_digests() {
        let base = identity_fixture();
        assert!(run_id_agrees(&base).is_empty());

        let mut edited = base.clone();
        edited.run.inputs_sha256 = "00".repeat(32);
        let found = run_id_agrees(&edited);
        assert_eq!(found.len(), 1, "{found:?}");
        assert_eq!(found[0].rule, RULE_RUN_ID);
        assert_eq!(found[0].property, "run.inputs_sha256");
        assert!(found[0].claims.iter().any(|c| c.contains(&"00".repeat(32))));
        assert!(
            found[0]
                .claims
                .iter()
                .any(|c| c.contains(&base.run.inputs_sha256))
        );

        let mut cell = base.clone();
        cell.observations[0].verdict = Verdict::On;
        let found = run_id_agrees(&cell);
        assert_eq!(found.len(), 1, "{found:?}");
        assert_eq!(found[0].rule, RULE_RUN_ID);
        assert_eq!(found[0].property, "run.id");
        assert!(found[0].claims.iter().any(|c| c.contains(&base.run.id)));

        // The rebuild pair: one toolchain id, two distributions, two ids.
        let mut rebuild = base.clone();
        rebuild.environment.distro.id = "rocky".to_owned();
        stamp(&mut rebuild);
        assert_ne!(base.run.id, rebuild.run.id);
        let mut foreign = base.clone();
        foreign.run.id.clone_from(&rebuild.run.id);
        let found = run_id_agrees(&foreign);
        assert_eq!(found.len(), 1, "{found:?}");
        assert_eq!(found[0].property, "run.id");
        assert!(
            found[0].claims.iter().any(|c| c.contains(&rebuild.run.id))
                && found[0].claims.iter().any(|c| c.contains(&base.run.id)),
            "{:?}",
            found[0].claims
        );
        assert!(
            consistency(&foreign)
                .contradictions
                .iter()
                .any(|c| c.rule == RULE_RUN_ID)
        );
    }

    #[test]
    fn every_run_id_contradiction_names_a_checked_field() {
        let base = identity_fixture();
        let mut edited = base.clone();
        edited.run.inputs_sha256 = "00".repeat(32);
        edited.run.id = "0".repeat(16);
        let found = run_id_agrees(&edited);
        let properties: Vec<&str> = found.iter().map(|c| c.property.as_str()).collect();
        assert_eq!(
            properties,
            ["run.inputs_sha256", "run.id"],
            "both properties must be provoked, or this test checks less than it says"
        );
        let checked = fields_the_rules_check();
        for property in properties {
            assert!(
                checked.iter().any(|f| f == property),
                "run_id_agrees contradicts `{property}`, which fields_checked does not list: \
                 {checked:?}"
            );
        }
    }

    #[test]
    fn a_runtime_reading_the_run_record_denies_contradicts_the_report() {
        // `timed_out` here is a run chard's deadline killed: `SIGKILL`, as `execute` sends.
        let run = |truncated: bool, timed_out: bool| RunRecord {
            argv: vec!["probe".to_owned()],
            exit_status: if timed_out { -1 } else { 0 },
            signal: timed_out.then(|| "SIGKILL".to_owned()),
            stdout: String::new(),
            stderr: String::new(),
            timed_out,
            deadline_ms: Some(5000),
            output_error: None,
            output_truncated: truncated,
            duration_ms: 1,
            environment: None,
        };
        let runtime = |check: &str, verdict: Verdict, record, rule: Option<gating_rule::Rule>| {
            let mut o = observation(check, "-f", Channel::Runtime, verdict);
            o.run = Some(record);
            o.gating = rule.map(|rule| Gating {
                rule,
                arch: None,
                libc: None,
                needs_vm: false,
                reason: "r".to_owned(),
            });
            o
        };

        let agreeing = vec![
            runtime("a", Verdict::Off, run(false, false), None),
            runtime(
                "b",
                Verdict::Indeterminate,
                run(true, false),
                Some(gating_rule::RUN_OUTPUT_UNREADABLE),
            ),
            runtime(
                "c",
                Verdict::Indeterminate,
                run(false, true),
                Some(gating_rule::RUN_DEADLINE_ELAPSED),
            ),
            runtime("d", Verdict::ProbeInvalid, run(true, false), None),
            runtime("e", Verdict::ProbeInvalid, run(false, true), None),
        ];
        assert!(run_record_agrees(&agreeing).is_empty());

        // A probe that exited in the window between the deadline and the kill finished,
        // so its reading stands and a deadline gating over it names a kill that did not
        // happen.
        let mut exited_in_window = run(false, true);
        exited_in_window.exit_status = 0;
        exited_in_window.signal = None;
        assert!(
            run_record_agrees(&[runtime("f", Verdict::Off, exited_in_window.clone(), None)])
                .is_empty()
        );

        let cases: Vec<Observation> = vec![
            runtime("off", Verdict::Off, run(true, false), None),
            runtime("on", Verdict::On, run(true, false), None),
            runtime(
                "whole",
                Verdict::Indeterminate,
                run(false, false),
                Some(gating_rule::RUN_OUTPUT_UNREADABLE),
            ),
            runtime(
                "in-time",
                Verdict::Indeterminate,
                run(false, false),
                Some(gating_rule::RUN_DEADLINE_ELAPSED),
            ),
            runtime(
                "in-window",
                Verdict::Indeterminate,
                exited_in_window,
                Some(gating_rule::RUN_DEADLINE_ELAPSED),
            ),
            // A killed run never finished writing: its output is cut however short it is.
            runtime("killed-off", Verdict::Off, run(false, true), None),
            runtime("killed-on", Verdict::On, run(false, true), None),
        ];
        for o in cases {
            let found = run_record_agrees(std::slice::from_ref(&o));
            assert_eq!(found.len(), 1, "{}", o.check);
            assert_eq!(found[0].rule, RULE_RUN_RECORD);
        }
    }

    #[test]
    fn a_run_under_emulation_is_held_to_the_artifact_and_the_kernel() {
        let kernel = crate::env::Kernel {
            release: "7.3.0".to_owned(),
            arch: "aarch64".to_owned(),
            // chard itself emulated: its own arch says aarch64 and the kernel says x86_64.
            machine: Some("x86_64".to_owned()),
            is_host_kernel: false,
            ownership: crate::env::KernelOwnership::Own,
        };
        let mut store = machines(&[(&"aa".repeat(32), "aarch64"), (&"bb".repeat(32), "x86_64")]);
        // The kernel's family at the other width, an x32 artifact, which the kernel runs
        // only through a compat option chard cannot see.
        let mut x32 = elf_of_machine("x86_64");
        x32.elf_class = 32;
        store
            .insert("cc".repeat(32), FactEntry::Elf { elf: Box::new(x32) })
            .expect("one machine per digest");
        // A build the reader refused (Darwin's Mach-O): nothing holds it to the kernel, so
        // a `Machine` measurement over it is the contradiction and the gating stands.
        store
            .insert(
                "dd".repeat(32),
                FactEntry::Unreadable {
                    error: "not an ELF file (bad magic)".to_owned(),
                    mach_o: false,
                },
            )
            .expect("one entry per digest");
        let runtime =
            |(check, verdict, sha, gated)| runtime_observation(check, verdict, sha, gated);
        let clash = "stack-clash-guard-page";
        let agreeing: Vec<Observation> = [
            (clash, Verdict::Indeterminate, "aa", true),
            (clash, Verdict::On, "bb", false),
            (clash, Verdict::Indeterminate, "cc", true),
            (clash, Verdict::Indeterminate, "dd", true),
            ("no-strict-overflow", Verdict::Off, "aa", false),
            ("no-strict-overflow", Verdict::Off, "dd", false),
        ]
        .into_iter()
        .map(runtime)
        .collect();
        assert!(emulation_agrees(&agreeing, &store, &kernel, false).is_empty());

        for o in [
            (clash, Verdict::Indeterminate, "bb", true),
            ("no-strict-overflow", Verdict::Indeterminate, "aa", true),
            (clash, Verdict::Off, "aa", false),
            (clash, Verdict::On, "cc", false),
            (clash, Verdict::On, "dd", false),
        ]
        .into_iter()
        .map(runtime)
        {
            let found = emulation_agrees(std::slice::from_ref(&o), &store, &kernel, false);
            assert_eq!(found.len(), 1, "{} {:?}", o.check, o.verdict);
            assert_eq!(found[0].rule, RULE_RUN_RECORD);
            assert_eq!(found[0].property, format!("observations[{}].run", o.check));
        }
    }

    #[test]
    fn the_kernel_gate_is_held_to_the_execution_mode_and_its_basis() {
        use crate::env::{ExecutionMode, ModeBasis, ModeEvidence};
        let mut env = environment_fixture();
        let attributed = |env: &mut Environment, mode: ExecutionMode, basis: ModeBasis| {
            env.execution.mode = mode;
            env.execution.mode_evidence = ModeEvidence {
                basis,
                observed: (mode == ExecutionMode::Container).then_some(mode),
                observation: "what chard looked at".to_owned(),
            };
        };
        let with = |check: &str, verdict: Verdict, rule: Option<gating_rule::Rule>| {
            let mut o = observation(check, "-f", Channel::Runtime, verdict);
            o.gating = rule.map(|rule| Gating {
                rule,
                arch: None,
                libc: None,
                needs_vm: false,
                reason: "r".to_owned(),
            });
            o
        };
        let measured = || with("noexecstack-enforced", Verdict::On, None);
        let invalid = || with("noexecstack-enforced", Verdict::ProbeInvalid, None);
        let under = |rule| with("noexecstack-enforced", Verdict::Indeterminate, Some(rule));
        let needs_vm = || under(gating_rule::NEEDS_VM);
        let assumed = || under(gating_rule::EXECUTION_MODE_ASSUMED);
        let arch = || {
            with(
                "noexecstack-enforced",
                Verdict::Unsupported,
                Some(gating_rule::ARCH),
            )
        };
        // The target witnesses overwrite an arch-gated observation after measurement, a
        // withheld one included, so they stand under any attribution (a rule refusing
        // them would refuse a correct report).
        let target = || under(gating_rule::TARGET_CONTRADICTED);
        let abi = || under(gating_rule::TARGET_ABI_CONTRADICTED);
        let other = || with("no-strict-overflow", Verdict::On, None);
        // (mode, basis, the states that agree, the states that contradict)
        let table: Vec<(ExecutionMode, ModeBasis, Vec<Observation>, Vec<Observation>)> = vec![
            (
                ExecutionMode::Host,
                ModeBasis::AssumedHost,
                vec![assumed(), arch(), target(), abi(), other()],
                vec![measured(), invalid(), needs_vm()],
            ),
            (
                ExecutionMode::Container,
                ModeBasis::Measured,
                vec![needs_vm(), arch(), target(), abi(), other()],
                vec![measured(), invalid(), assumed()],
            ),
            (
                ExecutionMode::Host,
                ModeBasis::AssertedButUnobservable,
                vec![measured(), invalid(), arch(), target(), abi(), other()],
                vec![needs_vm(), assumed()],
            ),
            (
                ExecutionMode::Vm,
                ModeBasis::AssertedButUnobservable,
                vec![measured(), arch(), other()],
                vec![needs_vm(), assumed()],
            ),
        ];
        let mut rows = 0;
        for (mode, basis, agreeing, contradicting) in table {
            attributed(&mut env, mode, basis);
            let found = kernel_gate_agrees(&agreeing, &env.execution);
            assert!(found.is_empty(), "{mode:?} on {basis:?}: {found:?}");
            for o in contradicting {
                let found = kernel_gate_agrees(std::slice::from_ref(&o), &env.execution);
                assert_eq!(
                    found.len(),
                    1,
                    "{mode:?} on {basis:?}: {} {:?}",
                    o.check,
                    o.verdict
                );
                assert_eq!(found[0].rule, RULE_KERNEL_GATE);
                assert_eq!(
                    found[0].property,
                    "observations[noexecstack-enforced].gating"
                );
                rows += 1;
            }
        }
        assert_eq!(
            rows, 10,
            "the contradicting states of the four attributions"
        );
    }

    #[test]
    fn on_macos_a_refused_record_is_held_to_the_probes_translation_read() {
        let kernel = crate::env::Kernel {
            release: "unknown".to_owned(),
            arch: "aarch64".to_owned(),
            machine: None,
            is_host_kernel: false,
            ownership: crate::env::KernelOwnership::Own,
        };
        let mut store = FactStore::default();
        store
            .insert(
                "dd".repeat(32),
                FactEntry::Unreadable {
                    error: "not an ELF file (bad magic)".to_owned(),
                    mach_o: false,
                },
            )
            .expect("one entry per digest");
        let clash = "stack-clash-guard-page";
        let with = |verdict: Verdict, gated: bool, sha: &str, stdout: &str| {
            let mut o = runtime_observation(clash, verdict, sha, gated);
            if let Some(run) = o.run.as_mut() {
                run.stdout = stdout.to_owned();
            }
            o
        };
        let scprt = "SCPRT dist=8388620 n=67108864 ratio_pct=12";
        let native = format!("CHARD-TRANSLATION 0\n{scprt}");
        let translated = format!("CHARD-TRANSLATION 1\n{scprt}");
        let unreadable = format!("CHARD-TRANSLATION unreadable errno:2\n{scprt}");
        let twice = format!("CHARD-TRANSLATION 0\nCHARD-TRANSLATION 0\n{scprt}");
        let measured = |stdout: &str| with(Verdict::On, false, "dd", stdout);
        let withheld = |stdout: &str| with(Verdict::Indeterminate, true, "dd", stdout);
        let agreeing = vec![
            measured(&native),
            withheld(&translated),
            withheld(&unreadable),
            withheld(scprt),
            withheld(&twice),
        ];
        assert!(emulation_agrees(&agreeing, &store, &kernel, true).is_empty());
        for (verdict, gated, sha, stdout) in [
            (Verdict::Indeterminate, true, "dd", native.as_str()),
            (Verdict::On, false, "dd", translated.as_str()),
            (Verdict::On, false, "dd", unreadable.as_str()),
            (Verdict::On, false, "dd", scprt),
            (Verdict::On, false, "dd", twice.as_str()),
            // No stored entry for the build: the line is not consulted.
            (Verdict::On, false, "ee", native.as_str()),
        ] {
            let o = with(verdict, gated, sha, stdout);
            let found = emulation_agrees(std::slice::from_ref(&o), &store, &kernel, true);
            assert_eq!(
                found.len(),
                1,
                "{:?} over {:?}",
                o.verdict,
                o.run.map(|r| r.stdout)
            );
            assert_eq!(found[0].rule, RULE_RUN_RECORD);
        }
        // Off macOS the line settles nothing: the measurement contradicts, the gating stands.
        assert_eq!(
            emulation_agrees(&[measured(&native)], &store, &kernel, false).len(),
            1
        );
        assert!(emulation_agrees(&[withheld(&native)], &store, &kernel, false).is_empty());
    }

    #[test]
    fn runs_agree_reads_the_platform_from_the_report() {
        let mut report = identity_fixture();
        report.environment.kernel = crate::env::Kernel {
            release: "unknown".to_owned(),
            arch: "aarch64".to_owned(),
            machine: None,
            is_host_kernel: false,
            ownership: crate::env::KernelOwnership::Own,
        };
        let mut store = FactStore::default();
        store
            .insert(
                "dd".repeat(32),
                FactEntry::Unreadable {
                    error: "not an ELF file (bad magic)".to_owned(),
                    mach_o: false,
                },
            )
            .expect("one entry per digest");
        report.facts = store;
        let mut o = runtime_observation("stack-clash-guard-page", Verdict::On, "dd", false);
        if let Some(run) = o.run.as_mut() {
            run.stdout =
                "CHARD-TRANSLATION 0\nSCPRT dist=8388620 n=67108864 ratio_pct=12".to_owned();
        }
        report.observations = vec![o];
        let emulation = |r: &Report| runs_agree(r).len() - run_record_agrees(&r.observations).len();
        report.environment.distro.id = "macos".to_owned();
        assert_eq!(
            emulation(&report),
            0,
            "on macOS the probe's 0 publishes the reading"
        );
        report.environment.distro.id = "fedora".to_owned();
        assert_eq!(
            emulation(&report),
            1,
            "off macOS a reading over a refused record contradicts"
        );
    }

    /// A runtime observation of `check` over the artifact `sha` (repeated to a digest),
    /// gated under `run-under-emulation` where `gated`: the emulation rule's test input.
    fn runtime_observation(check: &str, verdict: Verdict, sha: &str, gated: bool) -> Observation {
        let mut o = observation(check, "-f", Channel::Runtime, verdict);
        o.run = Some(RunRecord {
            argv: vec!["probe".to_owned()],
            exit_status: 0,
            signal: None,
            stdout: String::new(),
            stderr: String::new(),
            timed_out: false,
            deadline_ms: Some(5000),
            output_error: None,
            output_truncated: false,
            duration_ms: 1,
            environment: None,
        });
        o.build = Some(BuildRecord {
            argv: vec!["cc".to_owned()],
            dropped_flags: Vec::new(),
            exit_status: 0,
            stdout: String::new(),
            stderr: String::new(),
            duration_ms: 0,
            artifact_sha256: Some(sha.repeat(32)),
            stdout_sha256: None,
            stdout_unterminated: false,
        });
        o.gating = gated.then(|| Gating {
            rule: gating_rule::RUN_UNDER_EMULATION,
            arch: None,
            libc: None,
            needs_vm: false,
            reason: "r".to_owned(),
        });
        o
    }

    #[test]
    fn a_run_under_emulation_is_held_to_the_byte_order() {
        use crate::elf::ByteOrder::{BigEndian, LittleEndian};
        let runtime = runtime_observation;
        let clash = "stack-clash-guard-page";
        let kernel_of = |machine: &str| crate::env::Kernel {
            release: "7.3.0".to_owned(),
            arch: "x86_64".to_owned(),
            machine: Some(machine.to_owned()),
            is_host_kernel: false,
            ownership: crate::env::KernelOwnership::Own,
        };
        let mut store = FactStore::default();
        for (sha, machine, order) in [
            ("dd", "ppc64", Some(BigEndian)),
            ("ee", "ppc64", Some(LittleEndian)),
            ("ff", "aarch64", Some(LittleEndian)),
            ("gg", "aarch64", Some(BigEndian)),
            ("hh", "x86_64", None),
        ] {
            let mut elf = elf_of_machine(machine);
            elf.elf_data = order;
            store
                .insert(sha.repeat(32), FactEntry::Elf { elf: Box::new(elf) })
                .expect("one artifact per digest");
        }
        for (kernel, native, foreign) in [
            ("ppc64le", "ee", "dd"),
            ("aarch64_be", "gg", "ff"),
            ("x86_64", "bb", "hh"),
        ] {
            let kernel = kernel_of(kernel);
            let store = if native == "bb" {
                &agreeing_store(&store)
            } else {
                &store
            };
            let agreeing = [
                runtime(clash, Verdict::Indeterminate, foreign, true),
                runtime(clash, Verdict::On, native, false),
            ];
            assert!(
                emulation_agrees(&agreeing, store, &kernel, false).is_empty(),
                "{}: {foreign} withheld, {native} measured",
                kernel.native_machine()
            );
            for o in [
                runtime(clash, Verdict::On, foreign, false),
                runtime(clash, Verdict::Indeterminate, native, true),
            ] {
                let found = emulation_agrees(std::slice::from_ref(&o), store, &kernel, false);
                assert_eq!(
                    found.len(),
                    1,
                    "{}: {} {:?}",
                    kernel.native_machine(),
                    o.check,
                    o.verdict
                );
            }
        }
    }

    /// `store` with the `bb` x86_64 little-endian artifact of the test above beside it.
    fn agreeing_store(store: &FactStore) -> FactStore {
        let mut out = store.clone();
        out.insert(
            "bb".repeat(32),
            FactEntry::Elf {
                elf: Box::new(elf_of_machine("x86_64")),
            },
        )
        .expect("one artifact per digest");
        out
    }

    #[test]
    fn a_verdict_the_gating_rule_does_not_reserve_contradicts_the_report() {
        let gated = |check: &str, rule: gating_rule::Rule, verdict: Verdict| {
            let mut o = observation(check, "-f", Channel::ElfStatic, verdict);
            o.gating = Some(Gating {
                rule,
                arch: None,
                libc: None,
                needs_vm: false,
                reason: "r".to_owned(),
            });
            o
        };
        let agreeing = vec![
            gated(
                "a",
                gating_rule::NO_UNHARDENED_STATE,
                Verdict::Indeterminate,
            ),
            gated("b", gating_rule::FLAG_UNKNOWN, Verdict::Unsupported),
            gated(
                "c",
                gating_rule::STDLIB_LACKS_OBSERVABLE,
                Verdict::NotApplicable,
            ),
            observation("d", "-f", Channel::ElfStatic, Verdict::On),
        ];
        assert!(gating_verdict_agrees(&agreeing).is_empty());

        for (rule, verdict) in [
            (gating_rule::NO_UNHARDENED_STATE, Verdict::Unsupported),
            (gating_rule::FLAG_UNKNOWN, Verdict::Indeterminate),
            (gating_rule::STDLIB_LACKS_OBSERVABLE, Verdict::Unsupported),
            (gating_rule::LEVEL_OFF_SCALE, Verdict::On),
        ] {
            let found = gating_verdict_agrees(&[gated("x", rule, verdict)]);
            assert_eq!(found.len(), 1, "{} beside {verdict:?}", rule.id);
            assert_eq!(found[0].rule, RULE_GATING_VERDICT);
            assert!(
                found[0].claims.iter().any(|c| c.contains(verdict.as_str()))
                    && found[0].claims.iter().any(|c| c.contains(rule.id)),
                "{:?}",
                found[0].claims
            );
        }
    }

    #[test]
    fn an_explicit_profile_id_follows_its_flag_lists() {
        let hardened = ["-O2".to_owned(), "-fstack-protector-strong".to_owned()];
        let plain = ["-O2".to_owned()];
        let a = explicit_profile_id(&hardened, &[], &[]);
        assert_eq!(a, explicit_profile_id(&hardened, &[], &[]));
        assert_ne!(a, explicit_profile_id(&plain, &[], &[]));
        assert_ne!(
            explicit_profile_id(&plain, &[], &[]),
            explicit_profile_id(&[], &plain, &[]),
            "the same flags in a different list are a different profile"
        );
        assert!(a.starts_with("explicit:") && a.len() == "explicit:".len() + 12);
    }

    #[test]
    fn a_profile_id_carries_its_env_pairs() {
        use crate::compile::CompilerEnvironment;
        let pair = |name: &str, value: &str| format!("{name}={value}");
        let under = |id: &str, added: &[String]| Profile {
            id: id.to_owned(),
            compiler_environment: CompilerEnvironment::under(
                &crate::compile::compiler_environment_additions(added).expect("plain pairs"),
            ),
            ..bare()
        };
        assert_eq!(under("bare", &[]).published_id(), "bare");
        let a = under("bare", &[pair("NIX_HARDENING_ENABLE", "pic")]).published_id();
        let b = under("bare", &[pair("NIX_HARDENING_ENABLE", "pic fortify")]).published_id();
        assert_ne!(a, b, "two values joined as one column");
        assert!(
            a.starts_with("bare+env:") && a.len() == "bare+env:".len() + 12,
            "{a}"
        );
        assert_ne!(
            under("bare", &[pair("A", "1"), pair("B", "2")]).published_id(),
            under("bare", &[pair("A", "1B=2")]).published_id(),
            "two sets of pairs spelled one digest"
        );
        let json =
            serde_json::to_value(under("bare", &[pair("NIX_HARDENING_ENABLE", "pic")])).unwrap();
        assert_eq!(json["id"].as_str(), Some(a.as_str()));
        assert_eq!(
            json["compiler_environment"]["set"]["NIX_HARDENING_ENABLE"].as_str(),
            Some("pic")
        );
        let guide = under(OPENSSF_TLDR_ID, &[pair("NIX_HARDENING_ENABLE", "pic")]);
        assert_eq!(guide.guide_revision(), Some(crate::guide::REVISION));
        assert!(guide.published_id().starts_with("openssf-tldr+env:"));
        assert_eq!(
            under("bare", &[pair("B", "2"), pair("A", "1")]).published_id(),
            under("bare", &[pair("A", "1"), pair("B", "2")]).published_id(),
            "one set of pairs given in two orders is two ids"
        );
    }

    #[test]
    fn every_consistency_rule_declares_the_field_it_checks() {
        use std::collections::BTreeSet;

        let declared: BTreeSet<&str> = RULE_SUBJECTS.iter().map(|(rule, _)| *rule).collect();
        let applied: BTreeSet<&str> = RULES.iter().copied().collect();
        assert_eq!(
            declared, applied,
            "RULE_SUBJECTS and RULES name different rules, so one of them is stale"
        );

        let fields = fields_the_rules_check();
        for (rule, field) in RULE_SUBJECTS {
            assert!(
                fields.iter().any(|f| f == field),
                "`{rule}` checks `{field}`, which is not published in fields_checked"
            );
        }
        // And nothing is published that no rule checks.
        for field in &fields {
            assert!(
                RULE_SUBJECTS.iter().any(|(_, f)| f == field),
                "fields_checked publishes `{field}`, which no rule examines"
            );
        }
        assert!(!fields.is_empty(), "no field was published at all");
    }

    /// A published control arm with an outcome and nothing else.
    fn published_arm(outcome: Option<Outcome>) -> ControlArm {
        ControlArm {
            flags: Vec::new(),
            outcome,
            detail: None,
            build: None,
            run: None,
            macro_source: None,
            macro_dump: None,
            decoded: None,
            overridden: None,
        }
    }

    /// An observation carrying a triple, its arms and its discrimination given by hand.
    fn with_triple(
        verdict: Verdict,
        positive: Option<Outcome>,
        negative: Option<Outcome>,
        regime: Option<ControlArm>,
        discrimination: Discrimination,
    ) -> Observation {
        let mut o = observation("c", "-f", Channel::ElfStatic, verdict);
        o.controls = Some(Controls {
            positive: published_arm(positive),
            negative: published_arm(negative),
            regime_negative: regime,
            discrimination,
        });
        o
    }

    #[test]
    fn a_verdict_its_controls_earned_raises_nothing() {
        use Discrimination::{Discriminating, Withheld};
        use Outcome::{Absent, Present};

        let agreeing = vec![
            with_triple(
                Verdict::On,
                Some(Present),
                Some(Absent),
                None,
                Discriminating,
            ),
            with_triple(
                Verdict::Off,
                Some(Present),
                Some(Absent),
                Some(published_arm(Some(Absent))),
                Discriminating,
            ),
            with_triple(
                Verdict::ProbeInvalid,
                Some(Absent),
                Some(Absent),
                None,
                Withheld(WithheldBecause::PositiveSilent),
            ),
            with_triple(
                Verdict::Indeterminate,
                Some(Present),
                Some(Absent),
                None,
                Discriminating,
            ),
            with_triple(
                Verdict::Unsupported,
                Some(Present),
                None,
                None,
                Withheld(WithheldBecause::NegativeUnevaluable),
            ),
            observation("d", "-f", Channel::ElfStatic, Verdict::BuildFailed),
        ];
        assert!(
            controls_agree(&agreeing, false).is_empty(),
            "{:?}",
            controls_agree(&agreeing, false)
        );
    }

    #[test]
    fn a_verdict_its_controls_did_not_earn_contradicts_the_report() {
        use Discrimination::{Discriminating, Withheld};
        use Outcome::{Absent, Indeterminate, Present};

        let violations = vec![
            (
                "a measurement with no triple",
                observation("c", "-f", Channel::ElfStatic, Verdict::On),
            ),
            (
                "an on beside a withheld triple",
                with_triple(
                    Verdict::On,
                    Some(Present),
                    Some(Present),
                    None,
                    Withheld(WithheldBecause::NegativeAlsoShows),
                ),
            ),
            (
                "an off whose arms never showed absence",
                with_triple(
                    Verdict::Off,
                    Some(Present),
                    Some(Indeterminate),
                    None,
                    Discriminating,
                ),
            ),
            (
                "a regime arm that could not be evaluated",
                with_triple(
                    Verdict::On,
                    Some(Present),
                    Some(Absent),
                    Some(published_arm(None)),
                    Discriminating,
                ),
            ),
            (
                "a probe-invalid beside a discriminating triple",
                with_triple(
                    Verdict::ProbeInvalid,
                    Some(Present),
                    Some(Absent),
                    None,
                    Discriminating,
                ),
            ),
            (
                "a withheld cause the arms do not give",
                with_triple(
                    Verdict::ProbeInvalid,
                    Some(Absent),
                    Some(Absent),
                    None,
                    Withheld(WithheldBecause::NegativeAlsoShows),
                ),
            ),
        ];
        for (shape, o) in violations {
            let found = controls_agree(std::slice::from_ref(&o), false);
            assert!(!found.is_empty(), "{shape} raised nothing");
            assert!(
                found.iter().all(|c| c.rule == RULE_VERDICT_CONTROLS),
                "{shape}: {found:?}"
            );
        }
    }

    #[test]
    #[expect(
        clippy::too_many_lines,
        reason = "one table of edits, each read against the rule on both arms"
    )]
    fn an_overridden_record_is_held_to_its_arm_and_its_cause() {
        use Discrimination::Withheld;
        use Outcome::{Absent, Present};
        type Side = fn(&mut Controls) -> &mut ControlArm;
        type Edit = fn(&mut Controls, Side, Side, WithheldBecause);

        /// The clause a refused edit is refused by, as a fragment of its sentence.
        const CAUSE: &str = "and the published `controls` says otherwise";
        const UNASKED: &str = "name no question the driver was asked about this arm";
        const UNFOUNDED: &str = "is not one of the arm's";

        let finding = |flag: &str, by: &str| {
            Some(crate::overridden::Listed::Overridden(
                crate::overridden::Overridden {
                    flag: flag.to_owned(),
                    by: by.to_owned(),
                },
            ))
        };
        // Each side: the outcomes that ask about the arm, the cause a finding there earns
        // and the one the outcomes alone give, and the asked and the other arm.
        let negative: Side = |c| &mut c.negative;
        let positive: Side = |c| &mut c.positive;
        let sides = [
            (
                (Present, Present),
                WithheldBecause::NegativeOverridden,
                WithheldBecause::NegativeAlsoShows,
                negative,
                positive,
                ("-fno-stack-protector", "-fstack-protector-strong"),
            ),
            (
                (Absent, Absent),
                WithheldBecause::PositiveOverridden,
                WithheldBecause::PositiveSilent,
                positive,
                negative,
                (
                    "-ftrivial-auto-var-init=pattern",
                    "-ftrivial-auto-var-init=zero",
                ),
            ),
        ];
        let edits: [(&str, &str, Edit); 7] = [
            (
                "the record deleted under its cause",
                CAUSE,
                |c, asked, _, _| {
                    asked(c).overridden = None;
                },
            ),
            (
                "an unread command under the cause a finding earns",
                CAUSE,
                |c, asked, _, _| {
                    asked(c).overridden = Some(crate::overridden::Listed::OverriddenUnread(
                        "the driver exited 1".to_owned(),
                    ));
                },
            ),
            (
                "the generic cause over the record",
                CAUSE,
                |c, _, _, generic| {
                    c.discrimination = Withheld(generic);
                },
            ),
            (
                "the record on the arm nothing asked about",
                UNASKED,
                |c, asked, other, _| {
                    let (record, flags) = (asked(c).overridden.clone(), asked(c).flags.clone());
                    other(c).overridden = record;
                    other(c).flags = flags;
                },
            ),
            ("the record on the regime arm", UNASKED, |c, asked, _, _| {
                let mut arm = published_arm(Some(Absent));
                arm.flags = asked(c).flags.clone();
                arm.overridden = asked(c).overridden.clone();
                c.regime_negative = Some(arm);
            }),
            (
                "a flag the arm never carried",
                UNFOUNDED,
                |c, asked, _, _| {
                    asked(c).flags = vec!["-fcf-protection=none".to_owned()];
                },
            ),
            (
                "a second word of another option",
                UNFOUNDED,
                |c, asked, _, _| {
                    if let Some(crate::overridden::Listed::Overridden(found)) =
                        asked(c).overridden.as_mut()
                    {
                        found.by = "-fcf-protection=full".to_owned();
                    }
                },
            ),
        ];

        let mut refused = 0;
        for ((positive_read, negative_read), cause, generic, asked, other, (flag, by)) in sides {
            let published = || {
                let mut o = with_triple(
                    Verdict::ProbeInvalid,
                    Some(positive_read),
                    Some(negative_read),
                    None,
                    Withheld(cause),
                );
                let c = o.controls.as_mut().expect("the triple");
                other(c).flags = vec!["-fother-arm".to_owned()];
                asked(c).flags = vec![flag.to_owned()];
                asked(c).overridden = finding(flag, by);
                o
            };
            let found = controls_agree(&[published()], true);
            assert!(found.is_empty(), "{cause:?}: {found:?}");

            // A command the driver would not list is no finding: beside the cause the
            // outcomes give it raises nothing on the arm that was asked about, and is
            // refused on the other.
            let mut unanswered = published();
            let c = unanswered.controls.as_mut().expect("the triple");
            asked(c).overridden = Some(crate::overridden::Listed::OverriddenUnread(
                "the driver exited 1".to_owned(),
            ));
            c.discrimination = Withheld(generic);
            let found = controls_agree(std::slice::from_ref(&unanswered), true);
            assert!(found.is_empty(), "{cause:?}: {found:?}");
            let c = unanswered.controls.as_mut().expect("the triple");
            other(c).overridden = asked(c).overridden.take();
            let found = controls_agree(std::slice::from_ref(&unanswered), true);
            assert!(
                found.iter().any(|c| c.detail.contains(UNASKED)),
                "{cause:?}: {found:?}"
            );

            // The record deleted with its cause put back, which nothing published can refuse.
            let mut erased = published();
            let c = erased.controls.as_mut().expect("the triple");
            asked(c).overridden = None;
            c.discrimination = Withheld(generic);
            let found = controls_agree(std::slice::from_ref(&erased), true);
            assert!(found.is_empty(), "{cause:?}: {found:?}");
            assert_eq!(erased.verdict, published().verdict);

            // Its reverse: a finding added to a triple that carried none, with the cause it
            // earns.
            let mut forged = erased.clone();
            let c = forged.controls.as_mut().expect("the triple");
            asked(c).overridden = finding(flag, by);
            c.discrimination = Withheld(cause);
            let found = controls_agree(std::slice::from_ref(&forged), true);
            assert!(found.is_empty(), "{cause:?}: {found:?}");
            assert_eq!(forged.verdict, erased.verdict);

            // The second word changed to another setting of the same option stands as well as
            // the one the listing showed.
            let another = if flag == "-fno-stack-protector" {
                "-fstack-protector-all"
            } else {
                "-ftrivial-auto-var-init=uninitialized"
            };
            assert_ne!(another, by, "the swap changes the word");
            let mut swapped = published();
            let c = swapped.controls.as_mut().expect("the triple");
            if let Some(crate::overridden::Listed::Overridden(found)) = asked(c).overridden.as_mut()
            {
                another.clone_into(&mut found.by);
            }
            let found = controls_agree(std::slice::from_ref(&swapped), true);
            assert!(found.is_empty(), "{cause:?}: {found:?}");

            for (name, _, edit) in edits {
                let mut o = published();
                edit(
                    o.controls.as_mut().expect("the triple"),
                    asked,
                    other,
                    generic,
                );
                let found = controls_agree(std::slice::from_ref(&o), true);
                assert!(
                    found.len() == 1 && found.iter().all(|c| c.rule == RULE_VERDICT_CONTROLS),
                    "{cause:?}, {name}: {found:?}"
                );
                refused += 1;
            }
        }
        assert_eq!(refused, 14, "every edit was refused on each arm");
    }

    /// A profile adding to each of its three lists, so a regime arm's list shows which it read.
    fn regime_profile() -> Profile {
        let mut profile = bare();
        profile.cflags = vec!["-O2".to_owned()];
        profile.cxxflags = vec!["-O1".to_owned()];
        profile.ldflags = vec!["-Wl,-z,now".to_owned()];
        profile
    }

    /// The first check of a `lang` probe that declares a regime arm.
    fn regime_check(lang: crate::probe::Lang) -> &'static Check {
        crate::probe::CORPUS
            .iter()
            .filter(|p| p.lang == lang)
            .find_map(|p| p.checks.iter().find(|c| c.regime_arm().is_some()))
            .expect("a check of the language that declares a regime arm")
    }

    /// An observation of `id` stating `verdict` beside a discriminating triple whose regime arm
    /// reads `absent` and publishes `flags`.
    fn with_regime_arm(verdict: Verdict, id: &str, flags: &[String]) -> Observation {
        let mut arm = published_arm(Some(Outcome::Absent));
        arm.flags = flags.to_vec();
        let mut o = with_triple(
            verdict,
            Some(Outcome::Present),
            Some(Outcome::Absent),
            Some(arm),
            Discrimination::Discriminating,
        );
        o.check = id.to_owned();
        o
    }

    /// Where the rule names a regime arm's flags.
    fn regime_flags_property(id: &str) -> String {
        format!("observations[{id}].controls.regime_negative.flags")
    }

    #[test]
    fn a_regime_arm_is_held_to_the_profile_followed_by_its_declared_arm() {
        use crate::probe::Lang;

        let (check, cxx_check) = (regime_check(Lang::C), regime_check(Lang::Cxx));
        let undeclared = crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks)
            .find(|c| c.regime_arm().is_none())
            .expect("a check that declares no regime arm");
        let declared = check.regime_arm().expect("declared");
        let profile = regime_profile();
        let owed = crate::measure::variant_flags(&profile, Lang::C, declared);
        let cxx_declared = cxx_check.regime_arm().expect("declared");
        let cxx_owed = crate::measure::variant_flags(&profile, Lang::Cxx, cxx_declared);
        let cxx_as_c = crate::measure::variant_flags(&profile, Lang::C, cxx_declared);
        let observed = |id: &str, flags: &[String]| with_regime_arm(Verdict::On, id, flags);
        let countermand_dropped: Vec<String> = owed
            .iter()
            .filter(|f| !declared.contains(&f.as_str()))
            .cloned()
            .collect();
        let profile_dropped: Vec<String> = declared.iter().map(|f| (*f).to_owned()).collect();
        let link_dropped: Vec<String> = owed
            .iter()
            .filter(|f| !profile.ldflags.contains(f))
            .cloned()
            .collect();
        let reordered: Vec<String> = owed.iter().rev().cloned().collect();
        let mut extended = owed.clone();
        extended.push("-fno-stack-protector".to_owned());

        for (id, flags) in [(check.id, &owed), (cxx_check.id, &cxx_owed)] {
            assert!(
                regime_flags_agree(&[observed(id, flags)], &profile, true).is_empty(),
                "{id}: the arm `measure` builds"
            );
        }
        assert!(
            regime_flags_agree(&[observed("no-such-check", &owed)], &profile, true).is_empty(),
            "an id outside the corpus has no declaration"
        );
        assert!(
            controls_agree(&[observed(check.id, &countermand_dropped)], false).is_empty(),
            "the triple's own rule reads no flags"
        );
        let edits = [
            (check.id, &countermand_dropped),
            (check.id, &profile_dropped),
            (check.id, &link_dropped),
            (check.id, &reordered),
            (check.id, &extended),
            (cxx_check.id, &cxx_as_c),
            (undeclared.id, &owed),
        ];
        for (_, flags) in &edits[..6] {
            assert_ne!(*flags, &owed, "each edit changes the list");
        }
        assert_ne!(cxx_as_c, cxx_owed, "the two languages' lists differ");
        let verdicts = [Verdict::On, Verdict::ProbeInvalid, Verdict::Indeterminate];
        for ((id, flags), verdict) in edits.iter().flat_map(|e| verdicts.map(|v| (*e, v))) {
            let found = regime_flags_agree(&[with_regime_arm(verdict, id, flags)], &profile, true);
            assert!(
                found.len() == 1
                    && found[0].rule == RULE_VERDICT_CONTROLS
                    && found[0].property == regime_flags_property(id),
                "{id} {flags:?} beside {verdict:?}: {found:?}"
            );
            assert!(
                regime_flags_agree(&[observed(id, flags)], &profile, false).is_empty(),
                "{id} {flags:?}: a report of another corpus is read as written"
            );
        }
    }

    #[test]
    fn the_publication_pass_holds_a_regime_arm_in_a_report_of_this_corpus() {
        let check = regime_check(crate::probe::Lang::C);
        let profile = regime_profile();
        let declared = check.regime_arm().expect("declared");
        let owed = crate::measure::variant_flags(&profile, crate::probe::Lang::C, declared);
        let countermand_dropped: Vec<String> = owed
            .iter()
            .filter(|f| !declared.contains(&f.as_str()))
            .cloned()
            .collect();
        let mut report = identity_fixture();
        report.profile = profile;
        report.observations = vec![with_regime_arm(Verdict::On, check.id, &countermand_dropped)];
        let raised = |report: &Report| {
            consistency(report)
                .contradictions
                .iter()
                .filter(|c| c.property == regime_flags_property(check.id))
                .count()
        };
        report.run.probe_corpus_sha256 = crate::probe::corpus_sha256();
        assert_eq!(raised(&report), 1, "a report of this corpus");
        let mut unknown = report.clone();
        unknown.observations = vec![with_regime_arm(Verdict::On, "no-such-check", &owed)];
        assert!(
            consistency(&unknown)
                .contradictions
                .iter()
                .any(|c| c.property == "no-such-check"),
            "an id outside this corpus"
        );
        report.run.probe_corpus_sha256 = "another corpus".to_owned();
        assert_eq!(raised(&report), 0, "a report of another corpus");
    }

    #[test]
    fn a_regime_arm_owed_by_the_profile_is_owed_whether_or_not_it_is_published() {
        use Outcome::{Absent, Present};

        let check = crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks)
            .find(|c| c.regime_arm().is_some())
            .expect("a check that declares a regime arm");
        let mut o = with_triple(
            Verdict::On,
            Some(Present),
            Some(Absent),
            None,
            Discrimination::Discriminating,
        );
        o.check = check.id.to_owned();
        assert!(
            controls_agree(std::slice::from_ref(&o), true).is_empty(),
            "a clean profile owes no regime arm"
        );
        let found = controls_agree(std::slice::from_ref(&o), false);
        assert!(
            !found.is_empty() && found.iter().all(|c| c.rule == RULE_VERDICT_CONTROLS),
            "an owed regime arm deleted from {}: {found:?}",
            check.id
        );
    }

    /// The first graded check on an ordered scale whose ask sits above its lowest word,
    /// with a word below the ask and the ask itself.
    fn ordered_check() -> (&'static Check, &'static str, &'static str) {
        crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks)
            .find_map(|c| {
                let grade = c.levels.grade()?;
                let crate::probe::Scale::Ordered(words) = grade.scale else {
                    return None;
                };
                let below = words.first().filter(|w| **w != grade.recommended)?;
                Some((c, *below, grade.recommended))
            })
            .expect("the corpus grades a check on an ordered scale")
    }

    #[test]
    fn a_level_off_its_checks_scale_contradicts_the_report() {
        let (graded, below, ask) = ordered_check();
        let ungraded = crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks)
            .find(|c| c.levels == crate::probe::Levels::None)
            .expect("the corpus has a check with no level vocabulary");
        let cell = |check: &Check, verdict: Verdict, level: Option<&str>| {
            let mut o = observation(check.id, check.flag, check.channel(), verdict);
            o.level = level.map(ToOwned::to_owned);
            o.recommended_level = check.recommended_level().map(ToOwned::to_owned);
            o
        };
        let agreeing = vec![
            cell(graded, Verdict::On, Some(ask)),
            cell(graded, Verdict::Partial, Some(below)),
            cell(graded, Verdict::Off, None),
            cell(graded, Verdict::Indeterminate, None),
            cell(ungraded, Verdict::On, None),
        ];
        let found = level_agrees(&agreeing, &corpus_check_by_id);
        assert!(found.is_empty(), "{found:?}");

        let mut wrong_ask = cell(graded, Verdict::On, Some(ask));
        wrong_ask.recommended_level = Some(below.to_owned());
        let violations = vec![
            (
                "an on below the ask",
                cell(graded, Verdict::On, Some(below)),
            ),
            (
                "a partial that meets the ask",
                cell(graded, Verdict::Partial, Some(ask)),
            ),
            (
                "a partial on no scale",
                cell(ungraded, Verdict::Partial, None),
            ),
            (
                "an on beside an off-scale word",
                cell(graded, Verdict::On, Some("not-a-word-on-any-scale")),
            ),
            (
                "an on with a word its vocabulary lacks",
                cell(ungraded, Verdict::On, Some("strong")),
            ),
            (
                "a level beside a withheld verdict",
                cell(graded, Verdict::ProbeInvalid, Some(ask)),
            ),
            ("an ask the check does not make", wrong_ask),
        ];
        for (shape, o) in violations {
            let found = level_agrees(std::slice::from_ref(&o), &corpus_check_by_id);
            assert!(!found.is_empty(), "{shape} raised nothing");
            assert!(
                found.iter().all(|c| c.rule == RULE_LEVEL_SCALE),
                "{shape}: {found:?}"
            );
        }
    }

    /// A build record whose stderr is `stderr`.
    fn stderr_record(exit_status: i32, stderr: &str) -> BuildRecord {
        BuildRecord {
            argv: vec!["cc".to_owned()],
            dropped_flags: Vec::new(),
            exit_status,
            stdout: String::new(),
            stderr: stderr.to_owned(),
            duration_ms: 1,
            artifact_sha256: None,
            stdout_sha256: None,
            stdout_unterminated: false,
        }
    }

    /// An observation of `check` withheld under `rule`, its two arms' stderr given and its
    /// reason quoting `quote`.
    fn rejection_cell(
        check: &Check,
        rule: gating_rule::Rule,
        [positive, negative]: [&str; 2],
        quote: &str,
    ) -> Observation {
        let mut o = observation(check.id, check.flag, check.channel(), rule.verdict());
        let mut pos = published_arm(Some(Outcome::Indeterminate));
        pos.build = Some(stderr_record(1, positive));
        let mut neg = published_arm(Some(Outcome::Absent));
        neg.build = Some(stderr_record(1, negative));
        o.controls = Some(Controls {
            positive: pos,
            negative: neg,
            regime_negative: None,
            discrimination: Discrimination::Withheld(WithheldBecause::PositiveIndeterminate),
        });
        o.gating = Some(Gating {
            rule,
            arch: None,
            libc: None,
            needs_vm: false,
            reason: format!("the driver said: {quote}"),
        });
        o
    }

    #[test]
    fn a_rejection_its_arm_did_not_print_contradicts_the_report() {
        use crate::measure::control_flag_rejection;

        let check = crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks)
            .find(|c| {
                c.positive.first().is_some_and(|f| f.starts_with("-f"))
                    && c.negative.first().is_some_and(|f| f.starts_with("-f"))
            })
            .expect("the corpus has a check with -f controls on both arms");
        let unknown = |flag: &str| format!("cc: error: unknown argument: '{flag}'");
        let refused = |flag: &str| format!("cc: error: '{flag}' hasn't been enabled");
        let cell = |rule: gating_rule::Rule, positive: &str, negative: &str, quote: &str| {
            rejection_cell(check, rule, [positive, negative], quote)
        };
        let pos_line = unknown(check.positive[0]);
        let neg_line = unknown(check.negative[0]);
        let refusal = refused(check.positive[0]);
        let quoted = |line: &str, flags: &[&str]| {
            control_flag_rejection(&stderr_record(1, line), flags).expect("the reader sees it")
        };
        let (q_pos, q_neg) = (
            quoted(&pos_line, check.positive),
            quoted(&neg_line, check.negative),
        );
        let q_ref = quoted(&refusal, check.positive);
        let (unknown_rule, refused_rule) = (gating_rule::FLAG_UNKNOWN, gating_rule::FLAG_REFUSED);
        let unhardened = gating_rule::NO_UNHARDENED_STATE;
        let agreeing = vec![
            cell(unknown_rule, &pos_line, "", &q_pos),
            cell(refused_rule, &refusal, "", &q_ref),
            cell(unhardened, "", &neg_line, &q_neg),
            cell(gating_rule::LIBC_DECLARED, "", "", "no stderr is quoted"),
        ];
        let found = rejection_agrees(&agreeing, &corpus_check_by_id, None);
        assert!(found.is_empty(), "{found:?}");

        let mut no_build = cell(unknown_rule, &pos_line, "", &q_pos);
        if let Some(c) = no_build.controls.as_mut() {
            c.positive.build = None;
        }
        let violations = vec![
            (
                "a line the arm never printed",
                cell(unknown_rule, "cc: warning: nothing to see", "", &q_pos),
            ),
            (
                "a reason quoting another line",
                cell(unknown_rule, &pos_line, "", "cc: error: something else"),
            ),
            ("an arm that published no build", no_build),
            (
                "a refusal published as an unknown flag",
                cell(unknown_rule, &refusal, "", &q_ref),
            ),
            (
                "an unknown flag published as a refusal",
                cell(refused_rule, &pos_line, "", &q_pos),
            ),
            (
                "the negative arm's rule quoting the positive arm",
                cell(unhardened, &neg_line, "", &q_neg),
            ),
        ];
        for (shape, o) in violations {
            let found = rejection_agrees(std::slice::from_ref(&o), &corpus_check_by_id, None);
            assert_eq!(found.len(), 1, "{shape}: {found:?}");
            assert_eq!(found[0].rule, RULE_REJECTION_STDERR, "{shape}");
        }

        // The positive arm's list is the one the gate's architecture selects:
        // `-mcmodel=large` is only in `textrel-absent`'s x86_64 list, so quoting it agrees
        // under x86_64 and contradicts under x86.
        let textrel = corpus_check_by_id("textrel-absent").expect("textrel-absent is a check");
        let x86 = textrel.positive_for("x86");
        assert!(x86.contains(&"-fno-pic") && !x86.contains(&"-mcmodel=large"));
        assert!(textrel.positive_for("x86_64").contains(&"-mcmodel=large"));
        let arch_cell = |flag: &str, list: &[&str]| {
            let line = unknown(flag);
            let q = quoted(&line, list);
            rejection_cell(textrel, unknown_rule, [&line, ""], &q)
        };
        let on_x86 = arch_cell("-fno-pic", x86);
        let found = rejection_agrees(
            std::slice::from_ref(&on_x86),
            &corpus_check_by_id,
            Some("x86"),
        );
        assert!(found.is_empty(), "x86 list on x86: {found:?}");
        let model = arch_cell("-mcmodel=large", textrel.positive_for("x86_64"));
        for (arch, contradicts) in [(Some("x86_64"), false), (None, false), (Some("x86"), true)] {
            let found = rejection_agrees(std::slice::from_ref(&model), &corpus_check_by_id, arch);
            assert_eq!(found.len(), usize::from(contradicts), "{arch:?}: {found:?}");
        }
    }

    #[test]
    fn a_build_rejection_its_stderr_does_not_give_contradicts_the_report() {
        use crate::measure::profile_flag_rejection;

        let mut profile = bare();
        profile.ldflags = vec!["-Wl,-z,relro".to_owned()];
        let line = "ld: unknown options: -z";
        let failed = |stderr: &str, rejection: Option<String>| {
            let mut o = observation("c", "-f", Channel::ElfStatic, Verdict::BuildFailed);
            o.build = Some(stderr_record(1, stderr));
            o.build_rejection = rejection;
            o
        };
        let named = profile_flag_rejection(&stderr_record(1, line), &profile);
        assert!(named.is_some(), "the reader names the profile's -z");

        let agreeing = [
            failed(line, named.clone()),
            failed("cc: error: probe.c:1: expected ';'", None),
        ];
        let found = build_rejection_agrees(&agreeing, &profile);
        assert!(found.is_empty(), "{found:?}");

        let mut measured = observation("d", "-f", Channel::ElfStatic, Verdict::On);
        measured.build_rejection.clone_from(&named);
        let violations = [
            (
                "a rejection its stderr lacks",
                failed("cc: error: x", named.clone()),
            ),
            ("a rejection left out", failed(line, None)),
            (
                "a rejection reworded",
                failed(line, Some("ld rejected everything".to_owned())),
            ),
            ("a rejection beside a measurement", measured),
        ];
        for (shape, o) in violations {
            let found = build_rejection_agrees(std::slice::from_ref(&o), &profile);
            assert_eq!(found.len(), 1, "{shape}: {found:?}");
            assert_eq!(found[0].rule, RULE_BUILD_REJECTION, "{shape}");
        }
    }

    /// Cells a profile flag's refusal withheld, the refusal as the cell publishes it, over
    /// `profile`.
    fn refused(check: &str, stderr: &str, profile: &Profile) -> Observation {
        let mut o = observation(check, "-f", Channel::ElfStatic, Verdict::BuildFailed);
        o.build = Some(stderr_record(1, stderr));
        o.build_rejection =
            crate::measure::profile_flag_rejection(&stderr_record(1, stderr), profile);
        o
    }

    /// An explicit profile carrying three flags its toolchain rejects in three lines.
    fn rejecting_profile() -> Profile {
        let mut profile = bare();
        "explicit:0123456789ab".clone_into(&mut profile.id);
        flags_source::USER.clone_into(&mut profile.flags_source);
        profile.cflags = ["-O2", "-fno-such-flag", "-fno-other-flag"]
            .map(str::to_owned)
            .to_vec();
        profile.ldflags = vec!["-Wl,--no-such-option".to_owned()];
        profile
    }

    const CC1_SUCH: &str = "cc1: error: unrecognized command-line option '-fno-such-flag'";
    const CC1_OTHER: &str = "cc1: error: unrecognized command-line option '-fno-other-flag'";
    const LD_SUCH: &str = "/usr/bin/ld: unrecognized option '--no-such-option'";

    /// Seven cells: four refusing one flag each, a measurement, a probe's own error, and one
    /// build refusing two flags on two lines, as gcc prints them.
    fn rejecting_cells(profile: &Profile) -> Vec<Observation> {
        vec![
            refused("a", LD_SUCH, profile),
            refused("b", CC1_SUCH, profile),
            refused("c", CC1_SUCH, profile),
            refused("d", CC1_OTHER, profile),
            observation("e", "-f", Channel::ElfStatic, Verdict::On),
            refused("f", "cc: error: probe.c:1: expected ';'", profile),
            refused("g", &format!("{CC1_OTHER}\n{CC1_SUCH}"), profile),
        ]
    }

    #[test]
    fn a_rejected_profile_flag_is_one_diagnostic_per_tool_and_flag() {
        let mut profile = rejecting_profile();
        let cells = rejecting_cells(&profile);
        assert!(
            cells[5].build_rejection.is_none() && cells[4].build_rejection.is_none(),
            "a probe's own error and a measurement name no refusal"
        );
        assert!(
            cells[6]
                .build_rejection
                .as_deref()
                .is_some_and(|b| b.starts_with("cc1 rejected -fno-other-flag,")),
            "the cell names its first refusal: {:?}",
            cells[6].build_rejection
        );
        let found = profile_flag_rejections(&cells, &profile);
        let rejections: Vec<&ProfileFlagRejection> =
            found.iter().filter_map(|d| d.rejection.as_ref()).collect();
        assert_eq!(rejections.len(), 3, "{found:#?}");
        let keys: Vec<(&str, &str, usize, &str)> = rejections
            .iter()
            .map(|r| {
                (
                    r.tool.as_str(),
                    r.flag.as_str(),
                    r.cells_withheld,
                    r.first_check.as_str(),
                )
            })
            .collect();
        assert_eq!(
            keys,
            [
                ("cc1", "-fno-such-flag", 3, "b"),
                ("cc1", "-fno-other-flag", 2, "d"),
                ("/usr/bin/ld", "--no-such-option", 1, "a"),
            ]
        );
        for (d, r) in found.iter().zip(&rejections) {
            assert_eq!(d.severity, Severity::Warning);
            assert_eq!(d.context.as_deref(), Some(PROFILE_FLAG_REJECTED));
            assert_eq!(r.cells_attempted, cells.len());
            assert_eq!(r.supplied_by, SuppliedBy::Operator);
            assert_eq!(d.message, r.sentence(&profile.id));
            for word in ["typo", "misspel", "too new", "newer", "older", "driver"] {
                assert!(!d.message.contains(word), "{word}: {}", d.message);
            }
        }
        assert_eq!(
            found[0].message,
            "a flag the operator supplied is rejected: cc1 refused -fno-such-flag in 3 of the \
             7 checks attempted, each published build-failed; the line, as first read on b: \
             cc1: error: unrecognized command-line option '-fno-such-flag'"
        );
        assert_eq!(
            found[2].message,
            "a flag the operator supplied is rejected: /usr/bin/ld refused --no-such-option in \
             1 of the 7 checks attempted, each published build-failed; the line, as first read \
             on a: /usr/bin/ld: unrecognized option '--no-such-option'"
        );

        let mut reversed = cells.clone();
        reversed.reverse();
        let again: Vec<(String, String)> = profile_flag_rejections(&reversed, &profile)
            .into_iter()
            .filter_map(|d| d.rejection.map(|r| (r.tool, r.flag)))
            .collect();
        let first: Vec<(String, String)> = rejections
            .iter()
            .map(|r| (r.tool.clone(), r.flag.clone()))
            .collect();
        assert_eq!(
            again, first,
            "the order is the counts', the tools' and the flags', not the cells'"
        );

        "openssf-tldr".clone_into(&mut profile.id);
        flags_source::OPENSSF_GUIDE.clone_into(&mut profile.flags_source);
        let built_in = profile_flag_rejections(&cells, &profile);
        assert_eq!(
            built_in[2].message,
            "this toolchain rejects a flag the openssf-tldr profile supplies: /usr/bin/ld \
             refused --no-such-option in 1 of the 7 checks attempted, each published \
             build-failed; the line, as first read on a: /usr/bin/ld: unrecognized option \
             '--no-such-option'"
        );
        for d in &built_in {
            assert_eq!(
                d.rejection.as_ref().map(|r| r.supplied_by),
                Some(SuppliedBy::BuiltInProfile)
            );
        }

        let none = [cells[4].clone(), cells[5].clone()];
        assert!(
            profile_flag_rejections(&none, &profile).is_empty(),
            "cells with no rejected flag yield no diagnostic"
        );
    }

    /// The seeded disagreements [`a_rejection_diagnostic_the_cells_do_not_give_contradicts_the_report`]
    /// holds the rule to, each an edit of the honest diagnostics.
    fn seeded_rejection_violations(honest: &[Diagnostic]) -> Vec<(&'static str, Vec<Diagnostic>)> {
        let edit = |f: fn(&mut Vec<Diagnostic>)| {
            let mut d = honest.to_vec();
            f(&mut d);
            d
        };
        vec![
            (
                "a count one too high",
                edit(|d| {
                    if let Some(r) = d[2].rejection.as_mut() {
                        r.cells_withheld += 1;
                    }
                }),
            ),
            (
                "another frame",
                edit(|d| {
                    if let Some(r) = d[0].rejection.as_mut() {
                        r.cells_attempted = 72;
                    }
                }),
            ),
            (
                "another tool",
                edit(|d| {
                    if let Some(r) = d[1].rejection.as_mut() {
                        "gcc".clone_into(&mut r.tool);
                    }
                }),
            ),
            (
                "another line",
                edit(|d| {
                    if let Some(r) = d[1].rejection.as_mut() {
                        r.line.push('!');
                    }
                }),
            ),
            (
                "another flag",
                edit(|d| {
                    if let Some(r) = d[0].rejection.as_mut() {
                        "-fno-such-flagg".clone_into(&mut r.flag);
                    }
                }),
            ),
            (
                "another provenance",
                edit(|d| {
                    if let Some(r) = d[0].rejection.as_mut() {
                        r.supplied_by = SuppliedBy::BuiltInProfile;
                    }
                }),
            ),
            (
                "another first check",
                edit(|d| {
                    if let Some(r) = d[0].rejection.as_mut() {
                        "c".clone_into(&mut r.first_check);
                    }
                }),
            ),
            (
                "the second refusal of a build left out",
                edit(|d| {
                    // A first-line reader counts g under -fno-other-flag only.
                    if let Some(r) = d[0].rejection.as_mut() {
                        r.cells_withheld -= 1;
                    }
                }),
            ),
            (
                "a message reworded",
                edit(|d| d[0].message.push_str(", probably a typo")),
            ),
            ("one dropped", edit(|d| drop(d.remove(1)))),
            ("two out of order", edit(|d| d.swap(1, 2))),
            (
                "the code without its reading",
                edit(|d| d[0].rejection = None),
            ),
            (
                "the reading under another code",
                edit(|d| d[0].context = Some("toolchain.target".to_owned())),
            ),
        ]
    }

    #[test]
    fn a_rejection_diagnostic_the_cells_do_not_give_contradicts_the_report() {
        let profile = rejecting_profile();
        let cells = rejecting_cells(&profile);
        let honest = profile_flag_rejections(&cells, &profile);
        let other = Diagnostic {
            severity: Severity::Warning,
            message: "something else".to_owned(),
            context: Some("toolchain.target".to_owned()),
            rejection: None,
        };
        let mut beside = vec![other.clone()];
        beside.extend(honest.iter().cloned());
        beside.push(other.clone());
        for shape in [&honest, &beside] {
            let found = profile_flag_rejections_agree(shape, &cells, &profile);
            assert!(found.is_empty(), "{found:#?}");
        }
        assert!(
            profile_flag_rejections_agree(std::slice::from_ref(&other), &cells[4..6], &profile)
                .is_empty()
        );

        let violations = seeded_rejection_violations(&honest);
        for (shape, diagnostics) in violations {
            let found = profile_flag_rejections_agree(&diagnostics, &cells, &profile);
            assert_eq!(found.len(), 1, "{shape}: {found:#?}");
            assert_eq!(found[0].rule, RULE_PROFILE_REJECTION, "{shape}");
            assert_eq!(found[0].property, "diagnostics", "{shape}");
        }
        let found = profile_flag_rejections_agree(&honest, &cells[4..6], &profile);
        assert_eq!(found.len(), 1, "a refusal no cell gives: {found:#?}");
    }

    #[test]
    fn a_cxx_assertions_source_its_inputs_do_not_give_contradicts_the_report() {
        let unoptimized: BTreeMap<String, String> =
            [("_CXX_STDLIB", "libstdc++"), ("_GLIBCXX_ASSERTIONS", "1")]
                .iter()
                .map(|(k, v)| ((*k).to_owned(), (*v).to_owned()))
                .collect();
        let requested = |source: Option<&str>| {
            let mut o = observation("cxx-hardening-requested", "-f", Channel::Macro, Verdict::On);
            o.evidence.macros = Some(unoptimized.clone());
            o.evidence.cxx_assertions_source = source.map(ToOwned::to_owned);
            o
        };
        let sha = "c".repeat(64);
        let mut facts = FactStore::default();
        let mut optimized = elf_of_machine("x86_64");
        optimized.self_report = "CHARD-REPORT-V1\n_CXX_STDLIB=libstdc++\n_GLIBCXX_ASSERTIONS=1\n\
                                 __OPTIMIZE__=1\nCHARD-REPORT-END"
            .to_owned();
        facts
            .insert(
                sha.clone(),
                FactEntry::Elf {
                    elf: Box::new(optimized),
                },
            )
            .expect("one entry");
        let symbol = |source: Option<&str>| {
            let mut o =
                artifact_observation("cxx-stdlib-assertions", "cxx-assertions-symbol", &sha);
            o.evidence.cxx_assertions_source = source.map(ToOwned::to_owned);
            o
        };
        let none: Vec<String> = Vec::new();
        let fedora = vec!["-O2".to_owned(), "-Wp,-D_GLIBCXX_ASSERTIONS".to_owned()];
        let no_assertions = vec!["-D_GLIBCXX_NO_ASSERTIONS".to_owned()];

        let agreeing = vec![
            (requested(Some("library-unoptimized-default")), &none),
            (requested(Some("profile")), &fedora),
            (symbol(Some("unattributed")), &none),
            (symbol(Some("profile")), &fedora),
            (requested(Some("unattributed")), &no_assertions),
        ];
        for (o, flags) in &agreeing {
            let found = cxx_assertions_source_agrees(std::slice::from_ref(o), &facts, flags);
            assert!(found.is_empty(), "{}: {found:?}", o.check);
        }
        // The same symbol observation withheld before its triple reads no store entry.
        let mut early = symbol(None);
        early.controls = None;
        assert!(cxx_assertions_source_agrees(&[early], &facts, &none).is_empty());

        let mut elsewhere = observation("pie-macro", "-f", Channel::Macro, Verdict::On);
        elsewhere.evidence.macros = Some(unoptimized.clone());
        elsewhere.evidence.cxx_assertions_source = Some("profile".to_owned());
        let violations = vec![
            ("an attribution left out", requested(None), &none),
            (
                "the library named for the profile",
                requested(Some("profile")),
                &none,
            ),
            (
                "the profile named for the library",
                requested(Some("library-unoptimized-default")),
                &fedora,
            ),
            (
                "an optimized build read as the -O0 default",
                symbol(Some("library-unoptimized-default")),
                &none,
            ),
            (
                "the -O0 default named where the profile suppresses it",
                requested(Some("library-unoptimized-default")),
                &no_assertions,
            ),
            (
                "an attribution on a check that reads no assertions",
                elsewhere,
                &none,
            ),
        ];
        for (shape, o, flags) in violations {
            let found = cxx_assertions_source_agrees(std::slice::from_ref(&o), &facts, flags);
            assert_eq!(found.len(), 1, "{shape}: {found:?}");
            assert_eq!(found[0].rule, RULE_CXX_ASSERTIONS, "{shape}");
        }
    }

    /// One edit to a published set of corroboration groups.
    type GroupEdit = fn(&mut BTreeMap<String, Corroboration>);

    #[test]
    fn a_corroboration_group_its_members_do_not_give_contradicts_the_report() {
        let obs = vec![
            observation("cet-macro", "-f", Channel::Macro, Verdict::On),
            observation("cet-marked", "-f", Channel::ElfStatic, Verdict::Off),
            observation("pie-macro", "-f", Channel::Macro, Verdict::On),
            observation("pie-elf", "-f", Channel::ElfStatic, Verdict::ProbeInvalid),
            observation("lonely", "-f", Channel::ElfStatic, Verdict::On),
        ];
        let key = |check: &str| -> Option<&'static str> {
            if check.starts_with("cet") {
                Some("cet")
            } else if check.starts_with("pie") {
                Some("pie")
            } else {
                None
            }
        };
        let groups = corroboration(&obs, &key);
        let found = corroboration_agrees(&groups, &obs, &key);
        assert!(found.is_empty(), "{found:?}");
        assert!(!groups["cet"].agree && groups["cet"].corroborated);
        assert!(!groups["pie"].corroborated);

        let edits: [(&str, GroupEdit); 7] = [
            ("agreement over an on and an off", |g| {
                g.get_mut("cet").expect("cet").agree = true;
            }),
            ("corroboration over one measuring channel", |g| {
                g.get_mut("pie").expect("pie").corroborated = true;
            }),
            ("a withheld member counted as measuring", |g| {
                g.get_mut("pie").expect("pie").measured_channels = 2;
            }),
            ("a member dropped", |g| {
                g.get_mut("pie").expect("pie").members.pop();
            }),
            ("a withheld member forgotten", |g| {
                g.get_mut("pie").expect("pie").withheld.clear();
            }),
            ("a group dropped", |g| {
                g.remove("pie");
            }),
            ("a group invented", |g| {
                let mut extra = g["pie"].clone();
                extra.protection = "invented".to_owned();
                g.insert("invented".to_owned(), extra);
            }),
        ];
        for (shape, edit) in edits {
            let mut published = groups.clone();
            edit(&mut published);
            let found = corroboration_agrees(&published, &obs, &key);
            assert!(!found.is_empty(), "{shape} raised nothing");
            assert!(
                found.iter().all(|c| c.rule == RULE_CORROBORATION),
                "{shape}: {found:?}"
            );
        }
    }

    #[test]
    fn a_gating_beside_a_triple_its_stage_never_sees_contradicts_the_report() {
        use Outcome::{Absent, Present};
        use gating_rule::Triple;

        let discriminating = || {
            with_triple(
                Verdict::Off,
                Some(Present),
                Some(Absent),
                None,
                Discrimination::Discriminating,
            )
            .controls
        };
        let withheld = || {
            with_triple(
                Verdict::ProbeInvalid,
                Some(Absent),
                Some(Absent),
                None,
                Discrimination::Withheld(WithheldBecause::PositiveSilent),
            )
            .controls
        };
        for rule in gating_rule::ALL {
            for (shape, controls) in [
                ("none", None),
                ("withheld", withheld()),
                ("discriminating", discriminating()),
            ] {
                let mut o = observation("c", "-f", Channel::ElfStatic, rule.verdict());
                o.controls = controls;
                o.gating = Some(Gating {
                    rule: *rule,
                    arch: None,
                    libc: None,
                    needs_vm: false,
                    reason: "r".to_owned(),
                });
                let allowed = match rule.stage.triple() {
                    Triple::None => shape == "none",
                    Triple::Withheld => shape == "withheld",
                    Triple::Discriminating => shape == "discriminating",
                    Triple::Built => shape != "none",
                    Triple::Any => true,
                };
                let found = gating_stage_agrees(&o);
                assert_eq!(
                    found.is_none(),
                    allowed,
                    "{} at {:?} beside {shape}: {found:?}",
                    rule.id,
                    rule.stage
                );
                if let Some(c) = found {
                    assert_eq!(c.rule, RULE_VERDICT_CONTROLS);
                }
            }
        }
    }

    /// Every base-inference rule, the per-cell rules `consistency` applies to observations.
    fn base_inference_contradictions(obs: &[Observation], profile: &Profile) -> Vec<Contradiction> {
        let mut out = gating_verdict_agrees(obs);
        out.extend(run_record_agrees(obs));
        out.extend(controls_agree(
            obs,
            crate::measure::Conditions::profile_is_clean(profile),
        ));
        out.extend(level_agrees(obs, &corpus_check_by_id));
        out.extend(rejection_agrees(obs, &corpus_check_by_id, None));
        out.extend(build_rejection_agrees(obs, profile));
        out
    }

    /// The corpus check `id`, beside the probe it belongs to.
    fn corpus_pair(id: &str) -> (&'static crate::probe::Probe, &'static Check) {
        crate::probe::CORPUS
            .iter()
            .find_map(|p| p.checks.iter().find(|c| c.id == id).map(|c| (p, c)))
            .unwrap_or_else(|| panic!("{id} is not in the corpus"))
    }

    /// An observation of the corpus check `id`, carrying its own probe, flag and channel.
    fn corpus_observation(id: &str, verdict: Verdict) -> Observation {
        let (probe, check) = corpus_pair(id);
        let mut o = observation(check.id, check.flag, check.channel(), verdict);
        o.probe = probe.id.to_owned();
        o.recommended_level = check.recommended_level().map(str::to_owned);
        o
    }

    #[test]
    fn a_run_withholding_raises_no_base_inference_contradiction() {
        use Outcome::{Absent, Present};

        let (_, check) = corpus_pair("no-delete-null-pointer-checks");
        assert_eq!(check.channel(), Channel::Runtime);
        let record = |killed: bool| RunRecord {
            argv: vec!["probe".to_owned()],
            exit_status: if killed { -1 } else { 0 },
            signal: killed.then(|| "SIGKILL".to_owned()),
            stdout: "null-check=deleted".to_owned(),
            stderr: String::new(),
            timed_out: killed,
            deadline_ms: Some(5000),
            output_error: None,
            output_truncated: !killed,
            duration_ms: 1,
            environment: None,
        };
        let profile = bare();
        for (killed, rule) in [
            (true, gating_rule::RUN_DEADLINE_ELAPSED),
            (false, gating_rule::RUN_OUTPUT_UNREADABLE),
        ] {
            assert_eq!(
                rule.stage.triple(),
                gating_rule::Triple::Discriminating,
                "{}",
                rule.id
            );
            let run = record(killed);
            for verdict in [Verdict::On, Verdict::Off, Verdict::Indeterminate] {
                let gating = if killed {
                    deadline_limitation(verdict, check, Some(&run))
                } else {
                    stream_limitation(verdict, check, Some(&run))
                }
                .unwrap_or_else(|| panic!("{} declined {verdict:?}", rule.id));
                assert_eq!(gating.rule, rule);
                let mut o = corpus_observation(check.id, gating.rule.verdict());
                o.controls = with_triple(
                    Verdict::Off,
                    Some(Present),
                    Some(Absent),
                    None,
                    Discrimination::Discriminating,
                )
                .controls;
                o.run = Some(run.clone());
                o.gating = Some(gating);
                let found = base_inference_contradictions(std::slice::from_ref(&o), &profile);
                assert!(found.is_empty(), "{} over {verdict:?}: {found:?}", rule.id);

                o.controls = with_triple(
                    Verdict::ProbeInvalid,
                    Some(Absent),
                    Some(Absent),
                    None,
                    Discrimination::Withheld(WithheldBecause::PositiveSilent),
                )
                .controls;
                let found = controls_agree(std::slice::from_ref(&o), false);
                assert_eq!(
                    found.len(),
                    1,
                    "{} beside a withheld triple: {found:?}",
                    rule.id
                );
                assert_eq!(found[0].rule, RULE_VERDICT_CONTROLS);
            }
            assert!(
                deadline_limitation(Verdict::ProbeInvalid, check, Some(&record(true))).is_none()
                    && stream_limitation(Verdict::ProbeInvalid, check, Some(&record(false)))
                        .is_none(),
                "the run rules decline the verdict of a withheld triple"
            );
        }
    }

    #[test]
    fn a_target_withholding_raises_no_base_inference_contradiction() {
        use Outcome::{Absent, Present};

        let aarch64_only: Vec<&str> = crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks)
            .filter(|c| c.gate.arch == ["aarch64"])
            .map(|c| c.id)
            .collect();
        assert!(
            !aarch64_only.is_empty(),
            "the corpus gates a check to aarch64"
        );
        let pick = |i: usize| aarch64_only[i % aarch64_only.len()];

        let mut profile = bare();
        profile.ldflags = vec!["-Wl,-z,relro".to_owned()];
        let rejected = "ld: unknown options: -z";

        let mut measured = artifact_observation(corpus_pair(pick(0)).0.id, pick(0), "aa");
        let facts = machines(&[("aa", "x86_64")]);
        let template = corpus_observation(pick(0), Verdict::On);
        measured.flag = template.flag;
        measured.channel = template.channel;
        measured.recommended_level = template.recommended_level;
        measured.level = measured.recommended_level.clone();
        measured.controls = with_triple(
            Verdict::On,
            Some(Present),
            Some(Absent),
            None,
            Discrimination::Discriminating,
        )
        .controls;

        let mut withheld_triple = corpus_observation(pick(1), Verdict::ProbeInvalid);
        withheld_triple.controls = with_triple(
            Verdict::ProbeInvalid,
            Some(Absent),
            Some(Absent),
            None,
            Discrimination::Withheld(WithheldBecause::PositiveSilent),
        )
        .controls;
        let mut declared = corpus_observation(pick(3), gating_rule::LIBC_DECLARED.verdict());
        declared.controls.clone_from(&withheld_triple.controls);
        declared.gating = Some(Gating {
            rule: gating_rule::LIBC_DECLARED,
            arch: None,
            libc: Some("musl".to_owned()),
            needs_vm: false,
            reason: "declared".to_owned(),
        });

        let mut failed = corpus_observation(pick(2), Verdict::BuildFailed);
        failed.build = Some(stderr_record(1, rejected));
        failed.build_rejection =
            crate::measure::profile_flag_rejection(&stderr_record(1, rejected), &profile);
        let rejection = failed
            .build_rejection
            .clone()
            .expect("the reader names the profile's -z");

        let mut gated_out = corpus_observation("cet-marked", Verdict::Unsupported);
        gated_out.gating = Some(Gating {
            rule: gating_rule::ARCH,
            arch: Some("aarch64".to_owned()),
            libc: None,
            needs_vm: false,
            reason: "r".to_owned(),
        });

        let mut observations = vec![measured, withheld_triple, failed, declared, gated_out];
        let before = base_inference_contradictions(&observations, &profile);
        assert!(
            before.is_empty(),
            "the shapes are ones a run publishes: {before:#?}"
        );
        let target = crate::toolchain::target_agreement(
            "aarch64",
            crate::toolchain::ArchSource::Dumpmachine,
            &artifact_machines(&observations, &facts),
            &["__aarch64__".to_owned()],
            None,
        );
        assert_eq!(target.agreement, crate::toolchain::ArchAgreement::Disagrees);
        let withheld = withhold_on_contradicted_target(&mut observations, &target);
        assert_eq!(withheld.len(), observations.len(), "{withheld:?}");
        for o in &observations {
            assert_eq!(
                o.gating.as_ref().map(|g| g.rule),
                Some(gating_rule::TARGET_CONTRADICTED),
                "{}",
                o.check
            );
            assert!(o.build_rejection.is_none(), "{}", o.check);
        }
        assert!(
            observations[2]
                .gating
                .as_ref()
                .is_some_and(|g| g.reason.contains(&rejection)),
            "the rejection is quoted in the verdict it had"
        );
        let found = base_inference_contradictions(&observations, &profile);
        assert!(found.is_empty(), "{found:?}");
        let held = target_arch_agrees(Some(&target), None, false, &[], &observations, &facts);
        assert!(held.is_empty(), "{held:?}");
    }

    /// A build record naming `sha` as its artifact.
    fn built(sha: &str) -> BuildRecord {
        let mut record = stderr_record(0, "");
        record.artifact_sha256 = Some(sha.to_owned());
        record
    }

    /// A report's store and the observations referencing it, each reference resolving:
    /// an elf-static cell whose own artifact and two arms' artifacts are stored, one arm
    /// unreadable, and a macro cell whose macros came from a stored dump. The macro cell
    /// carries no `build`, so `macro-verdict-unearned-by-artifact` has nothing to read in it.
    fn a_store_and_its_references() -> (FactStore, Vec<Observation>) {
        let [measured, positive, negative, dump] = ["a", "b", "c", "d"].map(|c| c.repeat(64));
        let mut elf_cell = with_triple(
            Verdict::On,
            Some(Outcome::Present),
            Some(Outcome::Absent),
            None,
            Discrimination::Discriminating,
        );
        elf_cell.build = Some(built(&measured));
        if let Some(controls) = elf_cell.controls.as_mut() {
            controls.positive.build = Some(built(&positive));
            controls.negative.build = Some(built(&negative));
        }
        let macros = BTreeMap::from([("__SSP_STRONG__".to_owned(), "2".to_owned())]);
        let mut macro_cell = observation("ssp", "-fstack-protector", Channel::Macro, Verdict::On);
        macro_cell.evidence.macros = Some(macros.clone());
        macro_cell.evidence.macro_source = Some("preprocessor".to_owned());
        let mut record = stderr_record(0, "");
        record.stdout_sha256 = Some(dump.clone());
        macro_cell.evidence.macro_dump = Some(record);

        let mut facts = FactStore::default();
        for (key, entry) in [
            (
                measured,
                FactEntry::Elf {
                    elf: Box::new(elf_of_machine("x86_64")),
                },
            ),
            (
                positive,
                FactEntry::Elf {
                    elf: Box::new(elf_of_machine("x86_64")),
                },
            ),
            (
                negative,
                FactEntry::Unreadable {
                    error: "<artifact>: not an ELF file".to_owned(),
                    mach_o: false,
                },
            ),
            (
                dump,
                FactEntry::MacroDump {
                    defines: 3,
                    macros_filter: evidence_filters().macros.sha256,
                    macros,
                },
            ),
        ] {
            facts.insert(key, entry).expect("one entry per digest");
        }
        (facts, vec![elf_cell, macro_cell])
    }

    fn store_contradictions(facts: &FactStore, observations: &[Observation]) -> Vec<Contradiction> {
        fact_store_agrees(
            facts,
            observations,
            &evidence_filters().macros.sha256,
            &|_| false,
        )
    }

    #[test]
    fn the_fact_store_rule_fires_once_for_each_way_a_store_can_disagree() {
        let (facts, observations) = a_store_and_its_references();
        assert!(
            store_contradictions(&facts, &observations).is_empty(),
            "{:#?}",
            store_contradictions(&facts, &observations)
        );
        let fires_once = |facts: &FactStore, observations: &[Observation], what: &str| {
            let found = store_contradictions(facts, observations);
            assert_eq!(found.len(), 1, "{what}: {found:#?}");
            assert_eq!(found[0].rule, RULE_FACT_STORE, "{what}");
            found[0].property.clone()
        };

        let mut dropped = facts.clone();
        dropped.0.remove(&"b".repeat(64));
        let property = fires_once(&dropped, &observations, "a dropped entry");
        assert_eq!(property, format!("facts[{}]", "b".repeat(64)));

        let mut orphaned = facts.clone();
        orphaned
            .insert(
                "e".repeat(64),
                FactEntry::Unreadable {
                    error: "x".to_owned(),
                    mach_o: false,
                },
            )
            .expect("a new key");
        fires_once(&orphaned, &observations, "an orphan");

        let mut relabelled = facts.clone();
        relabelled.0.insert(
            "a".repeat(64),
            FactEntry::MacroDump {
                defines: 0,
                macros_filter: evidence_filters().macros.sha256,
                macros: BTreeMap::new(),
            },
        );
        let property = fires_once(&relabelled, &observations, "a relabelled kind");
        assert!(property.ends_with("].kind"), "{property}");

        let mut edited = observations.clone();
        edited[1].evidence.macros = Some(BTreeMap::from([(
            "__SSP_STRONG__".to_owned(),
            "3".to_owned(),
        )]));
        let property = fires_once(&facts, &edited, "an edited inline macro");
        assert_eq!(property, "observations[ssp].evidence.macros");

        let mut misfiltered = facts.clone();
        if let Some(FactEntry::MacroDump { macros_filter, .. }) =
            misfiltered.0.get_mut(&"d".repeat(64))
        {
            *macros_filter = "0".repeat(64);
        }
        fires_once(&misfiltered, &observations, "a misnamed filter");

        // A misspelt key is unresolved under the reference's spelling, orphaned under its
        // own, and not a digest: three findings about one entry, each its own.
        let mut misspelt = facts.clone();
        let entry = misspelt.0.remove(&"c".repeat(64)).expect("stored");
        misspelt.0.insert("C".repeat(64), entry);
        assert_eq!(store_contradictions(&misspelt, &observations).len(), 3);

        // A preprocessor reading whose dump names no digest cannot be looked up.
        let mut undigested = observations;
        if let Some(dump) = undigested[1].evidence.macro_dump.as_mut() {
            dump.stdout_sha256 = None;
        }
        let mut unreferenced = facts;
        unreferenced.0.remove(&"d".repeat(64));
        let property = fires_once(&unreferenced, &undigested, "a dump with no digest");
        assert_eq!(property, "observations[ssp].evidence.macro_dump");
    }

    /// [`a_store_and_its_references`] with its positive arm's facts differing from the
    /// measured build's in `sections`, compacted against the measured build.
    fn a_compacted_store() -> (FactStore, Vec<Observation>, ElfFacts) {
        let (mut facts, observations) = a_store_and_its_references();
        let mut arm = elf_of_machine("x86_64");
        arm.sections = vec![".text".to_owned(), ".chard.report".to_owned()];
        facts.0.insert(
            "b".repeat(64),
            FactEntry::Elf {
                elf: Box::new(arm.clone()),
            },
        );
        facts.compact_arms(&std::collections::BTreeSet::from(["a".repeat(64)]));
        (facts, observations, arm)
    }

    #[test]
    fn an_arm_is_stored_as_its_changes_and_resolves_to_its_whole_facts() {
        let (facts, observations, arm) = a_compacted_store();
        let Some(FactEntry::ElfDelta { base, elf_changes }) = facts.get(&"b".repeat(64)) else {
            panic!("the arm is a delta: {:?}", facts.get(&"b".repeat(64)));
        };
        assert_eq!(base, &"a".repeat(64));
        assert_eq!(
            elf_changes.keys().collect::<Vec<_>>(),
            ["sections"],
            "only the member that differs"
        );
        assert_eq!(facts.elf_facts(&"b".repeat(64)).as_deref(), Some(&arm));
        assert!(matches!(
            facts.get(&"a".repeat(64)),
            Some(FactEntry::Elf { .. })
        ));
        let found = store_contradictions(&facts, &observations);
        assert!(found.is_empty(), "{found:#?}");
    }

    #[test]
    fn an_arm_whose_member_is_empty_where_its_base_is_not_states_it_empty() {
        let (mut facts, observations) = a_store_and_its_references();
        let mut measured = elf_of_machine("x86_64");
        measured
            .gnu_property_notes
            .insert("0xc0000002".to_owned(), 1);
        facts.0.insert(
            "a".repeat(64),
            FactEntry::Elf {
                elf: Box::new(measured),
            },
        );
        facts.compact_arms(&std::collections::BTreeSet::from(["a".repeat(64)]));
        let Some(FactEntry::ElfDelta { elf_changes, .. }) = facts.get(&"b".repeat(64)) else {
            panic!("the arm is a delta: {:?}", facts.get(&"b".repeat(64)));
        };
        assert_eq!(
            elf_changes.get("gnu_property_notes"),
            Some(&serde_json::json!({}))
        );
        assert_eq!(
            facts.elf_facts(&"b".repeat(64)).as_deref(),
            Some(&elf_of_machine("x86_64"))
        );
        let found = store_contradictions(&facts, &observations);
        assert!(found.is_empty(), "{found:#?}");
    }

    #[test]
    fn an_arm_without_the_opt_out_header_its_base_carries_states_it_false() {
        let (mut facts, observations) = a_store_and_its_references();
        let mut measured = elf_of_machine("x86_64");
        measured.openbsd_nobtcfi = true;
        facts.0.insert(
            "a".repeat(64),
            FactEntry::Elf {
                elf: Box::new(measured),
            },
        );
        facts.compact_arms(&std::collections::BTreeSet::from(["a".repeat(64)]));
        let Some(FactEntry::ElfDelta { elf_changes, .. }) = facts.get(&"b".repeat(64)) else {
            panic!("the arm is a delta: {:?}", facts.get(&"b".repeat(64)));
        };
        assert_eq!(
            elf_changes.get("openbsd_nobtcfi"),
            Some(&serde_json::json!(false))
        );
        assert_eq!(
            facts.elf_facts(&"b".repeat(64)).as_deref(),
            Some(&elf_of_machine("x86_64"))
        );
        let found = store_contradictions(&facts, &observations);
        assert!(found.is_empty(), "{found:#?}");
    }

    #[test]
    fn a_delta_that_does_not_resolve_is_a_contradiction() {
        let (facts, observations, _) = a_compacted_store();
        let delta =
            |edit: &dyn Fn(&mut String, &mut serde_json::Map<String, serde_json::Value>)| {
                let mut edited = facts.clone();
                if let Some(FactEntry::ElfDelta { base, elf_changes }) =
                    edited.0.get_mut(&"b".repeat(64))
                {
                    edit(base, elf_changes);
                }
                store_contradictions(&edited, &observations)
            };

        let found = delta(&|base, _| *base = "c".repeat(64));
        assert_eq!(found.len(), 1, "{found:#?}");
        assert_eq!(found[0].property, format!("facts[{}].base", "b".repeat(64)));

        for nonsense in [serde_json::json!(1), serde_json::json!([])] {
            let found = delta(&|_, changes| {
                changes.insert("nonsense".to_owned(), nonsense.clone());
            });
            assert_eq!(found.len(), 1, "{nonsense}: {found:#?}");
        }
        assert!(facts.elf_facts(&"b".repeat(64)).is_some());

        let mut under_a_build = facts.clone();
        under_a_build.0.insert(
            "a".repeat(64),
            FactEntry::ElfDelta {
                base: "b".repeat(64),
                elf_changes: serde_json::Map::new(),
            },
        );
        let found = store_contradictions(&under_a_build, &observations);
        assert!(
            found.iter().any(|c| c.property.ends_with("].kind")),
            "{found:#?}"
        );
    }

    #[test]
    fn only_an_artifact_reading_check_has_its_arms_stored() {
        let (facts, mut observations) = a_store_and_its_references();
        observations[0].channel = Channel::Runtime;
        let orphans = store_contradictions(&facts, &observations);
        assert_eq!(orphans.len(), 2, "{orphans:#?}");
        let declared = fact_store_agrees(
            &facts,
            &observations,
            &evidence_filters().macros.sha256,
            &|id| id == "c",
        );
        assert!(declared.is_empty(), "{declared:#?}");
        for check in crate::probe::CORPUS.iter().flat_map(|p| p.checks) {
            assert_eq!(
                stores_arm_artifacts(check),
                matches!(check.channel(), Channel::Macro | Channel::ElfStatic)
                    || !check.reads().is_empty(),
                "{}",
                check.id
            );
        }
    }

    #[test]
    fn a_store_refuses_a_second_different_fact_for_one_digest() {
        let mut facts = FactStore::default();
        let key = "f".repeat(64);
        let first = FactEntry::Unreadable {
            error: "one".to_owned(),
            mach_o: false,
        };
        facts.insert(key.clone(), first.clone()).expect("a new key");
        facts
            .insert(key.clone(), first.clone())
            .expect("the same fact");
        let second = FactEntry::Unreadable {
            error: "two".to_owned(),
            mach_o: false,
        };
        let conflict = facts
            .insert(key.clone(), second.clone())
            .expect_err("a different fact");
        assert_eq!(facts.get(&key), Some(&first), "the first is kept");
        assert_eq!((conflict.kept, conflict.refused), (first, second));

        let mut other = FactStore::default();
        other
            .insert(
                key,
                FactEntry::Unreadable {
                    error: "three".to_owned(),
                    mach_o: false,
                },
            )
            .expect("a new key");
        assert_eq!(facts.merge(other).len(), 1, "a merge refuses the same way");
    }

    /// The reading `check`'s predicate takes of `macros` and `elf`, as `measure` publishes
    /// it over the store key `facts`.
    fn read(
        check: &str,
        facts: &str,
        macros: &BTreeMap<String, String>,
        elf: Option<&ElfFacts>,
    ) -> Decoded {
        let p = crate::predicate::for_check(check).expect("a predicate check");
        let eval = crate::predicate::evaluate(
            p,
            &crate::predicate::Live {
                macros: Some(macros),
                elf,
            },
        )
        .expect("the Live view answers every key");
        Decoded {
            facts: facts.to_owned(),
            macros: None,
            clause: eval.clause,
            outcome: eval.outcome,
            level: eval.level,
        }
    }

    /// A store and the two observations that read it, every reading published: a macro
    /// cell (`optimization-enabled`) whose measured build and arms read preprocessor
    /// dumps, and an `elf-static` cell (`relative-relocs`) whose measured build and arms
    /// read artifacts. Each verdict is the one its measured reading licenses.
    fn decoded_fixture() -> (FactStore, Vec<Observation>) {
        let key = |c: char| c.to_string().repeat(64);
        let mut facts = FactStore::default();
        let optimized = BTreeMap::from([("__OPTIMIZE__".to_owned(), "1".to_owned())]);
        let unoptimized = BTreeMap::new();
        let dump = |macros: &BTreeMap<String, String>| FactEntry::MacroDump {
            defines: 3,
            macros_filter: evidence_filters().macros.sha256,
            macros: macros.clone(),
        };
        let dumped = |sha: &str| {
            let mut record = stderr_record(0, "");
            record.stdout_sha256 = Some(sha.to_owned());
            record
        };
        let mut macro_cell = with_triple(
            Verdict::On,
            Some(Outcome::Present),
            Some(Outcome::Absent),
            None,
            Discrimination::Discriminating,
        );
        macro_cell.check = "optimization-enabled".to_owned();
        macro_cell.channel = Channel::Macro;
        macro_cell.evidence.macro_source = Some("preprocessor".to_owned());
        macro_cell.evidence.macro_dump = Some(dumped(&key('1')));
        macro_cell.evidence.decoded =
            Some(read("optimization-enabled", &key('1'), &optimized, None));
        if let Some(controls) = macro_cell.controls.as_mut() {
            let arms = [(key('2'), &optimized), (key('3'), &unoptimized)];
            for (arm, (sha, macros)) in [&mut controls.positive, &mut controls.negative]
                .into_iter()
                .zip(arms)
            {
                arm.macro_source = Some("preprocessor".to_owned());
                arm.macro_dump = Some(dumped(&sha));
                arm.decoded = Some(read("optimization-enabled", &sha, macros, None));
            }
        }
        for (sha, macros) in [
            (key('1'), &optimized),
            (key('2'), &optimized),
            (key('3'), &unoptimized),
        ] {
            facts
                .insert(sha, dump(macros))
                .expect("one entry per digest");
        }

        let mut relr = elf_of_machine("x86_64");
        relr.dt_relr = true;
        let plain = elf_of_machine("x86_64");
        let mut elf_cell = with_triple(
            Verdict::On,
            Some(Outcome::Present),
            Some(Outcome::Absent),
            None,
            Discrimination::Discriminating,
        );
        elf_cell.check = "relative-relocs".to_owned();
        elf_cell.build = Some(built(&key('a')));
        elf_cell.evidence.decoded = Some(read(
            "relative-relocs",
            &key('a'),
            &unoptimized,
            Some(&relr),
        ));
        if let Some(controls) = elf_cell.controls.as_mut() {
            let arms = [(key('b'), &relr), (key('c'), &plain)];
            for (arm, (sha, elf)) in [&mut controls.positive, &mut controls.negative]
                .into_iter()
                .zip(arms)
            {
                arm.build = Some(built(&sha));
                arm.decoded = Some(read("relative-relocs", &sha, &unoptimized, Some(elf)));
            }
        }
        for (sha, elf) in [(key('a'), &relr), (key('b'), &relr), (key('c'), &plain)] {
            facts
                .insert(
                    sha,
                    FactEntry::Elf {
                        elf: Box::new(elf.clone()),
                    },
                )
                .expect("one entry per digest");
        }
        (facts, vec![macro_cell, elf_cell])
    }

    /// The decoded rule over `observations` and `facts`, with the `decoders` block the
    /// report would carry for them unless `decoders` is given.
    fn decoded_contradictions(
        facts: &FactStore,
        observations: &[Observation],
        decoders: Option<&Decoders>,
    ) -> (Vec<Contradiction>, Replay) {
        let own = decoders_of(observations);
        decoded_readings_agree(
            decoders.or(own.as_ref()),
            observations,
            facts,
            &evidence_filters(),
            &corpus_check_by_id,
        )
    }

    /// `decoded-reading-disagrees-with-facts` over `observations`, asserting it fires once,
    /// and the property it names.
    fn decoded_fires_once(
        facts: &FactStore,
        observations: &[Observation],
        decoders: Option<&Decoders>,
        what: &str,
    ) -> String {
        let (found, _) = decoded_contradictions(facts, observations, decoders);
        assert_eq!(found.len(), 1, "{what}: {found:#?}");
        assert_eq!(found[0].rule, RULE_DECODED, "{what}");
        found[0].property.clone()
    }

    #[test]
    fn each_way_a_reading_can_disagree_with_its_facts_fires_once() {
        let (facts, observations) = decoded_fixture();
        let (found, replay) = decoded_contradictions(&facts, &observations, None);
        assert!(found.is_empty(), "{found:#?}");
        assert_eq!(
            replay,
            Replay {
                readings: 6,
                replayed: 6,
                unresolved: 0,
                not_replayable: Vec::new(),
            }
        );
        let store = store_contradictions(&facts, &observations);
        assert!(store.is_empty(), "{store:#?}");

        let mut flipped = observations.clone();
        if let Some(controls) = flipped[1].controls.as_mut() {
            controls.negative.outcome = Some(Outcome::Present);
        }
        assert_eq!(
            decoded_fires_once(&facts, &flipped, None, "a flipped arm outcome"),
            "observations[relative-relocs].controls.negative.outcome"
        );

        let mut altered = facts.clone();
        if let Some(FactEntry::Elf { elf }) = altered.0.get_mut(&"b".repeat(64)) {
            elf.dt_relr = false;
        }
        assert_eq!(
            decoded_fires_once(&altered, &observations, None, "an altered ELF bool"),
            "observations[relative-relocs].controls.positive.decoded"
        );

        let mut dropped = facts.clone();
        if let Some(FactEntry::MacroDump { macros, .. }) = dropped.0.get_mut(&"2".repeat(64)) {
            macros.remove("__OPTIMIZE__");
        }
        assert_eq!(
            decoded_fires_once(&dropped, &observations, None, "a dropped macro"),
            "observations[optimization-enabled].controls.positive.decoded"
        );

        let mut removed = observations.clone();
        if let Some(controls) = removed[0].controls.as_mut() {
            controls.negative.decoded = None;
        }
        assert_eq!(
            decoded_fires_once(&facts, &removed, None, "a removed arm reading"),
            "observations[optimization-enabled].controls.negative.decoded"
        );
        let mut unread = observations.clone();
        unread[1].evidence.decoded = None;
        assert_eq!(
            decoded_fires_once(&facts, &unread, None, "a removed measured reading"),
            "observations[relative-relocs].evidence.decoded"
        );

        let mut edited = decoders_of(&observations).expect("both checks carry readings");
        if let Some(entry) = edited.predicates.get_mut("relative-relocs") {
            entry.predicate.clauses[0].because = "an edited reason".to_owned();
        }
        assert_eq!(
            decoded_fires_once(&facts, &observations, Some(&edited), "an edited clause"),
            "decoders.predicates[relative-relocs]"
        );

        let mut changed = observations;
        changed[1].verdict = Verdict::Off;
        assert_eq!(
            decoded_fires_once(
                &facts,
                &changed,
                None,
                "a verdict its reading does not give"
            ),
            "observations[relative-relocs].verdict"
        );
        // A gated verdict keeps its own rules: the same `off` under a gating is not held
        // to the reading.
        changed[1].gating = Some(Gating {
            rule: gating_rule::ARTIFACT_UNREADABLE,
            arch: None,
            libc: None,
            needs_vm: false,
            reason: "a table was cut".to_owned(),
        });
        let (found, _) = decoded_contradictions(&facts, &changed, None);
        assert!(found.is_empty(), "{found:#?}");
    }

    #[test]
    fn a_reading_moved_to_another_builds_facts_fires_once() {
        let (facts, observations) = decoded_fixture();
        // A measured reading moved to the negative arm's artifact, with the clause and
        // outcome that artifact gives and the `off` they license: the reading replays and
        // the verdict restates, and only the key names another build's facts.
        let mut displaced = observations.clone();
        let plain = elf_of_machine("x86_64");
        displaced[1].evidence.decoded = Some(read(
            "relative-relocs",
            &"c".repeat(64),
            &BTreeMap::new(),
            Some(&plain),
        ));
        displaced[1].verdict = Verdict::Off;
        assert_eq!(
            decoded_fires_once(&facts, &displaced, None, "a displaced measured key"),
            "observations[relative-relocs].evidence.decoded.facts"
        );
        // The same on an arm: the positive arm's reading moved to the measured build's
        // dump, which gives the same outcome.
        let mut swapped = observations.clone();
        if let Some(controls) = swapped[0].controls.as_mut()
            && let Some(decoded) = controls.positive.decoded.as_mut()
        {
            decoded.facts = "1".repeat(64);
        }
        assert_eq!(
            decoded_fires_once(&facts, &swapped, None, "a displaced arm key"),
            "observations[optimization-enabled].controls.positive.decoded.facts"
        );
    }

    #[test]
    fn the_decoders_block_holds_exactly_the_checks_with_a_reading() {
        let (facts, observations) = decoded_fixture();
        let mut decoders = decoders_of(&observations).expect("both checks carry readings");
        assert_eq!(
            decoders.predicates.keys().collect::<Vec<_>>(),
            ["optimization-enabled", "relative-relocs"]
        );
        let entry = decoders
            .predicates
            .remove("relative-relocs")
            .expect("present");
        let property =
            decoded_fires_once(&facts, &observations, Some(&decoders), "a missing entry");
        assert_eq!(property, "decoders.predicates[relative-relocs]");
        decoders
            .predicates
            .insert("relative-relocs".to_owned(), entry);
        decoders.predicates.insert(
            "pie".to_owned(),
            PublishedPredicate {
                sha256: corpus_check_by_id("pie").expect("pie").decoder.sha256(),
                predicate: crate::predicate::for_check("pie").expect("pie").clone(),
            },
        );
        let property = decoded_fires_once(&facts, &observations, Some(&decoders), "an extra entry");
        assert_eq!(property, "decoders.predicates[pie]");

        let mut gated = observations;
        gated.push(observation(
            "pie",
            "-pie",
            Channel::ElfStatic,
            Verdict::Unsupported,
        ));
        assert!(decoders_of(&gated).is_some_and(|d| !d.predicates.contains_key("pie")));
    }

    #[test]
    fn a_mode_reached_through_an_unkept_name_is_not_replayable() {
        let key = "9".repeat(64);
        let live = BTreeMap::from([
            ("_LIBCPP_VERSION".to_owned(), "210000".to_owned()),
            ("_LIBCPP_HARDENING_MODE".to_owned(), "MYMODE".to_owned()),
            ("MYMODE".to_owned(), "4".to_owned()),
        ]);
        let decoded = read("cxx-hardening-requested", &key, &live, None);
        assert_eq!(decoded.level.as_deref(), Some("fast"), "{decoded:?}");
        let mut o = observation(
            "cxx-hardening-requested",
            "-D_LIBCPP_HARDENING_MODE",
            Channel::Macro,
            Verdict::Indeterminate,
        );
        o.evidence.decoded = Some(decoded);
        o.evidence.macro_source = Some("preprocessor".to_owned());
        let mut record = stderr_record(0, "");
        record.stdout_sha256 = Some(key.clone());
        o.evidence.macro_dump = Some(record);
        let mut facts = FactStore::default();
        facts
            .insert(
                key,
                FactEntry::MacroDump {
                    defines: 3,
                    macros_filter: evidence_filters().macros.sha256,
                    macros: crate::measure::relevant_macros(&live),
                },
            )
            .expect("a new key");
        let (found, replay) = decoded_contradictions(&facts, &[o], None);
        assert!(found.is_empty(), "{found:#?}");
        assert_eq!(
            (replay.readings, replay.replayed, replay.unresolved),
            (1, 0, 0)
        );
        assert_eq!(
            replay.not_replayable,
            [NotReplayable {
                property: "observations[cxx-hardening-requested].evidence.decoded".to_owned(),
                key: "macros.MYMODE".to_owned(),
            }]
        );
    }

    #[test]
    fn a_mode_that_is_no_macros_name_replays_over_the_trimmed_map() {
        let mut fed = 0usize;
        for (mode, replayed) in [
            ("B=1", 1),
            ("3L", 1),
            ("-1", 1),
            ("a b", 1),
            ("MYMODE", 0),
            ("M\u{e9}", 0),
            ("M\\U000000e9", 0),
        ] {
            let key = "9".repeat(64);
            let live = BTreeMap::from([
                ("_LIBCPP_VERSION".to_owned(), "210000".to_owned()),
                ("_LIBCPP_HARDENING_MODE".to_owned(), mode.to_owned()),
            ]);
            let decoded = read("cxx-hardening-requested", &key, &live, None);
            assert_eq!(decoded.clause, "libcxx-unrecognised", "{mode}: {decoded:?}");
            let mut o = observation(
                "cxx-hardening-requested",
                "-D_LIBCPP_HARDENING_MODE",
                Channel::Macro,
                Verdict::Indeterminate,
            );
            o.evidence.decoded = Some(decoded);
            o.evidence.macro_source = Some("preprocessor".to_owned());
            let mut record = stderr_record(0, "");
            record.stdout_sha256 = Some(key.clone());
            o.evidence.macro_dump = Some(record);
            let mut facts = FactStore::default();
            facts
                .insert(
                    key,
                    FactEntry::MacroDump {
                        defines: 2,
                        macros_filter: evidence_filters().macros.sha256,
                        macros: crate::measure::relevant_macros(&live),
                    },
                )
                .expect("a new key");
            let (found, replay) = decoded_contradictions(&facts, &[o], None);
            assert!(found.is_empty(), "{mode}: {found:#?}");
            assert_eq!(
                (replay.readings, replay.replayed, replay.unresolved),
                (1, replayed, 0),
                "{mode}"
            );
            assert_eq!(replay.not_replayable.len(), 1 - replayed, "{mode}");
            fed += 1;
        }
        assert_eq!(fed, 7);
    }

    #[test]
    fn every_reading_replays_from_the_published_document() {
        let (mut facts, observations) = decoded_fixture();
        if let Some(FactEntry::Elf { elf }) = facts.0.get_mut(&"c".repeat(64)) {
            elf.truncations.push(crate::elf::Truncation {
                table: crate::elf::ElfTable::Comment,
                kind: crate::elf::TruncationKind::Ignored,
                detail: "a view that disagreed".to_owned(),
            });
        }
        let subjects = std::collections::BTreeSet::from(["1".repeat(64), "a".repeat(64)]);
        facts.compact_arms(&subjects);
        let mut report = identity_fixture();
        report.decoders = decoders_of(&observations);
        report.observations = observations;
        report.facts = facts;
        report.consistency = consistency(&report);
        let doc = serde_json::to_value(&report).expect("a report serializes");

        let kinds: Vec<&str> = doc["facts"]
            .as_object()
            .expect("the store is an object")
            .values()
            .filter_map(|e| e["kind"].as_str())
            .collect();
        assert!(kinds.contains(&"elf-delta"), "{kinds:?}");
        let delta = &doc["facts"]["c".repeat(64)];
        assert_eq!(delta["kind"], "elf-delta", "{delta}");
        assert!(delta["elf_changes"]["truncations"].is_array(), "{delta}");
        let names = |v: &serde_json::Value| -> Vec<String> {
            serde_json::from_value(v.clone()).expect("a published name list")
        };
        let macro_names = names(&doc["evidence_filters"]["macros"]["names"]);
        let symbol_names = names(&doc["evidence_filters"]["symbols"]["names"]);

        let mut fed = 0;
        let mut replayed = Vec::new();
        for o in doc["observations"].as_array().expect("observations") {
            let check = o["check"].as_str().expect("a check id");
            let elf_static = o["channel"] == "elf-static";
            assert!(
                elf_static || o["channel"] == "macro",
                "{check}: {}",
                o["channel"]
            );
            let predicate: crate::predicate::Predicate =
                serde_json::from_value(doc["decoders"]["predicates"][check]["predicate"].clone())
                    .expect("the published predicate deserializes");
            let mut at = vec![("evidence", &o["evidence"]["decoded"])];
            for arm in ["positive", "negative", "regime_negative"] {
                at.push((arm, &o["controls"][arm]["decoded"]));
            }
            for (field, published) in at {
                if published.is_null() {
                    continue;
                }
                fed += 1;
                let facts = published["facts"].as_str();
                let keys = if elf_static {
                    ReadingKeys {
                        elf: facts,
                        macros: published["macros"].as_str(),
                    }
                } else {
                    ReadingKeys {
                        elf: None,
                        macros: facts,
                    }
                };
                let sources = replay_sources(&doc["facts"], &predicate, keys)
                    .unwrap_or_else(|| panic!("{check} {field}: its keys resolve"));
                let view = crate::predicate::Published::new(
                    sources.macros.as_ref(),
                    sources.filtered.then_some(macro_names.as_slice()),
                    sources.elf.as_ref(),
                    Some(symbol_names.as_slice()),
                )
                .expect("the sources are objects");
                let eval = crate::predicate::evaluate(&predicate, &view)
                    .unwrap_or_else(|i| panic!("{check} {field}: Incomplete({})", i.0));
                assert_eq!(
                    serde_json::json!({
                        "facts": facts,
                        "macros": published["macros"],
                        "clause": eval.clause,
                        "outcome": eval.outcome.as_str(),
                        "level": eval.level,
                    }),
                    serde_json::json!({
                        "facts": facts,
                        "macros": published["macros"],
                        "clause": published["clause"],
                        "outcome": published["outcome"],
                        "level": published["level"],
                    }),
                    "{check} {field}"
                );
                replayed.push(format!("{check} {field}"));
            }
        }
        assert_eq!(fed, 6, "the fixture publishes six readings: {replayed:?}");
        assert_eq!(replayed.len(), fed, "every reading fed was replayed");
    }

    /// A report that contradicts itself is refused: [`publish`] writes it to
    /// `<output>.contradicted` and not to the requested path, and names how many places it
    /// contradicts itself in; the same report untouched is written where it was asked for.
    /// One macro cell from [`decoded_fixture`] in a report that publishes: no artifact's
    /// machine to hold the target to, so the published target stands on the macro witness,
    /// as a no-ELF run's does.
    fn publishable_fixture() -> Report {
        let (facts, mut observations) = decoded_fixture();
        observations.truncate(1);
        let mut report = identity_fixture();
        report.toolchain.detected.target = Some(crate::toolchain::target_agreement(
            "x86_64",
            crate::toolchain::ArchSource::Dumpmachine,
            &[],
            &["__x86_64__".to_owned()],
            None,
        ));
        let mut expected = ids_of(&observations);
        expected.insert("c".to_owned());
        report.coverage = coverage(&observations, &expected, 3, &report.profile, Vec::new());
        report.decoders = decoders_of(&observations);
        report.observations = observations;
        for (key, entry) in facts.iter().filter(|(_, e)| e.kind() == "macro-dump") {
            report
                .facts
                .insert(key.clone(), entry.clone())
                .expect("a new key");
        }
        stamp(&mut report);
        report
    }

    /// A scratch directory for one publication test, and the two paths [`publish`] writes.
    fn publication_paths(
        test: &str,
    ) -> (std::path::PathBuf, std::path::PathBuf, std::path::PathBuf) {
        let dir = std::env::temp_dir().join(format!("chard-publish-{test}-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("a scratch directory");
        let output = dir.join("report.json");
        let quarantine = dir.join("report.json.contradicted");
        (dir, output, quarantine)
    }

    #[test]
    fn the_output_check_takes_the_in_place_route() {
        let (dir, output, _) = publication_paths("in-place-route");
        let pid = std::process::id();
        let listing = || {
            let mut names: Vec<String> = std::fs::read_dir(&dir)
                .expect("the scratch directory")
                .map(|e| {
                    e.expect("an entry")
                        .file_name()
                        .to_string_lossy()
                        .into_owned()
                })
                .collect();
            names.sort();
            names
        };
        let mut fed = 0;
        for earlier in [None, Some("earlier")] {
            for n in 0..u64::from(PARTIAL_ATTEMPTS) {
                std::fs::write(sibling(&output, &format!("{PARTIAL_SUFFIX}.{pid}.{n}")), "")
                    .expect("a planted name");
            }
            if let Some(text) = earlier {
                std::fs::write(&output, text).expect("an earlier output");
            }
            let before = listing();
            let counter = std::sync::atomic::AtomicU64::new(0);
            let staged = Staged::create_numbered(&output, pid, &counter);
            assert!(staged.is_err(), "every name was planted");
            let judged = judge_file(&output, dir.clone(), staged);
            fed += 1;
            assert!(
                judged.is_ok(),
                "earlier output {earlier:?}: refused {:?}",
                judged.err()
            );
            assert_eq!(listing(), before, "earlier output {earlier:?}");
        }
        assert_eq!(fed, 2);
        std::fs::remove_dir_all(&dir).expect("cleanup");
    }

    #[test]
    fn a_name_beside_the_output_too_long_to_create_is_refused() {
        let (dir, _, _) = publication_paths("sibling-length");
        let name_max = (1..=255usize)
            .rev()
            .find(|length| {
                let path = dir.join("n".repeat(*length));
                match std::fs::File::create_new(&path) {
                    Ok(_) => {
                        std::fs::remove_file(&path).expect("removing the name tried");
                        true
                    }
                    Err(e) if e.kind() == std::io::ErrorKind::InvalidFilename => false,
                    Err(e) => panic!(
                        "creating a {length}-byte name failed for another reason than its \
                         length: {e}"
                    ),
                }
            })
            .expect("the scratch directory takes some name");
        let before = std::fs::read_dir(&dir).expect("listing").count();
        let mut fed = 0;
        for (under, refused) in [(11usize, true), (13, false), (25, false)] {
            fed += 1;
            let length = name_max - under;
            let output = dir.join("r".repeat(length));
            let got = sibling_length_refused(&output);
            assert_eq!(
                got.as_ref().map(std::io::Error::kind),
                refused.then_some(std::io::ErrorKind::InvalidFilename),
                "a {length}-byte output name, where names hold {name_max} bytes"
            );
            assert_eq!(
                std::fs::read_dir(&dir).expect("listing").count(),
                before,
                "a {length}-byte output name: the trial left a file"
            );
        }
        assert_eq!(fed, 3);
        std::fs::remove_dir_all(&dir).expect("cleanup");
    }

    #[test]
    fn the_output_trial_leaves_the_directory_as_it_was() {
        let (dir, output, _) = publication_paths("trial");
        let listing = || {
            let mut names: Vec<String> = std::fs::read_dir(&dir)
                .expect("the scratch directory")
                .map(|e| {
                    e.expect("an entry")
                        .file_name()
                        .to_string_lossy()
                        .into_owned()
                })
                .collect();
            names.sort();
            names
        };
        let mut fed = 0;
        for earlier in [None, Some("earlier")] {
            if let Some(text) = earlier {
                std::fs::write(&output, text).expect("an earlier output");
            }
            let before = listing();
            refuse_unpublishable(&output).expect("a writable directory is usable");
            fed += 1;
            assert_eq!(listing(), before, "earlier output {earlier:?}");
            let now = match std::fs::read_to_string(&output) {
                Ok(text) => Some(text),
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
                Err(e) => panic!("reading the output back: {e}"),
            };
            assert_eq!(now.as_deref(), earlier, "the earlier output is untouched");
        }
        assert_eq!(fed, 2);
        std::fs::remove_dir_all(&dir).expect("cleanup");
    }

    #[test]
    fn a_declared_execution_the_observation_contradicts_is_the_operators_refusal() {
        use crate::env::{ExecutionMode, ModeBasis};
        let mut report = publishable_fixture();
        let (dir, output, quarantine) = publication_paths("declared");
        report.environment.execution.mode = ExecutionMode::Host;
        report.environment.execution.mode_evidence.basis = ModeBasis::AssertedAndContradicted;
        report.environment.execution.mode_evidence.observed = Some(ExecutionMode::Container);
        // The derived kernel fields follow the execution record, as `env` derives them in a
        // run; a stale one would be a contradiction of its own (the kernel-ownership rule).
        report.environment.kernel.ownership =
            report.environment.execution.kernel_attribution().into();
        report.environment.kernel.is_host_kernel = !ExecutionMode::Host.kernel_is_representative();
        report.run.inputs_sha256 = inputs_of(&report).sha256();
        report.run.id = run_id(&report.run.inputs_sha256, &report.observations);
        let refused = publish(&mut report.clone(), Some(&Destination::file(&output)))
            .expect("refused, not failed");
        assert_eq!(
            refused,
            Publication::Refused {
                contradictions: 1,
                quarantine: Some(quarantine.clone()),
                cause: RefusalCause::DeclaredExecution,
            },
            "{:#?}",
            report.consistency
        );
        assert!(!output.exists() && quarantine.exists());

        if let Some(controls) = report.observations[0].controls.as_mut() {
            controls.positive.outcome = Some(Outcome::Absent);
        }
        let refused =
            publish(&mut report, Some(&Destination::file(&output))).expect("refused, not failed");
        assert!(
            matches!(
                refused,
                Publication::Refused {
                    cause: RefusalCause::Defect,
                    ..
                }
            ),
            "{refused:?}"
        );
        std::fs::remove_dir_all(&dir).expect("cleanup");
    }

    #[test]
    fn a_contradicted_report_for_a_stream_is_kept_nowhere_and_refused_as_a_contradiction() {
        let mut report = publishable_fixture();
        let (dir, _, _) = publication_paths("stream");
        if let Some(controls) = report.observations[0].controls.as_mut() {
            controls.positive.outcome = Some(Outcome::Absent);
        }
        let stream = dir.join("stream");
        let refused = publish(&mut report, Some(&Destination::Stream(stream.clone())))
            .expect("refused, not failed");
        assert!(
            matches!(
                refused,
                Publication::Refused {
                    quarantine: None,
                    ..
                }
            ),
            "{refused:?}"
        );
        assert!(!stream.exists(), "nothing is written to the stream");
        assert!(
            !sibling(&stream, QUARANTINE_SUFFIX).exists(),
            "and nothing beside it"
        );
        std::fs::remove_dir_all(&dir).expect("cleanup");
    }

    #[test]
    fn a_report_whose_reading_disagrees_is_refused_and_quarantined() {
        let mut report = publishable_fixture();
        let (dir, output, quarantine) = publication_paths("reading");

        let mut healthy = report.clone();
        let published = publish(&mut healthy, Some(&Destination::file(&output))).expect("written");
        assert_eq!(
            published,
            Publication::Written,
            "{:#?}",
            healthy.consistency
        );
        assert!(output.exists() && !quarantine.exists());
        let clean: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&output).expect("the report"))
                .expect("JSON");
        assert_eq!(
            (
                &clean["consistency"]["status"],
                &clean["consistency"]["contradictions"]
            ),
            (&serde_json::json!("consistent"), &serde_json::json!([])),
            "a clean report says so, with the empty list present"
        );
        std::fs::remove_file(&output).expect("removed");

        if let Some(controls) = report.observations[0].controls.as_mut() {
            controls.positive.outcome = Some(Outcome::Absent);
        }
        let refused = publish(&mut report, Some(&Destination::file(&output))).expect("quarantined");
        let rules: Vec<&str> = report
            .consistency
            .contradictions
            .iter()
            .map(|c| c.rule.as_str())
            .collect();
        assert!(rules.contains(&RULE_DECODED), "{rules:?}");
        assert_eq!(
            refused,
            Publication::Refused {
                contradictions: rules.len(),
                quarantine: Some(quarantine.clone()),
                cause: RefusalCause::Defect,
            }
        );
        assert!(!output.exists(), "the requested path stays clean");
        let written: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(&quarantine).expect("the quarantined report"),
        )
        .expect("JSON");
        assert!(
            written["consistency"]["contradictions"]
                .as_array()
                .is_some_and(|c| c.iter().any(|c| c["rule"] == RULE_DECODED)),
            "{}",
            written["consistency"]
        );
        assert_eq!(
            written["consistency"]["status"], "contradicted",
            "the quarantined file names its own status"
        );
        std::fs::remove_dir_all(&dir).expect("cleaned up");
    }

    #[test]
    fn the_consistency_status_follows_the_list_and_an_unfilled_block_does_not_serialize() {
        let unfilled = Consistency::default();
        let err = serde_json::to_value(&unfilled).expect_err("an unfilled block is refused");
        assert!(err.to_string().contains("never filled"), "{err}");

        let mut filled = consistency(&publishable_fixture());
        assert_eq!(filled.status(), ConsistencyStatus::Consistent);
        let value = serde_json::to_value(&filled).expect("a filled block serializes");
        assert_eq!(value["status"], "consistent");
        assert_eq!(value["contradictions"], serde_json::json!([]));
        let text = serde_json::to_string(&filled).expect("serializes");
        assert!(
            text.starts_with(r#"{"status":"consistent","#),
            "the word leads the block: {text}"
        );

        filled.contradictions.push(Contradiction {
            rule: RULE_DECODED.to_owned(),
            property: "p".to_owned(),
            claims: Vec::new(),
            detail: String::new(),
        });
        assert_eq!(filled.status(), ConsistencyStatus::Contradicted);
        assert_eq!(
            serde_json::to_value(&filled).expect("serializes")["status"],
            "contradicted"
        );
    }

