    #[test]
    fn a_refused_run_removes_the_previous_report() {
        let (dir, output, quarantine) = publication_paths("stale");
        let healthy = publishable_fixture();
        let mut first = healthy.clone();
        assert_eq!(
            publish(&mut first, Some(&Destination::file(&output))).expect("written"),
            Publication::Written
        );
        assert!(output.exists(), "the earlier run's report is in place");

        let mut contradicting = healthy.clone();
        if let Some(controls) = contradicting.observations[0].controls.as_mut() {
            controls.positive.outcome = Some(Outcome::Absent);
        }
        assert!(matches!(
            publish(&mut contradicting, Some(&Destination::file(&output))).expect("quarantined"),
            Publication::Refused { .. }
        ));
        assert!(!output.exists(), "the earlier run's report is gone");
        assert!(quarantine.exists());

        let mut again = healthy;
        assert_eq!(
            publish(&mut again, Some(&Destination::file(&output))).expect("written"),
            Publication::Written
        );
        assert!(output.exists() && !quarantine.exists());
        std::fs::remove_dir_all(&dir).expect("cleaned up");
    }

    #[test]
    fn an_earlier_output_is_set_aside_until_a_publication() {
        let (dir, output, quarantine) = publication_paths("set-aside");
        let previous = dir.join("report.json.previous");

        set_aside(&output).expect("an absent output is nothing to set aside");
        assert!(!previous.exists());

        std::fs::write(&output, "earlier").expect("an earlier report");
        set_aside(&output).expect("set aside");
        assert!(
            !output.exists(),
            "the earlier report left the requested path"
        );
        assert_eq!(std::fs::read_to_string(&previous).expect("kept"), "earlier");

        let healthy = publishable_fixture();
        let mut contradicting = healthy.clone();
        if let Some(controls) = contradicting.observations[0].controls.as_mut() {
            controls.positive.outcome = Some(Outcome::Absent);
        }
        assert!(matches!(
            publish(&mut contradicting, Some(&Destination::file(&output))).expect("quarantined"),
            Publication::Refused { .. }
        ));
        assert!(
            !output.exists() && quarantine.exists() && previous.exists(),
            "a refusal keeps the earlier report beside its quarantine"
        );

        let mut again = healthy;
        assert_eq!(
            publish(&mut again, Some(&Destination::file(&output))).expect("written"),
            Publication::Written
        );
        assert!(output.exists() && !previous.exists() && !quarantine.exists());
        std::fs::remove_dir_all(&dir).expect("cleaned up");
    }

    #[test]
    fn a_link_to_a_file_is_resolved_and_a_stream_is_left_alone() {
        let (dir, _, _) = publication_paths("set-aside-links");
        let is_link = |p: &std::path::Path| {
            p.symlink_metadata()
                .is_ok_and(|m| m.file_type().is_symlink())
        };
        let target = dir.join("target.json");
        std::fs::write(&target, "linked").expect("a link target");
        let link = dir.join("link.json");
        std::os::unix::fs::symlink("target.json", &link).expect("a link");
        let resolved = set_aside(&link).expect("a link to a regular file is resolved");
        assert_eq!(
            resolved,
            Destination::File {
                requested: link.clone(),
                path: target.clone(),
            }
        );
        assert!(is_link(&link), "the link stays a link");
        assert!(!target.exists(), "the target's earlier contents left it");
        assert_eq!(
            std::fs::read_to_string(dir.join("target.json.previous"))
                .expect("the target's earlier contents"),
            "linked",
            "and are kept beside the target"
        );
        assert!(!dir.join("link.json.previous").exists());
        let mut through = publishable_fixture();
        assert_eq!(
            publish(&mut through, Some(&resolved)).expect("written"),
            Publication::Written
        );
        assert!(is_link(&link), "a publication leaves the link a link");
        assert!(
            std::fs::read_to_string(&link).is_ok_and(|t| t.starts_with('{')),
            "naming this run's report"
        );
        assert!(!dir.join("target.json.previous").exists());
        assert!(!dir.join("target.json.partial").exists());
        // A failed run leaves the link dangling, its target set aside; the next run
        // resolves it again rather than writing through and leaving the `.previous`.
        std::fs::rename(&target, dir.join("target.json.previous")).expect("set aside");
        assert_eq!(
            set_aside(&link).expect("a dangling link is resolved"),
            resolved
        );
        let nowhere = dir.join("nowhere.json");
        std::os::unix::fs::symlink("no-such-dir/x.json", &nowhere).expect("a link");
        assert_eq!(
            set_aside(&nowhere).expect("a link into nothing is left alone"),
            Destination::Stream(nowhere.clone())
        );

        let device = dir.join("null.json");
        std::os::unix::fs::symlink("/dev/null", &device).expect("a link to a device");
        let streamed = set_aside(&device).expect("a link to a device is left alone");
        assert_eq!(streamed, Destination::Stream(device.clone()));
        assert!(is_link(&device) && !dir.join("null.json.previous").exists());
        let mut contradicting = publishable_fixture();
        if let Some(controls) = contradicting.observations[0].controls.as_mut() {
            controls.positive.outcome = Some(Outcome::Absent);
        }
        assert!(matches!(
            publish(&mut contradicting, Some(&streamed)).expect("quarantined"),
            Publication::Refused { .. }
        ));
        assert!(is_link(&device), "a refusal does not remove a stream");

        let directory = dir.join("dir.json");
        std::fs::create_dir(&directory).expect("a directory");
        assert_eq!(
            set_aside(&directory).expect("a directory is left alone"),
            Destination::Stream(directory.clone())
        );
        assert!(directory.is_dir() && !dir.join("dir.json.previous").exists());

        std::fs::remove_dir_all(&dir).expect("cleaned up");
    }

    #[test]
    fn an_atomic_write_replaces_the_inode_and_leaves_a_hard_link_its_old_contents() {
        use std::os::unix::fs::PermissionsExt as _;
        let (dir, output, _) = publication_paths("inode");
        std::fs::write(&output, "earlier").expect("an earlier output");
        let keep = dir.join("keep");
        std::fs::hard_link(&output, &keep).expect("a hard link");
        assert_eq!(
            write_output(&output, b"this run").expect("written"),
            Written::Replaced
        );
        assert_eq!(std::fs::read_to_string(&keep).expect("keep"), "earlier");
        assert_eq!(
            std::fs::read_to_string(&output).expect("output"),
            "this run"
        );
        assert!(!dir.join("report.json.partial").exists());
        let fresh = dir.join("fresh");
        std::fs::write(&fresh, "").expect("a fresh file");
        let mode =
            |p: &std::path::Path| std::fs::metadata(p).expect("metadata").permissions().mode();
        assert_eq!(mode(&output), mode(&fresh));
        std::fs::remove_dir_all(&dir).expect("cleaned up");
    }

    #[test]
    fn two_writers_sharing_an_output_each_publish_their_own_file() {
        let (dir, output, _) = publication_paths("race");
        std::fs::write(&output, "earlier").expect("an earlier output");
        let read = || std::fs::read_to_string(&output).expect("the output");
        let (whole_a, whole_b) = (b"run A, whole".as_slice(), b"run B, whole".as_slice());
        let (mut created, mut published) = (0, 0);
        let mut a = Staged::create(&output).expect("A's temporary file");
        created += 1;
        a.fill(whole_a).expect("A filled");
        let mut b = Staged::create(&output).expect("B's temporary file");
        created += 1;
        let names = (a.partial.clone(), b.partial.clone());
        assert_eq!(
            a.publish(&output, whole_a).expect("A published"),
            Written::Replaced
        );
        published += 1;
        assert_eq!(
            read(),
            "run A, whole",
            "A's rename published a file A did not fill"
        );
        b.fill(whole_b).expect("B filled");
        assert_eq!(
            b.publish(&output, whole_b).expect("B published"),
            Written::Replaced,
            "B's rename did not find its own file"
        );
        published += 1;
        assert_eq!(read(), "run B, whole");
        assert_ne!(names.0, names.1, "the two writers shared a temporary name");
        let left: Vec<_> = std::fs::read_dir(&dir)
            .expect("the scratch directory")
            .map(|e| e.expect("a scratch directory entry").file_name())
            .filter(|n| n.to_string_lossy().contains(PARTIAL_SUFFIX))
            .collect();
        assert!(left.is_empty(), "temporary files left: {left:?}");
        assert_eq!(
            (created, published),
            (2, 2),
            "two writers, two publications"
        );
        std::fs::remove_dir_all(&dir).expect("cleaned up");
    }

    #[test]
    fn a_planted_partial_link_is_not_followed() {
        use std::os::unix::fs::PermissionsExt as _;
        let (dir, _, _) = publication_paths("planted");
        let victim = dir.join("victim");
        let pid = std::process::id();
        let mut fed = 0;
        let mut expected = 3;
        for (arm, mode, planted) in [
            ("writable", 0o755, 2),
            ("every name taken", 0o755, PARTIAL_ATTEMPTS),
            ("mode 555", 0o555, 2),
        ] {
            let sub = dir.join(arm.replace(' ', "-"));
            std::fs::create_dir(&sub).expect("mkdir");
            let output = sub.join("report.json");
            std::fs::write(&victim, "victim").expect("a victim");
            std::fs::write(&output, "earlier").expect("an earlier output");
            let mut links = vec![sub.join("report.json.partial")];
            links.extend((0..planted).map(|n| sub.join(format!("report.json.partial.{pid}.{n}"))));
            for link in &links {
                std::os::unix::fs::symlink(&victim, link).expect("a planted link");
            }
            std::fs::set_permissions(&sub, std::fs::Permissions::from_mode(mode)).expect("chmod");
            if mode == 0o555 && std::fs::write(sub.join("probe"), "").is_ok() {
                std::fs::set_permissions(&sub, std::fs::Permissions::from_mode(0o755))
                    .expect("chmod 755");
                expected -= 1;
                eprintln!(
                    "chard: arm not exercised, a planted link in a mode-555 directory: this \
                     process writes in it anyway, so the mode stops nothing here"
                );
                continue;
            }
            let counter = std::sync::atomic::AtomicU64::new(0);
            let staged = Staged::create_numbered(&output, pid, &counter);
            let written = write_staged(&output, b"this run", staged);
            std::fs::set_permissions(&sub, std::fs::Permissions::from_mode(0o755))
                .expect("chmod 755");
            fed += 1;
            assert_eq!(
                std::fs::read_to_string(&victim).expect("victim"),
                "victim",
                "{arm}: a planted link was followed"
            );
            assert_eq!(
                std::fs::read_to_string(&output).expect("output"),
                "this run",
                "{arm}"
            );
            for link in &links {
                assert!(
                    link.symlink_metadata()
                        .is_ok_and(|m| m.file_type().is_symlink()),
                    "{arm}: {} is no longer the planted link",
                    link.display()
                );
            }
            let entries = std::fs::read_dir(&sub)
                .expect("the arm's directory")
                .count();
            assert_eq!(
                entries,
                links.len() + 1,
                "{arm}: the output and the planted links, and no temporary file of this run's"
            );
            let how = written.expect("written");
            if arm == "writable" {
                assert_eq!(how, Written::Replaced, "{arm}");
                assert_eq!(
                    counter.into_inner(),
                    3,
                    "{arm}: two planted names skipped, the third created"
                );
            } else {
                assert_eq!(how, Written::InPlace, "{arm}");
            }
        }
        assert_eq!(fed, expected, "arms run against arms the host allowed");
        std::fs::remove_dir_all(&dir).expect("cleaned up");
    }

