    #[test]
    fn a_fact_store_conflict_refuses_the_report() {
        let (dir, output, quarantine) = publication_paths("conflict");
        let mut report = publishable_fixture();
        let (key, kept) = report
            .facts
            .iter()
            .next()
            .map(|(k, e)| (k.clone(), e.clone()))
            .expect("the fixture stores its dump");
        // The same dump, one `#define` longer: a second reading of the bytes under `key`.
        let mut other = kept.clone();
        let FactEntry::MacroDump { defines, .. } = &mut other else {
            panic!("the fixture's entry is a macro dump: {}", kept.kind());
        };
        *defines += 1;
        let mut offered = FactStore::default();
        offered.insert(key.clone(), other).expect("a new key");
        report.fact_conflicts = report
            .facts
            .merge(offered)
            .into_iter()
            .map(|c| *c)
            .collect();
        assert_eq!(
            report.fact_conflicts.len(),
            1,
            "the merge refused the entry"
        );
        assert_eq!(report.facts.get(&key), Some(&kept), "and kept the first");

        let refused = publish(&mut report, Some(&Destination::file(&output))).expect("quarantined");
        let conflicts: Vec<&Contradiction> = report
            .consistency
            .contradictions
            .iter()
            .filter(|c| c.rule == RULE_FACT_STORE && c.property == format!("facts[{key}]"))
            .collect();
        assert_eq!(conflicts.len(), 1, "{:#?}", report.consistency);
        assert_eq!(
            refused,
            Publication::Refused {
                contradictions: report.consistency.contradictions.len(),
                quarantine: Some(quarantine.clone()),
                cause: RefusalCause::Defect,
            }
        );
        assert!(!output.exists() && quarantine.exists());
        std::fs::remove_dir_all(&dir).expect("cleaned up");
    }

    /// `report` as [`publish`] would render it: the consistency block filled first, since an
    /// unfilled one refuses to serialize.
    fn as_published(mut report: Report) -> serde_json::Value {
        report.consistency = consistency(&report);
        fill_digest(&mut report);
        serde_json::to_value(&report).expect("a filled report serializes")
    }

    /// [`reread_fixture`] with one observation an `arch-gated` rule earned as `unsupported`,
    /// so the digest has a row carrying a gating rule and a reason of each standing.
    fn digest_fixture() -> Report {
        let mut report = reread_fixture();
        let mut gated = obs("gated", Polarity::Weaken, Verdict::Unsupported, "");
        gated.defects = Vec::new();
        gated.gating = Some(Gating {
            rule: gating_rule::ARCH,
            arch: Some("aarch64".to_owned()),
            libc: None,
            needs_vm: false,
            reason: "applies to aarch64;\n this build targets x86_64".to_owned(),
        });
        // Beside the rule's sentence, so the reason is shown to be the rule's.
        gated.evidence.observed = Some("the detector's own reading".to_owned());
        report.observations.push(gated);
        // The withheld check beside a triple that withheld, so a reason carries its cause.
        let at = report
            .observations
            .iter()
            .position(|o| o.check == "withheld")
            .expect("the fixture's withheld check");
        let withheld = report.observations.remove(at);
        report
            .observations
            .insert(at, withheld_by(withheld, WithheldBecause::PositiveSilent));
        report.defect_coverage = defect_coverage(&report.observations);
        let mut expected = ids_of(&report.observations);
        expected.insert("c".to_owned());
        report.coverage = coverage(
            &report.observations,
            &expected,
            6,
            &report.profile,
            Vec::new(),
        );
        stamp(&mut report);
        report
    }

    #[test]
    fn the_digest_leads_the_report_and_restates_its_observations() {
        let mut report = digest_fixture();
        report.consistency = consistency(&report);
        fill_digest(&mut report);
        let text = serde_json::to_string(&report).expect("serializes");
        assert!(
            text.starts_with("{\"digest\":{\"chard_schema\":"),
            "{}",
            text.chars().take(80).collect::<String>()
        );
        let json: serde_json::Value = serde_json::from_str(&text).expect("json");
        let digest = &json["digest"];
        let observations = json["observations"].as_array().expect("observations");
        let rows = digest["checks"].as_array().expect("rows");
        assert_eq!(rows.len(), observations.len());
        let mut unmeasured = Vec::new();
        for (row, o) in rows.iter().zip(observations) {
            for field in ["check", "verdict", "level", "polarity", "channel"] {
                assert_eq!(row.get(field), o.get(field), "{field} of {}", o["check"]);
            }
            assert_eq!(
                row.get("gating"),
                o.get("gating").map(|g| &g["rule"]),
                "{}",
                o["check"]
            );
            if !matches!(o["verdict"].as_str(), Some("on" | "off" | "partial")) {
                unmeasured.push(o["check"].clone());
            }
        }
        let reasons: Vec<&serde_json::Value> = digest["reasons"]
            .as_array()
            .expect("the fixture withholds")
            .iter()
            .collect();
        assert_eq!(
            reasons
                .iter()
                .map(|r| r["check"].clone())
                .collect::<Vec<_>>(),
            unmeasured
        );
        let gated = reasons
            .iter()
            .find(|r| r["check"] == "gated")
            .expect("the gated row");
        assert_eq!(gated["standing"], "earned-limitation");
        assert_eq!(gated["rule"], "arch-gated");
        assert!(
            gated.get("reason").is_none(),
            "the sentence stays in the observation"
        );
        assert!(
            reasons
                .iter()
                .any(|r| r["standing"] == "instrument-withholding"),
            "{reasons:?}"
        );
        for field in ["withholding", "verdict_counts", "checks_expected"] {
            assert_eq!(
                digest["coverage"][field], json["coverage"][field],
                "{field}"
            );
        }
        assert_eq!(digest["consistency"], json["consistency"]["status"]);
        assert_eq!(digest["toolchain"], json["toolchain"]["id"]);
        assert_eq!(digest["profile"]["id"], json["profile"]["id"]);
        assert_eq!(
            digest["profile"]["flags_sha256"],
            json["profile"]["flags_sha256"]
        );
        assert_eq!(digest["run"]["id"], json["run"]["id"]);
        let read = reread_contradictions(&json);
        assert!(read.is_empty(), "{read:?}");
    }

    /// Every member of `value` as a JSON pointer under `at` (`true`), and every leaf
    /// (`false`).
    fn digest_pointers(value: &serde_json::Value, at: &str, out: &mut Vec<(String, bool)>) {
        match value {
            serde_json::Value::Object(map) => {
                for (key, child) in map {
                    let here = format!("{at}/{key}");
                    out.push((here.clone(), true));
                    digest_pointers(child, &here, out);
                }
            }
            serde_json::Value::Array(items) => {
                for (i, child) in items.iter().enumerate() {
                    digest_pointers(child, &format!("{at}/{i}"), out);
                }
            }
            _ => out.push((at.to_owned(), false)),
        }
    }

    /// One edit of [`a_digest_set_apart_from_its_report_is_named_on_read`]: its name, the
    /// edit, and the property the rule names.
    type DigestEdit<'a> = (&'a str, &'a dyn Fn(&mut serde_json::Value), String);

    #[test]
    fn a_digest_set_apart_from_its_report_is_named_on_read() {
        let honest = as_published(digest_fixture());
        let named = |edit: &dyn Fn(&mut serde_json::Value)| {
            let mut json = honest.clone();
            edit(&mut json);
            let read = reread_contradictions(&json);
            assert!(
                read.unreadable.is_empty() && read.older.is_empty(),
                "{read:?}"
            );
            read.contradictions
                .iter()
                .filter(|c| c.rule == RULE_DIGEST)
                .map(|c| c.property.clone())
                .collect::<Vec<_>>()
        };
        assert!(named(&|_| {}).is_empty(), "the control");
        let first = honest["digest"]["checks"][0]["check"]
            .as_str()
            .expect("a row")
            .to_owned();
        let cases: [DigestEdit; 8] = [
            (
                "a row's verdict",
                &|j| j["digest"]["checks"][0]["verdict"] = "partial".into(),
                format!("digest.checks[{first}].verdict"),
            ),
            (
                "an observation's polarity, the digest untouched",
                &|j| j["observations"][0]["polarity"] = "weaken".into(),
                format!("digest.checks[{first}].polarity"),
            ),
            (
                "a row's gating rule removed",
                &|j| {
                    let rows = j["digest"]["checks"].as_array_mut().expect("rows");
                    let row = rows
                        .iter_mut()
                        .find(|r| r["check"] == "gated")
                        .expect("row");
                    row.as_object_mut().expect("object").remove("gating");
                },
                "digest.checks[gated].gating".to_owned(),
            ),
            (
                "a reason dropped",
                &|j| {
                    j["digest"]["reasons"]
                        .as_array_mut()
                        .expect("reasons")
                        .pop();
                },
                "digest.reasons".to_owned(),
            ),
            (
                "a key added",
                &|j| j["digest"]["score"] = 1.into(),
                "digest.score".to_owned(),
            ),
            (
                "the recounted withholding",
                &|j| j["digest"]["coverage"]["withholding"]["published"] = 0.into(),
                "digest.coverage.withholding.published".to_owned(),
            ),
            (
                "the profile's meaning",
                &|j| j["digest"]["profile"]["meaning"] = "hardened".into(),
                "digest.profile.meaning".to_owned(),
            ),
            (
                "the flags hash",
                &|j| j["profile"]["flags_sha256"] = "0".repeat(64).into(),
                "profile.flags_sha256".to_owned(),
            ),
        ];
        for (name, edit, property) in cases {
            assert_eq!(named(edit), vec![property], "{name}");
        }
        let mut older = honest.clone();
        older.as_object_mut().expect("object").remove("digest");
        older["profile"]
            .as_object_mut()
            .expect("profile")
            .remove("flags_sha256");
        let read = reread_contradictions(&older);
        assert!(
            read.is_empty(),
            "a report with no digest, the rule alone: {read:?}"
        );
    }

    #[test]
    fn every_leaf_and_member_of_the_digest_is_held_on_read() {
        let honest = as_published(digest_fixture());
        let mut found = Vec::new();
        digest_pointers(&honest["digest"], "/digest", &mut found);
        let (mut leaves, mut members) = (0, 0);
        for (pointer, is_member) in found {
            let mut edited = honest.clone();
            if is_member {
                let (parent, key) = pointer.rsplit_once('/').expect("a parent");
                edited
                    .pointer_mut(parent)
                    .and_then(serde_json::Value::as_object_mut)
                    .expect("an object")
                    .remove(key);
                members += 1;
            } else {
                let leaf = edited.pointer_mut(&pointer).expect("the leaf");
                *leaf = match leaf.take() {
                    serde_json::Value::String(s) => format!("{s}x").into(),
                    serde_json::Value::Number(n) => (n.as_u64().expect("a count") + 1).into(),
                    serde_json::Value::Bool(b) => (!b).into(),
                    other => panic!("{pointer}: {other}"),
                };
                leaves += 1;
            }
            let read = reread_contradictions(&edited);
            let named: Vec<&str> = read
                .contradictions
                .iter()
                .filter(|c| c.rule == RULE_DIGEST)
                .map(|c| c.property.as_str())
                .collect();
            assert!(
                named.len() == 1 && named[0].starts_with("digest"),
                "{pointer}: {named:?} {:?}",
                read.unreadable
            );
        }
        assert!(
            leaves > 50 && members > 50,
            "{leaves} leaves, {members} members"
        );
    }

    #[test]
    fn every_object_and_list_of_the_digest_grown_is_held_on_read() {
        let honest = as_published(digest_fixture());
        // Growth, each alone: a member added to every object, an entry appended to every list.
        let mut containers = vec!["/digest".to_owned()];
        let mut seen = Vec::new();
        digest_pointers(&honest["digest"], "/digest", &mut seen);
        containers.extend(seen.into_iter().map(|(p, _)| p).filter(|p| {
            honest
                .pointer(p)
                .is_some_and(|v| v.is_object() || v.is_array())
        }));
        let mut grown = 0;
        for pointer in &containers {
            let mut edited = honest.clone();
            match edited.pointer_mut(pointer).expect("the container") {
                serde_json::Value::Object(map) => {
                    map.insert("added".to_owned(), 1.into());
                }
                serde_json::Value::Array(items) => {
                    let first = items.first().cloned().expect("a non-empty list");
                    items.push(first);
                }
                other => panic!("{pointer} was filtered to containers and holds {other}"),
            }
            grown += 1;
            let named = reread_contradictions(&edited)
                .contradictions
                .iter()
                .filter(|c| c.rule == RULE_DIGEST)
                .count();
            assert_eq!(named, 1, "{pointer} grown");
        }
        assert!(grown > 10, "{grown} containers");
        let carries = |list: &str, member: &str| {
            honest["digest"][list]
                .as_array()
                .expect("a list")
                .iter()
                .any(|entry| entry.get(member).is_some())
        };
        let carried = [
            ("checks[].level", carries("checks", "level")),
            ("checks[].gating", carries("checks", "gating")),
            ("reasons[].rule", carries("reasons", "rule")),
            ("reasons[].cause", carries("reasons", "cause")),
            (
                "run.harness_revision",
                honest["digest"]["run"].get("harness_revision").is_some(),
            ),
            (
                "execution.basis",
                honest["digest"]["execution"].get("basis").is_some(),
            ),
        ];
        for (member, present) in carried {
            assert!(present, "the fixture's digest carries {member}");
        }
    }

    #[test]
    fn a_report_whose_digest_cannot_be_made_is_refused() {
        let mut report = digest_fixture();
        "unheard-of".clone_into(&mut report.profile.flags_source);
        let Publication::Refused { cause, .. } = publish(&mut report, None).expect("publishes")
        else {
            panic!("published a report with no digest");
        };
        assert_eq!(cause, RefusalCause::Defect);
        let found: Vec<&str> = report
            .consistency
            .contradictions
            .iter()
            .filter(|c| c.rule == RULE_DIGEST)
            .map(|c| c.property.as_str())
            .collect();
        assert_eq!(found, ["digest"]);
        assert!(report.digest.is_none());
    }

    #[test]
    fn a_digest_that_cannot_be_made_is_recorded_even_where_the_pass_did_not() {
        let mut report = digest_fixture();
        "unheard-of".clone_into(&mut report.profile.flags_source);
        report.consistency = Consistency {
            rules_applied: RULES.iter().map(|r| (*r).to_owned()).collect(),
            ..Consistency::default()
        };
        fill_digest(&mut report);
        assert!(report.digest.is_none());
        let found: Vec<&str> = report
            .consistency
            .contradictions
            .iter()
            .map(|c| c.rule.as_str())
            .collect();
        assert_eq!(found, [RULE_DIGEST]);
        assert_eq!(
            report.consistency.refusal_cause(),
            Some(RefusalCause::Defect)
        );
    }

    #[test]
    fn the_flags_hash_is_the_explicit_ids_digest_and_its_own_spelling() {
        assert_eq!(
            flags_sha256(&[], &[], &[]),
            crate::digest::sha256_hex(b"\n\n")
        );
        let c = vec!["-O2".to_owned(), "-fPIE".to_owned()];
        let l = vec!["-pie".to_owned()];
        let hash = flags_sha256(&c, &[], &l);
        assert_eq!(
            hash,
            crate::digest::sha256_hex("-O2\u{1f}-fPIE\n\n-pie".as_bytes())
        );
        assert_eq!(
            explicit_profile_id(&c, &[], &l),
            format!(
                "explicit:{}",
                hash.get(..12).expect("a sha256 in hex is 64 ASCII digits")
            )
        );
    }

    /// `report` made a report of this corpus: its corpus hash this binary's, each observation
    /// of a corpus check declaring the defects the corpus declares for it, and the rollup
    /// derived again over them, so that a test of another statement over this corpus meets
    /// only the edit it makes.
    fn make_of_this_corpus(report: &mut Report) {
        report.run.probe_corpus_sha256 = crate::probe::corpus_sha256();
        for o in &mut report.observations {
            if let Some(check) = corpus_check_by_id(&o.check) {
                o.defects = check.defects.iter().map(|d| (*d).to_owned()).collect();
            }
        }
        report.defect_coverage = defect_coverage(&report.observations);
    }

    /// A report carrying every input [`REREAD_RULES`] read, and agreeing with itself:
    /// `fortify-effective` at level 2 beside glibc's four rungs of level 2 and the ratchet
    /// [`withhold_inconsistent_rungs`] derives from them, a defect class borne by an `on`
    /// and an `off`, a withheld check, and the rollup and `coverage` computed by the
    /// functions `measure` calls.
    fn reread_fixture() -> Report {
        let mut report = identity_fixture();
        let mut effective = fortify_effective(Verdict::On, Some("2"));
        effective.defects = vec!["heap-buffer-overflow".to_owned()];
        let bare = |check: &str, verdict: Verdict| {
            let mut o = obs(check, Polarity::Harden, verdict, "");
            o.defects = Vec::new();
            o
        };
        report.observations.push(effective);
        for (rung, verdict) in [
            (RUNG_GE_1, Verdict::On),
            (RUNG_GE_2_SUBOBJECT, Verdict::On),
            (RUNG_GE_2_PERCENT_N, Verdict::On),
        ] {
            report.observations.push(bare(rung, verdict));
        }
        report.observations.push(obs(
            RUNG_LEVEL_3,
            Polarity::Harden,
            Verdict::Off,
            "heap-buffer-overflow",
        ));
        report
            .observations
            .push(bare("withheld", Verdict::ProbeInvalid));
        let (ratchet, diagnostic) =
            withhold_inconsistent_rungs(&mut report.observations, &FactStore::default());
        assert!(diagnostic.is_none(), "the fixture's rungs are monotone");
        report.fortify_ratchet = ratchet;
        assert_eq!(
            report
                .fortify_ratchet
                .as_ref()
                .and_then(|r| r.implied_level.as_deref()),
            Some("2")
        );
        report.defect_coverage = defect_coverage(&report.observations);
        let mut expected = ids_of(&report.observations);
        expected.insert("c".to_owned());
        report.coverage = coverage(
            &report.observations,
            &expected,
            5,
            &report.profile,
            Vec::new(),
        );
        stamp(&mut report);
        report
    }

    /// `(rule, property, claims)` of each contradiction a rule of [`REREAD_RULES`] raised.
    fn rereadable(found: &[Contradiction]) -> Vec<(String, String, Vec<String>)> {
        found
            .iter()
            .filter(|c| REREAD_RULES.contains(&c.rule.as_str()))
            .map(|c| (c.rule.clone(), c.property.clone(), c.claims.clone()))
            .collect()
    }

    /// One edit of [`the_reread_finds_what_publish_finds_over_a_report_and_its_json`]:
    /// its name, the edit, and how many contradictions publish finds over it.
    type RereadCase = (&'static str, fn(&mut Report), usize);

    fn ratchet_of(r: &mut Report) -> &mut FortifyRatchet {
        r.fortify_ratchet.as_mut().expect("a ratchet")
    }
    fn rollup_of(r: &mut Report) -> &mut DefectStatus {
        r.defect_coverage
            .get_mut("heap-buffer-overflow")
            .expect("the rollup")
    }

    /// The count is publish's, over every rule of `REREAD_RULES`; the reread must find
    /// the same contradictions. Where an edit breaks more than one statement of a rule,
    /// each is its own finding, and the count says which.
    fn reread_cases() -> [RereadCase; 8] {
        [
            ("honest", |_| {}, 0),
            // `complete` edited apart from its counts, which decide both bearing checks.
            ("complete", |r| rollup_of(r).complete = false, 1),
            // The other direction: a withheld check made to bear the defect, so the honest rollup
            // is incomplete, then `complete` written `true` over it, counts and status untouched.
            (
                "complete over a withheld check",
                |r| {
                    let withheld = r
                        .observations
                        .iter_mut()
                        .find(|o| o.check == "withheld")
                        .expect("the fixture's withheld check");
                    withheld.defects = vec!["heap-buffer-overflow".to_owned()];
                    r.defect_coverage = defect_coverage(&r.observations);
                    let rollup = rollup_of(r);
                    assert!(!rollup.complete, "the honest rollup over a withheld check");
                    rollup.complete = true;
                },
                1,
            ),
            (
                "status",
                |r| rollup_of(r).status = "mitigated".to_owned(),
                1,
            ),
            // Above the measured level, and off the point its own axes land on.
            (
                "level",
                |r| ratchet_of(r).implied_level = Some("3".to_owned()),
                2,
            ),
            // The axis rule, and both axes and the level against the rungs.
            (
                "axes",
                |r| {
                    let ratchet = ratchet_of(r);
                    ratchet.dynamic_bounds = Some(true);
                    ratchet.whole_object_level = Some("0".to_owned());
                },
                4,
            ),
            // The tally statement, and the recount from the observations.
            ("withholding", |r| r.coverage.withholding.published += 1, 2),
            (
                "all four",
                |r| {
                    rollup_of(r).status = "not-mitigated".to_owned();
                    let ratchet = ratchet_of(r);
                    ratchet.implied_level = Some("3".to_owned());
                    ratchet.dynamic_bounds = Some(true);
                    ratchet.whole_object_level = Some("0".to_owned());
                    r.coverage.withholding.instrument_withholdings.count += 1;
                },
                8,
            ),
        ]
    }

    /// The rest of the reread cases, counted as [`reread_cases`] counts.
    fn reread_cases_of_the_holes() -> [RereadCase; 11] {
        [
            // Not a number: not a level, and not the ladder's point.
            (
                "level word",
                |r| ratchet_of(r).implied_level = Some("two".to_owned()),
                2,
            ),
            (
                "level lowered",
                |r| ratchet_of(r).implied_level = Some("1".to_owned()),
                1,
            ),
            (
                "level and axis lowered",
                |r| {
                    let ratchet = ratchet_of(r);
                    ratchet.implied_level = Some("1".to_owned());
                    ratchet.whole_object_level = Some("1".to_owned());
                },
                1,
            ),
            ("ratchet deleted", |r| r.fortify_ratchet = None, 1),
            ("rung deleted", |r| drop(ratchet_of(r).rungs.pop()), 1),
            (
                "monotone flipped",
                |r| {
                    let ratchet = ratchet_of(r);
                    ratchet.monotone = false;
                    ratchet.inconsistency = Some("invented".to_owned());
                },
                1,
            ),
            (
                "inconsistency without a fault",
                |r| ratchet_of(r).inconsistency = Some("invented".to_owned()),
                1,
            ),
            // Two observations declare the defect, and each is a finding.
            (
                "defect entry deleted",
                |r| drop(r.defect_coverage.remove("heap-buffer-overflow")),
                2,
            ),
            (
                "defect check deleted",
                |r| {
                    let rollup = rollup_of(r);
                    rollup.from_checks.retain(|c| c != RUNG_LEVEL_3);
                    rollup.verdict_counts = BTreeMap::from([("on".to_owned(), 1)]);
                    rollup.status = "mitigated".to_owned();
                },
                // The omitted check, and the recount, which still
                // counts the observation that declares the defect.
                2,
            ),
            (
                "by_verdict relabelled",
                |r| {
                    r.coverage.withholding.instrument_withholdings.by_verdict =
                        BTreeMap::from([("indeterminate".to_owned(), 1)]);
                },
                // Against the tally, and against the observations.
                2,
            ),
            (
                "unknown verdict key",
                |r| {
                    let previous = r
                        .coverage
                        .verdict_counts
                        .insert("mitigated-probably".to_owned(), 2);
                    assert_eq!(previous, None);
                },
                // The withholding rule, and the two statements of the
                // coverage rule over the tally: its total against `checks_attempted`, and
                // its keys against the observations.
                3,
            ),
        ]
    }

    /// [`reread_fixture`] with its withheld check dropped and its coverage taken over the
    /// observations it carries: every corpus check attempted under its own id and none
    /// withheld, so both completeness flags read `true`.
    fn complete_reread_fixture(r: &mut Report) {
        r.observations.retain(|o| o.check != "withheld");
        let expected = ids_of(&r.observations);
        r.coverage = coverage(
            &r.observations,
            &expected,
            r.observations.len(),
            &r.profile,
            Vec::new(),
        );
        assert!(r.coverage.all_checks_attempted && r.coverage.all_verdicts_published);
        stamp(r);
    }

    /// The edits of the id lists and the counts that summarise them, each held at
    /// publish and on read.
    fn reread_cases_of_the_ids() -> [RereadCase; 8] {
        [
            // A second copy of an observation under its id, with every count beside it moved
            // to match: the repetition is the one statement left, refused on read as at
            // publish.
            (
                "an observation repeated, the counts moved to match",
                |r| {
                    let copy = r.observations[0].clone();
                    let verdict = copy.verdict.as_str().to_owned();
                    r.observations.push(copy);
                    r.coverage.checks_attempted += 1;
                    *r.coverage
                        .verdict_counts
                        .get_mut(&verdict)
                        .expect("the copied verdict is counted") += 1;
                    r.coverage.withholding = Withholding::of(&r.observations);
                    stamp(r);
                },
                1,
            ),
            // The count kept and the list not the list: one id unobserved, one observed and
            // never selected.
            (
                "one missing and one unexpected id, both flags kept",
                |r| {
                    complete_reread_fixture(r);
                    let observed = r.observations[0].check.clone();
                    let c = &mut r.coverage;
                    c.checks_missing = vec!["c".to_owned()];
                    c.checks_unexpected = vec![observed];
                    c.checks_skipped = 1;
                },
                2,
            ),
            // Each half of the identity alone: a selected id unobserved, with the selection
            // counted to match, keeps the count and neither flag.
            (
                "one missing id alone, both flags kept",
                |r| {
                    complete_reread_fixture(r);
                    let c = &mut r.coverage;
                    c.checks_missing = vec!["c".to_owned()];
                    c.checks_skipped = 1;
                    c.checks_expected += 1;
                },
                2,
            ),
            (
                "one unexpected id alone, both flags kept",
                |r| {
                    complete_reread_fixture(r);
                    let observed = r.observations[0].check.clone();
                    let c = &mut r.coverage;
                    c.checks_unexpected = vec![observed];
                    c.checks_expected -= 1;
                },
                2,
            ),
            (
                "all_checks_attempted set beside a missing id",
                |r| {
                    assert!(
                        !r.coverage.checks_missing.is_empty(),
                        "the missing id is listed as missing"
                    );
                    r.coverage.all_checks_attempted = true;
                },
                1,
            ),
            // The identity over the lists, and the unexpected id grounded in nothing.
            (
                "an unexpected id no observation carries",
                |r| r.coverage.checks_unexpected.push("ghost".to_owned()),
                2,
            ),
            (
                "checks_skipped apart from the missing list",
                |r| r.coverage.checks_skipped += 1,
                1,
            ),
            (
                "checks_valid apart from the triples",
                |r| r.coverage.checks_valid += 1,
                1,
            ),
        ]
    }

    /// The tally and rollup edits whose sums agree, which a check of the totals alone does
    /// not see, counted as [`reread_cases`] counts. The last two are an exchange of `on` and
    /// `off` inside a rollup, with the status edited to match, which the recount refuses since
    /// it reads polarity through [`protection_term`].
    fn reread_cases_of_the_tally() -> [RereadCase; 7] {
        [
            (
                "tally relabelled off to on",
                |r| {
                    let tally = &mut r.coverage.verdict_counts;
                    let off = tally.remove("off").expect("the fixture has an off");
                    *tally.get_mut("on").expect("and an on") += off;
                },
                1,
            ),
            // With the withholding block moved to match, so only the recounts see it: the
            // tally's from the observations, and the withholding's.
            (
                "tally withheld counted as on",
                |r| {
                    let tally = &mut r.coverage.verdict_counts;
                    let withheld = tally
                        .remove("probe-invalid")
                        .expect("the fixture withholds one");
                    *tally.get_mut("on").expect("an on") += withheld;
                    let w = &mut r.coverage.withholding;
                    w.published += withheld;
                    w.instrument_withholdings = WithholdingSet::default();
                },
                2,
            ),
            (
                // Two statements: the recount from the observations, and `complete` (still `true`)
                // held to counts that now withhold one of the two bearing checks.
                "rollup off counted as withheld",
                |r| rollup_of(r).verdict_counts = counts(&[("on", 1), ("indeterminate", 1)]),
                2,
            ),
            // A withheld bearing check made honest first, then counted as `on` with the
            // status `mitigated` the counts then license.
            (
                "rollup withheld counted as on, status mitigated",
                |r| {
                    let withheld = r
                        .observations
                        .iter_mut()
                        .find(|o| o.check == "withheld")
                        .expect("the fixture's withheld check");
                    withheld.defects = vec!["heap-buffer-overflow".to_owned()];
                    r.defect_coverage = defect_coverage(&r.observations);
                    let rollup = rollup_of(r);
                    assert_eq!(
                        rollup.verdict_counts,
                        counts(&[("on", 1), ("off", 1), ("probe-invalid", 1)])
                    );
                    rollup.verdict_counts = counts(&[("on", 3)]);
                    rollup.status = "mitigated".to_owned();
                },
                // The recount, and `complete` (still `false`) against counts that now decide
                // all three.
                2,
            ),
            // A request's `off` made a request first (the rung observed as what it asks),
            // which the status does not read, so the counts license `mitigated`; then its
            // key relabelled as protection's `on`, which the recount refuses.
            (
                "rollup not-requested counted as on, status mitigated",
                |r| {
                    let rung = r
                        .observations
                        .iter_mut()
                        .find(|o| o.check == RUNG_LEVEL_3)
                        .expect("the fixture's off rung");
                    rung.observes = Observes::Request;
                    r.defect_coverage = defect_coverage(&r.observations);
                    let rollup = rollup_of(r);
                    assert_eq!(
                        rollup.verdict_counts,
                        counts(&[("on", 1), ("not-requested", 1)])
                    );
                    assert_eq!(rollup.status, "mitigated");
                    rollup.verdict_counts = counts(&[("on", 2)]);
                },
                1,
            ),
            (
                "rollup on and off exchanged, status mitigated",
                |r| {
                    let rollup = rollup_of(r);
                    rollup.verdict_counts = counts(&[("on", 2)]);
                    rollup.status = "mitigated".to_owned();
                },
                1,
            ),
            (
                "rollup on and off exchanged, status not-mitigated",
                |r| {
                    let rollup = rollup_of(r);
                    rollup.verdict_counts = counts(&[("off", 2)]);
                    rollup.status = "not-mitigated".to_owned();
                },
                1,
            ),
        ]
    }

    /// The kernel fields edited apart from the mode and basis they are derived from, counted
    /// as [`reread_cases`] counts. The fixture runs in a container, so `borrowed` and `true`.
    /// The last is the boundary: the default with both fields as it gives them is honest,
    /// though `is_host_kernel` reads `false` there.
    fn reread_cases_of_the_kernel() -> [RereadCase; 4] {
        use crate::env::{ExecutionMode, KernelOwnership, ModeBasis};
        [
            (
                "kernel.ownership own under a container",
                |r| r.environment.kernel.ownership = KernelOwnership::Own,
                1,
            ),
            (
                "kernel.is_host_kernel false under a container",
                |r| r.environment.kernel.is_host_kernel = false,
                1,
            ),
            (
                "the default, with the container's ownership left",
                |r| {
                    let e = &mut r.environment.execution;
                    e.mode = ExecutionMode::Host;
                    e.mode_evidence.basis = ModeBasis::AssumedHost;
                    e.mode_evidence.observed = None;
                    r.environment.kernel.is_host_kernel = false;
                },
                1,
            ),
            (
                "the default, unsettled",
                |r| {
                    let e = &mut r.environment.execution;
                    e.mode = ExecutionMode::Host;
                    e.mode_evidence.basis = ModeBasis::AssumedHost;
                    e.mode_evidence.observed = None;
                    r.environment.kernel.is_host_kernel = false;
                    r.environment.kernel.ownership = KernelOwnership::Unsettled;
                },
                0,
            ),
        ]
    }

    #[test]
    fn the_kernel_fields_are_held_on_read_as_far_as_the_report_carries_them() {
        use serde_json::json;
        let mut honest = as_published(reread_fixture());
        // The digest restates the mode and basis edited below, and its own rule names that
        // apart; this test is about the kernel rule alone.
        honest.as_object_mut().expect("an object").remove("digest");
        let mut older = honest.clone();
        older["environment"]["kernel"]
            .as_object_mut()
            .expect("a kernel object")
            .remove("ownership");
        assert!(reread_contradictions(&older).is_empty());
        older["environment"]["kernel"]["is_host_kernel"] = false.into();
        let found = reread_contradictions(&older);
        assert_eq!(
            found
                .contradictions
                .iter()
                .map(|c| (c.rule.as_str(), c.property.as_str()))
                .collect::<Vec<_>>(),
            [(RULE_KERNEL_OWNERSHIP, "environment.kernel.is_host_kernel")]
        );

        let mut fed = 0;
        for (path, word, named) in [
            (&["kernel", "ownership"][..], json!("theirs"), "theirs"),
            // Present and `null`, which `measure` never writes, is not absence.
            (&["kernel", "ownership"][..], json!(null), "null"),
            (&["kernel", "ownership"][..], json!(7), "7"),
            (&["execution", "mode"][..], json!("chroot"), "chroot"),
            (
                &["execution", "mode_evidence", "basis"][..],
                json!("guessed"),
                "guessed",
            ),
            // An ownership with no basis beside it cannot be held, so it is not passed.
            (
                &["execution", "mode_evidence"][..],
                json!(null),
                "stands beside no",
            ),
            // A mode or an `is_host_kernel` of the wrong type: the subtree does not read.
            (
                &["execution", "mode"][..],
                json!(7),
                "`environment` is not readable",
            ),
            (
                &["kernel", "is_host_kernel"][..],
                json!("false"),
                "`environment` is not readable",
            ),
        ] {
            let mut report = honest.clone();
            let mut at = &mut report["environment"];
            for key in path {
                at = &mut at[*key];
            }
            *at = word;
            if named == "stands beside no" {
                report["environment"]["execution"]
                    .as_object_mut()
                    .expect("an execution object")
                    .remove("mode_evidence");
                report["environment"]["kernel"]["ownership"] = json!("own");
            }
            let found = reread_contradictions(&report);
            fed += 1;
            assert!(found.contradictions.is_empty(), "{found:?}");
            assert_eq!(found.unreadable.len(), 1, "{found:?}");
            assert!(
                found.unreadable[0].contains(named)
                    && found.unreadable[0].contains(RULE_KERNEL_OWNERSHIP),
                "{}",
                found.unreadable[0]
            );
        }
        assert_eq!(fed, 8);

        // No `environment` at all, which every report `measure` writes carries: a finding.
        let mut bare = honest.clone();
        bare.as_object_mut()
            .expect("a report")
            .remove("environment");
        let found = reread_contradictions(&bare);
        assert!(
            found.unreadable.iter().any(
                |u| u.contains("carries no `environment`") && u.contains(RULE_KERNEL_OWNERSHIP)
            ),
            "{found:?}"
        );
    }

    #[test]
    fn the_reread_finds_what_publish_finds_over_a_report_and_its_json() {
        let cases: Vec<RereadCase> = reread_cases()
            .into_iter()
            .chain(reread_cases_of_the_holes())
            .chain(reread_cases_of_the_tally())
            .chain(reread_cases_of_the_kernel())
            .chain(reread_cases_of_the_ids())
            .collect();
        assert_eq!(cases.len(), 38);
        let mut fed = 0;
        for &(name, edit, expected) in &cases {
            let mut report = reread_fixture();
            edit(&mut report);
            report.consistency = consistency(&report);
            let published = rereadable(&report.consistency.contradictions);
            let reread = reread_contradictions(&serde_json::to_value(&report).expect("serializes"));
            fed += 1;
            assert!(
                reread.unreadable.is_empty() && reread.older.is_empty(),
                "{name}: the report chard wrote reads back: {:?} {:?}",
                reread.unreadable,
                reread.older
            );
            assert_eq!(
                published.len(),
                expected,
                "{name}: publish finds {published:#?}"
            );
            assert_eq!(
                rereadable(&reread.contradictions),
                published,
                "{name}: the reread and publish disagree"
            );
        }
        assert_eq!(fed, cases.len());

        // And the fixtures the publication tests use, which carry neither a ratchet nor a
        // rollup, read back clean.
        let mut honest = 0;
        for report in [identity_fixture(), publishable_fixture()] {
            let reread = reread_contradictions(&as_published(report));
            honest += 1;
            assert!(reread.is_empty(), "{reread:?}");
        }
        assert_eq!(honest, 2);
    }

    #[test]
    fn a_missing_and_an_unexpected_id_keep_neither_completeness_flag() {
        let observations = vec![
            obs("a", Polarity::Harden, Verdict::On, ""),
            obs("c", Polarity::Harden, Verdict::On, ""),
        ];
        let expected: std::collections::BTreeSet<String> =
            ["a".to_owned(), "b".to_owned()].into_iter().collect();
        let profile = identity_fixture().profile;
        let made = coverage(&observations, &expected, 2, &profile, Vec::new());
        assert_eq!(made.checks_attempted, made.corpus_checks_total);
        assert_eq!(made.checks_missing, vec!["b".to_owned()]);
        assert_eq!(made.checks_unexpected, vec!["c".to_owned()]);
        assert!(!made.all_checks_attempted && !made.all_verdicts_published);

        // Each half alone keeps neither flag: a selected id unobserved, and an observed id
        // the selection never named.
        let selected: std::collections::BTreeSet<String> =
            ["a".to_owned(), "b".to_owned(), "c".to_owned()]
                .into_iter()
                .collect();
        let missing_only = coverage(&observations, &selected, 2, &profile, Vec::new());
        assert_eq!(missing_only.checks_missing, vec!["b".to_owned()]);
        assert!(
            missing_only.checks_unexpected.is_empty(),
            "a missing id is not counted as unexpected: {:?}",
            missing_only.checks_unexpected
        );
        assert!(!missing_only.all_checks_attempted && !missing_only.all_verdicts_published);
        let only_a: std::collections::BTreeSet<String> = ["a".to_owned()].into_iter().collect();
        let unexpected_only = coverage(&observations, &only_a, 2, &profile, Vec::new());
        assert!(
            unexpected_only.checks_missing.is_empty(),
            "an unexpected id is not counted as missing: {:?}",
            unexpected_only.checks_missing
        );
        assert_eq!(unexpected_only.checks_unexpected, vec!["c".to_owned()]);
        assert!(!unexpected_only.all_checks_attempted && !unexpected_only.all_verdicts_published);

        // The same observations under the selection they answer read whole.
        let whole = coverage(
            &observations,
            &ids_of(&observations),
            2,
            &profile,
            Vec::new(),
        );
        assert!(whole.all_checks_attempted && whole.all_verdicts_published);
    }

    #[test]
    fn the_named_coverage_read_limits_read_as_written() {
        let coverage_found = |r: &Report| {
            reread_contradictions(&serde_json::to_value(r).expect("serializes"))
                .contradictions
                .into_iter()
                .filter(|c| c.rule == RULE_COVERAGE)
                .count()
        };
        let mut narrowed = reread_fixture();
        narrowed.observations.retain(|o| o.check != "withheld");
        let expected = ids_of(&narrowed.observations);
        let attempted = narrowed.observations.len();
        narrowed.coverage = coverage(
            &narrowed.observations,
            &expected,
            attempted + 5,
            &narrowed.profile,
            Vec::new(),
        );
        assert!(!narrowed.coverage.all_checks_attempted);
        narrowed.consistency = consistency(&narrowed);
        assert_eq!(coverage_found(&narrowed), 0, "the honest narrowed run");
        narrowed.coverage.corpus_checks_total = attempted;
        narrowed.coverage.all_checks_attempted = true;
        narrowed.coverage.all_verdicts_published = true;
        assert_eq!(
            coverage_found(&narrowed),
            0,
            "the corpus total is the file's word"
        );

        let mut listed = reread_fixture();
        listed.consistency = consistency(&listed);
        listed
            .coverage
            .profile_flags_unexamined
            .push("-fnot-a-flag".to_owned());
        assert_eq!(
            coverage_found(&listed),
            0,
            "the list is held at publish only"
        );
        assert!(
            consistency(&listed)
                .contradictions
                .iter()
                .any(|c| c.rule == RULE_COVERAGE),
            "and is held there"
        );
    }

    #[test]
    fn every_step_is_a_rule_and_every_rule_a_step() {
        let mut declared: Vec<&str> = Vec::new();
        for step in STEPS {
            assert!(!step.rules.is_empty(), "a step that declares no rule");
            for rule in step.rules {
                if !declared.contains(rule) {
                    declared.push(rule);
                }
            }
        }
        assert_eq!(declared, RULES.to_vec());
        let per_step: Vec<&[&str]> = STEPS.iter().map(|s| s.rules).collect();
        let pinned: Vec<&[&str]> = vec![
            &[RULE_FORTIFY_LEVEL, RULE_FORTIFY_AXES],
            &[RULE_DEFECT_STATUS],
            &[RULE_DEFECT_STATUS],
            &[RULE_COMPOSITE],
            &[RULE_FORTIFY_SLOT],
            &[RULE_SSP_SLOT],
            &[RULE_EXECUTION_MODE],
            &[RULE_WITHHOLDING],
            &[RULE_COVERAGE],
            &[RULE_RUN_ID],
            &[RULE_GATING_VERDICT],
            &[RULE_RUN_RECORD],
            &[RULE_KERNEL_GATE],
            &[RULE_KERNEL_OWNERSHIP],
            &[RULE_TARGET_ARCH],
            &[RULE_TARGET_ARCH],
            &[RULE_TARGET_ARCH],
            &[RULE_STRUCTURED],
            &[RULE_VERDICT_CONTROLS],
            &[RULE_VERDICT_CONTROLS],
            &[RULE_LEVEL_SCALE],
            &[RULE_REJECTION_STDERR],
            &[RULE_BUILD_REJECTION],
            &[RULE_CORROBORATION],
            &[RULE_FACT_STORE],
            &[RULE_FACT_STORE],
            &[RULE_FACT_STORE],
            &[RULE_FACT_STORE],
            &[RULE_DECODED],
            &[RULE_CXX_ASSERTIONS],
            &[RULE_PROFILE_REJECTION],
            &[RULE_DIGEST],
            &[RULE_SELF_REPORT],
            &[RULE_MACRO_TWIN],
        ];
        assert_eq!(per_step, pinned);
    }

    #[test]
    fn rules_applied_is_the_rules_that_ran() {
        let mut report = reread_fixture();
        complete_reread_fixture(&mut report);
        report.coverage.checks_missing = vec!["c".to_owned()];
        report.coverage.checks_skipped = 1;

        let full = consistency(&report);
        assert_eq!(full.rules_applied, RULES.to_vec());
        assert_eq!(full.fields_checked, fields_the_rules_check());
        assert!(
            full.contradictions.iter().any(|c| c.rule == RULE_COVERAGE),
            "the full pass refuses the edited coverage: {:?}",
            full.contradictions
        );

        let without: Vec<Step> = STEPS
            .iter()
            .filter(|s| s.rules != [RULE_COVERAGE])
            .map(|s| Step {
                rules: s.rules,
                run: s.run,
            })
            .collect();
        assert_eq!(without.len(), STEPS.len() - 1);
        let partial = consistency_over(&report, &without);
        let expected: Vec<&str> = RULES
            .iter()
            .copied()
            .filter(|r| *r != RULE_COVERAGE)
            .collect();
        assert_eq!(partial.rules_applied, expected);
        assert!(
            !partial
                .contradictions
                .iter()
                .any(|c| c.rule == RULE_COVERAGE),
            "{:?}",
            partial.contradictions
        );
        assert!(!partial.fields_checked.iter().any(|f| f == "coverage"));
        assert!(full.fields_checked.iter().any(|f| f == "coverage"));

        // A contradiction under a rule its step did not declare is recorded as applied: the
        // statement was made, whatever the declaration says.
        let undeclared = [Step {
            rules: &[RULE_RUN_ID],
            run: |r, _| coverage_agrees(&r.coverage, &r.observations, &r.profile),
        }];
        let recorded = consistency_over(&report, &undeclared);
        assert_eq!(recorded.rules_applied, vec![RULE_RUN_ID, RULE_COVERAGE]);
    }

    #[test]
    fn a_composite_is_held_to_every_verdict_the_reduction_gives() {
        use crate::composite::ConstituentState as S;
        let held = |verdict: Verdict, constituents: Vec<crate::composite::Constituent>| {
            let observations: Vec<Observation> = constituents
                .iter()
                .filter_map(|k| k.verdict.map(|v| obs(k.check, Polarity::Harden, v, "")))
                .collect();
            composite_agrees(
                &[umbrella(verdict, constituents)],
                &observations,
                &FactStore::default(),
                &test_libc("glibc"),
            )
        };
        let one_absent = || {
            vec![
                constituent("pie", S::InForce, Some(Verdict::On)),
                constituent("relro", S::Absent, Some(Verdict::Off)),
            ]
        };
        let off_beside_in_force = held(Verdict::Off, one_absent());
        assert_eq!(off_beside_in_force.len(), 1, "{off_beside_in_force:?}");
        assert!(off_beside_in_force[0].claims[1].ends_with("reduce to partial"));
        assert!(held(Verdict::Partial, one_absent()).is_empty());

        let unconfirmed = || {
            vec![
                constituent("pie", S::InForce, Some(Verdict::On)),
                constituent("relro", S::NotEstablished, None),
            ]
        };
        let partial_with_none_absent = held(Verdict::Partial, unconfirmed());
        assert_eq!(
            partial_with_none_absent.len(),
            1,
            "{partial_with_none_absent:?}"
        );
        assert!(partial_with_none_absent[0].claims[1].ends_with("reduce to indeterminate"));
        assert!(held(Verdict::Indeterminate, unconfirmed()).is_empty());

        // The two ends the older statements name are named once, by them and not again by
        // the reduction; an honest `off` over every constituent absent is no contradiction.
        let on_beside_absent = held(Verdict::On, one_absent());
        assert_eq!(on_beside_absent.len(), 1, "{on_beside_absent:?}");
        assert!(on_beside_absent[0].claims[1].starts_with("constituents not confirmed"));
        let off_with_none_absent = held(Verdict::Off, unconfirmed());
        assert_eq!(off_with_none_absent.len(), 1, "{off_with_none_absent:?}");
        assert!(off_with_none_absent[0].detail.contains("measured absent"));
        let all_absent = || vec![constituent("relro", S::Absent, Some(Verdict::Off))];
        assert!(held(Verdict::Off, all_absent()).is_empty());

        let all_on = || vec![constituent("pie", S::InForce, Some(Verdict::On))];
        assert_eq!(held(Verdict::Indeterminate, all_on()).len(), 1);
        assert_eq!(held(Verdict::NotApplicable, all_on()).len(), 1);
        assert!(held(Verdict::On, all_on()).is_empty());
    }

    /// `fortify-effective` measured `verdict` at `level`, bearing no defect, as the fortify
    /// slot reads it.
    fn fortify_at(verdict: Verdict, level: &str) -> Observation {
        let mut o = fortify_effective(verdict, Some(level));
        o.defects = Vec::new();
        o
    }

    /// A report whose `fhardened-effective` umbrella `measure`'s own function derived over
    /// `driver`, `libc`, `triple` and `observations`, on x86_64 with an empty fact store:
    /// the shape [`RULE_FORTIFY_SLOT`] holds, with every input it reads published.
    fn fortify_slot_report(
        driver: crate::toolchain::FhardenedFortify,
        libc: crate::env::Libc,
        triple: Option<&str>,
        observations: Vec<Observation>,
    ) -> Report {
        let mut report = identity_fixture();
        report.toolchain.detected.fhardened_fortify = driver;
        report.toolchain.detected.target_triple = triple.map(str::to_owned);
        report.environment.libc = libc;
        report.composites = vec![
            crate::composite::fhardened(
                &observations,
                "x86_64",
                &report.toolchain.detected.fhardened_fortify,
                &report.environment.libc,
                report.toolchain.detected.target_triple.as_deref(),
                &report.facts,
            ),
            crate::composite::cfi(
                &observations,
                "x86_64",
                &report.environment.libc,
                &report.facts,
            ),
        ];
        let mut expected = ids_of(&observations);
        expected.insert("c".to_owned());
        report.coverage = coverage(&observations, &expected, 5, &report.profile, Vec::new());
        report.observations = observations;
        stamp(&mut report);
        report
    }

    /// A glibc 2.43 host whose gcc defines level 3 under `-fhardened -O2`, so the driver
    /// sets the bar, measured at `level`.
    fn driver_bar_report(level: &str) -> Report {
        fortify_slot_report(
            crate::toolchain::FhardenedFortify::defining("3"),
            environment_fixture().libc,
            Some("x86_64-redhat-linux"),
            vec![fortify_at(Verdict::Partial, level)],
        )
    }

    /// The same host under a driver that refuses the token, as clang does, so the library
    /// sets the bar.
    fn library_bar_report(level: &str) -> Report {
        fortify_slot_report(
            crate::toolchain::FhardenedFortify::refused(),
            environment_fixture().libc,
            Some("x86_64-redhat-linux"),
            vec![fortify_at(Verdict::Partial, level)],
        )
    }

    /// An Alpine host: musl 1.2.6 under a musl triple, gcc defining 2, `fortify-effective`
    /// decided by its fortify-headers clause at the level 1 that library enforces, and
    /// `fortify-requested` at 2, so the slot is in force by the request.
    fn fortify_headers_report() -> Report {
        let mut effective = fortify_at(Verdict::Partial, "1");
        effective.evidence.decoded = Some(Decoded {
            facts: "0".repeat(64),
            macros: None,
            clause: crate::predicate::macro_channel::FORTIFY_HEADERS_CLAUSE.to_owned(),
            outcome: Outcome::Present,
            level: Some("1".to_owned()),
        });
        let mut requested = obs("fortify-requested", Polarity::Harden, Verdict::Partial, "");
        requested.defects = Vec::new();
        requested.level = Some("2".to_owned());
        fortify_slot_report(
            crate::toolchain::FhardenedFortify::defining("2"),
            crate::env::Libc {
                impl_name: "musl".to_owned(),
                version: Some("1.2.6".to_owned()),
                detection: "__NEED_size_t".to_owned(),
            },
            Some("x86_64-alpine-linux-musl"),
            vec![effective, requested],
        )
    }

    /// An OpenBSD host: the driver refuses the token and the library names no glibc or
    /// musl, so no reading sets a bar and the slot is `not-established` with none.
    fn unset_bar_report() -> Report {
        fortify_slot_report(
            crate::toolchain::FhardenedFortify::refused(),
            test_libc("openbsd"),
            Some("aarch64-unknown-openbsd7.9"),
            vec![fortify_at(Verdict::Partial, "2")],
        )
    }

    /// The fortify slot of `report`'s umbrella, to read or edit.
    fn fortify_slot_of(report: &mut Report) -> &mut crate::composite::Constituent {
        report
            .composites
            .iter_mut()
            .find(|c| c.id == "fhardened-effective")
            .expect("the umbrella")
            .constituents
            .iter_mut()
            .find(|k| k.check == "fortify-effective")
            .expect("its fortify slot")
    }

    /// The same slot in a report's JSON, to edit as a file would be.
    fn fortify_slot_json(report: &mut serde_json::Value) -> &mut serde_json::Value {
        report["composites"]
            .as_array_mut()
            .expect("composites")
            .iter_mut()
            .find(|c| c["id"] == "fhardened-effective")
            .expect("the umbrella")["constituents"]
            .as_array_mut()
            .expect("constituents")
            .iter_mut()
            .find(|k| k["check"] == "fortify-effective")
            .expect("its fortify slot")
    }

    /// The properties [`RULE_FORTIFY_SLOT`] names over `report` at publication, in order.
    fn slot_findings_at_publish(report: &Report) -> Vec<Contradiction> {
        consistency(report)
            .contradictions
            .into_iter()
            .filter(|c| c.rule == RULE_FORTIFY_SLOT)
            .collect()
    }

    /// The properties the rule names over `report` as JSON on read, with the unreadable
    /// findings naming it.
    fn slot_findings_on_read(report: &serde_json::Value) -> (Vec<String>, Vec<String>) {
        let reread = reread_contradictions(report);
        (
            reread
                .contradictions
                .into_iter()
                .filter(|c| c.rule == RULE_FORTIFY_SLOT)
                .map(|c| c.property)
                .collect(),
            reread
                .unreadable
                .into_iter()
                .filter(|u| u.contains(RULE_FORTIFY_SLOT))
                .collect(),
        )
    }

    /// The property the rule names for `field` of the slot.
    fn slot_field(field: &str) -> String {
        format!("{FORTIFY_SLOT}.{field}")
    }

    /// The fields [`fortify_slot_invariants`] raised, in order.
    fn invariant_fields(found: Vec<(&'static str, Contradiction)>) -> Vec<&'static str> {
        found.into_iter().map(|(f, _)| f).collect()
    }

    /// A slot as written, for the statements: `state`, `level`, fortify-headers' request
    /// where `requested` names one, and `bar`.
    fn slot_shape(
        state: crate::composite::ConstituentState,
        level: &str,
        requested: Option<&str>,
        bar: Option<crate::composite::FortifyBarReading>,
    ) -> FortifySlot {
        FortifySlot {
            state,
            level: Some(level.to_owned()),
            implementation: requested.map(|r| ImplementationReading {
                name: "fortify-headers".to_owned(),
                top_level: "1".to_owned(),
                requested_level: Some(r.to_owned()),
            }),
            bar,
        }
    }

    /// `report` as the JSON `measure` writes it, its consistency block filled, for the
    /// reread to run over.
    fn slot_json_of(mut report: Report) -> serde_json::Value {
        report.consistency = consistency(&report);
        serde_json::to_value(&report).expect("a filled report serializes")
    }

    #[test]
    fn the_freebsd_cause_names_the_release_the_level_or_the_rung() {
        let macros = |pairs: &[(&str, &str)]| -> BTreeMap<String, String> {
            pairs
                .iter()
                .map(|(k, v)| ((*k).to_owned(), (*v).to_owned()))
                .collect()
        };
        let cause =
            |check: &str, pairs: &[(&str, &str)]| freebsd_limitation_cause(check, &macros(pairs));
        let sub = "fortify-level-ge-2-subobject";
        assert!(cause(sub, &[("__FreeBSD__", "14")]).is_some_and(|c| c.contains("below 15")));
        assert!(
            cause(sub, &[("__FreeBSD__", "14"), ("__SSP_FORTIFY_LEVEL", "2")])
                .is_some_and(|c| c.contains("below 15")),
            "the release decides before the level"
        );
        assert_eq!(
            cause(sub, &[("__FreeBSD__", "15")]),
            None,
            "15 with no level: withheld"
        );
        let settled = [("__FreeBSD__", "15"), ("__SSP_FORTIFY_LEVEL", "2")];
        assert!(cause(sub, &settled).is_some_and(|c| c.contains("strcpy wrapper")));
        assert!(
            cause("strict-flex-arrays-enforced", &settled)
                .is_some_and(|c| c.contains("strcpy wrapper"))
        );
        assert!(cause("fortify-level-ge-2-percent-n", &settled).is_some_and(|c| c.contains("%n")));
        assert!(cause("fortify-enforced-dynamic", &settled).is_some_and(|c| c.contains("dynamic")));
        assert_eq!(cause("fortify-enforced-known", &settled), None);
        assert_eq!(cause("fortify-effective", &settled), None);
        assert_eq!(
            cause(sub, &[("__FreeBSD__", "x"), ("__SSP_FORTIFY_LEVEL", "2")]),
            None
        );
        assert_eq!(cause(sub, &[("__SSP_FORTIFY_LEVEL", "2")]), None);

        let check_of = |id: &str| {
            crate::probe::CORPUS
                .iter()
                .flat_map(|p| p.checks)
                .find(|c| c.id == id)
                .expect("the check")
        };
        let gating = |libc: &str| Gating {
            rule: gating_rule::LIBC_DECLARED,
            arch: None,
            libc: Some(libc.to_owned()),
            needs_vm: false,
            reason: "generic".to_owned(),
        };
        let gated = |libc: &str, id: &str, pairs: &[(&str, &str)]| {
            freebsd_gating(gating(libc), check_of(id), Some(&macros(pairs))).map(|g| g.reason)
        };
        let composed = gated("freebsd", sub, &settled).expect("gated with its cause");
        assert!(composed.starts_with(check_of(sub).flag), "{composed}");
        assert!(
            composed.contains("strcpy wrapper") && !composed.contains("generic"),
            "{composed}"
        );
        assert_eq!(
            gated("freebsd", sub, &[("__FreeBSD__", "15")]).as_deref(),
            Some("generic")
        );
        assert_eq!(gated("musl", sub, &settled).as_deref(), Some("generic"));
        // A 15 whose wrappers instantiated, on a rung the table has no cause for: the gate
        // declines, since a release that implements the rung showed nothing.
        assert!(gated("freebsd", "fortify-enforced-known", &settled).is_none());
        assert!(
            gated(
                "freebsd",
                "fortify-enforced-known",
                &[("__FreeBSD__", "14")]
            )
            .is_some(),
            "below 15 the cause stands for every check"
        );
    }

    #[test]
    fn every_slot_key_is_held_or_named_unheld() {
        use std::collections::BTreeSet;
        let full = crate::composite::Constituent {
            flag: "-D_FORTIFY_SOURCE",
            check: "fortify-effective",
            applicable: true,
            verdict: Some(Verdict::Partial),
            level: Some("2".to_owned()),
            state: crate::composite::ConstituentState::Absent,
            note: Some("n".to_owned()),
            opt_out: Some(crate::composite::OptOut {
                header: crate::composite::PT_OPENBSD_NOBTCFI,
                facts: "0".repeat(64),
            }),
            implementation: Some(crate::composite::FortifyImplementation {
                name: "fortify-headers",
                top_level: "1",
                requested_level: Some("2".to_owned()),
            }),
            bar: Some(crate::composite::FortifyBarReading {
                level: 2,
                source: crate::composite::BarSource::Library,
            }),
        };
        let json = serde_json::to_value(&full).expect("serializes");
        let published: BTreeSet<&str> = json
            .as_object()
            .expect("an object")
            .keys()
            .map(String::as_str)
            .collect();
        let held = ["state", "level", "implementation", "bar"];
        // `flag`, `check` and `applicable` name the slot; `verdict` is `composite_agrees`'s
        // copy check; `satisfied` is derived from `state` by the serializer; `note` is the
        // same derivation's prose; `opt_out` is never on this slot
        // (`composite::FORWARD_EDGE_MARKINGS`).
        let unheld = [
            "flag",
            "check",
            "applicable",
            "verdict",
            "satisfied",
            "note",
            "opt_out",
        ];
        let decided: BTreeSet<&str> = held.iter().chain(unheld.iter()).copied().collect();
        assert_eq!(published, decided);
        assert_eq!(
            FortifySlot::deserialize(&json).expect("reads"),
            FortifySlot::of(&full)
        );
    }

    #[test]
    fn the_fortify_slot_agrees_with_its_published_inputs() {
        use crate::composite::{BarSource, ConstituentState as S, FortifyBarReading};
        let bar = |level: u32, source: BarSource| Some(FortifyBarReading { level, source });
        let shapes: Vec<(&str, Report, S, Option<FortifyBarReading>)> = vec![
            (
                "driver bar, short",
                driver_bar_report("2"),
                S::Absent,
                bar(3, BarSource::Driver),
            ),
            (
                "driver bar, met",
                driver_bar_report("3"),
                S::InForce,
                bar(3, BarSource::Driver),
            ),
            (
                "library bar, short",
                library_bar_report("2"),
                S::Absent,
                bar(3, BarSource::Library),
            ),
            (
                "library bar, met",
                library_bar_report("3"),
                S::InForce,
                bar(3, BarSource::Library),
            ),
            (
                "fortify-headers' request",
                fortify_headers_report(),
                S::InForce,
                bar(2, BarSource::Driver),
            ),
            ("unset bar", unset_bar_report(), S::NotEstablished, None),
            (
                "library bar at glibc 2.35 exactly",
                fortify_slot_report(
                    crate::toolchain::FhardenedFortify::refused(),
                    crate::env::Libc {
                        version: Some("2.35".to_owned()),
                        ..environment_fixture().libc
                    },
                    Some("x86_64-redhat-linux"),
                    vec![fortify_at(Verdict::Partial, "2")],
                ),
                S::Absent,
                bar(3, BarSource::Library),
            ),
        ];
        let mut fed = 0;
        for (name, mut report, state, expected) in shapes {
            fed += 1;
            let slot = fortify_slot_of(&mut report);
            assert_eq!(slot.state, state, "{name}: {:?}", slot.note);
            assert_eq!(slot.bar, expected, "{name}");
            let found = slot_findings_at_publish(&report);
            assert!(found.is_empty(), "{name}: {found:#?}");
            let json = slot_json_of(report);
            assert_eq!(
                slot_findings_on_read(&json),
                (Vec::new(), Vec::new()),
                "{name}"
            );
        }
        assert_eq!(fed, 7);
        let mut report = fortify_headers_report();
        assert_eq!(
            fortify_slot_of(&mut report)
                .implementation
                .as_ref()
                .and_then(|i| i.requested_level.as_deref()),
            Some("2")
        );
    }

    /// One forged shape of the slot: its name, the report it is made from, the edit, and
    /// the fields the rule names over it.
    type ForgedSlot = (
        &'static str,
        fn() -> Report,
        fn(&mut Report),
        &'static [&'static str],
    );

    /// The forged shapes that edit the slot itself. A bar forged down to the level the slot
    /// measured beside an `absent` state is also the state statement's under-claim, so two
    /// fields are refused there.
    fn forged_slot_edits() -> Vec<ForgedSlot> {
        use crate::composite::{BarSource, ConstituentState as S, FortifyBarReading};
        vec![
            (
                "state flipped to in-force",
                || driver_bar_report("2"),
                |r| fortify_slot_of(r).state = S::InForce,
                &["state"],
            ),
            (
                "state flipped to absent",
                || driver_bar_report("3"),
                |r| fortify_slot_of(r).state = S::Absent,
                &["state"],
            ),
            (
                "level edited",
                || driver_bar_report("3"),
                |r| fortify_slot_of(r).level = Some("2".to_owned()),
                &["level"],
            ),
            (
                "requested_level edited",
                fortify_headers_report,
                |r| {
                    if let Some(i) = fortify_slot_of(r).implementation.as_mut() {
                        i.requested_level = Some("3".to_owned());
                    }
                },
                &["implementation"],
            ),
            (
                "requested_level removed",
                fortify_headers_report,
                |r| {
                    if let Some(i) = fortify_slot_of(r).implementation.as_mut() {
                        i.requested_level = None;
                    }
                },
                &["implementation"],
            ),
            (
                "a bar where none was set",
                unset_bar_report,
                |r| {
                    fortify_slot_of(r).bar = Some(FortifyBarReading {
                        level: 2,
                        source: BarSource::Library,
                    });
                },
                &["bar", "state"],
            ),
            (
                "bar.level edited on a set bar",
                || driver_bar_report("2"),
                |r| {
                    if let Some(b) = fortify_slot_of(r).bar.as_mut() {
                        b.level = 2;
                    }
                },
                &["bar", "state"],
            ),
            (
                "bar.source flipped on a set bar",
                || driver_bar_report("2"),
                |r| {
                    if let Some(b) = fortify_slot_of(r).bar.as_mut() {
                        b.source = BarSource::Library;
                    }
                },
                &["bar"],
            ),
            (
                "implementation.name edited",
                fortify_headers_report,
                |r| {
                    if let Some(i) = fortify_slot_of(r).implementation.as_mut() {
                        i.name = "glibc";
                    }
                },
                &["implementation"],
            ),
            (
                "implementation.top_level edited",
                fortify_headers_report,
                |r| {
                    if let Some(i) = fortify_slot_of(r).implementation.as_mut() {
                        i.top_level = "2";
                    }
                },
                &["implementation"],
            ),
        ]
    }

    /// The forged shapes that edit an input under the slot. The two C library edits under the
    /// driver's bar move nothing, since the driver's reading does not depend on the headers.
    fn forged_input_edits() -> Vec<ForgedSlot> {
        vec![
            (
                "fortify-requested's level raised under the slot",
                fortify_headers_report,
                |r| {
                    if let Some(o) = r
                        .observations
                        .iter_mut()
                        .find(|o| o.check == "fortify-requested")
                    {
                        o.level = Some("3".to_owned());
                    }
                },
                &["implementation"],
            ),
            (
                "fortify_source lowered",
                || driver_bar_report("2"),
                |r| r.toolchain.detected.fhardened_fortify.fortify_source = Some("2".to_owned()),
                &["state", "bar"],
            ),
            (
                "fortify_source removed",
                || driver_bar_report("2"),
                |r| r.toolchain.detected.fhardened_fortify.fortify_source = None,
                &["state", "bar"],
            ),
            (
                "the control defines the level too",
                || driver_bar_report("2"),
                |r| {
                    r.toolchain
                        .detected
                        .fhardened_fortify
                        .baseline
                        .fortify_source = Some("3".to_owned());
                },
                &["bar"],
            ),
            (
                "glibc moved below 2.35 under the library's bar",
                || library_bar_report("2"),
                |r| r.environment.libc.version = Some("2.34".to_owned()),
                &["state", "bar"],
            ),
            (
                "glibc moved below 2.35 under the driver's bar",
                || driver_bar_report("2"),
                |r| r.environment.libc.version = Some("2.34".to_owned()),
                &[],
            ),
            (
                "a musl triple under glibc headers, the library's bar",
                || library_bar_report("2"),
                |r| {
                    r.toolchain.detected.target_triple =
                        Some("x86_64-alpine-linux-musl".to_owned());
                },
                &["state", "bar"],
            ),
            (
                "a musl triple under glibc headers, the driver's bar",
                || driver_bar_report("2"),
                |r| {
                    r.toolchain.detected.target_triple =
                        Some("x86_64-alpine-linux-musl".to_owned());
                },
                &[],
            ),
        ]
    }

    #[test]
    fn a_fortify_slot_apart_from_its_inputs_is_refused_at_publish_and_on_read() {
        let shapes: Vec<ForgedSlot> = forged_slot_edits()
            .into_iter()
            .chain(forged_input_edits())
            .collect();
        let mut fed = 0;
        for (name, report, edit, fields) in shapes {
            fed += 1;
            let mut report = report();
            edit(&mut report);
            let expected: Vec<String> = fields.iter().map(|f| slot_field(f)).collect();
            let published = slot_findings_at_publish(&report);
            assert_eq!(
                published
                    .iter()
                    .map(|c| c.property.clone())
                    .collect::<Vec<_>>(),
                expected,
                "{name} at publication: {published:#?}"
            );
            for c in &published {
                assert_eq!(c.claims.len(), 2, "{name}: {:?}", c.claims);
                // The recomputation's second claim names the inputs; a statement's names
                // the observation or the record it holds the field to.
                assert!(
                    c.claims[0].starts_with(&c.property)
                        && (c.claims[1].starts_with("recomputed from ")
                            || c.claims[1].starts_with("observations[fortify-effective]")
                            || c.claims[1].starts_with("toolchain.fhardened_fortify")),
                    "{name}: {:?}",
                    c.claims
                );
                assert_ne!(
                    c.claims[0].rsplit(" = ").next(),
                    c.claims[1].rsplit(" = ").next(),
                    "{name}: both values are named and differ: {:?}",
                    c.claims
                );
            }
            let pinned = match name {
                "state flipped to in-force" => Some(("state = in-force", "absent")),
                "level edited" => Some(("level = 2", "3")),
                "bar.level edited on a set bar" => {
                    Some(("bar = level 2 by the driver", "level 3 by the driver"))
                }
                "requested_level edited" => Some((
                    "implementation = fortify-headers (top_level 1, requested_level 3)",
                    "fortify-headers (top_level 1, requested_level 2)",
                )),
                _ => None,
            };
            if let Some((written, recomputed)) = pinned {
                assert_eq!(
                    published[0].claims,
                    [
                        format!("{FORTIFY_SLOT}.{written}"),
                        format!("recomputed from {FORTIFY_SLOT_INPUTS} = {recomputed}"),
                    ],
                    "{name}: the written value first, the recomputed second"
                );
            }
            let json = slot_json_of(report);
            let (read, unreadable) = slot_findings_on_read(&json);
            assert_eq!(read, expected, "{name} on read");
            assert!(unreadable.is_empty(), "{name} on read: {unreadable:?}");
        }
        assert_eq!(fed, 18);
    }

    #[test]
    fn the_slot_state_statements_hold_apart_from_the_derivation() {
        use crate::composite::{BarSource, ConstituentState as S, FortifyBarReading};
        let fed = std::cell::Cell::new(0);
        let d3 = || {
            Some(FortifyBarReading {
                level: 3,
                source: BarSource::Driver,
            })
        };
        let l2 = || {
            Some(FortifyBarReading {
                level: 2,
                source: BarSource::Library,
            })
        };
        let (on, partial, off, invalid) = (
            Some(Verdict::On),
            Some(Verdict::Partial),
            Some(Verdict::Off),
            Some(Verdict::ProbeInvalid),
        );
        let (inf, ab, ne) = (S::InForce, S::Absent, S::NotEstablished);
        let (no, st): (&[&str], &[&str]) = (&[], &["state"]);
        let row = |name: &str, state: S, level: &str, requested, bar, effective, expected| {
            fed.set(fed.get() + 1);
            let written = slot_shape(state, level, requested, bar);
            let found = invariant_fields(fortify_slot_invariants(&written, effective, None));
            assert_eq!(found, expected, "{name}");
        };
        row("in force, partial", inf, "2", None, None, partial, no);
        row("in force, on", inf, "2", None, None, on, no);
        row("in force, off", inf, "2", None, None, off, st);
        row("in force, probe-invalid", inf, "2", None, None, invalid, st);
        row("in force, nothing", inf, "2", None, None, None, st);
        row("marked, on", S::Marked, "2", None, None, on, st);
        row("marked, nothing", S::Marked, "2", None, None, None, st);
        row("absent, off", ab, "2", None, None, off, no);
        row(
            "absent, level under the bar",
            ab,
            "2",
            None,
            d3(),
            partial,
            no,
        );
        row(
            "absent, level meets the bar",
            ab,
            "3",
            None,
            d3(),
            partial,
            st,
        );
        row(
            "not established, level meets",
            ne,
            "3",
            None,
            d3(),
            partial,
            st,
        );
        row(
            "absent, request meets the bar",
            ab,
            "1",
            Some("2"),
            l2(),
            partial,
            st,
        );
        row("absent, level meets, off", ab, "3", None, d3(), off, no);
        row(
            "absent, no bar, high level",
            ab,
            "3",
            None,
            None,
            partial,
            no,
        );
        assert_eq!(fed.get(), 14);
    }

    #[test]
    fn the_slot_bar_statements_hold_apart_from_the_derivation() {
        use crate::composite::{BarSource, ConstituentState as S, FortifyBarReading};
        use crate::toolchain::FhardenedFortify;
        let fed = std::cell::Cell::new(0);
        let d3 = || {
            Some(FortifyBarReading {
                level: 3,
                source: BarSource::Driver,
            })
        };
        let d2 = || {
            Some(FortifyBarReading {
                level: 2,
                source: BarSource::Driver,
            })
        };
        let l3 = || {
            Some(FortifyBarReading {
                level: 3,
                source: BarSource::Library,
            })
        };
        let defining = FhardenedFortify::defining("3");
        let refused = FhardenedFortify::refused();
        let equal = FhardenedFortify {
            baseline: crate::toolchain::FortifyBaseline {
                fortify_source: Some("3".to_owned()),
                ..FhardenedFortify::defining("3").baseline
            },
            ..FhardenedFortify::defining("3")
        };
        let unlevelled = FhardenedFortify {
            fortify_source: None,
            ..FhardenedFortify::defining("3")
        };
        let worded = FhardenedFortify::defining("three");
        let spaced = FhardenedFortify::defining(" 3 ");
        let row = |name: &str, bar, driver: Option<&FhardenedFortify>, expected: &[&str]| {
            fed.set(fed.get() + 1);
            let written = slot_shape(S::Absent, "1", None, bar);
            let found = fortify_slot_invariants(&written, Some(Verdict::Partial), driver);
            assert_eq!(invariant_fields(found), expected, "{name}");
        };
        row("driver bar at the dump's level", d3(), Some(&defining), &[]);
        row(
            "driver bar at another level",
            d2(),
            Some(&defining),
            &["bar"],
        );
        row(
            "driver bar beside a dump that did not answer",
            d3(),
            Some(&refused),
            &["bar"],
        );
        row(
            "driver bar beside a control defining the level too",
            d3(),
            Some(&equal),
            &["bar"],
        );
        row(
            "driver bar at a level that is not a number",
            d3(),
            Some(&worded),
            &["bar"],
        );
        row(
            "driver bar at a level with spaces",
            d3(),
            Some(&spaced),
            &[],
        );
        row(
            "library bar beside a dump that did not answer",
            l3(),
            Some(&refused),
            &[],
        );
        row(
            "library bar beside a dump that answered",
            l3(),
            Some(&defining),
            &["bar"],
        );
        row(
            "library bar beside a dump answering with no level",
            l3(),
            Some(&unlevelled),
            &["bar"],
        );
        row("a bar with no record to hold it to", d3(), None, &[]);
        assert_eq!(fed.get(), 10);
    }

    #[test]
    fn the_slot_statements_add_one_per_field_and_hold_the_state_without_the_record() {
        use crate::composite::{BarSource, ConstituentState as S, FortifyBarReading};
        let found = with_invariants(
            vec![fortify_slot_contradiction("bar", "a", "b")],
            fortify_slot_invariants(
                &FortifySlot {
                    state: S::InForce,
                    level: Some("2".to_owned()),
                    implementation: None,
                    bar: Some(FortifyBarReading {
                        level: 2,
                        source: BarSource::Driver,
                    }),
                },
                Some(Verdict::Off),
                Some(&crate::toolchain::FhardenedFortify::defining("3")),
            ),
        );
        assert_eq!(
            found
                .iter()
                .map(|c| c.property.as_str())
                .collect::<Vec<_>>(),
            [slot_field("bar"), slot_field("state")]
        );
        assert!(
            found[0].claims[1].ends_with(" = b"),
            "{:?}",
            found[0].claims
        );

        // On read without the record: the state in force beside a fortify-effective edited
        // to off is refused by the statement, where the recomputation has nothing to say.
        let mut unrecorded = slot_json_of(driver_bar_report("2"));
        unrecorded["toolchain"]
            .as_object_mut()
            .expect("toolchain")
            .remove("fhardened_fortify");
        fortify_slot_json(&mut unrecorded)["state"] = serde_json::json!("in-force");
        assert_eq!(
            slot_findings_on_read(&unrecorded),
            (Vec::new(), Vec::new()),
            "in force beside the measured partial is not refused without the record"
        );
        observation_named(&mut unrecorded, "fortify-effective")["verdict"] =
            serde_json::json!("off");
        assert_eq!(
            slot_findings_on_read(&unrecorded),
            (vec![slot_field("state")], Vec::new())
        );
    }

    #[test]
    fn complete_absent_is_refused_on_the_readers_own_revision_alone() {
        let mut fixture = reread_fixture();
        fixture.consistency = consistency(&fixture);
        let mut json = serde_json::to_value(fixture).expect("serializes");
        json["run"]["harness_revision_source"] = serde_json::json!("git");
        let own = crate::dataset::revision_key(&json);
        let found = |json: &serde_json::Value, reader: &str| {
            let defects =
                BTreeMap::<String, DefectStatusOnRead>::deserialize(&json["defect_coverage"])
                    .expect("reads");
            complete_absent_on_own_revision(json, &defects, Some(reader))
        };
        let id = json["defect_coverage"]
            .as_object()
            .and_then(|m| m.keys().next().cloned())
            .expect("the fixture has a defect entry");

        assert!(found(&json, &own).is_empty(), "every entry carries it");
        for edit in ["removed", "null"] {
            let mut edited = json.clone();
            let entry = &mut edited["defect_coverage"][&id];
            if edit == "removed" {
                entry.as_object_mut().expect("an entry").remove("complete");
            } else {
                entry["complete"] = serde_json::Value::Null;
            }
            let at_own = found(&edited, &own);
            assert_eq!(at_own.len(), 1, "{edit}: {at_own:?}");
            assert_eq!(at_own[0].rule, RULE_DEFECT_STATUS);
            assert_eq!(at_own[0].property, id);
            assert!(
                found(&edited, "rev-b").is_empty(),
                "{edit}: another revision's report reads"
            );
        }
        // No reader revision (a build that names none): nothing is held.
        let mut edited = json.clone();
        edited["defect_coverage"][&id]
            .as_object_mut()
            .expect("an entry")
            .remove("complete");
        let defects =
            BTreeMap::<String, DefectStatusOnRead>::deserialize(&edited["defect_coverage"])
                .expect("reads");
        assert!(complete_absent_on_own_revision(&edited, &defects, None).is_empty());
    }

    #[test]
    fn a_slot_key_or_record_absent_is_held_by_the_readers_own_revision_alone() {
        let json_of = |report: Report| {
            let mut json = slot_json_of(report);
            json["run"]["harness_revision_source"] = serde_json::json!("git");
            json
        };
        let at = |json: &serde_json::Value, own: bool| {
            let observations =
                Vec::<ObservationOnRead>::deserialize(&json["observations"]).expect("reads");
            let reader = crate::dataset::revision_key(json);
            let reader = if own { reader.as_str() } else { "rev-b" };
            let mut out = Reread::default();
            reread_fortify_slot(json, Some(&observations), Some(reader), &mut out);
            assert!(out.unreadable.is_empty(), "{:?}", out.unreadable);
            out.contradictions
                .into_iter()
                .map(|c| c.property)
                .collect::<Vec<_>>()
        };
        let none: Vec<String> = Vec::new();

        // At publication this build is the writer, so a key the derivation gives and the
        // slot lacks is refused there.
        let properties =
            |found: Vec<Contradiction>| found.into_iter().map(|c| c.property).collect::<Vec<_>>();
        let mut unbarred = driver_bar_report("2");
        fortify_slot_of(&mut unbarred).bar = None;
        assert_eq!(
            properties(slot_findings_at_publish(&unbarred)),
            [slot_field("bar")]
        );
        let mut unexplained = fortify_headers_report();
        fortify_slot_of(&mut unexplained).implementation = None;
        assert_eq!(
            properties(slot_findings_at_publish(&unexplained)),
            [slot_field("implementation")]
        );

        // The bar removed, and the implementation removed.
        let mut bare = json_of(driver_bar_report("2"));
        fortify_slot_json(&mut bare)
            .as_object_mut()
            .expect("a slot")
            .remove("bar");
        assert_eq!(at(&bare, false), none);
        assert_eq!(at(&bare, true), [slot_field("bar")]);
        let mut bare = json_of(fortify_headers_report());
        fortify_slot_json(&mut bare)
            .as_object_mut()
            .expect("a slot")
            .remove("implementation");
        assert_eq!(at(&bare, false), none);
        assert_eq!(at(&bare, true), [slot_field("implementation")]);

        // The record removed: honest otherwise, the level and the implementation held.
        let mut unrecorded = json_of(driver_bar_report("2"));
        unrecorded["toolchain"]
            .as_object_mut()
            .expect("toolchain")
            .remove("fhardened_fortify");
        assert_eq!(at(&unrecorded, false), none);
        assert_eq!(at(&unrecorded, true), ["toolchain.fhardened_fortify"]);
        let mut edited = unrecorded.clone();
        fortify_slot_json(&mut edited)["level"] = serde_json::json!("3");
        // The level against the observation's, and the state statement: a level meeting the
        // published bar beside an absent slot is the under-claim.
        assert_eq!(
            at(&edited, false),
            [slot_field("level"), slot_field("state")]
        );
        let mut edited = unrecorded.clone();
        fortify_slot_json(&mut edited)["state"] = serde_json::json!("in-force");
        assert_eq!(
            at(&edited, false),
            none,
            "the state is not held without the record"
        );
        let mut unrecorded = json_of(fortify_headers_report());
        unrecorded["toolchain"]
            .as_object_mut()
            .expect("toolchain")
            .remove("fhardened_fortify");
        fortify_slot_json(&mut unrecorded)["implementation"]["requested_level"] =
            serde_json::json!("3");
        assert_eq!(at(&unrecorded, false), [slot_field("implementation")]);

        // The dodge: the bar removed with the one input edit that moves the bar's source and
        // not the state (the control defining the level too, so the library sets the same
        // bar).
        let mut dodged = json_of(driver_bar_report("2"));
        fortify_slot_json(&mut dodged)
            .as_object_mut()
            .expect("a slot")
            .remove("bar");
        dodged["toolchain"]["fhardened_fortify"]["baseline"]["fortify_source"] =
            serde_json::json!("3");
        assert_eq!(at(&dodged, false), none);
        assert_eq!(at(&dodged, true), [slot_field("bar")]);
        let mut moved = json_of(driver_bar_report("2"));
        fortify_slot_json(&mut moved)
            .as_object_mut()
            .expect("a slot")
            .remove("bar");
        moved["toolchain"]["fhardened_fortify"]
            .as_object_mut()
            .expect("the record")
            .remove("fortify_source");
        assert_eq!(at(&moved, false), [slot_field("state")]);

        // No umbrella at all: nothing to hold, whoever wrote the report, as at publication.
        let mut unreduced = json_of(driver_bar_report("2"));
        unreduced["composites"] = serde_json::json!([]);
        assert_eq!(at(&unreduced, false), none);
        assert_eq!(at(&unreduced, true), none);

        // Through the reread, which keys on this build: the fixture names another revision,
        // so the removals read as an older writer's.
        assert_eq!(slot_findings_on_read(&dodged), (Vec::new(), Vec::new()));
        assert_eq!(slot_findings_on_read(&unreduced), (Vec::new(), Vec::new()));
    }

    /// A report whose umbrella `measure`'s own function derived over `emitted`, the
    /// `ssp-level-emitted` observation, beside a fortify in force: the shape
    /// [`RULE_SSP_SLOT`] holds.
    fn ssp_slot_report(emitted: Option<Observation>) -> Report {
        let mut observations = vec![fortify_at(Verdict::On, "3")];
        observations.extend(emitted);
        fortify_slot_report(
            crate::toolchain::FhardenedFortify::defining("3"),
            environment_fixture().libc,
            Some("x86_64-redhat-linux"),
            observations,
        )
    }

    /// `ssp-level-emitted` at `verdict` and `level`, as the composites read it.
    fn emitted_at(verdict: Verdict, level: Option<&str>) -> Observation {
        let mut o = obs("ssp-level-emitted", Polarity::Harden, verdict, "");
        o.defects = Vec::new();
        o.level = level.map(str::to_owned);
        o
    }

    /// The protector slot of `report`'s umbrella, by its flag, to read or edit.
    fn ssp_slot_of(report: &mut Report) -> &mut crate::composite::Constituent {
        report
            .composites
            .iter_mut()
            .find(|c| c.id == "fhardened-effective")
            .expect("the umbrella")
            .constituents
            .iter_mut()
            .find(|k| k.flag == crate::composite::SSP_SLOT_FLAG)
            .expect("its protector slot")
    }

    /// The same slot in a report's JSON, to edit as a file would be.
    fn ssp_slot_json(report: &mut serde_json::Value) -> &mut serde_json::Value {
        report["composites"]
            .as_array_mut()
            .expect("composites")
            .iter_mut()
            .find(|c| c["id"] == "fhardened-effective")
            .expect("the umbrella")["constituents"]
            .as_array_mut()
            .expect("constituents")
            .iter_mut()
            .find(|k| k["flag"] == crate::composite::SSP_SLOT_FLAG)
            .expect("its protector slot")
    }

    /// The property the protector rule names for `field` of the slot.
    fn ssp_field(field: &str) -> String {
        format!("{SSP_SLOT}.{field}")
    }

    /// The properties [`RULE_SSP_SLOT`] names over `report` at publication, in order.
    fn ssp_findings_at_publish(report: &Report) -> Vec<String> {
        consistency(report)
            .contradictions
            .into_iter()
            .filter(|c| c.rule == RULE_SSP_SLOT)
            .map(|c| c.property)
            .collect()
    }

    /// The properties the protector rule names over `report` as JSON on read, with the
    /// unreadable findings naming it.
    fn ssp_findings_on_read(report: &serde_json::Value) -> (Vec<String>, Vec<String>) {
        let reread = reread_contradictions(report);
        (
            reread
                .contradictions
                .into_iter()
                .filter(|c| c.rule == RULE_SSP_SLOT)
                .map(|c| c.property)
                .collect(),
            reread
                .unreadable
                .into_iter()
                .filter(|u| u.contains(RULE_SSP_SLOT))
                .collect(),
        )
    }

    #[test]
    fn the_protector_slot_is_held_to_its_observation_at_publication() {
        use crate::composite::ConstituentState as S;
        let none: Vec<String> = Vec::new();
        let plain = || ssp_slot_report(Some(emitted_at(Verdict::Partial, Some("basic"))));
        let mut honest = plain();
        assert_eq!(ssp_slot_of(&mut honest).state, S::Absent);
        assert_eq!(ssp_slot_of(&mut honest).check, "ssp-level-emitted");
        assert_eq!(ssp_findings_at_publish(&honest), none);

        let mut flipped = plain();
        ssp_slot_of(&mut flipped).state = S::InForce;
        assert_eq!(ssp_findings_at_publish(&flipped), [ssp_field("state")]);
        let mut raised = plain();
        ssp_slot_of(&mut raised).level = Some("strong".to_owned());
        assert_eq!(ssp_findings_at_publish(&raised), [ssp_field("level")]);
        let mut renamed = plain();
        ssp_slot_of(&mut renamed).check = "canary-emitted";
        assert_eq!(ssp_findings_at_publish(&renamed), [ssp_field("check")]);

        // Derived in force at strong, then the observation lowered under it.
        let mut moved = ssp_slot_report(Some(emitted_at(Verdict::On, Some("strong"))));
        assert_eq!(ssp_slot_of(&mut moved).state, S::InForce);
        let o = moved
            .observations
            .iter_mut()
            .find(|o| o.check == "ssp-level-emitted")
            .expect("the observation");
        o.verdict = Verdict::Partial;
        o.level = Some("basic".to_owned());
        assert_eq!(
            ssp_findings_at_publish(&moved),
            [ssp_field("state"), ssp_field("level")]
        );

        let mut unmeasured = ssp_slot_report(None);
        assert_eq!(ssp_slot_of(&mut unmeasured).state, S::NotEstablished);
        assert_eq!(ssp_findings_at_publish(&unmeasured), none);
        let mut unreduced = plain();
        unreduced.composites.clear();
        assert_eq!(ssp_findings_at_publish(&unreduced), none);
    }

    #[test]
    fn the_protector_slot_statements_hold_the_state_to_the_measured_verdict() {
        use crate::composite::ConstituentState as S;
        let slot = |state: S, level: Option<&str>| SspSlot {
            check: "ssp-level-emitted".to_owned(),
            state,
            level: level.map(str::to_owned),
        };
        let raised = |state: S, level: Option<&str>, emitted: Option<Verdict>| {
            invariant_fields(ssp_slot_invariants(&slot(state, level), emitted))
        };
        let none: Vec<&str> = Vec::new();
        assert_eq!(raised(S::InForce, Some("strong"), Some(Verdict::On)), none);
        assert_eq!(
            raised(S::InForce, Some("strong"), Some(Verdict::Partial)),
            ["state"]
        );
        assert_eq!(raised(S::InForce, Some("strong"), None), ["state"]);
        assert_eq!(
            raised(S::Absent, Some("basic"), Some(Verdict::Partial)),
            none
        );
        assert_eq!(raised(S::Absent, None, Some(Verdict::Off)), none);
        assert_eq!(
            raised(S::Absent, Some("basic"), Some(Verdict::On)),
            ["state"]
        );
        assert_eq!(
            raised(S::Absent, None, Some(Verdict::Indeterminate)),
            ["state"]
        );
        assert_eq!(raised(S::Absent, None, None), ["state"]);
        assert_eq!(raised(S::NotEstablished, None, None), none);
        assert_eq!(
            raised(S::NotEstablished, Some("unsafe-frame"), Some(Verdict::On)),
            none
        );
        // A protector slot reads no marking, so `marked` is refused beside any reading.
        for emitted in [Some(Verdict::On), Some(Verdict::Partial), None] {
            assert_eq!(
                raised(S::Marked, Some("strong"), emitted),
                ["state"],
                "{emitted:?}"
            );
        }
    }

    #[test]
    fn the_protector_slot_is_held_to_its_observation_on_read() {
        let none: Vec<String> = Vec::new();
        let json = slot_json_of(ssp_slot_report(Some(emitted_at(
            Verdict::Partial,
            Some("basic"),
        ))));
        assert_eq!(ssp_findings_on_read(&json), (none.clone(), none.clone()));

        let mut flipped = json.clone();
        ssp_slot_json(&mut flipped)["state"] = serde_json::json!("in-force");
        assert_eq!(
            ssp_findings_on_read(&flipped),
            (vec![ssp_field("state")], none.clone())
        );
        // The level raised beside a kept `partial`: the pair the slot reads as not
        // established, so state and level both move.
        let mut edited = json.clone();
        observation_named(&mut edited, "ssp-level-emitted")["level"] = serde_json::json!("strong");
        assert_eq!(
            ssp_findings_on_read(&edited),
            (vec![ssp_field("state"), ssp_field("level")], none.clone())
        );

        let at = |json: &serde_json::Value, own: bool| {
            let observations =
                Vec::<ObservationOnRead>::deserialize(&json["observations"]).expect("reads");
            let reader = crate::dataset::revision_key(json);
            let reader = if own { reader.as_str() } else { "rev-b" };
            let mut out = Reread::default();
            reread_ssp_slot(json, Some(&observations), Some(reader), &mut out);
            assert!(out.unreadable.is_empty(), "{:?}", out.unreadable);
            out.contradictions
                .into_iter()
                .map(|c| (c.property, c.claims.len()))
                .collect::<Vec<_>>()
        };
        let mut older = json.clone();
        older["run"]["harness_revision_source"] = serde_json::json!("git");
        ssp_slot_json(&mut older)["check"] = serde_json::json!("canary-emitted");
        assert_eq!(at(&older, false), Vec::<(String, usize)>::new());
        assert_eq!(at(&older, true), [(ssp_field("check"), 2)]);
        // A `canary-emitted` slot in force under a measured `basic`: refused whoever wrote
        // it, naming the writer where it is another revision.
        ssp_slot_json(&mut older)["state"] = serde_json::json!("in-force");
        assert_eq!(at(&older, false), [(ssp_field("state"), 3)]);
        // The shapes another revision writes: a `canary-emitted` slot carries no level, which
        // holds from another revision and is refused from this build.
        let mut written_by_canary = slot_json_of(ssp_slot_report(Some(emitted_at(
            Verdict::On,
            Some("strong"),
        ))));
        written_by_canary["run"]["harness_revision_source"] = serde_json::json!("git");
        let slot = ssp_slot_json(&mut written_by_canary);
        slot["check"] = serde_json::json!("canary-emitted");
        slot.as_object_mut().expect("a slot").remove("level");
        assert_eq!(at(&written_by_canary, false), Vec::<(String, usize)>::new());
        assert_eq!(
            at(&written_by_canary, true),
            [(ssp_field("check"), 2), (ssp_field("level"), 2)]
        );
        let mut downgraded = json.clone();
        downgraded["run"]["harness_revision_source"] = serde_json::json!("git");
        let slot = ssp_slot_json(&mut downgraded);
        slot["check"] = serde_json::json!("canary-emitted");
        slot["state"] = serde_json::json!("in-force");
        slot.as_object_mut().expect("a slot").remove("level");
        assert_eq!(at(&downgraded, false), [(ssp_field("state"), 3)]);
        // The exemption is `canary-emitted`'s alone, and only where no level is written: a
        // slot of another revision citing ssp-level-emitted with its level removed, and a
        // `canary-emitted` slot carrying a level other than the recomputed one, are refused.
        let mut unlevelled = json.clone();
        unlevelled["run"]["harness_revision_source"] = serde_json::json!("git");
        ssp_slot_json(&mut unlevelled)
            .as_object_mut()
            .expect("a slot")
            .remove("level");
        assert_eq!(at(&unlevelled, false), [(ssp_field("level"), 3)]);
        let mut mislevelled = json.clone();
        mislevelled["run"]["harness_revision_source"] = serde_json::json!("git");
        let slot = ssp_slot_json(&mut mislevelled);
        slot["check"] = serde_json::json!("canary-emitted");
        slot["level"] = serde_json::json!("strong");
        assert_eq!(at(&mislevelled, false), [(ssp_field("level"), 3)]);
        // The slot removed with the umbrella kept reads as written.
        let mut unslotted = json.clone();
        unslotted["composites"][0]["constituents"]
            .as_array_mut()
            .expect("constituents")
            .retain(|k| k["flag"] != crate::composite::SSP_SLOT_FLAG);
        assert_eq!(
            ssp_findings_on_read(&unslotted),
            (none.clone(), none.clone())
        );

        let mut broken = json.clone();
        broken["composites"][0]["constituents"] = serde_json::json!("x");
        let (found, unreadable) = ssp_findings_on_read(&broken);
        assert_eq!(found, none);
        assert_eq!(unreadable.len(), 1, "{unreadable:?}");

        let mut unflagged = json.clone();
        ssp_slot_json(&mut unflagged)["state"] = serde_json::json!("in-force");
        ssp_slot_json(&mut unflagged)["flag"] = serde_json::json!("-fstack-protector");
        assert_eq!(ssp_findings_on_read(&unflagged), (none.clone(), none));
    }

    #[test]
    fn a_protector_slot_that_disagrees_with_its_observation_is_not_published() {
        use crate::composite::ConstituentState as S;
        let (dir, output, quarantine) = publication_paths("protector-slot");
        let destination = Destination::File {
            requested: output.clone(),
            path: output.clone(),
        };
        let mut honest = publishable_fixture();
        honest.composites = vec![
            crate::composite::fhardened(
                &honest.observations,
                "x86_64",
                &honest.toolchain.detected.fhardened_fortify,
                &honest.environment.libc,
                honest.toolchain.detected.target_triple.as_deref(),
                &honest.facts,
            ),
            crate::composite::cfi(
                &honest.observations,
                "x86_64",
                &honest.environment.libc,
                &honest.facts,
            ),
        ];
        let mut flipped = honest.clone();
        assert_eq!(ssp_slot_of(&mut flipped).state, S::NotEstablished);
        ssp_slot_of(&mut flipped).state = S::InForce;
        assert_eq!(
            publish(&mut honest, Some(&destination)).expect("publication runs"),
            Publication::Written,
            "{:?}",
            honest.consistency.contradictions
        );
        assert!(output.exists() && !quarantine.exists());
        assert_eq!(
            publish(&mut flipped, Some(&destination)).expect("publication runs"),
            Publication::Refused {
                contradictions: 1,
                quarantine: Some(quarantine.clone()),
                cause: RefusalCause::Defect,
            },
            "{:?}",
            flipped.consistency.contradictions
        );
        assert_eq!(crate::error::EXIT_CONTRADICTION, 3);
        assert!(quarantine.exists() && !output.exists());
        let found = &flipped.consistency.contradictions[0];
        assert_eq!(found.rule, RULE_SSP_SLOT);
        assert_eq!(found.property, ssp_field("state"));
        std::fs::remove_dir_all(&dir).expect("the scratch directory is removed");
    }

    #[test]
    fn every_protector_slot_key_is_held_or_named_unheld() {
        use std::collections::BTreeSet;
        let slot =
            crate::composite::ssp_constituent(&[emitted_at(Verdict::Partial, Some("basic"))]);
        let json = serde_json::to_value(&slot).expect("serializes");
        let published: BTreeSet<&str> = json
            .as_object()
            .expect("an object")
            .keys()
            .map(String::as_str)
            .collect();
        let held = ["check", "state", "level"];
        // `flag` finds the slot and `applicable` is always true; `verdict` is
        // `composite_agrees`'s copy check; `satisfied` is derived from `state` by the
        // serializer; `note` is the same derivation's prose.
        let unheld = ["flag", "applicable", "verdict", "satisfied", "note"];
        let decided: BTreeSet<&str> = held.iter().chain(unheld.iter()).copied().collect();
        assert_eq!(published, decided);
        let read = SspSlot::deserialize(&json).expect("the held keys read back");
        assert_eq!(read, SspSlot::of(&slot));
    }

    #[test]
    fn a_finding_on_another_revisions_report_names_that_revision() {
        let mut flipped = slot_json_of(driver_bar_report("2"));
        flipped["run"]["harness_revision_source"] = serde_json::json!("git");
        fortify_slot_json(&mut flipped)["state"] = serde_json::json!("in-force");
        let claims_at = |own: bool| {
            let observations =
                Vec::<ObservationOnRead>::deserialize(&flipped["observations"]).expect("reads");
            let reader = crate::dataset::revision_key(&flipped);
            let reader = if own { reader.as_str() } else { "rev-b" };
            let mut out = Reread::default();
            reread_fortify_slot(&flipped, Some(&observations), Some(reader), &mut out);
            assert_eq!(out.contradictions.len(), 1, "{:?}", out.contradictions);
            out.contradictions.remove(0).claims
        };
        let named = claims_at(false);
        assert_eq!(named.len(), 3, "{named:?}");
        assert_eq!(
            named[2],
            format!(
                "run.harness_revision, with its source and rustflags, names {}, not this \
                 build (rev-b)",
                crate::dataset::revision_key(&flipped)
            )
        );
        assert_eq!(claims_at(true).len(), 2);
    }

    #[test]
