    #[test]
    fn a_fortify_slot_subtree_that_does_not_read_is_a_finding() {
        type Edit = fn(&mut serde_json::Value);
        let honest = slot_json_of(driver_bar_report("2"));
        let edits: [(&str, Edit, &str); 8] = [
            (
                "libc removed",
                |r| {
                    r["environment"]
                        .as_object_mut()
                        .expect("environment")
                        .remove("libc");
                },
                "`environment.libc`",
            ),
            (
                "libc unreadable",
                |r| r["environment"]["libc"]["impl"] = serde_json::json!(7),
                "`environment.libc`",
            ),
            (
                "triple not a string",
                |r| r["toolchain"]["target_triple"] = serde_json::json!(7),
                "`toolchain.target_triple`",
            ),
            (
                "record unreadable",
                |r| r["toolchain"]["fhardened_fortify"] = serde_json::json!("x"),
                "`toolchain.fhardened_fortify`",
            ),
            (
                "state outside its enumeration",
                |r| fortify_slot_json(r)["state"] = serde_json::json!("maybe"),
                "constituents[-D_FORTIFY_SOURCE]",
            ),
            (
                "composites not a list",
                |r| r["composites"] = serde_json::json!("x"),
                "`composites`",
            ),
            (
                "the umbrella's constituents not a list",
                |r| r["composites"][0]["constituents"] = serde_json::json!("x"),
                "constituents` is not a list",
            ),
            (
                "observations not a list",
                |r| r["observations"] = serde_json::json!("x"),
                "`observations`",
            ),
        ];
        let mut fed = 0;
        for (name, edit, names) in edits {
            fed += 1;
            let mut report = honest.clone();
            edit(&mut report);
            let (found, unreadable) = slot_findings_on_read(&report);
            assert!(found.is_empty(), "{name}: {found:?}");
            assert_eq!(unreadable.len(), 1, "{name}: {unreadable:?}");
            assert!(unreadable[0].contains(names), "{name}: {}", unreadable[0]);
        }
        assert_eq!(fed, 8);
        let mut report = honest;
        report
            .as_object_mut()
            .expect("a report")
            .remove("composites");
        assert_eq!(slot_findings_on_read(&report), (Vec::new(), Vec::new()));
    }

    #[test]
    fn an_unreadable_subtree_blocks_only_the_rules_that_read_it() {
        let mut fixture = reread_fixture();
        fixture.consistency = consistency(&fixture);
        let mut report = serde_json::to_value(fixture).expect("serializes");
        report["defect_coverage"] = serde_json::Value::Null;
        report["fortify_ratchet"]["dynamic_bounds"] = true.into();
        report["fortify_ratchet"]["whole_object_level"] = "0".into();
        let reread = reread_contradictions(&report);
        assert_eq!(reread.unreadable.len(), 1, "{:?}", reread.unreadable);
        assert!(
            reread.unreadable[0].contains("`defect_coverage`")
                && reread.unreadable[0].contains(RULE_DEFECT_STATUS),
            "{}",
            reread.unreadable[0]
        );
        // Both axes and the level they land on against the rungs, then the axis rule.
        assert_eq!(
            reread
                .contradictions
                .iter()
                .map(|c| c.rule.as_str())
                .collect::<Vec<_>>(),
            [
                RULE_FORTIFY_LEVEL,
                RULE_FORTIFY_LEVEL,
                RULE_FORTIFY_LEVEL,
                RULE_FORTIFY_AXES
            ],
            "the ratchet read, so its rules ran, and the rollup's did not"
        );

        // Absent where `measure` always writes it: a finding too, not an empty input.
        let mut bare = as_published(reread_fixture());
        bare.as_object_mut()
            .expect("a report")
            .remove("observations");
        let reread = reread_contradictions(&bare);
        assert!(
            reread
                .unreadable
                .iter()
                .any(|u| u.contains("carries no `observations`")),
            "{:?}",
            reread.unreadable
        );
    }

