    /// [`reread_fixture`] with what the gating and corroboration rules read beside it, as
    /// the JSON `measure` writes: `unsupported` under `arch-gated` (`arch`),
    /// `indeterminate` under `no-check-on-target` (`unread`), a plain `off` (`plain`), and
    /// a group of two members measured `on` through two channels. Its `consistency` block
    /// lists no finding.
    fn gated_reread_json() -> serde_json::Value {
        let mut report = reread_fixture();
        let plain = |check: &str, verdict: Verdict, channel: Channel| {
            let mut o = obs(check, Polarity::Harden, verdict, "");
            o.defects = Vec::new();
            o.channel = channel;
            o
        };
        let gated = |check: &str, verdict: Verdict, rule: gating_rule::Rule| {
            let mut o = plain(check, verdict, Channel::ElfStatic);
            o.gating = Some(Gating {
                rule,
                arch: None,
                libc: None,
                needs_vm: false,
                reason: "a gating rule".to_owned(),
            });
            o
        };
        report
            .observations
            .push(gated("arch", Verdict::Unsupported, gating_rule::ARCH));
        report.observations.push(gated(
            "unread",
            Verdict::Indeterminate,
            gating_rule::NO_CHECK_ON_TARGET,
        ));
        report
            .observations
            .push(plain("plain", Verdict::Off, Channel::ElfStatic));
        report
            .observations
            .push(plain("member-macro", Verdict::On, Channel::Macro));
        report
            .observations
            .push(plain("member-elf", Verdict::On, Channel::ElfStatic));
        report.corroboration = corroboration(&report.observations, &|id| {
            id.starts_with("member-").then_some("group")
        });
        let mut expected = ids_of(&report.observations);
        expected.insert("c".to_owned());
        report.coverage = coverage(
            &report.observations,
            &expected,
            5,
            &report.profile,
            Vec::new(),
        );
        stamp(&mut report);
        // The block `measure` fills, emptied of its findings: like `reread_fixture`, this
        // agrees with itself under the rules the reread runs and not under the rest, and a
        // renderer reads a report's own list before it re-runs anything.
        let mut block = consistency(&report);
        block.contradictions.clear();
        report.consistency = block;
        serde_json::to_value(&report).expect("the report serializes")
    }

    /// `report["observations"][check]`, for an edit.
    fn observation_named<'a>(
        report: &'a mut serde_json::Value,
        check: &str,
    ) -> &'a mut serde_json::Value {
        report["observations"]
            .as_array_mut()
            .expect("observations")
            .iter_mut()
            .find(|o| o["check"] == check)
            .unwrap_or_else(|| panic!("no observation {check}"))
    }

    /// The rules the reread raised over `report`, in order, and its unreadable subtrees.
    fn reread_rules(report: &serde_json::Value) -> (Vec<String>, Vec<String>) {
        let read = reread_contradictions(report);
        assert!(
            read.older.is_empty(),
            "no fixture here is an older shape: {read:?}"
        );
        (
            read.contradictions.into_iter().map(|c| c.rule).collect(),
            read.unreadable,
        )
    }

    #[test]
    fn the_gated_fixture_publishes_each_class_and_reads_clean() {
        let report = gated_reread_json();
        for (check, class) in [
            ("arch", "toolchain-fact"),
            ("unread", "instrument-limitation"),
        ] {
            let gating = &report["observations"]
                .as_array()
                .expect("observations")
                .iter()
                .find(|o| o["check"] == check)
                .expect("the gated observation")["gating"];
            assert_eq!(gating["premise"], class, "{check}");
            let mut keys: Vec<&str> = gating
                .as_object()
                .expect("an object")
                .keys()
                .map(String::as_str)
                .collect();
            keys.sort_unstable();
            assert_eq!(keys, ["needs_vm", "premise", "reason", "rule"], "{check}");
        }
        assert_eq!(reread_rules(&report), (Vec::new(), Vec::new()));
        assert!(
            moved_rules(&report).is_empty(),
            "the gated fixture moves no rule"
        );
        let reports = [("r.json".to_owned(), report)];
        assert!(
            crate::dataset::moved_rule_notes(&reports).is_empty(),
            "the gated fixture carries no moved-rule note"
        );
        assert!(
            crate::dataset::self_contradicted(&reports).is_empty(),
            "the gated fixture is not self-contradicted"
        );
    }

    #[test]
    fn a_rule_that_moved_class_is_sorted_by_its_writer_and_named_as_moved() {
        use gating_rule::Premise::{InstrumentLimitation, ToolchainFact};
        let honest = gated_reread_json().to_string();
        for (from, to, check, written, reading, resorted) in [
            (
                "no-check-on-target",
                "libc-declared",
                "unread",
                InstrumentLimitation,
                ToolchainFact,
                false,
            ),
            (
                "arch-gated",
                "needs-vm",
                "arch",
                ToolchainFact,
                InstrumentLimitation,
                true,
            ),
        ] {
            assert_eq!(honest.matches(&format!("\"{from}\"")).count(), 2, "{from}");
            assert_eq!(gating_rule::by_id(to).map(|r| r.premise), Some(reading));
            let mut moved: serde_json::Value =
                serde_json::from_str(&honest.replace(&format!("\"{from}\""), &format!("\"{to}\"")))
                    .expect("JSON");
            // The rename is textual, so `arch-gated`'s count stays behind; a writer whose
            // rule was `needs-vm` counted no check out of the ISA's reach, and the coverage
            // rule holds the count to the arch-gated tally.
            if from == "arch-gated" {
                moved["coverage"]["checks_not_applicable_here"] = 0.into();
            }
            assert_eq!(reread_rules(&moved), (Vec::new(), Vec::new()), "{to}");
            assert_eq!(
                moved_rules(&moved),
                [MovedRule {
                    rule: to.to_owned(),
                    written: Some(written),
                    reading: Some(reading),
                    observations: 1,
                }]
            );
            let reports = [("r.json".to_owned(), moved.clone())];
            assert!(
                crate::dataset::self_contradicted(&reports).is_empty(),
                "{to}"
            );
            let notes = crate::dataset::moved_rule_notes(&reports);
            assert_eq!(notes.len(), 1, "{notes:?}");
            for word in [
                "GATING RULE MOVED: r.json:".to_owned(),
                format!("`{to}`"),
                format!("`{}`", written.as_str()),
                format!("`{}`", reading.as_str()),
                format!("`{}`", written.verdict().as_str()),
                format!("`{}`", reading.verdict().as_str()),
            ] {
                assert!(notes[0].contains(&word), "{word}: {}", notes[0]);
            }

            // The older writer: the class absent, so this build's table sorts it.
            let mut older = moved;
            observation_named(&mut older, check)["gating"]
                .as_object_mut()
                .expect("an object")
                .remove("premise");
            let (rules, unreadable) = reread_rules(&older);
            assert!(unreadable.is_empty(), "{unreadable:?}");
            assert!(
                rules.contains(&RULE_GATING_VERDICT.to_owned()),
                "{to}: {rules:?}"
            );
            assert_eq!(
                rules.contains(&RULE_WITHHOLDING.to_owned()),
                resorted,
                "{to}: {rules:?}"
            );
            assert!(
                moved_rules(&older).is_empty(),
                "no class was written to move"
            );
        }
    }

    #[test]
    fn a_written_class_is_held_to_its_verdict_and_to_itself() {
        let honest = gated_reread_json();

        let mut edited = honest.clone();
        observation_named(&mut edited, "arch")["gating"]["premise"] =
            serde_json::json!("instrument-limitation");
        let (rules, _) = reread_rules(&edited);
        assert!(rules.contains(&RULE_GATING_VERDICT.to_owned()), "{rules:?}");

        for word in [serde_json::json!("fact"), serde_json::Value::Null] {
            let mut unknown = honest.clone();
            observation_named(&mut unknown, "arch")["gating"]["premise"] = word.clone();
            let read = reread_contradictions(&unknown);
            assert!(
                read.unreadable
                    .iter()
                    .any(|u| u.contains("`observations`") && u.contains(RULE_GATING_VERDICT)),
                "{word}: {:?}",
                read.unreadable
            );
        }

        let text = honest.to_string();
        let later: serde_json::Value = serde_json::from_str(
            &text.replace("\"no-check-on-target\"", "\"rule-of-a-later-chard\""),
        )
        .expect("JSON");
        assert_eq!(reread_rules(&later), (Vec::new(), Vec::new()));
        let named = moved_rules(&later);
        assert_eq!(named.len(), 1, "{named:?}");
        assert_eq!(named[0].heading(), "GATING RULE UNKNOWN");
        assert!(named[0].to_string().contains("`instrument-limitation`"));
        let mut unclassed = later;
        observation_named(&mut unclassed, "unread")["gating"]
            .as_object_mut()
            .expect("an object")
            .remove("premise");
        assert_eq!(reread_rules(&unclassed), (Vec::new(), Vec::new()));
        assert!(
            moved_rules(&unclassed)[0]
                .to_string()
                .contains("no premise class"),
            "{:?}",
            moved_rules(&unclassed)
        );

        // `unread` relabelled to `arch-gated` keeps its own class beside it: two classes.
        let mut two = honest;
        observation_named(&mut two, "unread")["gating"]["rule"] = serde_json::json!("arch-gated");
        let found = reread_contradictions(&two).contradictions;
        assert!(
            found.iter().any(|c| c.rule == RULE_GATING_VERDICT
                && c.property == "observations[unread].gating.premise"),
            "{found:?}"
        );
    }

    #[test]
    fn a_verdict_swapped_apart_from_its_gating_is_refused_on_read() {
        let honest = gated_reread_json();
        let mut forged = honest.clone();
        let gating = observation_named(&mut forged, "arch")["gating"].clone();
        observation_named(&mut forged, "arch")["verdict"] = serde_json::json!("off");
        let plain = observation_named(&mut forged, "plain");
        plain["verdict"] = serde_json::json!("unsupported");
        plain["gating"] = gating;
        assert_eq!(
            forged["coverage"], honest["coverage"],
            "the tally is neutral"
        );
        let found = reread_contradictions(&forged);
        assert!(
            found.unreadable.is_empty() && found.older.is_empty(),
            "{found:?}"
        );
        assert_eq!(
            found
                .contradictions
                .iter()
                .map(|c| (c.rule.as_str(), c.property.as_str()))
                .collect::<Vec<_>>(),
            [(RULE_GATING_VERDICT, "observations[arch].verdict")]
        );
        let reports = [("r.json".to_owned(), forged)];
        let refused = crate::dataset::self_contradicted(&reports);
        assert_eq!(refused.len(), 1, "{refused:?}");
        assert!(
            refused[0].text.contains(RULE_GATING_VERDICT),
            "{}",
            refused[0]
        );

        let mut unknown = honest;
        let unread = observation_named(&mut unknown, "unread");
        unread["gating"] = serde_json::json!({"rule": "rule-of-a-later-chard",
                                              "needs_vm": false, "reason": "r"});
        unread["verdict"] = serde_json::json!("off");
        let found = reread_contradictions(&unknown).contradictions;
        assert!(
            found.iter().any(|c| c.rule == RULE_GATING_VERDICT),
            "{found:?}"
        );
    }

